            );
        END IF;

        RETURN jsonb_build_object(
            'success', false,
            'error', 'Pending upload not found',
            'code', 'NOT_FOUND'
        );
    END IF;

    -- 3. Delete the pending record
    DELETE FROM grn_images
    WHERE id = p_image_id
    AND status = 'pending'
    AND (uploaded_by = public.get_current_user_profile_id()
         OR warehouse_security.active_role() IN ('admin','supervisor'));

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Pending upload not found', 'code', 'NOT_FOUND');
    END IF;

    -- 4. Return success with storage_path for frontend to delete from storage
    RETURN jsonb_build_object(
        'success', true,
        'storage_path', v_storage_path,
        'message', 'Upload cancelled. Frontend should delete from storage.'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Unexpected error: ' || SQLERRM,
        'code', 'INTERNAL_ERROR'
    );
END;
