--
-- Name: cancel_invoice(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.cancel_invoice(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_invoice_record RECORD;
      v_user_id UUID;
  BEGIN
      -- Check if user is admin
      IF NOT EXISTS(SELECT 1 FROM user_profiles WHERE auth_user_id = auth.uid() AND role = 'admin') THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Only administrators can cancel invoices'
          );
      END IF;

      -- Get current user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

      -- Get invoice record
      SELECT * INTO v_invoice_record FROM invoice WHERE id = p_invoice_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Invoice not found'
          );
      END IF;

      -- Delete invoice trail records
      DELETE FROM invoice_trl WHERE invoice_id = p_invoice_id;

      -- Delete invoice
      DELETE FROM invoice WHERE id = p_invoice_id;

      -- Update GRN invoiced status
      UPDATE goodsreceived
      SET invoiced = false
      WHERE id = v_invoice_record.gr_id;

      RETURN jsonb_build_object(
          'success', true,
          'invoice_id', p_invoice_id,
          'message', 'Invoice cancelled successfully'
      );

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', SQLERRM
          );
  END;
  $$;

ALTER FUNCTION public.cancel_invoice(p_invoice_id uuid) OWNER TO supabase_admin;

--
-- Name: cancel_invoice(uuid, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.cancel_invoice(p_invoice_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_gr_id UUID;
    v_invoice_no VARCHAR(20);
BEGIN
    -- Get invoice details
    SELECT gr_id, CONCAT(inv_fin_year, '/', inv_no) INTO v_gr_id, v_invoice_no
    FROM invoice
    WHERE id = p_invoice_id;

    IF v_gr_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Invoice not found'
        );
    END IF;

    -- Soft delete by updating notes
    UPDATE invoice
    SET notes = COALESCE(notes, '') || ' [CANCELLED: ' || COALESCE(p_reason, 'No reason provided') || ']'
    WHERE id = p_invoice_id;

    -- Reset GRN invoiced flag
    UPDATE goodsreceived SET invoiced = false WHERE id = v_gr_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Invoice cancelled successfully',
        'invoice_no', v_invoice_no,
        'gr_id', v_gr_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM
    );
END;
$$;

ALTER FUNCTION public.cancel_invoice(p_invoice_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: cancel_print_job(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.cancel_print_job(p_print_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_role VARCHAR(20);
    v_job_user_id UUID;
    v_cups_job_id INTEGER;
    v_job_status VARCHAR(20);
BEGIN
    SELECT role INTO v_user_role FROM public.user_profiles WHERE id = auth.uid();

    IF v_user_role IS NULL THEN
        RETURN utils.not_authenticated_response();
    END IF;

    SELECT user_id, cups_job_id, status INTO v_job_user_id, v_cups_job_id, v_job_status
    FROM public.print_jobs WHERE id = p_print_job_id;

    IF v_job_user_id IS NULL THEN
        RETURN utils.not_found_response('Print job', p_print_job_id::text);
    END IF;

    IF v_job_user_id != auth.uid() AND v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN utils.error_response('PERMISSION_DENIED', 'Permission denied. You can only cancel your own print jobs.');
    END IF;

    IF v_job_status IN ('completed', 'cancelled', 'failed') THEN
        RETURN utils.error_response('INVALID_STATUS', 'Cannot cancel job with status: ' || v_job_status);
    END IF;

    UPDATE public.print_jobs SET status = 'cancelled', completed_at = NOW(), updated_at = NOW() WHERE id = p_print_job_id;

    RETURN utils.success_response(
        jsonb_build_object(
            'print_job_id', p_print_job_id,
            'cups_job_id', v_cups_job_id,
            'note', 'Call manage-print-jobs Edge Function to cancel CUPS job: ' || v_cups_job_id
        ),
        'Print job marked as cancelled'
    );
END;
$$;

ALTER FUNCTION public.cancel_print_job(p_print_job_id uuid) OWNER TO supabase_admin;

