--
-- Name: check_ip_rate_limit(inet); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.check_ip_rate_limit(p_ip_address inet) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_rate_limit RECORD;
    v_hourly_limit INTEGER := 100;
    v_current_hour TIMESTAMP WITH TIME ZONE;
BEGIN
    IF p_ip_address IS NULL THEN
        RETURN utils.success_response(
            jsonb_build_object('allowed', true, 'remaining', v_hourly_limit),
            'IP rate limit check passed (no IP provided)'
        );
    END IF;

    v_current_hour := DATE_TRUNC('hour', NOW());

    INSERT INTO public.ip_rate_limits (ip_address)
    VALUES (p_ip_address)
    ON CONFLICT (ip_address) DO NOTHING;

    SELECT * INTO v_rate_limit FROM public.ip_rate_limits WHERE ip_address = p_ip_address;

    IF v_rate_limit.last_reset_hour < v_current_hour THEN
        UPDATE public.ip_rate_limits
        SET hourly_count = 0, last_reset_hour = v_current_hour, updated_at = NOW()
        WHERE ip_address = p_ip_address;
        v_rate_limit.hourly_count := 0;
    END IF;

    IF v_rate_limit.hourly_count >= v_hourly_limit THEN
        RETURN utils.error_response('RATE_LIMIT_EXCEEDED', 'IP rate limit exceeded. Please try again later.',
            'Limit: ' || v_hourly_limit || ' requests per hour');
    END IF;

    UPDATE public.ip_rate_limits
    SET hourly_count = hourly_count + 1, updated_at = NOW()
    WHERE ip_address = p_ip_address;

    RETURN utils.success_response(
        jsonb_build_object('allowed', true, 'remaining', v_hourly_limit - v_rate_limit.hourly_count - 1),
        'IP rate limit check passed'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('IP rate limit check failed', SQLERRM, SQLSTATE);
END;
$$;

ALTER FUNCTION public.check_ip_rate_limit(p_ip_address inet) OWNER TO supabase_admin;

--
-- Name: check_otp_rate_limit(character varying); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.check_otp_rate_limit(p_phone_number character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_phone_formatted VARCHAR(15);
    v_rate_limit RECORD;
    v_hourly_limit INTEGER := 40;
    v_daily_limit INTEGER := 20;
    v_current_hour TIMESTAMP WITH TIME ZONE;
    v_current_day TIMESTAMP WITH TIME ZONE;
BEGIN
    v_phone_formatted := REGEXP_REPLACE(p_phone_number, '[^0-9]', '', 'g');
    IF LENGTH(v_phone_formatted) = 10 THEN
        v_phone_formatted := '91' || v_phone_formatted;
    END IF;

    v_current_hour := DATE_TRUNC('hour', NOW());
    v_current_day := DATE_TRUNC('day', NOW());

    INSERT INTO public.otp_rate_limits (phone_number)
    VALUES (v_phone_formatted)
    ON CONFLICT (phone_number) DO NOTHING;

    SELECT * INTO v_rate_limit FROM public.otp_rate_limits WHERE phone_number = v_phone_formatted;

    IF v_rate_limit.last_reset_hour < v_current_hour THEN
        UPDATE public.otp_rate_limits
        SET hourly_count = 0, last_reset_hour = v_current_hour, updated_at = NOW()
        WHERE phone_number = v_phone_formatted;
        v_rate_limit.hourly_count := 0;
    END IF;

    IF v_rate_limit.last_reset_day < v_current_day THEN
        UPDATE public.otp_rate_limits
        SET daily_count = 0, last_reset_day = v_current_day, hourly_count = 0,
            last_reset_hour = v_current_hour, updated_at = NOW()
        WHERE phone_number = v_phone_formatted;
        v_rate_limit.daily_count := 0;
        v_rate_limit.hourly_count := 0;
    END IF;

    IF v_rate_limit.hourly_count >= v_hourly_limit THEN
        RETURN utils.error_response('OTP_RATE_LIMIT', 'Hourly OTP limit exceeded. Please try again later.',
            jsonb_build_object('hourly_remaining', 0, 'daily_remaining', v_daily_limit - v_rate_limit.daily_count)::text);
    ELSIF v_rate_limit.daily_count >= v_daily_limit THEN
        RETURN utils.error_response('OTP_RATE_LIMIT', 'Daily OTP limit exceeded. Please try again tomorrow.',
            jsonb_build_object('hourly_remaining', 0, 'daily_remaining', 0)::text);
    END IF;

    UPDATE public.otp_rate_limits
    SET hourly_count = hourly_count + 1, daily_count = daily_count + 1, updated_at = NOW()
    WHERE phone_number = v_phone_formatted;

    RETURN utils.success_response(
        jsonb_build_object(
            'allowed', true,
            'hourly_remaining', v_hourly_limit - v_rate_limit.hourly_count - 1,
            'daily_remaining', v_daily_limit - v_rate_limit.daily_count - 1
        ),
        'Rate limit check passed'
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Rate limit check failed', SQLERRM, SQLSTATE);
END;
$$;

ALTER FUNCTION public.check_otp_rate_limit(p_phone_number character varying) OWNER TO supabase_admin;

--
-- Name: check_session(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.check_session() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF auth.jwt()->>'role'='authenticated' AND NOT EXISTS (
    SELECT 1 FROM warehouse_security.refresh_sessions s JOIN public.user_profiles p ON p.auth_user_id=s.user_id
    WHERE s.id::text=auth.jwt()->>'session_id' AND s.user_id=auth.uid() AND s.expires_at>now()
      AND p.active AND p.enrollment_status='approved')
  THEN RAISE EXCEPTION 'Session expired or revoked' USING ERRCODE='42501'; END IF;
END $$;

ALTER FUNCTION public.check_session() OWNER TO supabase_admin;

--
-- Name: check_session_validity(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.check_session_validity() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_last_activity TIMESTAMPTZ;
    v_inactive_duration INTERVAL;
BEGIN
    SELECT id INTO v_user_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('valid', FALSE, 'error', 'Not authenticated');
    END IF;

    -- Get last activity
    SELECT last_activity_at INTO v_last_activity
    FROM user_session_activity
    WHERE user_id = v_user_id
    ORDER BY last_activity_at DESC
    LIMIT 1;

    IF v_last_activity IS NULL THEN
        -- First activity, session is valid
        RETURN jsonb_build_object('valid', TRUE, 'first_activity', TRUE);
    END IF;

    v_inactive_duration := NOW() - v_last_activity;

    -- Check 15-minute inactivity timeout
    IF v_inactive_duration > INTERVAL '15 minutes' THEN
        RETURN jsonb_build_object(
            'valid', FALSE,
            'error', 'Session expired due to inactivity',
            'last_activity', v_last_activity,
            'inactive_duration_seconds', EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER,
            'requires_reauth', TRUE
        );
    END IF;

    RETURN jsonb_build_object(
        'valid', TRUE,
        'last_activity', v_last_activity,
        'inactive_duration_seconds', EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER,
        'time_until_timeout_seconds', (900 - EXTRACT(EPOCH FROM v_inactive_duration))::INTEGER
    );
END;
$$;

ALTER FUNCTION public.check_session_validity() OWNER TO supabase_admin;

--
-- Name: check_stock_availability(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.check_stock_availability(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_profile_id UUID;
    v_order_customer_id UUID;
    v_accessible_customers UUID[];
    v_total_requested INTEGER := 0;
    v_total_fulfillable INTEGER := 0;
    v_can_fulfill_all BOOLEAN := TRUE;
    v_fulfillment_pct NUMERIC;
    v_items_result JSONB;
    v_dispatch_items JSONB;
BEGIN
    -- Get user profile ID
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'User not authenticated'
        );
    END IF;

    -- Get order customer ID
    SELECT customer_id INTO v_order_customer_id
    FROM orders
    WHERE id = p_order_id;

    IF v_order_customer_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Order not found'
        );
    END IF;

    -- Check access permissions
    IF NOT is_admin_or_supervisor() THEN
        v_accessible_customers := user_accessible_customers();
        IF v_order_customer_id != ALL(v_accessible_customers) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied'
            );
        END IF;
    END IF;

    -- Get items with current stock information
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', oi.id,
            'grn_item_id', oi.grn_items_id,
            'item_name', oi.grn_items_item_name,
            'package_mark', oi.grn_items_package_mark,
            'packaging', oi.grn_items_packaging,
            'rack', oi.grn_items_rack,
            'weight', oi.grn_items_weight,
            'requested_qty', oi.requested_quantity,
            'fulfilled_quantity', oi.fulfilled_quantity,
            'available_stock_at_order', oi.available_stock_at_order,
            'current_stock', grt.stock,
            'available_qty', LEAST(grt.stock, oi.requested_quantity),
            'status', CASE
                WHEN grt.stock >= oi.requested_quantity THEN 'available'
                WHEN grt.stock > 0 THEN 'partial'
                ELSE 'unavailable'
            END,
            'shortage_quantity', GREATEST(0, oi.requested_quantity - grt.stock),
            'item_status', oi.item_status,
            'sort_order', oi.sort_order
        )
        ORDER BY oi.sort_order, oi.created_at
    ) INTO v_items_result
    FROM order_items oi
    LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
    WHERE oi.order_id = p_order_id;

    -- Calculate fulfillment statistics
    SELECT
        SUM(oi.requested_quantity),
        SUM(LEAST(grt.stock, oi.requested_quantity)),
        BOOL_AND(grt.stock >= oi.requested_quantity)
    INTO v_total_requested, v_total_fulfillable, v_can_fulfill_all
    FROM order_items oi
    LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
    WHERE oi.order_id = p_order_id;

    -- Calculate fulfillment percentage
    IF v_total_requested > 0 THEN
        v_fulfillment_pct := ROUND((v_total_fulfillable::NUMERIC / v_total_requested::NUMERIC) * 100, 2);
    ELSE
        v_fulfillment_pct := 0;
    END IF;

    -- Prepare dispatch items (only items with available stock)
    SELECT jsonb_agg(
        jsonb_build_object(
            'grn_items_id', oi.grn_items_id,
            'grn_items_item_id', oi.grn_items_item_id,
            'grn_items_item_name', oi.grn_items_item_name,
            'grn_items_package_mark', oi.grn_items_package_mark,
            'grn_items_packaging', oi.grn_items_packaging,
            'grn_items_rack', oi.grn_items_rack,
            'grn_items_weight', oi.grn_items_weight,
            'grns_id', oi.grns_id,
            'grns_gr_no', oi.grns_gr_no,
            'grns_date', oi.grns_date,
            'requested_quantity', oi.requested_quantity,
            'dispatch_quantity', LEAST(grt.stock, oi.requested_quantity),
            'available_stock', grt.stock
        )
    ) INTO v_dispatch_items
    FROM order_items oi
    LEFT JOIN goodsreceived_trl grt ON grt.id = oi.grn_items_id
    WHERE oi.order_id = p_order_id
    AND grt.stock > 0;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'order_id', p_order_id,
            'can_fulfill_completely', COALESCE(v_can_fulfill_all, false),
            'fulfillment_percentage', COALESCE(v_fulfillment_pct, 0),
            'items', COALESCE(v_items_result, '[]'::jsonb),
            'prepared_dispatch_items', COALESCE(v_dispatch_items, '[]'::jsonb)
        )
    );
END;
$$;

ALTER FUNCTION public.check_stock_availability(p_order_id uuid) OWNER TO supabase_admin;

--
-- Name: cleanup_expired_otps(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.cleanup_expired_otps() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_deleted_count INTEGER;
  BEGIN
      DELETE FROM public.otp_verifications
      WHERE expires_at < NOW() - INTERVAL '1 hour'  -- Keep for 1 hour after expiry for logging
      OR (verified = TRUE AND verified_at < NOW() - INTERVAL '24 hours'); -- Clean verified OTPs after 24 hours

      GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

      RETURN v_deleted_count;
  END;
  $$;

ALTER FUNCTION public.cleanup_expired_otps() OWNER TO supabase_admin;

