ALTER FUNCTION public.cleanup_intrusion_events() OWNER TO supabase_admin;

--
-- Name: cleanup_old_audit_logs(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.cleanup_old_audit_logs() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    partition_name TEXT;
    cutoff_date DATE := CURRENT_DATE - INTERVAL '1 year';
BEGIN
    -- Drop partitions older than 1 year
    FOR partition_name IN
        SELECT tablename FROM pg_tables
        WHERE schemaname = 'public'
        AND tablename LIKE 'audit_log_%'
        AND tablename < 'audit_log_' || TO_CHAR(cutoff_date, 'YYYY_MM')
    LOOP
        EXECUTE format('DROP TABLE IF EXISTS public.%I', partition_name);
        RAISE NOTICE 'Dropped partition: %', partition_name;
    END LOOP;
END;
$$;

ALTER FUNCTION public.cleanup_old_audit_logs() OWNER TO supabase_admin;

--
-- Name: cleanup_orphaned_grn_images(integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.cleanup_orphaned_grn_images(p_max_age_hours integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_deleted_count integer;
    v_deleted_paths jsonb;
BEGIN
    -- Find and delete stale pending records (older than p_max_age_hours)
    -- Return the storage paths so the caller can delete from storage

    WITH deleted AS (
        DELETE FROM grn_images
        WHERE status = 'pending'
        AND created_at < NOW() - (p_max_age_hours || ' hours')::interval
        RETURNING storage_path
    )
    SELECT
        COUNT(*),
        COALESCE(jsonb_agg(storage_path), '[]'::jsonb)
    INTO v_deleted_count, v_deleted_paths
    FROM deleted;

    RETURN jsonb_build_object(
        'success', true,
        'deleted_count', v_deleted_count,
        'storage_paths', v_deleted_paths,
        'message', 'Cleanup completed. Delete these paths from storage.'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Cleanup error: ' || SQLERRM,
        'code', 'CLEANUP_ERROR'
    );
END;
$$;

ALTER FUNCTION public.cleanup_orphaned_grn_images(p_max_age_hours integer) OWNER TO supabase_admin;

--
-- Name: clear_user_central_identity(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.clear_user_central_identity(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE target public.user_profiles;
BEGIN
  PERFORM warehouse_security.authorize_rpc('clear_user_central_identity', jsonb_build_object('p_user_id', p_user_id));
  -- The guard lets the service key through; this is a signed-in administrator's action.
  IF auth.jwt()->>'role' IS DISTINCT FROM 'authenticated' OR warehouse_security.active_role() IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Administrator required' USING ERRCODE='42501';
  END IF;
  IF p_user_id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','INVALID_INPUT','message','User ID is required');
  END IF;
  SELECT * INTO target FROM public.user_profiles WHERE id=p_user_id FOR UPDATE;
  IF target.id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','NOT_FOUND','message','User not found');
  END IF;
  IF target.is_service_account THEN
    RETURN jsonb_build_object('success',false,'error','SERVICE_ACCOUNT_READ_ONLY','error_code','SERVICE_ACCOUNT_READ_ONLY',
      'message','A service account cannot be changed here');
  END IF;
  UPDATE public.user_profiles SET central_issuer=NULL,central_subject=NULL,updated_at=now() WHERE id=p_user_id;
  DELETE FROM warehouse_security.refresh_sessions WHERE user_id=target.auth_user_id;
  RETURN jsonb_build_object('success',true,'user_id',p_user_id,
    'was_linked',target.central_subject IS NOT NULL,
    'message','Central sign-in link cleared; the user is signed out');
END $$;

ALTER FUNCTION public.clear_user_central_identity(p_user_id uuid) OWNER TO supabase_admin;

--
-- Name: confirm_dispatch_image_upload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.confirm_dispatch_image_upload(p_image_id uuid, p_upload_token uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_record RECORD;
BEGIN
  PERFORM warehouse_security.authorize_rpc('confirm_dispatch_image_upload',jsonb_build_object());
    -- 1. Authenticate user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'code', 'AUTH_REQUIRED'
        );
    END IF;

    -- 2. Find the pending record with matching token
    SELECT * INTO v_record
    FROM dispatch_images
    WHERE id = p_image_id
    AND upload_token = p_upload_token
    AND status = 'pending';

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Upload not found, already confirmed, or invalid token',
            'code', 'NOT_FOUND'
        );
    END IF;

    IF warehouse_security.image_path_refusal('dispatch', v_record.dispatch_id, NULL, v_record.storage_path, v_record.id) IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', warehouse_security.image_path_refusal('dispatch', v_record.dispatch_id, NULL, v_record.storage_path, v_record.id),
            'code', 'IMAGE_NOT_VERIFIED'
        );
    END IF;

    -- 3. Update status to confirmed
    UPDATE dispatch_images
    SET status = 'confirmed',
        upload_token = NULL,  -- Clear token after use
        updated_at = NOW()
    WHERE id = p_image_id;

    -- 4. Return success
    RETURN jsonb_build_object(
        'success', true,
        'image_id', v_record.id,
        'storage_path', v_record.storage_path,
        'dispatch_id', v_record.dispatch_id,
        'status', 'confirmed'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Unexpected error: ' || SQLERRM,
        'code', 'INTERNAL_ERROR'
    );
END;
$$;

ALTER FUNCTION public.confirm_dispatch_image_upload(p_image_id uuid, p_upload_token uuid) OWNER TO supabase_admin;

