--
-- Name: constant_time_compare(text, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.constant_time_compare(a text, b text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result BOOLEAN := TRUE;
    v_len_a INTEGER := LENGTH(a);
    v_len_b INTEGER := LENGTH(b);
    v_max_len INTEGER;
    i INTEGER;
    v_char_a TEXT;
    v_char_b TEXT;
BEGIN
    -- Always compare lengths (but don't early exit)
    v_result := v_result AND (v_len_a = v_len_b);
    v_max_len := GREATEST(v_len_a, v_len_b);

    -- Always iterate through all characters (prevents early exit timing leak)
    FOR i IN 1..v_max_len LOOP
        -- Get characters (or null if out of bounds)
        v_char_a := CASE WHEN i <= v_len_a THEN SUBSTRING(a FROM i FOR 1) ELSE '' END;
        v_char_b := CASE WHEN i <= v_len_b THEN SUBSTRING(b FROM i FOR 1) ELSE '' END;

        -- Compare characters (always executes, never early exits)
        v_result := v_result AND (v_char_a = v_char_b);
    END LOOP;

    -- Final check to ensure strings are truly equal
    RETURN v_result AND (a = b);
END;
$$;

ALTER FUNCTION public.constant_time_compare(a text, b text) OWNER TO supabase_admin;

--
-- Name: convert_below_lakh(integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.convert_below_lakh(num integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    result TEXT := '';
    n INTEGER := num;
BEGIN
    IF n >= 1000 THEN
        result := result || convert_below_thousand(floor(n / 1000)::integer) || ' Thousand ';
        n := n % 1000;
    END IF;

    result := result || convert_below_thousand(n);
    RETURN TRIM(result);
END;
$$;

ALTER FUNCTION public.convert_below_lakh(num integer) OWNER TO supabase_admin;

--
-- Name: convert_below_thousand(integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.convert_below_thousand(num integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    ones TEXT[] := ARRAY['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine',
                        'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen',
                        'Seventeen', 'Eighteen', 'Nineteen'];
    tens TEXT[] := ARRAY['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
    result TEXT := '';
    n INTEGER := num;
BEGIN
    IF n = 0 THEN
        RETURN '';
    END IF;

    -- Handle Hundreds
    IF n >= 100 THEN
        result := result || ones[floor(n / 100)::integer + 1] || ' Hundred ';
        n := n % 100;
    END IF;

    -- Handle below 100
    IF n >= 20 THEN
        result := result || tens[floor(n / 10)::integer + 1];
        n := n % 10;
        IF n > 0 THEN
            result := result || ' ';
        END IF;
    END IF;

    IF n > 0 AND n < 20 THEN
        result := result || ones[n + 1];
    END IF;

    RETURN TRIM(result);
END;
$$;

ALTER FUNCTION public.convert_below_thousand(num integer) OWNER TO supabase_admin;

--
-- Name: convert_number_to_words(integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.convert_number_to_words(p_num integer) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    ones TEXT[] := ARRAY['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine',
                        'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen',
                        'Seventeen', 'Eighteen', 'Nineteen'];
    tens TEXT[] := ARRAY['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
    result TEXT := '';
    num INTEGER := p_num;
BEGIN
    IF num = 0 THEN
        RETURN 'Zero only';
    END IF;

    -- Handle Crores (10,000,000)
    IF num >= 10000000 THEN
        result := result || convert_below_lakh(floor(num / 10000000)::integer) || ' Crore ';
        num := num % 10000000;
    END IF;

    -- Handle Lakhs (100,000)
    IF num >= 100000 THEN
        result := result || convert_below_lakh(floor(num / 100000)::integer) || ' Lakh ';
        num := num % 100000;
    END IF;

    -- Handle Thousands (1,000)
    IF num >= 1000 THEN
        result := result || convert_below_thousand(floor(num / 1000)::integer) || ' Thousand ';
        num := num % 1000;
    END IF;

    -- Handle below 1000
    result := result || convert_below_thousand(num);

    RETURN TRIM(result) || ' only';
END;
$$;

ALTER FUNCTION public.convert_number_to_words(p_num integer) OWNER TO supabase_admin;

--
-- Name: create_customer(character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, text[], text[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.create_customer(p_name character varying, p_mobile character varying, p_email character varying DEFAULT NULL::character varying, p_address text DEFAULT NULL::text, p_city character varying DEFAULT NULL::character varying, p_state character varying DEFAULT NULL::character varying, p_pincode character varying DEFAULT NULL::character varying, p_gst_number character varying DEFAULT NULL::character varying, p_pan_number character varying DEFAULT NULL::character varying, p_contact_person character varying DEFAULT NULL::character varying, p_contact_mobile character varying DEFAULT NULL::character varying, p_contact_email character varying DEFAULT NULL::character varying, p_image_urls text[] DEFAULT NULL::text[], p_document_urls text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $_$
DECLARE
    v_customer_id UUID;
    v_image_count INTEGER;
    v_document_count INTEGER;
BEGIN
  PERFORM warehouse_security.authorize_rpc('create_customer',jsonb_build_object());
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
    -- Check permission: Admin/Supervisor only
    IF NOT is_admin_or_supervisor() THEN
        RETURN utils.permission_denied_response('admins and supervisors');
    END IF;

    -- Validate name
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RETURN utils.validation_error_response('name', 'Customer name is required');
    END IF;

    -- Validate mobile format (but allow duplicates)
    IF p_mobile IS NULL OR NOT p_mobile ~ '^[0-9]{10,15}$' THEN
        RETURN utils.validation_error_response('mobile', 'Mobile number must be 10-15 digits');
    END IF;

    -- Count images and documents
    v_image_count := COALESCE(array_length(p_image_urls, 1), 0);
    v_document_count := COALESCE(array_length(p_document_urls, 1), 0);

    -- Insert customer with image_urls and document_urls stored directly in the table
    INSERT INTO customers (
        name, mobile, email, address, city, state, pincode,
        gst, pan, contact_person, contact_mobile, contact_email,
        image_urls, document_urls
    )
    VALUES (
        TRIM(p_name), p_mobile, p_email, p_address, p_city, p_state, p_pincode,
        p_gst_number, p_pan_number, p_contact_person, p_contact_mobile, p_contact_email,
        p_image_urls, p_document_urls
    )
    RETURNING id INTO v_customer_id;

    RETURN utils.success_response(
        jsonb_build_object(
            'customer_id', v_customer_id,
            'images_saved', v_image_count,
            'documents_saved', v_document_count
        ),
        'Customer created successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN utils.error_response('DUPLICATE_NAME', 'A customer with this name already exists');
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to create customer', SQLERRM, SQLSTATE);
END;
$_$;

ALTER FUNCTION public.create_customer(p_name character varying, p_mobile character varying, p_email character varying, p_address text, p_city character varying, p_state character varying, p_pincode character varying, p_gst_number character varying, p_pan_number character varying, p_contact_person character varying, p_contact_mobile character varying, p_contact_email character varying, p_image_urls text[], p_document_urls text[]) OWNER TO supabase_admin;

--
-- Name: create_dispatch_with_stock_check(jsonb, jsonb[], integer, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.create_dispatch_with_stock_check(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_retry_count integer DEFAULT 0, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    SET jit TO 'off'
    AS $$
DECLARE
    v_validation_result JSONB;
BEGIN
  PERFORM warehouse_security.authorize_rpc('create_dispatch_with_stock_check',jsonb_build_object());
  PERFORM warehouse_security.require_person_supervisor(p_dispatch_data->>'supervisor_id');
  IF EXISTS (SELECT 1 FROM customers WHERE id::text = p_dispatch_data->>'customer_id' AND deleted_at IS NOT NULL) THEN
    RAISE EXCEPTION 'Business is not active' USING ERRCODE = 'P0001';
  END IF;
    -- Step 1: Validate dispatch data
    v_validation_result := validate_dispatch_input(p_dispatch_data);

    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid dispatch data',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 2: Validate dispatch items
    v_validation_result := validate_dispatch_items(p_dispatch_items);

    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid dispatch items',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 3: Call internal function with idempotency key
    RETURN create_dispatch_with_stock_check_internal_3param(
        p_dispatch_data,
        p_dispatch_items,
        p_retry_count,
        p_idempotency_key
    );
END;
$$;

ALTER FUNCTION public.create_dispatch_with_stock_check(p_dispatch_data jsonb, p_dispatch_items jsonb[], p_retry_count integer, p_idempotency_key text) OWNER TO supabase_admin;

