--
-- Name: create_first_admin(character varying, character varying, character varying); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.create_first_admin(admin_mobile character varying, admin_name character varying, admin_display_name character varying DEFAULT NULL::character varying) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
    new_profile_id uuid;
BEGIN
    INSERT INTO user_profiles (
        auth_user_id,
        name,
        display_name,
        mobile,
        role,
        active
    ) VALUES (
        gen_random_uuid(),
        admin_name,
        COALESCE(admin_display_name, admin_name),
        admin_mobile,
        'admin',
        true
    ) RETURNING id INTO new_profile_id;

    RAISE NOTICE 'Created admin user profile with ID: %', new_profile_id;
    RAISE NOTICE 'Mobile: %', admin_mobile;
    RAISE NOTICE 'IMPORTANT: User must log in through Supabase Auth to complete setup';

    RETURN new_profile_id;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'create_first_admin failed: % - %', SQLSTATE, SQLERRM;
        RETURN NULL;
END;
$$;

ALTER FUNCTION public.create_first_admin(admin_mobile character varying, admin_name character varying, admin_display_name character varying) OWNER TO supabase_admin;

--
-- Name: create_item(character varying, character varying, character varying, boolean, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.create_item(p_name character varying, p_packaging character varying DEFAULT NULL::character varying, p_description character varying DEFAULT NULL::character varying, p_active boolean DEFAULT true, p_rate_from_item uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_new_id uuid;
    v_result jsonb;
    v_source text := 'none';
    v_today date := warehouse_security.business_date(now());
BEGIN
  PERFORM warehouse_security.authorize_rpc('create_item',jsonb_build_object());
    -- Security check
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Access denied: Admin or supervisor role required'
        );
    END IF;

    -- Validate name
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item name is required'
        );
    END IF;

    -- Check for duplicate name
    IF EXISTS (SELECT 1 FROM items WHERE LOWER(name) = LOWER(TRIM(p_name))) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'An item with this name already exists'
        );
    END IF;

    -- Insert new item
    INSERT INTO items (name, packaging, description, active)
    VALUES (TRIM(p_name), NULLIF(TRIM(p_packaging), ''), NULLIF(TRIM(p_description), ''), p_active)
    RETURNING id INTO v_new_id;

    -- The item's rate (migration 85): a copy of another item's default rows in force today, else
    -- the standard tiers from today, else none. A save of the standard rate in progress is waited
    -- for (it holds the same lock exclusively), so the tiers read below are the committed ones.
    PERFORM pg_advisory_xact_lock_shared(hashtextextended('standard_rate', 0));
    IF p_rate_from_item IS NOT NULL
       AND warehouse_security.copy_default_rates(p_rate_from_item, v_new_id, v_today) > 0 THEN
        v_source := 'copied';
    ELSIF warehouse_security.give_standard_rate(v_new_id, v_today) > 0 THEN
        v_source := 'standard';
    END IF;

    -- Return created item
    SELECT jsonb_build_object(
        'id', id,
        'name', name,
        'packaging', packaging,
        'description', description,
        'active', active,
        'rate_source', v_source
    ) INTO v_result
    FROM items
    WHERE id = v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Item created successfully',
        'data', v_result
    );
END;
$$;

ALTER FUNCTION public.create_item(p_name character varying, p_packaging character varying, p_description character varying, p_active boolean, p_rate_from_item uuid) OWNER TO supabase_admin;

--
-- Name: create_item_storage_price(uuid, numeric, numeric, numeric, date, uuid, numeric, numeric, numeric, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.create_item_storage_price(p_item_id uuid, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_effective_from date, p_customer_id uuid DEFAULT NULL::uuid, p_unit_price_one_time numeric DEFAULT NULL::numeric, p_unit_price_monthly numeric DEFAULT NULL::numeric, p_tax_percent numeric DEFAULT 18, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_profile_id UUID;
    v_new_id UUID;
    v_validation JSONB;
    v_result RECORD;
BEGIN
  PERFORM warehouse_security.authorize_rpc('create_item_storage_price',jsonb_build_object('p_customer_id',p_customer_id));
    -- Authorization: admin/supervisor only
    SELECT up.id, up.role INTO v_user_profile_id, v_user_role
    FROM user_profiles up WHERE up.auth_user_id = auth.uid();

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Validation 1: weight_max >= weight_min
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validation 2: At least one price must be > 0
    IF COALESCE(p_unit_price_one_time, 0) <= 0 AND COALESCE(p_unit_price_monthly, 0) <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'At least one of unit_price_one_time or unit_price_monthly must be > 0');
    END IF;

    -- Validation 3: effective_to >= effective_from (if provided)
    IF p_effective_to IS NOT NULL AND p_effective_to < p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must be >= effective_from');
    END IF;

    -- Validation 4: Item must exist
    IF NOT EXISTS (SELECT 1 FROM items WHERE id = p_item_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not found');
    END IF;

    -- Validation 5: Customer must exist (if provided)
    IF p_customer_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
    END IF;

    -- Validation 6: No overlapping date ranges (use existing helper)
    v_validation := validate_price_configuration(
        p_item_id,
        p_weight_min::integer,
        p_weight_max::integer,
        p_effective_from,
        p_customer_id,
        p_effective_to
    );

    IF NOT (v_validation->>'valid')::boolean THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', COALESCE(v_validation->>'error', v_validation->>'message', 'Overlapping price configuration exists')
        );
    END IF;

    -- Insert the new price record
    INSERT INTO item_storage_prices (
        item_id,
        customer_id,
        weight_min,
        weight_max,
        unit_price_one_time,
        unit_price_monthly,
        labour_rate,
        tax_percent,
        effective_from,
        effective_to,
        created_by
    ) VALUES (
        p_item_id,
        p_customer_id,
        p_weight_min::integer,
        p_weight_max::integer,
        COALESCE(p_unit_price_one_time, 0),
        COALESCE(p_unit_price_monthly, 0),
        p_labour_rate,
        p_tax_percent,
        p_effective_from,
        p_effective_to,
        v_user_profile_id
    )
    RETURNING id INTO v_new_id;

    -- Fetch the created record with joined data
    SELECT
        isp.id,
        isp.item_id,
        i.name as item_name,
        isp.customer_id,
        c.name as customer_name,
        isp.weight_min,
        isp.weight_max,
        isp.unit_price_one_time,
        isp.unit_price_monthly,
        isp.labour_rate,
        isp.tax_percent,
        isp.effective_from,
        isp.effective_to,
        isp.created_at,
        isp.created_by
    INTO v_result
    FROM item_storage_prices isp
    LEFT JOIN items i ON isp.item_id = i.id
    LEFT JOIN customers c ON isp.customer_id = c.id
    WHERE isp.id = v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'id', v_result.id,
            'item_id', v_result.item_id,
            'item_name', v_result.item_name,
            'customer_id', v_result.customer_id,
            'customer_name', v_result.customer_name,
            'weight_min', v_result.weight_min,
            'weight_max', v_result.weight_max,
            'unit_price_one_time', v_result.unit_price_one_time,
            'unit_price_monthly', v_result.unit_price_monthly,
            'labour_rate', v_result.labour_rate,
            'tax_percent', v_result.tax_percent,
            'effective_from', v_result.effective_from,
            'effective_to', v_result.effective_to,
            'created_at', v_result.created_at,
            'created_by', v_result.created_by
        ),
        'message', 'Price created successfully'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Creation failed: ' || SQLERRM
    );
END;
$$;

ALTER FUNCTION public.create_item_storage_price(p_item_id uuid, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_effective_from date, p_customer_id uuid, p_unit_price_one_time numeric, p_unit_price_monthly numeric, p_tax_percent numeric, p_effective_to date) OWNER TO supabase_admin;

--
-- Name: create_item_storage_price(uuid, text, numeric, numeric, numeric, numeric, date, uuid, numeric, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.create_item_storage_price(p_item_id uuid, p_price_type text, p_unit_price numeric, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_effective_from date, p_customer_id uuid DEFAULT NULL::uuid, p_tax_percent numeric DEFAULT 18, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_id UUID;
    v_new_id UUID;
    v_item_exists BOOLEAN;
    v_customer_exists BOOLEAN;
BEGIN
  PERFORM warehouse_security.authorize_rpc('create_item_storage_price',jsonb_build_object('p_customer_id',p_customer_id));
    -- Authorization: admin/supervisor only
    SELECT role, id INTO v_user_role, v_user_id
    FROM user_profiles WHERE auth_user_id = auth.uid();

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- A rate that is already in force is changed by administrators and supervisors (migration 76).
    IF v_user_role = 'staff' AND p_effective_from < warehouse_security.business_date(now()) THEN
        RETURN warehouse_security.rate_failure('RATE_IN_FORCE_MANAGER_ONLY',
          'Only administrators and supervisors can change a rate that is already in force');
    END IF;

    -- Validate price_type
    IF p_price_type NOT IN ('one_time', 'monthly') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid price_type. Must be ''one_time'' or ''monthly''');
    END IF;

    -- Validate weight range
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validate unit_price
    IF p_unit_price IS NULL OR p_unit_price < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'unit_price must be >= 0');
    END IF;

    -- Validate date range
    IF p_effective_to IS NOT NULL AND p_effective_to < p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must not be before effective_from');
    END IF;

    -- Check item exists
    SELECT EXISTS(SELECT 1 FROM items WHERE id = p_item_id) INTO v_item_exists;
    IF NOT v_item_exists THEN
        RETURN jsonb_build_object('success', false, 'error', 'Item not found');
    END IF;

    -- Check customer exists if provided
    IF p_customer_id IS NOT NULL THEN
        SELECT EXISTS(SELECT 1 FROM customers WHERE id = p_customer_id) INTO v_customer_exists;
        IF NOT v_customer_exists THEN
            RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
        END IF;
    END IF;

    -- One change of this scope at a time, as in replace_item_rates (migration 87).
    PERFORM pg_advisory_xact_lock(hashtextextended('item_rates:' || p_item_id || ':' || COALESCE(p_customer_id::text, 'default') || ':' || p_price_type, 0));

    -- No other row of this item, customer and price type may share a weight and a day (migration 76).
    IF warehouse_security.price_rows_overlap(p_item_id, p_customer_id, p_price_type,
         p_weight_min::integer, p_weight_max::integer, p_effective_from, p_effective_to) THEN
        RETURN warehouse_security.rate_failure('BANDS_OVERLAP', 'Weight bands overlap');
    END IF;

    -- Insert the new price record
    INSERT INTO item_storage_prices (
        item_id, customer_id, price_type, unit_price,
        weight_min, weight_max, labour_rate, tax_percent,
        effective_from, effective_to, created_by,
        unit_price_one_time, unit_price_monthly  -- Keep old columns populated for backward compat
    ) VALUES (
        p_item_id, p_customer_id, p_price_type, p_unit_price,
        p_weight_min, p_weight_max, CASE WHEN p_price_type = 'one_time' THEN 0 ELSE p_labour_rate END, p_tax_percent,
        p_effective_from, p_effective_to, v_user_id,
        CASE WHEN p_price_type = 'one_time' THEN p_unit_price ELSE 0 END,
        CASE WHEN p_price_type = 'monthly' THEN p_unit_price ELSE 0 END
    )
    RETURNING id INTO v_new_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('id', v_new_id),
        'message', 'Price created successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'A price with the same item, customer, weight range, price type and effective dates already exists'
        );
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;

ALTER FUNCTION public.create_item_storage_price(p_item_id uuid, p_price_type text, p_unit_price numeric, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_effective_from date, p_customer_id uuid, p_tax_percent numeric, p_effective_to date) OWNER TO supabase_admin;

--
-- Name: deactivate_sensor(character varying, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.deactivate_sensor(p_device_mac character varying, p_reason text DEFAULT 'User removed sensor'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_sensor_id UUID;
    v_sensor_name TEXT;
BEGIN
    -- Get sensor info
    SELECT id, device_name INTO v_sensor_id, v_sensor_name
    FROM sensor_devices
    WHERE mac_address = p_device_mac;

    IF v_sensor_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'Sensor not found',
            'error', jsonb_build_object('code', 'SENSOR_NOT_FOUND')
        );
    END IF;

    -- Deactivate sensor in registry
    UPDATE sensor_devices
    SET
        active = FALSE,
        deactivated_at = NOW(),
        deactivation_reason = p_reason,
        updated_at = NOW()
    WHERE mac_address = p_device_mac;

    -- Log deactivation event
    INSERT INTO sensor_health_events (
        device_id,
        device_mac,
        device_name,
        event_type,
        severity,
        event_message,
        metadata
    ) VALUES (
        v_sensor_id,
        p_device_mac,
        v_sensor_name,
        'SENSOR_DEACTIVATED',
        'INFO',
        'Sensor removed from active monitoring: ' || p_reason,
        jsonb_build_object('reason', p_reason)
    );

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('sensor_id', v_sensor_id),
        'message', 'Sensor deactivated successfully'
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', SQLERRM,
            'error', jsonb_build_object('code', 'DATABASE_ERROR')
        );
END;
$$;

ALTER FUNCTION public.deactivate_sensor(p_device_mac character varying, p_reason text) OWNER TO supabase_admin;

--
-- Name: debug_auth_context(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.debug_auth_context() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_auth_uid UUID;
    v_jwt_claims TEXT;
    v_jwt_sub TEXT;
    v_user_profile RECORD;
BEGIN
    v_auth_uid := auth.uid();

    BEGIN
        v_jwt_claims := current_setting('request.jwt.claims', true);
    EXCEPTION WHEN OTHERS THEN
        v_jwt_claims := 'ERROR: ' || SQLERRM;
    END;

    BEGIN
        v_jwt_sub := current_setting('request.jwt.claim.sub', true);
    EXCEPTION WHEN OTHERS THEN
        v_jwt_sub := 'ERROR: ' || SQLERRM;
    END;

    SELECT * INTO v_user_profile FROM public.user_profiles WHERE auth_user_id = v_auth_uid;

    RETURN utils.success_response(
        jsonb_build_object(
            'auth_uid', v_auth_uid,
            'jwt_claims', v_jwt_claims,
            'jwt_sub', v_jwt_sub,
            'user_profile_found', (v_user_profile.id IS NOT NULL),
            'user_profile_id', v_user_profile.id,
            'user_name', v_user_profile.name,
            'user_role', v_user_profile.role
        )
    );
END;
$$;

ALTER FUNCTION public.debug_auth_context() OWNER TO supabase_admin;

--
-- Name: debug_current_user_grn_access(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.debug_current_user_grn_access() RETURNS TABLE(auth_uid uuid, user_email character varying, user_role public.user_role, is_supervisor boolean, can_access_grn_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
      RETURN QUERY
      SELECT
          auth.uid() as auth_uid,
          up.email as user_email,
          up.role as user_role,
          is_admin_or_supervisor() as is_supervisor,
          (SELECT COUNT(*) FROM goodsreceived WHERE date >= '2024-01-01' AND date <= '2025-01-11') as can_access_grn_count
      FROM user_profiles up
      WHERE up.auth_user_id = auth.uid();
  END;
  $$;

ALTER FUNCTION public.debug_current_user_grn_access() OWNER TO supabase_admin;

