-- Name: debug_jwt_claims(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.debug_jwt_claims() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  BEGIN
      RETURN jsonb_build_object(
          'jwt_setting_available',
          CASE
              WHEN current_setting('request.jwt.claims', true) IS NOT NULL
              THEN true
              ELSE false
          END,
          'jwt_claims',
          COALESCE(current_setting('request.jwt.claims', true)::jsonb, '{}'::jsonb),
          'user_role_from_jwt',
