--
-- Name: get_active_sessions(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_active_sessions(p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_sessions JSONB;
BEGIN
    -- Use provided user_id or current user
    IF p_user_id IS NOT NULL THEN
        v_user_id := p_user_id;
    ELSE
        SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
    END IF;

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'User not found');
    END IF;

    -- Get active sessions (last 1 hour)
    SELECT jsonb_agg(jsonb_build_object(
        'session_id', auth_session_id,
        'last_activity', last_activity_at,
        'inactive_duration_seconds', EXTRACT(EPOCH FROM (NOW() - last_activity_at))::INTEGER,
        'ip_address', ip_address,
        'user_agent', user_agent,
        'activity_type', activity_type
    ))
    INTO v_sessions
    FROM (
        SELECT DISTINCT ON (auth_session_id)
            auth_session_id,
            last_activity_at,
            ip_address,
            user_agent,
            activity_type
        FROM user_session_activity
        WHERE user_id = v_user_id
        AND last_activity_at > NOW() - INTERVAL '1 hour'
        ORDER BY auth_session_id, last_activity_at DESC
    ) active_sessions;

    RETURN jsonb_build_object(
        'success', TRUE,
        'user_id', v_user_id,
        'sessions', COALESCE(v_sessions, '[]'::JSONB)
    );
END;
$$;

ALTER FUNCTION public.get_active_sessions(p_user_id uuid) OWNER TO supabase_admin;

--
-- Name: get_all_customer_activity_summary(date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_all_customer_activity_summary(p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_result jsonb;
    v_summary jsonb;
    v_customers jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_all_customer_activity_summary',jsonb_build_object());
    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Get user's accessible customers if not staff
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;
    END IF;

    WITH customer_stock AS (
        -- Current stock per customer (no date filter - current snapshot)
        SELECT
            gr.customer_id,
            SUM(grt.stock) as current_stock
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.deleted_at IS NULL AND grt.stock > 0
        GROUP BY gr.customer_id
    ),
    customer_grns AS (
        -- GRN counts in date range
        SELECT
            customer_id,
            COUNT(*) as total_grns
        FROM goodsreceived
        WHERE deleted_at IS NULL
            AND date >= warehouse_security.business_day_start(p_from_date) AND date < warehouse_security.business_day_start(p_to_date + 1)
        GROUP BY customer_id
    ),
    customer_dispatches AS (
        -- Dispatch counts in date range
        SELECT
            customer_id,
            COUNT(*) as total_dispatches
        FROM dispatch
        WHERE deleted_at IS NULL
            AND disp_date >= warehouse_security.business_day_start(p_from_date) AND disp_date < warehouse_security.business_day_start(p_to_date + 1)
        GROUP BY customer_id
    ),
    customer_invoices AS (
        -- Invoice totals in date range
        SELECT
            customer_id,
            SUM(COALESCE(total, 0)) as total_invoice_amount
        FROM invoice
        WHERE deleted_at IS NULL
            AND inv_date >= warehouse_security.business_day_start(p_from_date) AND inv_date < warehouse_security.business_day_start(p_to_date + 1)
        GROUP BY customer_id
    ),
    last_activity AS (
        -- Most recent activity per customer (within date range)
        SELECT DISTINCT ON (customer_id)
            customer_id,
            activity_date as last_activity_date,
            activity_type as last_activity_type
        FROM (
            SELECT customer_id, date as activity_date, 'grn' as activity_type
            FROM goodsreceived
            WHERE deleted_at IS NULL AND date >= warehouse_security.business_day_start(p_from_date) AND date < warehouse_security.business_day_start(p_to_date + 1)
            UNION ALL
            SELECT customer_id, disp_date as activity_date, 'dispatch' as activity_type
            FROM dispatch
            WHERE deleted_at IS NULL AND disp_date >= warehouse_security.business_day_start(p_from_date) AND disp_date < warehouse_security.business_day_start(p_to_date + 1)
        ) activities
        ORDER BY customer_id, activity_date DESC
    ),
    customer_data AS (
        SELECT
            c.id as customer_id,
            c.name as customer_name,
            c.city as customer_city,
            COALESCE(cs.current_stock, 0) as current_stock,
            COALESCE(cg.total_grns, 0) as total_grns,
            COALESCE(cd.total_dispatches, 0) as total_dispatches,
            COALESCE(ci.total_invoice_amount, 0) as total_invoice_amount,
            la.last_activity_date,
            la.last_activity_type
        FROM customers c
        LEFT JOIN customer_stock cs ON c.id = cs.customer_id
        LEFT JOIN customer_grns cg ON c.id = cg.customer_id
        LEFT JOIN customer_dispatches cd ON c.id = cd.customer_id
        LEFT JOIN customer_invoices ci ON c.id = ci.customer_id
        LEFT JOIN last_activity la ON c.id = la.customer_id
        WHERE c.deleted_at IS NULL
            -- Filter by user's accessible customers if not staff
            AND (v_user_role IN ('admin', 'supervisor', 'staff') OR c.id = ANY(v_user_customer_ids))
            -- Only include customers with some activity or stock
            AND (
                COALESCE(cs.current_stock, 0) > 0
                OR COALESCE(cg.total_grns, 0) > 0
                OR COALESCE(cd.total_dispatches, 0) > 0
                OR COALESCE(ci.total_invoice_amount, 0) > 0
            )
    )
    SELECT
        jsonb_build_object(
            'total_customers', COUNT(*),
            'total_current_stock', COALESCE(SUM(current_stock), 0),
            'total_grns', COALESCE(SUM(total_grns), 0),
            'total_dispatches', COALESCE(SUM(total_dispatches), 0),
            'total_invoice_amount', COALESCE(SUM(total_invoice_amount), 0)
        ),
        COALESCE(jsonb_agg(
            jsonb_build_object(
                'customer_id', customer_id,
                'customer_name', customer_name,
                'customer_city', customer_city,
                'current_stock', current_stock,
                'total_grns', total_grns,
                'total_dispatches', total_dispatches,
                'total_invoice_amount', total_invoice_amount,
                'last_activity_date', last_activity_date,
                'last_activity_type', last_activity_type
            ) ORDER BY current_stock DESC
        ), '[]'::jsonb)
    INTO v_summary, v_customers
    FROM customer_data;

    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'summary', v_summary,
            'customers', v_customers
        ),
        'metadata', jsonb_build_object(
            'retrieved_at', NOW(),
            'from_date', p_from_date,
            'to_date', p_to_date
        )
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve customer activity summary: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;

ALTER FUNCTION public.get_all_customer_activity_summary(p_from_date date, p_to_date date) OWNER TO supabase_admin;

--
-- Name: get_all_dispatch_activity(date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_all_dispatch_activity(p_from_date date DEFAULT ((timezone('Asia/Kolkata'::text, now()))::date - 7), p_to_date date DEFAULT (timezone('Asia/Kolkata'::text, now()))::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
    v_user_id UUID;
    v_user_role TEXT;
    v_user_customer_ids UUID[];
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_all_dispatch_activity',jsonb_build_object());
    -- Get caller's user profile and role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid() AND active = true;
    END IF;

    -- Authentication required
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'summary', NULL,
            'dispatches', '[]'::jsonb
        );
    END IF;

    -- Get user's accessible customers if not admin/supervisor
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'summary', jsonb_build_object(
                    'total_dispatches', 0,
                    'total_customers', 0,
                    'total_quantity', 0,
                    'from_date', p_from_date,
                    'to_date', p_to_date
                ),
                'by_customer', '[]'::jsonb,
                'by_date', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'success', true,
        'summary', (
            SELECT jsonb_build_object(
                'total_dispatches', COUNT(DISTINCT d.id),
                'total_customers', COUNT(DISTINCT d.customer_id),
                'total_quantity', COALESCE(SUM(dt.disp_qty), 0),
                'from_date', p_from_date,
                'to_date', p_to_date
            )
            FROM dispatch d
            JOIN dispatch_trl dt ON dt.disp_id = d.id
            WHERE d.deleted_at IS NULL
              AND d.disp_date >= warehouse_security.business_day_start(p_from_date)
              AND d.disp_date < warehouse_security.business_day_start(p_to_date + 1)
              AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
        ),
        'by_customer', COALESCE((
            SELECT jsonb_agg(customer_data ORDER BY CASE WHEN jsonb_typeof(customer_data->'total_qty') = 'number' THEN (customer_data->>'total_qty')::numeric END DESC NULLS LAST, customer_data->>'customer_name', customer_data->>'customer_id')
            FROM (
                SELECT jsonb_build_object(
                    'customer_id', c.id,
                    'customer_name', c.name,
                    'dispatch_count', COUNT(DISTINCT d.id),
                    'total_qty', SUM(dt.disp_qty),
                    'latest_dispatch', warehouse_security.business_date(MAX(d.disp_date))
                ) AS customer_data
                FROM customers c
                JOIN dispatch d ON d.customer_id = c.id AND d.deleted_at IS NULL
                JOIN dispatch_trl dt ON dt.disp_id = d.id
                WHERE d.disp_date >= warehouse_security.business_day_start(p_from_date) AND d.disp_date < warehouse_security.business_day_start(p_to_date + 1)
                  AND (v_user_role IN ('admin', 'supervisor', 'staff') OR c.id = ANY(v_user_customer_ids))
                GROUP BY c.id, c.name
            ) AS customers_agg
        ), '[]'::jsonb),
        'by_date', COALESCE((
            SELECT jsonb_agg(date_data ORDER BY date_data->>'date' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'date', warehouse_security.business_date(d.disp_date),
                    'dispatch_count', COUNT(DISTINCT d.id),
                    'total_qty', SUM(dt.disp_qty),
                    'customer_count', COUNT(DISTINCT d.customer_id)
                ) AS date_data
                FROM dispatch d
                JOIN dispatch_trl dt ON dt.disp_id = d.id
                WHERE d.deleted_at IS NULL
                  AND d.disp_date >= warehouse_security.business_day_start(p_from_date)
                  AND d.disp_date < warehouse_security.business_day_start(p_to_date + 1)
                  AND (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
                GROUP BY warehouse_security.business_date(d.disp_date)
            ) AS dates_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve dispatch activity: ' || SQLERRM,
            'summary', NULL,
            'dispatches', '[]'::jsonb
        );
END;
$$;

ALTER FUNCTION public.get_all_dispatch_activity(p_from_date date, p_to_date date) OWNER TO supabase_admin;

--
-- Name: get_all_dispatch_items(timestamp with time zone, timestamp with time zone, jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_all_dispatch_items(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $_$
    DECLARE
        v_result jsonb;
        v_total_count integer;
        v_total_dispatch_qty bigint;
        v_total_dispatches integer;
        v_items jsonb;
        v_user_role text;
        v_user_customer_ids uuid[];
        v_sort_column text;
        v_order_direction text;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_all_dispatch_items',jsonb_build_object());
        -- Security: Get user role and accessible customers
        SELECT role INTO v_user_role FROM user_profiles
        WHERE auth_user_id = auth.uid();

        -- If user is not admin/supervisor, get their assigned customers
        IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
            v_user_customer_ids := user_accessible_customers();

            -- If no accessible customers, return empty result
            IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'data', null,
                    'message', 'Access denied: No accessible customers found'
                );
            END IF;
        END IF;

        -- Security: Validate sort column (whitelist approach - snake_case)
        IF p_sort_by NOT IN ('date', 'disp_no', 'customer_name', 'item_name', 'disp_qty') THEN
            RAISE EXCEPTION 'Invalid sort column: %. Allowed values: date, disp_no, customer_name, item_name, disp_qty', p_sort_by;
        END IF;

        -- Security: Validate sort order
        IF UPPER(p_sort_order) NOT IN ('ASC', 'DESC') THEN
            RAISE EXCEPTION 'Invalid sort order: %. Allowed values: ASC, DESC', p_sort_order;
        END IF;

        -- Map validated sort column to actual column reference
        v_sort_column := CASE p_sort_by
            WHEN 'date' THEN 'd.disp_date'
            WHEN 'disp_no' THEN 'd.disp_no'
            WHEN 'customer_name' THEN 'd.customer_name'
            WHEN 'item_name' THEN 'grt.item_name'
            WHEN 'disp_qty' THEN 'dt.disp_qty'
        END;

        v_order_direction := UPPER(p_sort_order);

        -- Validate limit and offset
        IF p_limit < 1 OR p_limit > 1000 THEN
            p_limit := 20;
        END IF;

        IF p_offset < 0 THEN
            p_offset := 0;
        END IF;

        -- Get total count for pagination (snake_case filter keys)
        SELECT COUNT(*) INTO v_total_count
        FROM dispatch_trl dt
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        WHERE (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
        AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
        AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
        AND (NOT p_filters ? 'customer_name' OR p_filters->>'customer_name' = '' OR d.customer_name ILIKE '%' || (p_filters->>'customer_name') || '%')
        AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
        AND (NOT p_filters ? 'rack' OR p_filters->>'rack' = '' OR grt.rack ILIKE '%' || (p_filters->>'rack') || '%');

        -- Get aggregations
        SELECT
            COALESCE(SUM(dt.disp_qty), 0),
            COUNT(DISTINCT d.id)
        INTO v_total_dispatch_qty, v_total_dispatches
        FROM dispatch_trl dt
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        WHERE (v_user_role IN ('admin', 'supervisor', 'staff') OR d.customer_id = ANY(v_user_customer_ids))
        AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
        AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
        AND (NOT p_filters ? 'customer_name' OR p_filters->>'customer_name' = '' OR d.customer_name ILIKE '%' || (p_filters->>'customer_name') || '%')
        AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
        AND (NOT p_filters ? 'rack' OR p_filters->>'rack' = '' OR grt.rack ILIKE '%' || (p_filters->>'rack') || '%');

        -- Get paginated items with dynamic sort (snake_case response keys)
        EXECUTE format('
            SELECT jsonb_agg(page.item ORDER BY page.rn)
            FROM (
              SELECT jsonb_build_object(
                    ''id'', dt.id,
                    ''dispatch_id'', d.id,
                    ''disp_no'', d.disp_no,
                    ''disp_date'', d.disp_date,
                    ''customer_name'', d.customer_name,
                    ''customer_id'', d.customer_id,
                    ''supervisor_name'', d.supervisor_name,
                    ''supervisor_id'', d.supervisor_id,
                    ''registration'', d.registration,
                    ''note'', d.note,
                    ''disp_image_url'', d.disp_image_url,
                    ''source_order_id'', d.source_order_id,
                    ''source_order_no'', d.source_order_no,
                    ''disp_qty'', dt.disp_qty,
                    ''grn_id'', grt.gr_id,
                    ''grn_item_id'', grt.id,
                    ''item_name'', grt.item_name,
                    ''item_id'', grt.item_id,
                    ''original_qty'', grt.qty,
                    ''current_stock'', grt.stock,
                    ''weight'', grt.weight,
                    ''rack'', grt.rack,
                    ''package_mark'', grt.package_mark,
                    ''packaging'', grt.packaging,
                    ''trl_img_url'', grt.trl_img_url,
                    ''pricing_mode'', gr.pricing_mode,
                    ''grn_no'', gr.gr_no,
                    ''grn_date'', gr.date,
                    ''created_at'', d.created_at,
                    ''updated_at'', d.updated_at
                ) AS item,
                row_number() OVER (ORDER BY %s %s, dt.id) AS rn
              FROM dispatch_trl dt
            JOIN dispatch d ON dt.disp_id = d.id
            JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            WHERE ($1 IN (''admin'', ''supervisor'', ''staff'') OR d.customer_id = ANY($2))
            AND ($3 IS NULL OR $4 IS NULL OR d.disp_date BETWEEN $3 AND $4)
            AND (NOT $5 ? ''item_name'' OR $5->>''item_name'' = '''' OR grt.item_name ILIKE ''%%'' || ($5->>''item_name'') || ''%%'')
            AND (NOT $5 ? ''disp_no'' OR $5->>''disp_no'' = '''' OR d.disp_no ILIKE ''%%'' || ($5->>''disp_no'') || ''%%'')
            AND (NOT $5 ? ''customer_name'' OR $5->>''customer_name'' = '''' OR d.customer_name ILIKE ''%%'' || ($5->>''customer_name'') || ''%%'')
            AND (NOT $5 ? ''package_mark'' OR $5->>''package_mark'' = '''' OR grt.package_mark ILIKE ''%%'' || ($5->>''package_mark'') || ''%%'')
            AND (NOT $5 ? ''rack'' OR $5->>''rack'' = '''' OR grt.rack ILIKE ''%%'' || ($5->>''rack'') || ''%%'')
              ORDER BY rn
              LIMIT $6 OFFSET $7
            ) page',
            v_sort_column, v_order_direction
        )
        INTO v_items
        USING v_user_role, v_user_customer_ids, p_date_from, p_date_to, p_filters, p_limit, p_offset;

        -- Build result (snake_case aggregation keys)
        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'items', COALESCE(v_items, '[]'::jsonb),
                'pagination', jsonb_build_object(
                    'total', v_total_count,
                    'limit', p_limit,
                    'offset', p_offset,
                    'has_more', (p_offset + p_limit) < v_total_count
                ),
                'aggregations', jsonb_build_object(
                    'total_dispatch_qty', v_total_dispatch_qty,
                    'total_dispatches', v_total_dispatches
                ),
                'applied_filters', p_filters,
                'sort', jsonb_build_object(
                    'column', p_sort_by,
                    'order', p_sort_order
                )
            ),
            'message', null
        );

        RETURN v_result;
    END;
$_$;

ALTER FUNCTION public.get_all_dispatch_items(p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_filters jsonb, p_sort_by text, p_sort_order text, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_all_grn_activity(date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_all_grn_activity(p_from_date date DEFAULT ((timezone('Asia/Kolkata'::text, now()))::date - 7), p_to_date date DEFAULT (timezone('Asia/Kolkata'::text, now()))::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
    v_user_id UUID;
    v_user_role TEXT;
    v_user_customer_ids UUID[];
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_all_grn_activity',jsonb_build_object());
    -- Get caller's user profile and role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid() AND active = true;
    END IF;

    -- Authentication required
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'summary', NULL,
            'grns', '[]'::jsonb
        );
    END IF;

    -- Get user's accessible customers if not admin/supervisor
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff', 'service_role') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'summary', jsonb_build_object(
                    'total_grns', 0,
                    'total_customers', 0,
                    'total_quantity', 0,
                    'total_weight', 0,
                    'from_date', p_from_date,
                    'to_date', p_to_date
                ),
                'by_customer', '[]'::jsonb,
                'by_date', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'success', true,
        'summary', (
            SELECT jsonb_build_object(
                'total_grns', COUNT(DISTINCT g.id),
                'total_customers', COUNT(DISTINCT g.customer_id),
                'total_quantity', COALESCE(SUM(gt.qty), 0),
                'total_weight', COALESCE(SUM(gt.weight::numeric * gt.qty), 0),
                'from_date', p_from_date,
                'to_date', p_to_date
            )
            FROM goodsreceived g
            JOIN goodsreceived_trl gt ON gt.gr_id = g.id
            WHERE g.deleted_at IS NULL
              AND g.date >= warehouse_security.business_day_start(p_from_date)
              AND g.date < warehouse_security.business_day_start(p_to_date + 1)
              AND (v_user_role IN ('admin', 'supervisor', 'staff', 'service_role') OR g.customer_id = ANY(v_user_customer_ids))
        ),
        'by_customer', COALESCE((
            SELECT jsonb_agg(customer_data ORDER BY CASE WHEN jsonb_typeof(customer_data->'total_qty') = 'number' THEN (customer_data->>'total_qty')::numeric END DESC NULLS LAST, customer_data->>'customer_name', customer_data->>'customer_id')
            FROM (
                SELECT jsonb_build_object(
                    'customer_id', c.id,
                    'customer_name', c.name,
                    'grn_count', COUNT(DISTINCT g.id),
                    'total_qty', SUM(gt.qty),
                    'total_weight', SUM(gt.weight::numeric * gt.qty),
                    'latest_grn', warehouse_security.business_date(MAX(g.date))
                ) AS customer_data
                FROM customers c
                JOIN goodsreceived g ON g.customer_id = c.id AND g.deleted_at IS NULL
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.date >= warehouse_security.business_day_start(p_from_date) AND g.date < warehouse_security.business_day_start(p_to_date + 1)
                  AND (v_user_role IN ('admin', 'supervisor', 'staff', 'service_role') OR c.id = ANY(v_user_customer_ids))
                GROUP BY c.id, c.name
            ) AS customers_agg
        ), '[]'::jsonb),
        'by_date', COALESCE((
            SELECT jsonb_agg(date_data ORDER BY date_data->>'date' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'date', warehouse_security.business_date(g.date),
                    'grn_count', COUNT(DISTINCT g.id),
                    'total_qty', SUM(gt.qty),
                    'customer_count', COUNT(DISTINCT g.customer_id)
                ) AS date_data
                FROM goodsreceived g
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE g.deleted_at IS NULL
                  AND g.date >= warehouse_security.business_day_start(p_from_date)
                  AND g.date < warehouse_security.business_day_start(p_to_date + 1)
                  AND (v_user_role IN ('admin', 'supervisor', 'staff', 'service_role') OR g.customer_id = ANY(v_user_customer_ids))
                GROUP BY warehouse_security.business_date(g.date)
            ) AS dates_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve GRN activity: ' || SQLERRM,
            'summary', NULL,
            'grns', '[]'::jsonb
        );
END;
$$;

ALTER FUNCTION public.get_all_grn_activity(p_from_date date, p_to_date date) OWNER TO supabase_admin;

--
-- Name: get_all_grn_items(timestamp with time zone, timestamp with time zone, jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_all_grn_items(p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_sort_column text;
    v_order_direction text;
    v_filter_customer_ids uuid[];
    v_filter_item_ids uuid[];
    v_filter_grn_ids uuid[];
    v_stock_status text;
    v_weight_min integer;
    v_weight_max integer;
    v_package_mark text;
    v_grn_no_from text;
    v_grn_no_to text;
    v_where_conditions text[];
    v_sql text;
    v_receipt boolean := COALESCE(p_filters->>'page_by', '') = 'receipt';
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_all_grn_items',jsonb_build_object());
    -- Security: Get user role and accessible customers
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, get their assigned customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        v_user_customer_ids := user_accessible_customers();

        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: No accessible customers found'
            );
        END IF;
    END IF;

    -- Extract filters (snake_case only)
    IF p_filters ? 'customer_ids' AND jsonb_array_length(p_filters->'customer_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_customer_ids
        FROM jsonb_array_elements_text(p_filters->'customer_ids') elem;
    END IF;

    IF p_filters ? 'item_ids' AND jsonb_array_length(p_filters->'item_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_item_ids
        FROM jsonb_array_elements_text(p_filters->'item_ids') elem;
    END IF;

    IF p_filters ? 'grn_ids' AND jsonb_array_length(p_filters->'grn_ids') > 0 THEN
        SELECT array_agg(elem::text::uuid)
        INTO v_filter_grn_ids
        FROM jsonb_array_elements_text(p_filters->'grn_ids') elem;
    END IF;

    -- Extract stock_status filter
    IF p_filters ? 'stock_status' THEN
        v_stock_status := p_filters->>'stock_status';
    END IF;

    -- Extract weight filters (snake_case)
    IF p_filters ? 'weight_min' THEN
        v_weight_min := (p_filters->>'weight_min')::integer;
    END IF;

    IF p_filters ? 'weight_max' THEN
        v_weight_max := (p_filters->>'weight_max')::integer;
    END IF;

    -- Extract package mark filter (snake_case)
    IF p_filters ? 'package_mark' THEN
        v_package_mark := TRIM(p_filters->>'package_mark');
    END IF;

    -- Extract GRN number range filters (snake_case)
    IF p_filters ? 'gr_no_from' THEN
        v_grn_no_from := TRIM(p_filters->>'gr_no_from');
    END IF;

    IF p_filters ? 'gr_no_to' THEN
        v_grn_no_to := TRIM(p_filters->>'gr_no_to');
    END IF;

    -- Receipt paging accepts receipt-level sorts only
    IF v_receipt AND p_sort_by IS NOT NULL AND p_sort_by NOT IN ('date', 'gr_no', 'customer_name') THEN
        RETURN jsonb_build_object('success', false, 'message', 'Invalid list parameters', 'data', NULL);
    END IF;

    -- Validate and set sort parameters
    v_sort_column := CASE
        WHEN p_sort_by = 'date' THEN 'gr.date'
        WHEN p_sort_by = 'gr_no' THEN '(warehouse_security.document_number_sort_key(gr.gr_no) COLLATE "C")'
        WHEN p_sort_by = 'customer_name' THEN 'gr.customer_name'
        WHEN p_sort_by = 'item_name' THEN 'grt.item_name'
        WHEN p_sort_by = 'qty' THEN 'grt.qty'
        WHEN p_sort_by = 'stock' THEN 'grt.stock'
        WHEN p_sort_by = 'weight' THEN 'grt.weight'
        WHEN p_sort_by = 'package_mark' THEN 'grt.package_mark'
        ELSE 'gr.date'
    END;

    v_order_direction := CASE
        WHEN UPPER(p_sort_order) = 'ASC' THEN 'ASC'
        ELSE 'DESC'
    END;

    -- Build WHERE conditions
    v_where_conditions := ARRAY['1=1'];

    -- Date filters
    IF p_date_from IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.date >= %L', p_date_from));
    END IF;

    IF p_date_to IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.date <= %L', p_date_to));
    END IF;

    -- Role-based customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.customer_id = ANY(%L::uuid[])', v_user_customer_ids));
    END IF;

    -- Customer filter
    IF v_filter_customer_ids IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.customer_id = ANY(%L::uuid[])', v_filter_customer_ids));
    END IF;

    -- Item filter
    IF v_filter_item_ids IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.item_id = ANY(%L::uuid[])', v_filter_item_ids));
    END IF;

    -- GRN filter
    IF v_filter_grn_ids IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('gr.id = ANY(%L::uuid[])', v_filter_grn_ids));
    END IF;

    -- Stock status filter
    IF v_stock_status = 'out_of_stock' THEN
        v_where_conditions := array_append(v_where_conditions, 'grt.stock = 0');
    ELSIF v_stock_status = 'in_stock' THEN
        v_where_conditions := array_append(v_where_conditions, 'grt.stock > 0');
    ELSIF v_stock_status = 'low_stock' THEN
        v_where_conditions := array_append(v_where_conditions, 'grt.stock > 0 AND grt.stock < 0.2 * grt.qty');
    END IF;

    -- Weight filters
    IF v_weight_min IS NOT NULL AND v_weight_max IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.weight BETWEEN %s AND %s', v_weight_min, v_weight_max));
    ELSIF v_weight_min IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.weight >= %s', v_weight_min));
    ELSIF v_weight_max IS NOT NULL THEN
        v_where_conditions := array_append(v_where_conditions,
            format('grt.weight <= %s', v_weight_max));
    END IF;

    -- Package mark filter
    IF v_package_mark IS NOT NULL AND LENGTH(v_package_mark) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('LOWER(COALESCE(grt.package_mark, '''')) LIKE LOWER(%L)', '%' || warehouse_security.like_literal(v_package_mark) || '%'));
    END IF;

    -- GRN number range filters
    IF v_grn_no_from IS NOT NULL AND LENGTH(v_grn_no_from) > 0 AND
       v_grn_no_to IS NOT NULL AND LENGTH(v_grn_no_to) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('(warehouse_security.document_number_sort_key(gr.gr_no) COLLATE "C") BETWEEN (warehouse_security.document_number_sort_key(%L) COLLATE "C") AND (warehouse_security.document_number_sort_key(%L) COLLATE "C")', v_grn_no_from, v_grn_no_to));
    ELSIF v_grn_no_from IS NOT NULL AND LENGTH(v_grn_no_from) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('(warehouse_security.document_number_sort_key(gr.gr_no) COLLATE "C") >= (warehouse_security.document_number_sort_key(%L) COLLATE "C")', v_grn_no_from));
    ELSIF v_grn_no_to IS NOT NULL AND LENGTH(v_grn_no_to) > 0 THEN
        v_where_conditions := array_append(v_where_conditions,
            format('(warehouse_security.document_number_sort_key(gr.gr_no) COLLATE "C") <= (warehouse_security.document_number_sort_key(%L) COLLATE "C")', v_grn_no_to));
    END IF;

    -- Quick search: every word must match some column of the receipt line
    IF btrim(COALESCE(p_filters->>'search', '')) <> '' THEN
        v_where_conditions := array_append(v_where_conditions, format(
            'NOT EXISTS (SELECT 1 FROM unnest(%L::text[]) AS term WHERE NOT (gr.gr_no ILIKE term OR COALESCE(gr.customer_name, '''') ILIKE term OR COALESCE(grt.item_name, '''') ILIKE term OR COALESCE(grt.package_mark, '''') ILIKE term OR COALESCE(grt.rack, '''') ILIKE term OR COALESCE(gr.registration, '''') ILIKE term))',
            warehouse_security.search_terms(p_filters->>'search')));
    END IF;

    -- Build and execute main query
    v_sql := format('
        WITH filtered_grn_items AS (
            SELECT
                gr.id,
                gr.gr_no,
                gr.date,
                gr.customer_name,
                gr.supervisor_name,
                gr.registration,
                gr.out_of_stock,
                gr.invoiced,
                gr.note,
                grt.id as grn_item_id,
                grt.item_name,
                grt.packaging,
                grt.qty,
                grt.stock,
                grt.weight,
                grt.rack,
                grt.package_mark,
                grt.trl_img_url,
                %s OVER (ORDER BY %s %s, gr.gr_no, %s) as row_num
            FROM goodsreceived gr
            JOIN goodsreceived_trl grt ON gr.id = grt.gr_id
            WHERE %s
        ),
        paginated_items AS (
            SELECT *
            FROM filtered_grn_items
            WHERE row_num BETWEEN %s AND %s
        ),
        aggregates AS (
            SELECT
                %s as total_count,
                COALESCE(SUM(qty), 0) as total_qty,
                COALESCE(SUM(stock), 0) as total_stock,
                COALESCE(SUM(weight), 0) as total_weight
            FROM filtered_grn_items
        )
        SELECT jsonb_build_object(
            ''success'', true,
            ''data'', COALESCE(
                (SELECT jsonb_agg(
                    jsonb_build_object(
                        ''id'', id,
                        ''gr_no'', gr_no,
                        ''date'', date,
                        ''customer_name'', customer_name,
                        ''supervisor_name'', supervisor_name,
                        ''registration'', registration,
                        ''out_of_stock'', out_of_stock,
                        ''invoiced'', invoiced,
                        ''note'', note,
                        ''grn_item_id'', grn_item_id,
                        ''item_name'', item_name,
                        ''packaging'', packaging,
                        ''qty'', qty,
                        ''stock'', stock,
                        ''weight'', weight,
                        ''rack'', rack,
                        ''package_mark'', package_mark,
                        ''trl_img_url'', trl_img_url
                    )
                ORDER BY row_num, grn_item_id
                ) FROM paginated_items),
                ''[]''::jsonb
            ),
            ''pagination'', jsonb_build_object(
                ''total_count'', (SELECT total_count FROM aggregates),
                ''limit'', %s,
                ''offset'', %s,
                ''unit'', %L::text
            ),
            ''aggregates'', jsonb_build_object(
                ''total_qty'', (SELECT total_qty FROM aggregates),
                ''total_stock'', (SELECT total_stock FROM aggregates),
                ''total_weight'', (SELECT total_weight FROM aggregates)
            )
        ) as result
    ',
    CASE WHEN v_receipt THEN 'DENSE_RANK()' ELSE 'ROW_NUMBER()' END,
    v_sort_column,
    v_order_direction,
    CASE WHEN v_receipt THEN 'gr.id' ELSE 'grt.id' END,
    array_to_string(v_where_conditions, ' AND '),
    p_offset + 1,
    p_offset + p_limit,
    CASE WHEN v_receipt THEN 'COUNT(DISTINCT id)' ELSE 'COUNT(*)' END,
    p_limit,
    p_offset,
    CASE WHEN v_receipt THEN 'receipt' ELSE 'line' END
    );

    -- Execute the query
    EXECUTE v_sql INTO v_result;

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_all_grn_items(p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_filters jsonb, p_sort_by text, p_sort_order text, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_all_stock_summary(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_all_stock_summary() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
    v_user_id UUID;
    v_user_role TEXT;
    v_user_customer_ids UUID[];
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_all_stock_summary',jsonb_build_object());
    -- Get caller's user profile and role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid() AND active = true;
    END IF;

    -- Authentication required
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'summary', NULL,
            'customers', '[]'::jsonb
        );
    END IF;

    -- Get user's accessible customers if not admin/supervisor
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'summary', jsonb_build_object(
                    'total_customers_with_stock', 0,
                    'total_items', 0,
                    'total_quantity', 0,
                    'total_weight_kg', 0,
                    'oldest_stock_date', NULL,
                    'grn_count', 0
                ),
                'customers', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'success', true,
        'summary', (
            SELECT jsonb_build_object(
                'total_customers_with_stock', COUNT(DISTINCT g.customer_id),
                'total_items', COUNT(DISTINCT gt.item_id),
                'total_quantity', COALESCE(SUM(gt.stock), 0),
                'total_weight_kg', COALESCE(SUM(gt.weight::numeric * gt.stock), 0),
                'oldest_stock_date', warehouse_security.business_date(MIN(g.date)),
                'grn_count', COUNT(DISTINCT g.id)
            )
            FROM goodsreceived g
            JOIN goodsreceived_trl gt ON gt.gr_id = g.id
            WHERE g.deleted_at IS NULL
                AND gt.stock > 0
                AND (v_user_role IN ('admin', 'supervisor', 'staff') OR g.customer_id = ANY(v_user_customer_ids))
        ),
        'customers', COALESCE((
            SELECT jsonb_agg(customer_data ORDER BY CASE WHEN jsonb_typeof(customer_data->'total_stock') = 'number' THEN (customer_data->>'total_stock')::numeric END DESC NULLS LAST, customer_data->>'customer_name', customer_data->>'customer_id')
            FROM (
                SELECT jsonb_build_object(
                    'customer_id', c.id,
                    'customer_name', c.name,
                    'total_stock', SUM(gt.stock),
                    'total_weight', SUM(gt.weight::numeric * gt.stock),
                    'item_count', COUNT(DISTINCT gt.item_id),
                    'grn_count', COUNT(DISTINCT g.id),
                    'oldest_date', warehouse_security.business_date(MIN(g.date)),
                    'latest_date', warehouse_security.business_date(MAX(g.date))
                ) AS customer_data
                FROM customers c
                JOIN goodsreceived g ON g.customer_id = c.id AND g.deleted_at IS NULL
                JOIN goodsreceived_trl gt ON gt.gr_id = g.id
                WHERE c.deleted_at IS NULL
                    AND gt.stock > 0
                    AND (v_user_role IN ('admin', 'supervisor', 'staff') OR c.id = ANY(v_user_customer_ids))
                GROUP BY c.id, c.name
            ) AS customers_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve stock summary: ' || SQLERRM,
            'summary', NULL,
            'customers', '[]'::jsonb
        );
END;
$$;

ALTER FUNCTION public.get_all_stock_summary() OWNER TO supabase_admin;

--
-- Name: get_auto_invoice_error_stats(date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_auto_invoice_error_stats(p_date_from date DEFAULT NULL::date, p_date_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_total_errors INTEGER;
      v_resolved_errors INTEGER;
      v_pending_errors INTEGER;
      v_error_by_type JSONB;
      v_error_by_customer JSONB;
      v_retry_stats JSONB;
      v_result JSONB;
  BEGIN
      -- Set default date range if not provided
      p_date_from := COALESCE(p_date_from, CURRENT_DATE - INTERVAL '30 days');
      p_date_to := COALESCE(p_date_to, CURRENT_DATE);

      -- Total errors
      SELECT COUNT(*) INTO v_total_errors
      FROM auto_invoice_errors
      WHERE created_at::DATE BETWEEN p_date_from AND p_date_to;

      -- Resolved errors
      SELECT COUNT(*) INTO v_resolved_errors
      FROM auto_invoice_errors
      WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
      AND resolved_at IS NOT NULL;

      -- Pending errors
      v_pending_errors := v_total_errors - v_resolved_errors;

      -- Error by type
      SELECT jsonb_object_agg(error_code, error_count) INTO v_error_by_type
      FROM (
          SELECT error_code, COUNT(*) as error_count
          FROM auto_invoice_errors
          WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
          GROUP BY error_code
      ) error_types;

      -- Error by customer
      SELECT jsonb_agg(customer_errors) INTO v_error_by_customer
      FROM (
          SELECT jsonb_build_object(
              'customer_id', customer_id,
              'customer_name', customer_name,
              'error_count', COUNT(*)
          ) as customer_errors
          FROM auto_invoice_errors
          WHERE created_at::DATE BETWEEN p_date_from AND p_date_to
          GROUP BY customer_id, customer_name
          ORDER BY COUNT(*) DESC
          LIMIT 10
      ) top_customers;

      -- Retry statistics
      SELECT jsonb_build_object(
          'avg_retry_count', ROUND(AVG(retry_count), 2),
          'max_retry_count', MAX(retry_count),
          'success_after_retry', COUNT(*) FILTER (WHERE retry_count > 0 AND resolved_at IS NOT NULL)
      ) INTO v_retry_stats
      FROM auto_invoice_errors
      WHERE created_at::DATE BETWEEN p_date_from AND p_date_to;

      -- Build result
      v_result := jsonb_build_object(
          'total_errors', v_total_errors,
          'resolved_errors', v_resolved_errors,
          'pending_errors', v_pending_errors,
          'error_by_type', COALESCE(v_error_by_type, '{}'::jsonb),
          'error_by_customer', COALESCE(v_error_by_customer, '[]'::jsonb),
          'retry_statistics', v_retry_stats,
          'date_range', jsonb_build_object(
              'from', p_date_from,
              'to', p_date_to
          )
      );

      RETURN v_result;
  END;
  $$;

ALTER FUNCTION public.get_auto_invoice_error_stats(p_date_from date, p_date_to date) OWNER TO supabase_admin;

