--
-- Name: get_cart_dispatches(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_cart_dispatches(p_cart_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_cart_dispatches',jsonb_build_object('p_cart_id',p_cart_id));
    WITH dispatch_summary AS (
        SELECT
            d.id,
            d.disp_no,
            d.disp_date,
            d.supervisor_name,
            d.created_at,
            COUNT(dt.id) as item_count,
            COALESCE(SUM(dt.disp_qty), 0) as total_quantity
        FROM dispatch d
        LEFT JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.source_order_id = p_cart_id
          AND d.customer_id = (SELECT o.customer_id FROM orders o WHERE o.id = p_cart_id)
        GROUP BY d.id, d.disp_no, d.disp_date, d.supervisor_name, d.created_at
    )
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'dispatch_id', ds.id,
                'dispatch_no', ds.disp_no,
                'dispatch_date', ds.disp_date,
                'supervisor_name', ds.supervisor_name,
                'item_count', ds.item_count::INTEGER,
                'total_quantity', ds.total_quantity::INTEGER,
                'created_at', ds.created_at
            ) ORDER BY ds.created_at DESC
        ),
        '[]'::jsonb
    ) INTO v_result
    FROM dispatch_summary ds;

    RETURN utils.success_response(v_result);
END;
$$;

ALTER FUNCTION public.get_cart_dispatches(p_cart_id uuid) OWNER TO supabase_admin;

--
-- Name: get_current_user_profile(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_current_user_profile() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_profile jsonb;
BEGIN
    SELECT jsonb_build_object(
        'id', p.id,
        'name', p.name,
        'display_name', p.display_name,
        'email', p.email,
        'mobile', p.mobile,
        'role', p.role::text,
        'auth_user_id', p.auth_user_id,
        'active', p.active,
        'mobile_verified', p.mobile_verified,
        'created_at', p.created_at,
        'updated_at', p.updated_at
    )
    INTO v_profile
    FROM user_profiles p
    WHERE p.auth_user_id = auth.uid() AND p.active = true;

    IF v_profile IS NULL THEN
        RETURN utils.not_authenticated_response();
    END IF;

    RETURN utils.success_response(v_profile, NULL);
END;
$$;

ALTER FUNCTION public.get_current_user_profile() OWNER TO supabase_admin;

