--
-- Name: get_customer_activity_detail(uuid, date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_activity_detail(p_customer_uuid uuid, p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_customer_name text;
    v_customer_city text;
    v_result jsonb;
    v_summary jsonb;
    v_monthly_trends jsonb;
    v_recent_grns jsonb;
    v_recent_dispatches jsonb;
    v_recent_invoices jsonb;
    v_top_stock_items jsonb;
    v_by_bucket jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_customer_activity_detail',jsonb_build_object('p_customer_uuid',p_customer_uuid));
    -- Validate customer_uuid is provided
    IF p_customer_uuid IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Customer UUID is required'
        );
    END IF;

    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Non-admin/supervisor can only view their own customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        IF v_user_customer_ids IS NULL OR NOT (p_customer_uuid = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied: You do not have permission to view this customer''s data'
            );
        END IF;
    END IF;

    -- Get customer info
    SELECT name, city INTO v_customer_name, v_customer_city
    FROM customers
    WHERE id = p_customer_uuid AND deleted_at IS NULL;

    IF v_customer_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Customer not found'
        );
    END IF;

    -- Calculate summary metrics
    WITH current_stock_data AS (
        SELECT
            SUM(grt.stock) as current_stock,
            -- Weighted average stock age
            CASE WHEN SUM(grt.stock) > 0 THEN
                ROUND(SUM(grt.stock * (warehouse_security.business_date(now()) - warehouse_security.business_date(gr.date))) / SUM(grt.stock))
            ELSE 0 END as average_stock_age_days
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND grt.stock > 0
    ),
    grn_data AS (
        SELECT
            COUNT(DISTINCT gr.id) as total_grns,
            COALESCE(SUM(grt.qty), 0) as total_grn_quantity
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND gr.date >= warehouse_security.business_day_start(p_from_date) AND gr.date < warehouse_security.business_day_start(p_to_date + 1)
    ),
    dispatch_data AS (
        SELECT
            COUNT(DISTINCT d.id) as total_dispatches,
            COALESCE(SUM(dt.disp_qty), 0) as total_dispatch_quantity
        FROM dispatch d
        JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.customer_id = p_customer_uuid
            AND d.deleted_at IS NULL
            AND d.disp_date >= warehouse_security.business_day_start(p_from_date) AND d.disp_date < warehouse_security.business_day_start(p_to_date + 1)
    ),
    invoice_data AS (
        SELECT
            COALESCE(SUM(COALESCE(total, 0)), 0) as total_invoice_amount,
            COALESCE(SUM(COALESCE(total, 0) - GREATEST(0, LEAST(COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id = invoice.id), 0), COALESCE(total, 0)))), 0) as total_pending_amount
        FROM invoice
        WHERE customer_id = p_customer_uuid
            AND deleted_at IS NULL
            AND inv_date >= warehouse_security.business_day_start(p_from_date) AND inv_date < warehouse_security.business_day_start(p_to_date + 1)
    ),
    payment_data AS (
        SELECT
            COALESCE(SUM(p.amount), 0) as total_paid_amount
        FROM payments p
        JOIN invoice i ON p.invoice_id = i.id
        WHERE i.customer_id = p_customer_uuid
            AND i.deleted_at IS NULL
            AND i.inv_date >= warehouse_security.business_day_start(p_from_date) AND i.inv_date < warehouse_security.business_day_start(p_to_date + 1)
    )
    SELECT jsonb_build_object(
        'current_stock', COALESCE(cs.current_stock, 0),
        'total_grns', COALESCE(gd.total_grns, 0),
        'total_grn_quantity', COALESCE(gd.total_grn_quantity, 0),
        'total_dispatches', COALESCE(dd.total_dispatches, 0),
        'total_dispatch_quantity', COALESCE(dd.total_dispatch_quantity, 0),
        'total_invoice_amount', COALESCE(id.total_invoice_amount, 0),
        'total_paid_amount', COALESCE(pd.total_paid_amount, 0),
        'total_pending_amount', COALESCE(id.total_pending_amount, 0),
        'average_stock_age_days', COALESCE(cs.average_stock_age_days, 0)
    ) INTO v_summary
    FROM current_stock_data cs
    CROSS JOIN grn_data gd
    CROSS JOIN dispatch_data dd
    CROSS JOIN invoice_data id
    CROSS JOIN payment_data pd;

    -- Monthly trends
    WITH months AS (
        SELECT generate_series(
            DATE_TRUNC('month', p_from_date::timestamp),
            DATE_TRUNC('month', p_to_date::timestamp),
            '1 month'::interval
        )::date as month_start
    ),
    grn_monthly AS (
        SELECT
            DATE_TRUNC('month', warehouse_security.business_date(gr.date)::timestamp)::date as month_start,
            COUNT(DISTINCT gr.id) as grn_count,
            COALESCE(SUM(grt.qty), 0) as grn_quantity
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND gr.date >= warehouse_security.business_day_start(p_from_date) AND gr.date < warehouse_security.business_day_start(p_to_date + 1)
        GROUP BY DATE_TRUNC('month', warehouse_security.business_date(gr.date)::timestamp)
    ),
    dispatch_monthly AS (
        SELECT
            DATE_TRUNC('month', warehouse_security.business_date(d.disp_date)::timestamp)::date as month_start,
            COUNT(DISTINCT d.id) as dispatch_count,
            COALESCE(SUM(dt.disp_qty), 0) as dispatch_quantity
        FROM dispatch d
        JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.customer_id = p_customer_uuid
            AND d.deleted_at IS NULL
            AND d.disp_date >= warehouse_security.business_day_start(p_from_date) AND d.disp_date < warehouse_security.business_day_start(p_to_date + 1)
        GROUP BY DATE_TRUNC('month', warehouse_security.business_date(d.disp_date)::timestamp)
    ),
    invoice_monthly AS (
        SELECT
            DATE_TRUNC('month', warehouse_security.business_date(inv_date)::timestamp)::date as month_start,
            COALESCE(SUM(COALESCE(total, 0)), 0) as invoice_amount
        FROM invoice
        WHERE customer_id = p_customer_uuid
            AND deleted_at IS NULL
            AND inv_date >= warehouse_security.business_day_start(p_from_date) AND inv_date < warehouse_security.business_day_start(p_to_date + 1)
        GROUP BY DATE_TRUNC('month', warehouse_security.business_date(inv_date)::timestamp)
    ),
    -- Stock level at end of each month (cumulative GRN - cumulative Dispatch up to month end)
    stock_monthly AS (
        SELECT
            m.month_start,
            (
                SELECT COALESCE(SUM(grt.qty), 0)
                FROM goodsreceived gr
                JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
                WHERE gr.customer_id = p_customer_uuid
                    AND gr.deleted_at IS NULL
                    AND gr.date < warehouse_security.business_day_start((m.month_start + INTERVAL '1 month - 1 day')::date + 1)
            ) - (
                SELECT COALESCE(SUM(dt.disp_qty), 0)
                FROM dispatch d
                JOIN dispatch_trl dt ON dt.disp_id = d.id
                WHERE d.customer_id = p_customer_uuid
                    AND d.deleted_at IS NULL
                    AND d.disp_date < warehouse_security.business_day_start((m.month_start + INTERVAL '1 month - 1 day')::date + 1)
            ) as stock_level_end
        FROM months m
    )
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'month', TO_CHAR(m.month_start, 'YYYY-MM'),
            'grn_count', COALESCE(gm.grn_count, 0),
            'grn_quantity', COALESCE(gm.grn_quantity, 0),
            'dispatch_count', COALESCE(dm.dispatch_count, 0),
            'dispatch_quantity', COALESCE(dm.dispatch_quantity, 0),
            'invoice_amount', COALESCE(im.invoice_amount, 0),
            'stock_level_end', COALESCE(sm.stock_level_end, 0)
        ) ORDER BY m.month_start
    ), '[]'::jsonb) INTO v_monthly_trends
    FROM months m
    LEFT JOIN grn_monthly gm ON m.month_start = gm.month_start
    LEFT JOIN dispatch_monthly dm ON m.month_start = dm.month_start
    LEFT JOIN invoice_monthly im ON m.month_start = im.month_start
    LEFT JOIN stock_monthly sm ON m.month_start = sm.month_start;

    -- Recent GRNs (last 5)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'grn_id', grn_id,
            'gr_no', gr_no,
            'grn_date', grn_date,
            'total_qty', total_qty,
            'current_stock', current_stock,
            'is_invoiced', is_invoiced
        ) ORDER BY grn_date DESC
    ), '[]'::jsonb) INTO v_recent_grns
    FROM (
        SELECT
            gr.id as grn_id,
            gr.gr_no,
            gr.date as grn_date,
            COALESCE(SUM(grt.qty), 0) as total_qty,
            COALESCE(SUM(grt.stock), 0) as current_stock,
            EXISTS (SELECT 1 FROM invoice i WHERE i.gr_id = gr.id AND i.deleted_at IS NULL) as is_invoiced
        FROM goodsreceived gr
        LEFT JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
        GROUP BY gr.id, gr.gr_no, gr.date
        ORDER BY gr.date DESC
        LIMIT 5
    ) recent;

    -- Recent Dispatches (last 5)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'dispatch_id', dispatch_id,
            'dispatch_no', dispatch_no,
            'dispatch_date', dispatch_date,
            'total_qty', total_qty,
            'supervisor_name', supervisor_name
        ) ORDER BY dispatch_date DESC
    ), '[]'::jsonb) INTO v_recent_dispatches
    FROM (
        SELECT
            d.id as dispatch_id,
            d.disp_no as dispatch_no,
            d.disp_date as dispatch_date,
            COALESCE(SUM(dt.disp_qty), 0) as total_qty,
            d.supervisor_name
        FROM dispatch d
        LEFT JOIN dispatch_trl dt ON dt.disp_id = d.id
        WHERE d.customer_id = p_customer_uuid
            AND d.deleted_at IS NULL
        GROUP BY d.id, d.disp_no, d.disp_date, d.supervisor_name
        ORDER BY d.disp_date DESC
        LIMIT 5
    ) recent;

    -- Recent Invoices (last 5)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'invoice_id', invoice_id,
            'invoice_number', invoice_number,
            'invoice_date', invoice_date,
            'net_total', net_total,
            'status', status
        ) ORDER BY invoice_date DESC
    ), '[]'::jsonb) INTO v_recent_invoices
    FROM (
        SELECT
            i.id as invoice_id,
            i.inv_fin_year::text || '-' || LPAD(i.inv_no::text, GREATEST(4, LENGTH(i.inv_no::text)), '0') as invoice_number,
            i.inv_date as invoice_date,
            COALESCE(i.total, 0) as net_total,
            CASE WHEN COALESCE(i.total, 0) - GREATEST(0, LEAST(COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.invoice_id = i.id), 0), COALESCE(i.total, 0))) <= 0.50 THEN 'paid' ELSE 'pending' END as status
        FROM invoice i
        WHERE i.customer_id = p_customer_uuid
            AND i.deleted_at IS NULL
        ORDER BY i.inv_date DESC
        LIMIT 5
    ) recent;

    -- Top Stock Items (top 5 by current stock)
    SELECT COALESCE(jsonb_agg(
        jsonb_build_object(
            'item_name', item_name,
            'total_stock', total_stock,
            'grn_count', grn_count
        ) ORDER BY total_stock DESC
    ), '[]'::jsonb) INTO v_top_stock_items
    FROM (
        SELECT
            grt.item_name,
            SUM(grt.stock) as total_stock,
            COUNT(DISTINCT gr.id) as grn_count
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND grt.stock > 0
        GROUP BY grt.item_name
        ORDER BY total_stock DESC
        LIMIT 5
    ) top_items;

    -- Aging distribution by bucket
    WITH aging_data AS (
        SELECT
            grt.stock as current_stock,
            (warehouse_security.business_date(now()) - warehouse_security.business_date(gr.date)) as aging_days,
            CASE
                WHEN (warehouse_security.business_date(now()) - warehouse_security.business_date(gr.date)) <= 120 THEN '0-120'
                WHEN (warehouse_security.business_date(now()) - warehouse_security.business_date(gr.date)) <= 240 THEN '121-240'
                WHEN (warehouse_security.business_date(now()) - warehouse_security.business_date(gr.date)) <= 364 THEN '241-364'
                ELSE '364+'
            END as aging_bucket
        FROM goodsreceived gr
        JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_uuid
            AND gr.deleted_at IS NULL
            AND grt.stock > 0
    )
    SELECT jsonb_build_object(
        '0-120', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '0-120'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '0-120'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '0-120') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        ),
        '121-240', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '121-240'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '121-240'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '121-240') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        ),
        '241-364', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '241-364'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '241-364'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '241-364') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        ),
        '364+', jsonb_build_object(
            'item_count', COUNT(*) FILTER (WHERE aging_bucket = '364+'),
            'total_quantity', COALESCE(SUM(current_stock) FILTER (WHERE aging_bucket = '364+'), 0),
            'percentage', CASE WHEN SUM(current_stock) > 0
                THEN ROUND(SUM(current_stock) FILTER (WHERE aging_bucket = '364+') * 100.0 / SUM(current_stock), 1)
                ELSE 0 END
        )
    ) INTO v_by_bucket
    FROM aging_data;

    -- Build final result
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'customer_id', p_customer_uuid,
            'customer_name', v_customer_name,
            'customer_city', v_customer_city,
            'summary', v_summary,
            'monthly_trends', v_monthly_trends,
            'recent_grns', v_recent_grns,
            'recent_dispatches', v_recent_dispatches,
            'top_stock_items', v_top_stock_items,
            'recent_invoices', v_recent_invoices,
            'by_bucket', v_by_bucket
        ),
        'metadata', jsonb_build_object(
            'retrieved_at', NOW(),
            'customer_id', p_customer_uuid,
            'from_date', p_from_date,
            'to_date', p_to_date
        )
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve customer activity detail: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;

ALTER FUNCTION public.get_customer_activity_detail(p_customer_uuid uuid, p_from_date date, p_to_date date) OWNER TO supabase_admin;

--
-- Name: get_customer_dispatch_activity(uuid, date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_dispatch_activity(p_customer_uuid uuid, p_from_date date, p_to_date date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
    v_user_role TEXT;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_customer_dispatch_activity',jsonb_build_object('p_customer_uuid',p_customer_uuid));
    -- Get user role from JWT claims
    v_user_role := COALESCE(warehouse_security.active_role(),
        CASE WHEN auth.jwt() ->> 'role' = 'service_role' THEN 'service_role' ELSE 'none' END);

    -- Check access: admin/supervisor can access all, others only assigned customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff', 'service_role') THEN
        IF NOT EXISTS (
            SELECT 1 FROM unnest(user_accessible_customers()) AS uc(id)
            WHERE uc.id = p_customer_uuid
        ) THEN
            RETURN jsonb_build_object(
                'error', 'Access denied: customer not accessible',
                'summary', NULL,
                'dispatches', '[]'::jsonb
            );
        END IF;
    END IF;

    SELECT jsonb_build_object(
        'summary', (
            SELECT jsonb_build_object(
                'total_dispatches', COUNT(DISTINCT d.id),
                'total_quantity', COALESCE(SUM(dt.disp_qty), 0),
                -- Fixed: weight is per unit, so total = weight × disp_qty
                'total_weight', COALESCE(SUM(gt.weight::numeric * dt.disp_qty), 0)
            )
            FROM dispatch d
            JOIN dispatch_trl dt ON dt.disp_id = d.id
            JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
            WHERE d.customer_id = p_customer_uuid
              AND d.deleted_at IS NULL
              AND d.disp_date >= warehouse_security.business_day_start(p_from_date)
              AND d.disp_date < warehouse_security.business_day_start(p_to_date + 1)
        ),
        'dispatches', COALESCE((
            SELECT jsonb_agg(dispatch_data ORDER BY dispatch_data->>'disp_date' DESC)
            FROM (
                SELECT jsonb_build_object(
                    'disp_id', d.id,
                    'disp_no', d.disp_no,
                    'disp_date', warehouse_security.business_date(d.disp_date),
                    'supervisor_name', d.supervisor_name,
                    'total_qty', (
                        SELECT SUM(dt2.disp_qty)
                        FROM dispatch_trl dt2
                        WHERE dt2.disp_id = d.id
                    ),
                    'total_weight', (
                        SELECT COALESCE(SUM(gt3.weight::numeric * dt3.disp_qty), 0)
                        FROM dispatch_trl dt3
                        JOIN goodsreceived_trl gt3 ON gt3.id = dt3.gr_trl_id
                        JOIN goodsreceived g3 ON g3.id = dt3.gr_id
                        WHERE dt3.disp_id = d.id
                    ),
                    'items', (
                        SELECT jsonb_agg(
                            jsonb_build_object(
                                'item_name', gt.item_name,
                                'qty', dt.disp_qty,
                                'source_grn', g.gr_no,
                                'source_grn_id', g.id,
                                'orig_qty', gt.qty,
                                'package_mark', gt.package_mark,
                                'rack', gt.rack,
                                'weight', COALESCE(gt.weight::numeric * dt.disp_qty, 0)
                            ) ORDER BY gt.item_name
                        )
                        FROM dispatch_trl dt
                        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
                        JOIN goodsreceived g ON g.id = dt.gr_id
                        WHERE dt.disp_id = d.id
                    )
                ) AS dispatch_data
                FROM dispatch d
                WHERE d.customer_id = p_customer_uuid
                  AND d.deleted_at IS NULL
                  AND d.disp_date >= warehouse_security.business_day_start(p_from_date)
                  AND d.disp_date < warehouse_security.business_day_start(p_to_date + 1)
            ) AS dispatches_agg
        ), '[]'::jsonb)
    ) INTO v_result;

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_customer_dispatch_activity(p_customer_uuid uuid, p_from_date date, p_to_date date) OWNER TO supabase_admin;

--
-- Name: get_customer_dispatch_items(uuid, timestamp with time zone, timestamp with time zone, jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_dispatch_items(p_customer_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'grn_gr_no'::text, p_sort_order text DEFAULT 'asc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
    v_total_count integer;
    v_total_initial_qty bigint;
    v_total_dispatch_qty bigint;
    v_total_weight bigint;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_order_direction text;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_customer_dispatch_items',jsonb_build_object('p_customer_id',p_customer_id));
    -- Security: Get user role and verify access
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, check customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

        -- Verify the requested customer is in their assigned list
        IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: You do not have permission to access this customer''s data'
            );
        END IF;
    END IF;

    -- Set order direction
    v_order_direction := CASE WHEN lower(p_sort_order) = 'desc' THEN 'DESC' ELSE 'ASC' END;

    -- Get total count for pagination (snake_case filter keys)
    SELECT COUNT(*) INTO v_total_count
    FROM dispatch_trl dt
    JOIN dispatch d ON dt.disp_id = d.id
    JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
    JOIN goodsreceived gr ON grt.gr_id = gr.id
    WHERE gr.customer_id = p_customer_id
    AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
    AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
    AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
    AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
    AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
    AND (NOT p_filters ? 'qty_min' OR (p_filters->>'qty_min')::integer IS NULL
         OR grt.qty >= (p_filters->>'qty_min')::integer)
    AND (NOT p_filters ? 'qty_max' OR (p_filters->>'qty_max')::integer IS NULL
         OR grt.qty <= (p_filters->>'qty_max')::integer)
    AND (NOT p_filters ? 'disp_qty_min' OR (p_filters->>'disp_qty_min')::integer IS NULL
         OR dt.disp_qty >= (p_filters->>'disp_qty_min')::integer)
    AND (NOT p_filters ? 'disp_qty_max' OR (p_filters->>'disp_qty_max')::integer IS NULL
         OR dt.disp_qty <= (p_filters->>'disp_qty_max')::integer);

    -- Get aggregations
    SELECT
        COALESCE(SUM(grt.qty), 0),
        COALESCE(SUM(dt.disp_qty), 0),
        COALESCE(SUM(grt.weight::numeric * dt.disp_qty), 0)
    INTO
        v_total_initial_qty,
        v_total_dispatch_qty,
        v_total_weight
    FROM dispatch_trl dt
    JOIN dispatch d ON dt.disp_id = d.id
    JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
    JOIN goodsreceived gr ON grt.gr_id = gr.id
    WHERE gr.customer_id = p_customer_id
    AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
    AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
    AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
    AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
    AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
    AND (NOT p_filters ? 'qty_min' OR (p_filters->>'qty_min')::integer IS NULL
         OR grt.qty >= (p_filters->>'qty_min')::integer)
    AND (NOT p_filters ? 'qty_max' OR (p_filters->>'qty_max')::integer IS NULL
         OR grt.qty <= (p_filters->>'qty_max')::integer)
    AND (NOT p_filters ? 'disp_qty_min' OR (p_filters->>'disp_qty_min')::integer IS NULL
         OR dt.disp_qty >= (p_filters->>'disp_qty_min')::integer)
    AND (NOT p_filters ? 'disp_qty_max' OR (p_filters->>'disp_qty_max')::integer IS NULL
         OR dt.disp_qty <= (p_filters->>'disp_qty_max')::integer);

    -- Get paginated items with dynamic sorting (snake_case sort keys and response keys)
    SELECT COALESCE(jsonb_agg(item_row ORDER BY
        CASE WHEN p_sort_by = 'grn_gr_no' AND v_order_direction = 'ASC' THEN grns_gr_no END ASC,
        CASE WHEN p_sort_by = 'grn_gr_no' AND v_order_direction = 'DESC' THEN grns_gr_no END DESC,
        CASE WHEN p_sort_by = 'grn_date' AND v_order_direction = 'ASC' THEN grns_date END ASC,
        CASE WHEN p_sort_by = 'grn_date' AND v_order_direction = 'DESC' THEN grns_date END DESC,
        CASE WHEN p_sort_by = 'item_name' AND v_order_direction = 'ASC' THEN grt_item_name END ASC,
        CASE WHEN p_sort_by = 'item_name' AND v_order_direction = 'DESC' THEN grt_item_name END DESC,
        CASE WHEN p_sort_by = 'disp_no' AND v_order_direction = 'ASC' THEN disp_no END ASC,
        CASE WHEN p_sort_by = 'disp_no' AND v_order_direction = 'DESC' THEN disp_no END DESC,
        CASE WHEN p_sort_by = 'disp_date' AND v_order_direction = 'ASC' THEN disp_date END ASC,
        CASE WHEN p_sort_by = 'disp_date' AND v_order_direction = 'DESC' THEN disp_date END DESC,
        CASE WHEN p_sort_by = 'qty' AND v_order_direction = 'ASC' THEN grt_qty END ASC,
        CASE WHEN p_sort_by = 'qty' AND v_order_direction = 'DESC' THEN grt_qty END DESC,
        CASE WHEN p_sort_by = 'disp_qty' AND v_order_direction = 'ASC' THEN disp_qty END ASC,
        CASE WHEN p_sort_by = 'disp_qty' AND v_order_direction = 'DESC' THEN disp_qty END DESC,
        dispatch_line_id
    ), '[]'::jsonb)
    INTO v_items
    FROM (
        SELECT
            jsonb_build_object(
                'dispatch_id', d.id,
                'disp_no', d.disp_no,
                'disp_date', d.disp_date,
                'disp_qty', dt.disp_qty,
                'grn_id', gr.id,
                'gr_no', gr.gr_no,
                'grn_date', gr.date,
                'grn_item_id', grt.id,
                'item_id', grt.item_id,
                'item_name', grt.item_name,
                'qty', grt.qty,
                'stock', grt.stock,
                'weight', grt.weight,
                'packaging', grt.packaging,
                'package_mark', grt.package_mark,
                'rack', grt.rack
            ) as item_row,
            gr.gr_no as grns_gr_no,
            gr.date as grns_date,
            grt.item_name as grt_item_name,
            d.disp_no as disp_no,
            d.disp_date as disp_date,
            grt.qty as grt_qty,
            dt.disp_qty as disp_qty,
            dt.id as dispatch_line_id
        FROM dispatch_trl dt
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_from IS NULL OR p_date_to IS NULL OR d.disp_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'item_name' OR p_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || (p_filters->>'item_name') || '%')
        AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
        AND (NOT p_filters ? 'disp_no' OR p_filters->>'disp_no' = '' OR d.disp_no ILIKE '%' || (p_filters->>'disp_no') || '%')
        AND (NOT p_filters ? 'package_mark' OR p_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (p_filters->>'package_mark') || '%')
        AND (NOT p_filters ? 'qty_min' OR (p_filters->>'qty_min')::integer IS NULL
             OR grt.qty >= (p_filters->>'qty_min')::integer)
        AND (NOT p_filters ? 'qty_max' OR (p_filters->>'qty_max')::integer IS NULL
             OR grt.qty <= (p_filters->>'qty_max')::integer)
        AND (NOT p_filters ? 'disp_qty_min' OR (p_filters->>'disp_qty_min')::integer IS NULL
             OR dt.disp_qty >= (p_filters->>'disp_qty_min')::integer)
        AND (NOT p_filters ? 'disp_qty_max' OR (p_filters->>'disp_qty_max')::integer IS NULL
             OR dt.disp_qty <= (p_filters->>'disp_qty_max')::integer)
        ORDER BY
            CASE WHEN p_sort_by = 'grn_gr_no' AND v_order_direction = 'ASC' THEN gr.gr_no END ASC,
            CASE WHEN p_sort_by = 'grn_gr_no' AND v_order_direction = 'DESC' THEN gr.gr_no END DESC,
            CASE WHEN p_sort_by = 'grn_date' AND v_order_direction = 'ASC' THEN gr.date END ASC,
            CASE WHEN p_sort_by = 'grn_date' AND v_order_direction = 'DESC' THEN gr.date END DESC,
            CASE WHEN p_sort_by = 'item_name' AND v_order_direction = 'ASC' THEN grt.item_name END ASC,
            CASE WHEN p_sort_by = 'item_name' AND v_order_direction = 'DESC' THEN grt.item_name END DESC,
            CASE WHEN p_sort_by = 'disp_no' AND v_order_direction = 'ASC' THEN d.disp_no END ASC,
            CASE WHEN p_sort_by = 'disp_no' AND v_order_direction = 'DESC' THEN d.disp_no END DESC,
            CASE WHEN p_sort_by = 'disp_date' AND v_order_direction = 'ASC' THEN d.disp_date END ASC,
            CASE WHEN p_sort_by = 'disp_date' AND v_order_direction = 'DESC' THEN d.disp_date END DESC,
            CASE WHEN p_sort_by = 'qty' AND v_order_direction = 'ASC' THEN grt.qty END ASC,
            CASE WHEN p_sort_by = 'qty' AND v_order_direction = 'DESC' THEN grt.qty END DESC,
            CASE WHEN p_sort_by = 'disp_qty' AND v_order_direction = 'ASC' THEN dt.disp_qty END ASC,
            CASE WHEN p_sort_by = 'disp_qty' AND v_order_direction = 'DESC' THEN dt.disp_qty END DESC,
            dt.id
        LIMIT p_limit OFFSET p_offset
    ) sub;

    -- Build final result (snake_case keys)
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', v_items,
            'pagination', jsonb_build_object(
                'total_count', v_total_count,
                'limit', p_limit,
                'offset', p_offset,
                'has_more', (p_offset + p_limit) < v_total_count
            ),
            'aggregations', jsonb_build_object(
                'total_initial_qty', v_total_initial_qty,
                'total_dispatch_qty', v_total_dispatch_qty,
                'total_weight', v_total_weight,
                'record_count', v_total_count
            )
        ),
        'message', null
    );

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_customer_dispatch_items(p_customer_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_filters jsonb, p_sort_by text, p_sort_order text, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_customer_dispatch_list(uuid, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_dispatch_list(p_customer_id uuid, p_limit integer DEFAULT 10, p_offset integer DEFAULT 0, p_include_items boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'warehouse_security', 'pg_temp'
    AS $$
DECLARE
  v_total_count integer;
  v_dispatches jsonb;
BEGIN
  IF p_customer_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Customer ID is required',
      'data', NULL
    );
  END IF;

  IF p_limit < 1 OR p_limit > 100 OR p_offset < 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Invalid pagination',
      'data', NULL
    );
  END IF;

  PERFORM warehouse_security.authorize_rpc(
    'get_customer_dispatch_list',
    jsonb_build_object('p_customer_id', p_customer_id)
  );

  SELECT count(*)
  INTO v_total_count
  FROM public.dispatch d
  WHERE d.customer_id = p_customer_id
    AND d.deleted_at IS NULL;

  WITH paged_dispatches AS (
    SELECT d.*
    FROM public.dispatch d
    WHERE d.customer_id = p_customer_id
      AND d.deleted_at IS NULL
    ORDER BY d.disp_date DESC NULLS LAST, d.created_at DESC, d.id DESC
    LIMIT p_limit OFFSET p_offset
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', d.id,
        'disp_no', d.disp_no,
        'disp_date', d.disp_date,
        'customer_id', d.customer_id,
        'customer_name', d.customer_name,
        'supervisor_id', d.supervisor_id,
        'supervisor_name', d.supervisor_name,
        'registration', d.registration,
        'note', d.note,
        'total_items', COALESCE(lines.total_items, 0),
        'total_qty', COALESCE(lines.total_qty, 0),
        'total_weight', COALESCE(lines.total_weight, 0),
        'items', CASE WHEN p_include_items THEN COALESCE(lines.items, '[]'::jsonb) ELSE NULL END,
        'created_at', d.created_at,
        'updated_at', d.updated_at
      )
      ORDER BY d.disp_date DESC NULLS LAST, d.created_at DESC, d.id DESC
    ),
    '[]'::jsonb
  )
  INTO v_dispatches
  FROM paged_dispatches d
  LEFT JOIN LATERAL (
    SELECT
      count(*)::integer AS total_items,
      COALESCE(sum(dt.disp_qty), 0)::bigint AS total_qty,
      COALESCE(sum(dt.disp_qty * COALESCE(grt.weight, 0)), 0)::bigint AS total_weight,
      jsonb_agg(
        jsonb_build_object(
          'item_id', grt.item_id,
          'item_name', grt.item_name,
          'disp_qty', dt.disp_qty,
          'weight', grt.weight,
          'gr_no', gr.gr_no,
          'grn_qty', grt.qty,
          'grn_item_id', grt.id,
          'package_mark', grt.package_mark,
          'rack', grt.rack
        )
        ORDER BY grt.item_name, grt.id
      ) AS items
    FROM public.dispatch_trl dt
    JOIN public.goodsreceived_trl grt ON grt.id = dt.gr_trl_id
    JOIN public.goodsreceived gr ON gr.id = grt.gr_id
    WHERE dt.disp_id = d.id
  ) lines ON true;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Customer dispatches retrieved successfully',
    'data', jsonb_build_object(
      'dispatches', v_dispatches,
      'pagination', jsonb_build_object(
        'total_count', v_total_count,
        'limit', p_limit,
        'offset', p_offset,
        'has_more', (p_offset + p_limit) < v_total_count
      )
    )
  );
END;
$$;

ALTER FUNCTION public.get_customer_dispatch_list(p_customer_id uuid, p_limit integer, p_offset integer, p_include_items boolean) OWNER TO supabase_admin;

--
-- Name: get_customer_grn_activity(uuid, date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_grn_activity(p_customer_uuid uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_from_date date;
    v_to_date date;
    v_result jsonb;
    v_summary jsonb;
    v_grns jsonb;
    v_by_customer jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_customer_grn_activity',jsonb_build_object('p_customer_uuid',p_customer_uuid));
    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Non-admin/supervisor can only view their own customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        IF p_customer_uuid IS NULL THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'PERMISSION_DENIED: Customer UUID required for non-staff users'
            );
        END IF;

        -- Check if user has access to this customer
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        IF v_user_customer_ids IS NULL OR NOT (p_customer_uuid = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied: You do not have permission to view this customer''s data'
            );
        END IF;
    END IF;

    -- Set date defaults
    v_from_date := COALESCE(p_from_date, warehouse_security.business_date(now()) - INTERVAL '10 days');
    v_to_date := COALESCE(p_to_date, warehouse_security.business_date(now()));

    -- Single customer view
    IF p_customer_uuid IS NOT NULL THEN
        WITH grn_data AS (
            SELECT
                gr.id as grn_id,
                gr.gr_no,
                gr.date as grn_date,
                gr.registration,
                gr.sender_name,
                up.name as supervisor_name,
                gr.note
            FROM goodsreceived gr
            LEFT JOIN user_profiles up ON gr.supervisor_id = up.id
            WHERE gr.customer_id = p_customer_uuid
                AND gr.deleted_at IS NULL
                AND gr.date >= warehouse_security.business_day_start(v_from_date) AND gr.date < warehouse_security.business_day_start(v_to_date + 1)
        ),
        grn_items AS (
            SELECT
                grt.gr_id,
                jsonb_agg(
                    jsonb_build_object(
                        'item_name', grt.item_name,
                        'packaging', grt.packaging,
                        'quantity', grt.qty,
                        'current_stock', grt.stock,
                        'dispatched_qty', grt.qty - grt.stock,
                        'weight', grt.weight,
                        'rack', grt.rack,
                        'package_mark', grt.package_mark
                    )
                ) as items,
                COUNT(*) as item_count,
                SUM(grt.qty) as total_qty,
                COALESCE(SUM(grt.weight::numeric * grt.qty), 0) as total_weight
            FROM goodsreceived_trl grt
            GROUP BY grt.gr_id
        ),
        invoice_status AS (
            SELECT DISTINCT ON (i.gr_id)
                i.gr_id,
                jsonb_build_object(
                    'is_invoiced', true,
                    'invoice_id', i.id,
                    'invoice_number', i.inv_fin_year::text || '-' || i.inv_no::text,
                    'invoice_count', COUNT(*) OVER (PARTITION BY i.gr_id)
                ) as status
            FROM invoice i
            WHERE i.deleted_at IS NULL
            ORDER BY i.gr_id, i.inv_date DESC, i.inv_fin_year DESC, i.inv_no DESC, i.id DESC
        ),
        dispatch_summary AS (
            SELECT
                dt.gr_trl_id,
                SUM(dt.disp_qty) as total_dispatched,
                COUNT(DISTINCT d.id) as dispatch_count,
                MAX(d.disp_date) as last_dispatch_date
            FROM dispatch_trl dt
            JOIN dispatch d ON dt.disp_id = d.id
            WHERE d.deleted_at IS NULL
            GROUP BY dt.gr_trl_id
        ),
        grn_dispatch_summary AS (
            SELECT
                grt.gr_id,
                COALESCE(SUM(ds.total_dispatched), 0) as total_dispatched,
                SUM(grt.stock) as current_stock,
                MAX(COALESCE(ds.dispatch_count, 0)) as dispatch_count,
                MAX(ds.last_dispatch_date) as last_dispatch_date,
                CASE WHEN SUM(grt.stock) = 0 THEN true ELSE false END as is_fully_dispatched
            FROM goodsreceived_trl grt
            LEFT JOIN dispatch_summary ds ON grt.id = ds.gr_trl_id
            GROUP BY grt.gr_id
        ),
        image_counts AS (
            SELECT
                grn_id,
                COUNT(*) as image_count
            FROM grn_images
            WHERE warehouse_security.grn_image_visible(grn_images.status, grn_images.uploaded_by)
            GROUP BY grn_id
        ),
        grn_full AS (
            SELECT
                gd.grn_id,
                gd.gr_no,
                gd.grn_date,
                gd.registration,
                gd.sender_name,
                gd.supervisor_name,
                gd.note,
                COALESCE(gi.item_count, 0) as total_items,
                COALESCE(gi.total_qty, 0) as total_qty,
                COALESCE(gi.total_weight, 0) as total_weight,
                COALESCE(ic.image_count, 0) as image_count,
                COALESCE(inv.status, jsonb_build_object('is_invoiced', false, 'invoice_id', null, 'invoice_number', null, 'invoice_count', 0)) as invoice_status,
                jsonb_build_object(
                    'total_dispatched', COALESCE(gds.total_dispatched, 0),
                    'current_stock', COALESCE(gds.current_stock, 0),
                    'dispatch_count', COALESCE(gds.dispatch_count, 0),
                    'last_dispatch_date', gds.last_dispatch_date,
                    'is_fully_dispatched', COALESCE(gds.is_fully_dispatched, false)
                ) as dispatch_summary,
                COALESCE(gi.items, '[]'::jsonb) as items
            FROM grn_data gd
            LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id
            LEFT JOIN invoice_status inv ON gd.grn_id = inv.gr_id
            LEFT JOIN grn_dispatch_summary gds ON gd.grn_id = gds.gr_id
            LEFT JOIN image_counts ic ON gd.grn_id = ic.grn_id
        )
        SELECT
            jsonb_build_object(
                'total_grns', COUNT(*),
                'total_items', COALESCE(SUM(total_items), 0),
                'total_quantity', COALESCE(SUM(total_qty), 0),
                'total_weight_kg', COALESCE(SUM(total_weight), 0),
                'total_invoiced_grns', COUNT(*) FILTER (WHERE (invoice_status->>'is_invoiced')::boolean = true),
                'total_images', COALESCE(SUM(image_count), 0)
            ),
            COALESCE(jsonb_agg(
                jsonb_build_object(
                    'grn_id', grn_id,
                    'gr_no', gr_no,
                    'grn_date', grn_date,
                    'registration', registration,
                    'sender_name', sender_name,
                    'supervisor_name', supervisor_name,
                    'note', note,
                    'total_items', total_items,
                    'total_qty', total_qty,
                    'total_weight', total_weight,
                    'image_count', image_count,
                    'invoice_status', invoice_status,
                    'dispatch_summary', dispatch_summary,
                    'items', items
                ) ORDER BY grn_date DESC
            ), '[]'::jsonb)
        INTO v_summary, v_grns
        FROM grn_full;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'grns', v_grns
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'customer_id', p_customer_uuid,
                'from_date', v_from_date,
                'to_date', v_to_date
            )
        );

    -- All customers view (staff only)
    ELSE
        WITH grn_data AS (
            SELECT
                gr.id as grn_id,
                gr.customer_id,
                c.name as customer_name,
                gr.date as grn_date
            FROM goodsreceived gr
            JOIN customers c ON gr.customer_id = c.id
            WHERE gr.deleted_at IS NULL
                AND gr.date >= warehouse_security.business_day_start(v_from_date) AND gr.date < warehouse_security.business_day_start(v_to_date + 1)
        ),
        grn_items AS (
            SELECT
                grt.gr_id,
                SUM(grt.qty) as total_qty,
                COALESCE(SUM(grt.weight::numeric * grt.qty), 0) as total_weight
            FROM goodsreceived_trl grt
            GROUP BY grt.gr_id
        ),
        customer_aggregates AS (
            SELECT
                gd.customer_id,
                gd.customer_name,
                COUNT(DISTINCT gd.grn_id) as grn_count,
                COALESCE(SUM(gi.total_qty), 0) as total_quantity,
                COALESCE(SUM(gi.total_weight), 0) as total_weight,
                MAX(gd.grn_date) as latest_grn_date
            FROM grn_data gd
            LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id
            GROUP BY gd.customer_id, gd.customer_name
        )
        SELECT
            jsonb_build_object(
                'total_grns', (SELECT COUNT(DISTINCT grn_id) FROM grn_data),
                'total_customers', (SELECT COUNT(DISTINCT customer_id) FROM grn_data),
                'total_items', COALESCE((SELECT SUM(gi.total_qty) FROM grn_data gd LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id), 0),
                'total_quantity', COALESCE((SELECT SUM(gi.total_qty) FROM grn_data gd LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id), 0),
                'total_weight_kg', COALESCE((SELECT SUM(gi.total_weight) FROM grn_data gd LEFT JOIN grn_items gi ON gd.grn_id = gi.gr_id), 0)
            ),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'customer_id', customer_id,
                        'customer_name', customer_name,
                        'grn_count', grn_count,
                        'total_quantity', total_quantity,
                        'total_weight', total_weight,
                        'latest_grn_date', latest_grn_date
                    ) ORDER BY grn_count DESC
                )
                FROM customer_aggregates
            ), '[]'::jsonb)
        INTO v_summary, v_by_customer;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'by_customer', v_by_customer
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'from_date', v_from_date,
                'to_date', v_to_date
            )
        );
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve GRN activity: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;

ALTER FUNCTION public.get_customer_grn_activity(p_customer_uuid uuid, p_from_date date, p_to_date date) OWNER TO supabase_admin;

--
-- Name: get_customer_grn_items(uuid, timestamp with time zone, timestamp with time zone, jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_grn_items(p_customer_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'warehouse_security', 'pg_temp'
    AS $$
DECLARE
  v_filters jsonb := COALESCE(p_filters, '{}'::jsonb);
  v_receipt boolean := COALESCE(v_filters->>'page_by', '') = 'receipt';
  v_total_count integer;
  v_total_qty bigint;
  v_total_stock bigint;
  v_items jsonb;
BEGIN
  IF p_customer_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Customer ID is required', 'data', NULL);
  END IF;

  IF p_limit < 1 OR p_limit > 100 OR p_offset < 0
     OR p_sort_by NOT IN ('date', 'gr_no', 'customer_name', 'item_name', 'qty', 'stock')
     OR (v_receipt AND p_sort_by NOT IN ('date', 'gr_no', 'customer_name'))
     OR p_sort_order NOT IN ('asc', 'desc') THEN
    RETURN jsonb_build_object('success', false, 'message', 'Invalid list parameters', 'data', NULL);
  END IF;

  PERFORM warehouse_security.authorize_rpc(
    'get_customer_grn_items',
    jsonb_build_object('p_customer_id', p_customer_id)
  );

  WITH filtered AS (
    SELECT
      grt.id,
      grt.gr_id,
      grt.item_id,
      grt.item_name,
      grt.qty,
      grt.stock,
      grt.weight,
      grt.rack,
      grt.package_mark,
      grt.packaging,
      gr.gr_no,
      gr.date,
      gr.customer_name,
      gr.customer_id,
      gr.registration,
      gr.supervisor_name,
      gr.sender_name,
      gr.invoiced,
      gr.leon,
      gr.out_of_stock,
      gr.note,
      gr.gr_image_url
    FROM public.goodsreceived_trl grt
    JOIN public.goodsreceived gr ON gr.id = grt.gr_id
    WHERE gr.customer_id = p_customer_id
      AND gr.deleted_at IS NULL
      AND (p_date_from IS NULL OR gr.date >= p_date_from)
      AND (p_date_to IS NULL OR gr.date <= p_date_to)
      AND (NOT (v_filters ? 'item_name') OR v_filters->>'item_name' = '' OR grt.item_name ILIKE '%' || warehouse_security.like_literal(v_filters->>'item_name') || '%')
      AND (NOT (v_filters ? 'customer_name') OR v_filters->>'customer_name' = '' OR gr.customer_name ILIKE '%' || warehouse_security.like_literal(v_filters->>'customer_name') || '%')
      AND (NOT (v_filters ? 'gr_no') OR v_filters->>'gr_no' = '' OR gr.gr_no ILIKE '%' || warehouse_security.like_literal(v_filters->>'gr_no') || '%')
      AND (NOT (v_filters ? 'package_mark') OR v_filters->>'package_mark' = '' OR grt.package_mark ILIKE '%' || warehouse_security.like_literal(v_filters->>'package_mark') || '%')
      AND (NOT (v_filters ? 'rack') OR v_filters->>'rack' = '' OR grt.rack ILIKE '%' || warehouse_security.like_literal(v_filters->>'rack') || '%')
      AND (NOT (v_filters ? 'gr_no_from') OR v_filters->>'gr_no_from' = '' OR (warehouse_security.document_number_sort_key(gr.gr_no) COLLATE "C") >= (warehouse_security.document_number_sort_key(v_filters->>'gr_no_from') COLLATE "C"))
      AND (NOT (v_filters ? 'gr_no_to') OR v_filters->>'gr_no_to' = '' OR (warehouse_security.document_number_sort_key(gr.gr_no) COLLATE "C") <= (warehouse_security.document_number_sort_key(v_filters->>'gr_no_to') COLLATE "C"))
      AND NOT EXISTS (SELECT 1 FROM unnest(warehouse_security.search_terms(v_filters->>'search')) AS term
        WHERE NOT (gr.gr_no ILIKE term OR COALESCE(gr.customer_name, '') ILIKE term OR COALESCE(grt.item_name, '') ILIKE term
          OR COALESCE(grt.package_mark, '') ILIKE term OR COALESCE(grt.rack, '') ILIKE term OR COALESCE(gr.registration, '') ILIKE term))
      AND (
        jsonb_typeof(v_filters->'item_ids') IS DISTINCT FROM 'array'
        OR jsonb_array_length(v_filters->'item_ids') = 0
        OR grt.item_id::text IN (SELECT jsonb_array_elements_text(v_filters->'item_ids'))
      )
      AND (
        jsonb_typeof(v_filters->'grn_ids') IS DISTINCT FROM 'array'
        OR jsonb_array_length(v_filters->'grn_ids') = 0
        OR gr.id::text IN (SELECT jsonb_array_elements_text(v_filters->'grn_ids'))
      )
      AND (
        NOT (v_filters ? 'stock_status')
        OR v_filters->>'stock_status' = 'all'
        OR (v_filters->>'stock_status' = 'in_stock' AND grt.stock > 0)
        OR (v_filters->>'stock_status' = 'out_of_stock' AND grt.stock = 0)
        OR (v_filters->>'stock_status' = 'low_stock' AND grt.stock > 0 AND grt.stock < 0.2 * grt.qty)
      )
      AND (
        NOT (v_filters ? 'weight_min')
        OR (jsonb_typeof(v_filters->'weight_min') = 'number' AND grt.weight >= (v_filters->>'weight_min')::numeric)
      )
      AND (
        NOT (v_filters ? 'weight_max')
        OR (jsonb_typeof(v_filters->'weight_max') = 'number' AND grt.weight <= (v_filters->>'weight_max')::numeric)
      )
  ), ordered AS (
    SELECT filtered.*,
      row_number() OVER (ORDER BY
        CASE WHEN p_sort_by = 'date' AND p_sort_order = 'desc' THEN date END DESC NULLS LAST,
        CASE WHEN p_sort_by = 'date' AND p_sort_order = 'asc' THEN date END ASC NULLS LAST,
        CASE WHEN p_sort_by = 'gr_no' AND p_sort_order = 'desc' THEN warehouse_security.document_number_sort_key(gr_no) COLLATE "C" END DESC,
        CASE WHEN p_sort_by = 'gr_no' AND p_sort_order = 'asc' THEN warehouse_security.document_number_sort_key(gr_no) COLLATE "C" END ASC,
        CASE WHEN p_sort_by = 'customer_name' AND p_sort_order = 'desc' THEN customer_name END DESC,
        CASE WHEN p_sort_by = 'customer_name' AND p_sort_order = 'asc' THEN customer_name END ASC,
        CASE WHEN p_sort_by = 'item_name' AND p_sort_order = 'desc' THEN item_name END DESC,
        CASE WHEN p_sort_by = 'item_name' AND p_sort_order = 'asc' THEN item_name END ASC,
        CASE WHEN p_sort_by = 'qty' AND p_sort_order = 'desc' THEN qty END DESC,
        CASE WHEN p_sort_by = 'qty' AND p_sort_order = 'asc' THEN qty END ASC,
        CASE WHEN p_sort_by = 'stock' AND p_sort_order = 'desc' THEN stock END DESC,
        CASE WHEN p_sort_by = 'stock' AND p_sort_order = 'asc' THEN stock END ASC,
        CASE WHEN v_receipt THEN gr_no END,
        id
      ) AS row_num
    FROM filtered
  ), stats AS (
    SELECT (CASE WHEN v_receipt THEN count(DISTINCT gr_id) ELSE count(*) END)::integer AS total_count,
      COALESCE(sum(qty), 0)::bigint AS total_qty,
      COALESCE(sum(stock), 0)::bigint AS total_stock
    FROM filtered
  ), receipts AS (
    SELECT gr_id, row_number() OVER (ORDER BY min(row_num)) AS receipt_no
    FROM ordered
    GROUP BY gr_id
  ), page AS (
    SELECT ordered.* FROM ordered
    JOIN receipts ON receipts.gr_id = ordered.gr_id
    WHERE (CASE WHEN v_receipt THEN receipts.receipt_no ELSE ordered.row_num END) > p_offset
      AND (CASE WHEN v_receipt THEN receipts.receipt_no ELSE ordered.row_num END) <= p_offset + p_limit
  )
  SELECT
    stats.total_count,
    stats.total_qty,
    stats.total_stock,
    COALESCE(
      jsonb_agg(
        jsonb_build_object(
          'id', page.id,
          'grn_item_id', page.id,
          'grn_id', page.gr_id,
          'gr_no', page.gr_no,
          'item_id', page.item_id,
          'item_name', page.item_name,
          'qty', page.qty,
          'stock', page.stock,
          'weight', page.weight,
          'rack', page.rack,
          'package_mark', page.package_mark,
          'packaging', page.packaging,
          'date', page.date,
          'grns_id', page.gr_id,
          'grns_gr_no', page.gr_no,
          'grns_date', page.date,
          'customer_name', page.customer_name,
          'customer_id', page.customer_id,
          'registration', page.registration,
          'supervisor_name', page.supervisor_name,
          'sender_name', page.sender_name,
          'invoiced', page.invoiced,
          'leon', page.leon,
          'out_of_stock', page.out_of_stock,
          'note', page.note,
          'image_url', page.gr_image_url
        ) ORDER BY page.row_num
      ) FILTER (WHERE page.id IS NOT NULL),
      '[]'::jsonb
    )
  INTO v_total_count, v_total_qty, v_total_stock, v_items
  FROM stats
  LEFT JOIN page ON true
  GROUP BY stats.total_count, stats.total_qty, stats.total_stock;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Customer GRN items retrieved successfully',
    'data', jsonb_build_object(
      'items', v_items,
      'pagination', jsonb_build_object(
        'total', v_total_count,
        'total_count', v_total_count,
        'limit', p_limit,
        'offset', p_offset,
        'has_more', (p_offset + p_limit) < v_total_count,
        'unit', CASE WHEN v_receipt THEN 'receipt' ELSE 'line' END
      ),
      'aggregations', jsonb_build_object(
        'total_qty', v_total_qty,
        'total_stock', v_total_stock,
        'total_count', v_total_count
      )
    )
  );
END;
$$;

ALTER FUNCTION public.get_customer_grn_items(p_customer_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_filters jsonb, p_sort_by text, p_sort_order text, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_customer_grns_with_stock_dispatch_sorted(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_grns_with_stock_dispatch_sorted(p_customer_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_role text;
    v_user_customer_ids uuid[];
    v_is_superuser boolean;
    v_result jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_customer_grns_with_stock_dispatch_sorted',jsonb_build_object('p_customer_id',p_customer_id));
    -- Validate required parameter
    IF p_customer_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', null,
            'message', 'p_customer_id is required'
        );
    END IF;

    -- Normalize pagination
    IF p_limit IS NULL OR p_limit < 1 THEN
        p_limit := 20;
    ELSIF p_limit > 100 THEN
        p_limit := 100;
    END IF;

    IF p_offset IS NULL OR p_offset < 0 THEN
        p_offset := 0;
    END IF;

    -- Check if running as superuser (for testing)
    SELECT current_user = 'postgres' INTO v_is_superuser;

    -- Security: Get user role (skip if superuser)
    IF NOT v_is_superuser THEN
        SELECT role INTO v_user_role FROM user_profiles
        WHERE auth_user_id = auth.uid();

        -- If user is not admin/supervisor, verify customer access
        IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
            v_user_customer_ids := user_accessible_customers();

            -- Check if user has access to this customer
            IF NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'data', null,
                    'message', 'Access denied'
                );
            END IF;
        END IF;
    END IF;

    -- Get GRNs with stock sorted by last dispatch
    SELECT jsonb_agg(row_data ORDER BY (row_data->>'last_dispatch_date') DESC NULLS LAST, (row_data->>'grn_date') DESC)
    INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'grn_id', gs.id,
            'gr_no', gs.gr_no,
            'grn_date', gs.date,
            'customer_name', gs.customer_name,
            'total_stock', gs.total_stock,
            'item_count', gs.item_count,
            'last_dispatch_date', (
                SELECT MAX(d.disp_date)
                FROM dispatch_trl dt
                JOIN dispatch d ON dt.disp_id = d.id AND d.deleted_at IS NULL
                WHERE dt.gr_id = gs.id
            )
        ) as row_data
        FROM (
            SELECT
                gr.id,
                gr.gr_no,
                gr.date,
                gr.customer_name,
                SUM(grt.stock)::INTEGER as total_stock,
                COUNT(grt.id)::INTEGER as item_count
            FROM goodsreceived gr
            JOIN goodsreceived_trl grt ON gr.id = grt.gr_id AND grt.stock > 0
            WHERE gr.customer_id = p_customer_id
              AND gr.deleted_at IS NULL
            GROUP BY gr.id, gr.gr_no, gr.date, gr.customer_name
        ) gs
        LIMIT p_limit
        OFFSET p_offset
    ) sub;

    RETURN jsonb_build_object(
        'success', true,
        'data', COALESCE(v_result, '[]'::jsonb)
    );
END;
$$;

ALTER FUNCTION public.get_customer_grns_with_stock_dispatch_sorted(p_customer_id uuid, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_customer_invoice_summary(uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_invoice_summary(p_customer_uuid uuid DEFAULT NULL::uuid, p_from_date date DEFAULT NULL::date, p_to_date date DEFAULT NULL::date, p_financial_year integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_from_date date;
    v_to_date date;
    v_result jsonb;
    v_summary jsonb;
    v_invoices jsonb;
    v_by_month jsonb;
    v_by_customer jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_customer_invoice_summary',jsonb_build_object('p_customer_uuid',p_customer_uuid));
    -- Get caller's role
    IF auth.uid() IS NOT NULL THEN
        SELECT id, role INTO v_user_id, v_user_role
        FROM user_profiles
        WHERE auth_user_id = auth.uid();
    END IF;

    -- Access control
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required'
        );
    END IF;

    -- Non-admin/supervisor: get accessible customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = v_user_id;

        -- If no customers assigned, return empty
        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            RETURN jsonb_build_object(
                'success', true,
                'data', jsonb_build_object(
                    'summary', jsonb_build_object(
                        'total_invoices', 0,
                        'total_amount', 0,
                        'net_amount', 0
                    ),
                    'invoices', '[]'::jsonb,
                    'by_month', '[]'::jsonb
                ),
                'metadata', jsonb_build_object('retrieved_at', NOW())
            );
        END IF;

        -- If specific customer requested, verify access
        IF p_customer_uuid IS NOT NULL AND NOT (p_customer_uuid = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'error', 'Access denied: You do not have permission to view this customer''s data'
            );
        END IF;
    END IF;

    -- Set date defaults
    v_from_date := COALESCE(p_from_date, warehouse_security.business_date(now()) - INTERVAL '30 days');
    v_to_date := COALESCE(p_to_date, warehouse_security.business_date(now()));

    -- Single customer view
    IF p_customer_uuid IS NOT NULL THEN
        WITH invoice_data AS (
            SELECT
                i.id as invoice_id,
                i.inv_fin_year::text || '-' || LPAD(i.inv_no::text, GREATEST(4, LENGTH(i.inv_no::text)), '0') as invoice_number,
                i.inv_fin_year,
                i.inv_no,
                i.inv_date,
                i.gr_id,
                gr.gr_no as grn_ref,
                i.total,
                i.labour,
                i.discount,
                i.tax_amount,
                COALESCE(i.total, 0) as net_total,
                i.notes
            FROM invoice i
            LEFT JOIN goodsreceived gr ON i.gr_id = gr.id
            WHERE i.customer_id = p_customer_uuid
                AND i.deleted_at IS NULL
                AND (p_financial_year IS NULL OR i.inv_fin_year = p_financial_year)
                AND i.inv_date >= warehouse_security.business_day_start(v_from_date) AND i.inv_date < warehouse_security.business_day_start(v_to_date + 1)
        ),
        invoice_items AS (
            SELECT
                it.invoice_id,
                COUNT(*) as item_count,
                SUM(dt.disp_qty) as total_quantity,
                jsonb_agg(
                    jsonb_build_object(
                        'item_id', grt.item_id,
                        'item_name', grt.item_name,
                        'packaging', grt.packaging,
                        'quantity', dt.disp_qty,
                        'rate', it.charge,
                        'no_of_days', it.no_of_days,
                        'charge', it.charge,
                        'labour_rate', it.labour_rate,
                        'labour_amount', amount.labour,
                        'tax_percent', it.tax,
                        'tax_amount', ROUND(amount.base * COALESCE(it.tax, 0)::numeric / 100, 2),
                        'line_total', amount.base + ROUND(amount.base * COALESCE(it.tax, 0)::numeric / 100, 2),
                        'grn_item_ref', jsonb_build_object(
                            'gr_no', gr.gr_no,
                            'rack', grt.rack,
                            'package_mark', grt.package_mark
                        )
                    )
                ) as line_items
            FROM invoice_trl it
            JOIN dispatch_trl dt ON it.disp_trl_id = dt.id
            JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            -- The line amount of get_invoice_items_detailed; labour is 0 for a ONE_TIME receipt.
            CROSS JOIN LATERAL (
                SELECT CASE WHEN gr.pricing_mode = 'ONE_TIME'
                            THEN ROUND(COALESCE(it.charge, 0)::numeric * COALESCE(dt.disp_qty, 0)::numeric, 2)
                            ELSE ROUND(COALESCE(it.charge, 0)::numeric * COALESCE(dt.disp_qty, 0)::numeric * COALESCE(it.duration, 1)::numeric, 2)
                                 + ROUND(COALESCE(it.labour_rate, 0)::numeric * COALESCE(dt.disp_qty, 0)::numeric, 2)
                            END AS base,
                       CASE WHEN gr.pricing_mode = 'ONE_TIME' THEN 0::numeric
                            ELSE ROUND(COALESCE(it.labour_rate, 0)::numeric * COALESCE(dt.disp_qty, 0)::numeric, 2) END AS labour
            ) AS amount
            GROUP BY it.invoice_id
        ),
        payment_status AS (
            SELECT DISTINCT ON (p.invoice_id)
                p.invoice_id,
                jsonb_build_object(
                    'status', 'paid',
                    'paid_date', p.payment_date,
                    'payment_ref', COALESCE(p.cheque_no, p.online_ref, p.payment_no),
                    'amount', SUM(p.amount) OVER (PARTITION BY p.invoice_id),
                    'payment_mode', p.payment_mode
                ) as status,
                SUM(p.amount) OVER (PARTITION BY p.invoice_id) as paid_sum
            FROM payments p
            WHERE p.invoice_id IS NOT NULL
            ORDER BY p.invoice_id, p.payment_date DESC, p.payment_no DESC
        ),
        invoices_full AS (
            SELECT
                id.invoice_id,
                id.invoice_number,
                id.inv_fin_year::text || '-' || (id.inv_fin_year + 1)::text as financial_year,
                id.inv_date as invoice_date,
                id.gr_id as grn_id,
                id.grn_ref,
                id.total,
                id.labour,
                id.discount,
                id.tax_amount,
                id.net_total,
                COALESCE(ii.item_count, 0) as item_count,
                COALESCE(ii.total_quantity, 0) as total_quantity,
                id.notes,
                jsonb_set(
                    COALESCE(ps.status, jsonb_build_object('status', 'pending', 'paid_date', null, 'payment_ref', null)),
                    '{status}',
                    CASE WHEN bal.balance <= 0.50 THEN to_jsonb('paid'::text) ELSE to_jsonb('pending'::text) END
                ) as payment_status,
                rcv.received as received_amount,
                bal.balance as balance_amount,
                COALESCE(ii.line_items, '[]'::jsonb) as line_items
            FROM invoice_data id
            LEFT JOIN invoice_items ii ON id.invoice_id = ii.invoice_id
            LEFT JOIN payment_status ps ON id.invoice_id = ps.invoice_id
            CROSS JOIN LATERAL (SELECT GREATEST(0, LEAST(COALESCE(ps.paid_sum, 0), COALESCE(id.total, 0))) AS received) rcv
            CROSS JOIN LATERAL (SELECT COALESCE(id.total, 0) - rcv.received AS balance) bal
        ),
        monthly_breakdown AS (
            SELECT
                TO_CHAR(warehouse_security.business_date(invoice_date), 'YYYY-MM') as month,
                COUNT(*) as invoice_count,
                SUM(total) as total_amount,
                SUM(received_amount) as paid_amount,
                SUM(balance_amount) as pending_amount
            FROM invoices_full
            GROUP BY TO_CHAR(warehouse_security.business_date(invoice_date), 'YYYY-MM')
            ORDER BY month DESC
        )
        SELECT
            jsonb_build_object(
                'total_invoices', (SELECT COUNT(*) FROM invoices_full),
                'total_amount', COALESCE((SELECT SUM(total) FROM invoices_full), 0),
                'total_labour', COALESCE((SELECT SUM(labour) FROM invoices_full), 0),
                'total_tax', COALESCE((SELECT SUM(tax_amount) FROM invoices_full), 0),
                'total_discount', COALESCE((SELECT SUM(discount) FROM invoices_full), 0),
                'net_amount', COALESCE((SELECT SUM(net_total) FROM invoices_full), 0),
                'paid_count', (SELECT COUNT(*) FROM invoices_full WHERE (payment_status->>'status') = 'paid'),
                'pending_count', (SELECT COUNT(*) FROM invoices_full WHERE (payment_status->>'status') = 'pending'),
                'paid_amount', COALESCE((SELECT SUM(received_amount) FROM invoices_full), 0),
                'pending_amount', COALESCE((SELECT SUM(balance_amount) FROM invoices_full), 0)
            ),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'invoice_id', invoice_id,
                        'invoice_number', invoice_number,
                        'invoice_date', invoice_date,
                        'financial_year', financial_year,
                        'grn_ref', grn_ref,
                        'grn_id', grn_id,
                        'total', total,
                        'labour', labour,
                        'discount', discount,
                        'tax_amount', tax_amount,
                        'net_total', net_total,
                        'item_count', item_count,
                        'total_quantity', total_quantity,
                        'notes', notes,
                        'payment_status', payment_status,
                        'paid_amount', received_amount,
                        'balance_amount', balance_amount,
                        'line_items', line_items
                    ) ORDER BY invoice_date DESC, invoice_number DESC
                )
                FROM invoices_full
            ), '[]'::jsonb),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'month', month,
                        'invoice_count', invoice_count,
                        'total_amount', total_amount,
                        'paid_amount', paid_amount,
                        'pending_amount', pending_amount
                    )
                )
                FROM monthly_breakdown
            ), '[]'::jsonb)
        INTO v_summary, v_invoices, v_by_month;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'invoices', v_invoices,
                'by_month', v_by_month
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'customer_id', p_customer_uuid,
                'from_date', v_from_date,
                'to_date', v_to_date,
                'financial_year', p_financial_year
            )
        );

    -- All customers view (filtered by accessible customers for non-staff)
    ELSE
        WITH invoice_data AS (
            SELECT
                i.id as invoice_id,
                i.customer_id,
                c.name as customer_name,
                i.inv_date,
                i.total,
                i.labour,
                i.discount,
                i.tax_amount,
                COALESCE(i.total, 0) as net_total
            FROM invoice i
            JOIN customers c ON i.customer_id = c.id
            WHERE i.deleted_at IS NULL
                AND (p_financial_year IS NULL OR i.inv_fin_year = p_financial_year)
                AND i.inv_date >= warehouse_security.business_day_start(v_from_date) AND i.inv_date < warehouse_security.business_day_start(v_to_date + 1)
                AND (v_user_role IN ('admin', 'supervisor', 'staff') OR i.customer_id = ANY(v_user_customer_ids))
        ),
        customer_aggregates AS (
            SELECT
                customer_id,
                customer_name,
                COUNT(*) as invoice_count,
                SUM(total) as total_amount,
                SUM(net_total) as net_amount,
                MAX(inv_date) as latest_invoice_date
            FROM invoice_data
            GROUP BY customer_id, customer_name
        ),
        monthly_breakdown AS (
            SELECT
                TO_CHAR(warehouse_security.business_date(inv_date), 'YYYY-MM') as month,
                COUNT(*) as invoice_count,
                SUM(total) as total_amount
            FROM invoice_data
            GROUP BY TO_CHAR(warehouse_security.business_date(inv_date), 'YYYY-MM')
            ORDER BY month DESC
        )
        SELECT
            jsonb_build_object(
                'total_invoices', (SELECT COUNT(*) FROM invoice_data),
                'total_customers', (SELECT COUNT(DISTINCT customer_id) FROM invoice_data),
                'total_amount', COALESCE((SELECT SUM(total) FROM invoice_data), 0),
                'total_tax', COALESCE((SELECT SUM(tax_amount) FROM invoice_data), 0),
                'net_amount', COALESCE((SELECT SUM(net_total) FROM invoice_data), 0)
            ),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'customer_id', customer_id,
                        'customer_name', customer_name,
                        'invoice_count', invoice_count,
                        'total_amount', total_amount,
                        'net_amount', net_amount,
                        'latest_invoice_date', latest_invoice_date
                    ) ORDER BY total_amount DESC
                )
                FROM customer_aggregates
            ), '[]'::jsonb),
            COALESCE((
                SELECT jsonb_agg(
                    jsonb_build_object(
                        'month', month,
                        'invoice_count', invoice_count,
                        'total_amount', total_amount
                    )
                )
                FROM monthly_breakdown
            ), '[]'::jsonb)
        INTO v_summary, v_by_customer, v_by_month;

        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'summary', v_summary,
                'by_customer', v_by_customer,
                'by_month', v_by_month
            ),
            'metadata', jsonb_build_object(
                'retrieved_at', NOW(),
                'from_date', v_from_date,
                'to_date', v_to_date,
                'financial_year', p_financial_year
            )
        );
    END IF;

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Failed to retrieve invoice summary: ' || SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;

ALTER FUNCTION public.get_customer_invoice_summary(p_customer_uuid uuid, p_from_date date, p_to_date date, p_financial_year integer) OWNER TO supabase_admin;

--
-- Name: get_customer_invoices(uuid, timestamp with time zone, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_invoices(p_customer_id uuid, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
    DECLARE
        v_result jsonb;
        v_total_amount numeric;
        v_total_tax numeric;
        v_total_discount numeric;
        v_total_labour numeric;
        v_invoice_count integer;
        v_invoices jsonb;
        v_user_role text;
        v_user_customer_ids uuid[];
    BEGIN
        -- Security: Get user role and verify access
        SELECT role INTO v_user_role FROM user_profiles
        WHERE auth_user_id = auth.uid();

        -- If user is not admin/supervisor, check customer access
        IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
            SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
            FROM users_customers_new
            WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

            -- Verify the requested customer is in their assigned list
            IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'data', null,
                    'message', 'Access denied: You do not have permission to access this customer''s data'
                );
            END IF;
        END IF;

        -- Get aggregations (snake_case filter keys)
        SELECT
            COALESCE(SUM(i.total), 0),
            COALESCE(SUM(i.tax_amount), 0),
            COALESCE(SUM(i.discount), 0),
            COALESCE(SUM(i.labour), 0),
            COUNT(*)
        INTO v_total_amount, v_total_tax, v_total_discount, v_total_labour, v_invoice_count
        FROM invoice i
        WHERE i.customer_id = p_customer_id
        AND (p_date_from IS NULL OR p_date_to IS NULL OR i.inv_date BETWEEN p_date_from AND p_date_to)
        AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR i.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
        AND (NOT p_filters ? 'invoice_no' OR p_filters->>'invoice_no' = '' OR CONCAT(i.inv_fin_year, '-', i.inv_no) ILIKE '%' || (p_filters->>'invoice_no') || '%');

        -- Get main data (snake_case response keys)
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', sub.id,
                'invoice_no', sub.invoice_no,
                'invoice_date', sub.inv_date,
                'amount', sub.total,
                'customer_name', sub.customer_name,
                'grn_id', sub.gr_id,
                'grn_no', sub.gr_no,
                'discount', sub.discount,
                'labour', sub.labour,
                'tax_amount', sub.tax_amount,
                'total', sub.total
            )
        ) INTO v_invoices
        FROM (
            SELECT
                i.id,
                CONCAT(i.inv_fin_year, '-', i.inv_no) as invoice_no,
                i.inv_date,
                i.total,
                i.customer_name,
                i.gr_id,
                i.gr_no,
                i.discount,
                i.labour,
                i.tax_amount
            FROM invoice i
            WHERE i.customer_id = p_customer_id
            AND (p_date_from IS NULL OR p_date_to IS NULL OR i.inv_date BETWEEN p_date_from AND p_date_to)
            AND (NOT p_filters ? 'gr_no' OR p_filters->>'gr_no' = '' OR i.gr_no ILIKE '%' || (p_filters->>'gr_no') || '%')
            AND (NOT p_filters ? 'invoice_no' OR p_filters->>'invoice_no' = '' OR CONCAT(i.inv_fin_year, '-', i.inv_no) ILIKE '%' || (p_filters->>'invoice_no') || '%')
            ORDER BY i.inv_date DESC
        ) sub;

        -- Build final result (snake_case aggregation keys)
        v_result := jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'invoices', COALESCE(v_invoices, '[]'::jsonb),
                'aggregations', jsonb_build_object(
                    'total_amount', v_total_amount,
                    'total_tax', v_total_tax,
                    'total_discount', v_total_discount,
                    'total_labour', v_total_labour,
                    'invoice_count', v_invoice_count
                )
            ),
            'message', 'Customer invoices retrieved successfully'
        );

        RETURN v_result;

    EXCEPTION
        WHEN OTHERS THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', NULL,
                'message', 'Error retrieving customer invoices: ' || SQLERRM
            );
    END;
$$;

ALTER FUNCTION public.get_customer_invoices(p_customer_id uuid, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_filters jsonb) OWNER TO supabase_admin;

--
-- Name: get_customer_items_for_order_selection(uuid, integer, integer, text, integer, character varying); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_items_for_order_selection(p_customer_id uuid, p_page_size integer DEFAULT 500, p_offset integer DEFAULT 0, p_search_term text DEFAULT NULL::text, p_stock_filter_min integer DEFAULT 1, p_grn_no_filter character varying DEFAULT NULL::character varying) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_items jsonb;
    v_total_count bigint;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_customer_items_for_order_selection',jsonb_build_object('p_customer_id',p_customer_id));
    WITH filtered_items AS (
        SELECT
            gt.id as grn_item_id,
            gr.id as grn_id,
            gr.gr_no,
            i.id as item_id,
            i.name as item_name,
            gt.package_mark,
            i.packaging,
            gt.rack,
            gt.stock,
            gt.qty,
            gt.weight,
            (SELECT storage_path FROM grn_images gi WHERE gi.grn_id = gr.id AND warehouse_security.grn_image_visible(gi.status, gi.uploaded_by) LIMIT 1) as image_url,
            gr.customer_id,
            c.name as customer_name,
            gr.date
        FROM goodsreceived_trl gt
        JOIN goodsreceived gr ON gt.gr_id = gr.id
        JOIN items i ON gt.item_id = i.id
        JOIN customers c ON gr.customer_id = c.id
        WHERE gr.customer_id = p_customer_id
          AND gt.stock >= p_stock_filter_min
          AND gr.deleted_at IS NULL
          AND (p_search_term IS NULL OR i.name ILIKE '%' || p_search_term || '%')
          AND (p_grn_no_filter IS NULL OR gr.gr_no ILIKE '%' || p_grn_no_filter || '%')
        ORDER BY gr.date DESC, i.name
        LIMIT p_page_size OFFSET p_offset
    )
    SELECT COALESCE(jsonb_agg(row_to_json(fi)::jsonb), '[]'::jsonb)
    INTO v_items
    FROM filtered_items fi;

    SELECT COUNT(*) INTO v_total_count
    FROM goodsreceived_trl gt
    JOIN goodsreceived gr ON gt.gr_id = gr.id
    WHERE gr.customer_id = p_customer_id
      AND gt.stock >= p_stock_filter_min
      AND gr.deleted_at IS NULL
      AND (p_search_term IS NULL OR EXISTS(SELECT 1 FROM items i WHERE i.id = gt.item_id AND i.name ILIKE '%' || p_search_term || '%'))
      AND (p_grn_no_filter IS NULL OR gr.gr_no ILIKE '%' || p_grn_no_filter || '%');

    RETURN utils.success_response_paginated(v_items, v_total_count, p_page_size, p_offset);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get customer items for order', SQLERRM, SQLSTATE);
END;
$$;

ALTER FUNCTION public.get_customer_items_for_order_selection(p_customer_id uuid, p_page_size integer, p_offset integer, p_search_term text, p_stock_filter_min integer, p_grn_no_filter character varying) OWNER TO supabase_admin;

--
-- Name: get_customer_stock_analysis(uuid, timestamp with time zone, jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_stock_analysis(p_customer_id uuid, p_date_filter timestamp with time zone DEFAULT NULL::timestamp with time zone, p_item_filter jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_grn_qty bigint;
    v_total_dispatch_qty bigint;
    v_total_calculated_stock bigint;
    v_item_count integer;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_items_with_negative_stock integer;
BEGIN
    -- Security: Get user role and verify access
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, check customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

        -- Verify the requested customer is in their assigned list
        IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: You do not have permission to access this customer''s data'
            );
        END IF;
    END IF;

    -- Time-traveling inventory calculation
    WITH grn_data AS (
        -- Sum all GRN quantities up to the specified date
        SELECT
            grt.item_id,
            SUM(grt.qty) as total_grn_qty
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR gr.date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    dispatch_data AS (
        -- Sum all dispatch quantities up to the specified date
        -- CRITICAL: Use dispatch date, not GRN date
        SELECT
            grt.item_id,
            SUM(dt.disp_qty) as total_dispatch_qty
        FROM dispatch_trl dt
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR d.disp_date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    stock_calculation AS (
        -- Calculate stock as GRN minus Dispatch for each item
        SELECT
            i.id as item_id,
            i.name as item_name,
            i.packaging,
            i.description,
            COALESCE(grn.total_grn_qty, 0) as grn_qty,
            COALESCE(disp.total_dispatch_qty, 0) as dispatch_qty,
            COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) as calculated_stock
        FROM items i
        LEFT JOIN grn_data grn ON i.id = grn.item_id
        LEFT JOIN dispatch_data disp ON i.id = disp.item_id
        WHERE i.active = true
        AND (grn.item_id IS NOT NULL OR disp.item_id IS NOT NULL)
        AND (NOT p_item_filter ? 'item_name' OR p_item_filter->>'item_name' = ''
             OR i.name ILIKE '%' || (p_item_filter->>'item_name') || '%')
        AND (NOT p_item_filter ? 'item_id' OR p_item_filter->>'item_id' = ''
             OR i.id = (p_item_filter->>'item_id')::uuid)
    )
    -- Final aggregation and result building
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'item_id', sc.item_id,
                'item_name', sc.item_name,
                'packaging', sc.packaging,
                'description', sc.description,
                'total_grn_qty', sc.grn_qty,
                'total_dispatch_qty', sc.dispatch_qty,
                'calculated_stock', sc.calculated_stock,
                'has_negative_stock', sc.calculated_stock < 0,
                -- Include date context in response
                'as_of_date', COALESCE(p_date_filter, NOW())
            ) ORDER BY sc.item_name
        ),
        COALESCE(SUM(sc.grn_qty), 0),
        COALESCE(SUM(sc.dispatch_qty), 0),
        COALESCE(SUM(sc.calculated_stock), 0),
        COUNT(*),
        COUNT(*) FILTER (WHERE sc.calculated_stock < 0)
    INTO v_items, v_total_grn_qty, v_total_dispatch_qty, v_total_calculated_stock, v_item_count, v_items_with_negative_stock
    FROM stock_calculation sc;

    -- Build final result
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_items, '[]'::jsonb),
            'aggregations', jsonb_build_object(
                'total_grn_qty', v_total_grn_qty,
                'total_dispatch_qty', v_total_dispatch_qty,
                'calculated_stock', v_total_calculated_stock,
                'item_count', v_item_count,
                'items_with_negative_stock', v_items_with_negative_stock,
                'as_of_date', COALESCE(p_date_filter, NOW()),
                'has_data_integrity_issues', v_items_with_negative_stock > 0
            )
        ),
        'message', CASE
            WHEN p_date_filter IS NOT NULL THEN
                'Historical stock analysis as of ' || to_char(p_date_filter, 'YYYY-MM-DD') || ' retrieved successfully'
            ELSE
                'Current stock analysis retrieved successfully'
        END
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Error retrieving customer stock analysis: ' || SQLERRM
        );
END;
$$;

ALTER FUNCTION public.get_customer_stock_analysis(p_customer_id uuid, p_date_filter timestamp with time zone, p_item_filter jsonb) OWNER TO supabase_admin;

--
-- Name: get_customer_stock_analysis(uuid, timestamp with time zone, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_customer_stock_analysis(p_customer_id uuid, p_date_filter timestamp with time zone DEFAULT NULL::timestamp with time zone, p_item_filter jsonb DEFAULT '{}'::jsonb, p_in_stock_only boolean DEFAULT NULL::boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_grn_qty bigint;
    v_total_dispatch_qty bigint;
    v_total_calculated_stock bigint;
    v_item_count integer;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_items_with_negative_stock integer;
BEGIN
    -- Security: Get user role and verify access
    SELECT role INTO v_user_role FROM user_profiles
    WHERE auth_user_id = auth.uid();

    -- If user is not admin/supervisor, check customer access
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());

        -- Verify the requested customer is in their assigned list
        IF v_user_customer_ids IS NULL OR NOT (p_customer_id = ANY(v_user_customer_ids)) THEN
            RETURN jsonb_build_object(
                'success', false,
                'data', null,
                'message', 'Access denied: You do not have permission to access this customer''s data'
            );
        END IF;
    END IF;

    -- Time-traveling inventory calculation
    WITH grn_data AS (
        -- Sum all GRN quantities up to the specified date
        SELECT
            grt.item_id,
            SUM(grt.qty) as total_grn_qty
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR gr.date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    dispatch_data AS (
        -- Sum all dispatch quantities up to the specified date
        -- CRITICAL: Use dispatch date, not GRN date
        SELECT
            grt.item_id,
            SUM(dt.disp_qty) as total_dispatch_qty
        FROM dispatch_trl dt
        JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
        JOIN dispatch d ON dt.disp_id = d.id
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE gr.customer_id = p_customer_id
        AND (p_date_filter IS NULL OR d.disp_date <= p_date_filter)
        GROUP BY grt.item_id
    ),
    stock_calculation AS (
        -- Calculate stock as GRN minus Dispatch for each item
        SELECT
            i.id as item_id,
            i.name as item_name,
            i.packaging,
            i.description,
            COALESCE(grn.total_grn_qty, 0) as grn_qty,
            COALESCE(disp.total_dispatch_qty, 0) as dispatch_qty,
            COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) as calculated_stock
        FROM items i
        LEFT JOIN grn_data grn ON i.id = grn.item_id
        LEFT JOIN dispatch_data disp ON i.id = disp.item_id
        WHERE i.active = true
        AND (grn.item_id IS NOT NULL OR disp.item_id IS NOT NULL)
        AND (NOT p_item_filter ? 'item_name' OR p_item_filter->>'item_name' = ''
             OR i.name ILIKE '%' || (p_item_filter->>'item_name') || '%')
        AND (NOT p_item_filter ? 'item_id' OR p_item_filter->>'item_id' = ''
             OR i.id = (p_item_filter->>'item_id')::uuid)
        -- NEW: In-stock filter
        AND (p_in_stock_only IS NULL OR
             (p_in_stock_only = true AND
              COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) > 0) OR
             (p_in_stock_only = false))
    )
    -- Final aggregation and result building
    SELECT
        jsonb_agg(
            jsonb_build_object(
                'item_id', sc.item_id,
                'item_name', sc.item_name,
                'packaging', sc.packaging,
                'description', sc.description,
                'total_grn_qty', sc.grn_qty,
                'total_dispatch_qty', sc.dispatch_qty,
                'calculated_stock', sc.calculated_stock,
                'has_negative_stock', sc.calculated_stock < 0,
                -- Include date context in response
                'as_of_date', COALESCE(p_date_filter, NOW())
            ) ORDER BY sc.item_name
        ),
        COALESCE(SUM(sc.grn_qty), 0),
        COALESCE(SUM(sc.dispatch_qty), 0),
        COALESCE(SUM(sc.calculated_stock), 0),
        COUNT(*),
        COUNT(*) FILTER (WHERE sc.calculated_stock < 0)
    INTO v_items, v_total_grn_qty, v_total_dispatch_qty, v_total_calculated_stock, v_item_count, v_items_with_negative_stock
    FROM stock_calculation sc;

    -- Build final result
    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_items, '[]'::jsonb),
            'aggregations', jsonb_build_object(
                'total_grn_qty', v_total_grn_qty,
                'total_dispatch_qty', v_total_dispatch_qty,
                'calculated_stock', v_total_calculated_stock,
                'item_count', v_item_count,
                'items_with_negative_stock', v_items_with_negative_stock,
                'as_of_date', COALESCE(p_date_filter, NOW()),
                'has_data_integrity_issues', v_items_with_negative_stock > 0
            )
        ),
        'message', CASE
            WHEN p_date_filter IS NOT NULL THEN
                'Historical stock analysis as of ' || to_char(p_date_filter, 'YYYY-MM-DD') || ' retrieved successfully'
            ELSE
                'Current stock analysis retrieved successfully'
        END
    );

    RETURN v_result;

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'data', NULL,
            'message', 'Error retrieving customer stock analysis: ' || SQLERRM
        );
END;
$$;

