--
-- Name: get_invoice_items_detailed(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_invoice_items_detailed(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
  v_items jsonb;
  v_summary jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc(
    'get_invoice_items_detailed',
    jsonb_build_object('p_invoice_id', p_invoice_id)
  );

  IF NOT EXISTS (
    SELECT 1
    FROM public.invoice i
    WHERE i.id = p_invoice_id
      AND i.deleted_at IS NULL
  ) THEN
    RETURN utils.not_found_response('Invoice', p_invoice_id::text);
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', line.id,
        'item_id', line.catalog_item_id,
        'duration', line.duration,
        'no_of_days', line.no_of_days,
        'charge', line.charge_rate,
        'labour_rate', line.labour_rate,
        'tax', line.tax_rate,
        'tax_amount', line.tax_amount,
        'total_amount', line.total_amount,
        'dispatch_qty', line.dispatch_qty,
        'grn_quantity', line.grn_quantity,
        'item_name', line.item_name,
        'gr_no', line.gr_no,
        'dispatch_id', line.dispatch_id,
        'dispatch_no', line.dispatch_no,
        'dispatch_date', line.dispatch_date,
        'package_mark', line.package_mark,
        'rack', line.rack,
        'weight', line.weight,
        'packaging', line.catalog_packaging,
        'catalog', jsonb_build_object(
          'id', line.catalog_item_id,
          'name', line.catalog_name,
          'packaging', line.catalog_packaging
        ),
        'grn_item', jsonb_build_object(
          'id', line.grn_item_id,
          'name', line.item_name,
          'original_quantity', line.grn_quantity,
          'package_mark', line.package_mark,
          'rack', line.rack,
          'weight', line.weight,
          'packaging', line.grn_packaging
        ),
        'dispatch', jsonb_build_object(
          'id', line.dispatch_item_id,
          'disp_id', line.dispatch_id,
          'dispatch_no', line.dispatch_no,
          'dispatch_date', line.dispatch_date,
          'quantity', line.dispatch_qty
        )
      )
      ORDER BY line.dispatch_no, line.id
    ),
    '[]'::jsonb
  ),
  jsonb_build_object(
    'total_items', COUNT(*),
    'total_quantity', COALESCE(SUM(line.dispatch_qty), 0),
    'total_amount', COALESCE(ROUND(SUM(line.total_amount), 2), 0)
  )
  INTO v_items, v_summary
  FROM (
    SELECT
      it.id,
      it.duration,
      it.no_of_days,
      COALESCE(it.charge, 0)::numeric AS charge_rate,
      COALESCE(it.labour_rate, 0)::numeric AS labour_rate,
      COALESCE(it.tax, 0)::numeric AS tax_rate,
      COALESCE(dt.disp_qty, 0)::numeric AS dispatch_qty,
      ROUND(amount.base * COALESCE(it.tax, 0)::numeric / 100, 2) AS tax_amount,
      amount.base + ROUND(amount.base * COALESCE(it.tax, 0)::numeric / 100, 2) AS total_amount,
      dt.id AS dispatch_item_id,
      d.id AS dispatch_id,
      d.disp_no AS dispatch_no,
      d.disp_date AS dispatch_date,
      gr.id AS grn_id,
      gr.gr_no,
      grt.id AS grn_item_id,
      grt.item_id AS catalog_item_id,
      grt.item_name,
      grt.qty AS grn_quantity,
      grt.package_mark,
      grt.rack,
      grt.weight,
      grt.packaging AS grn_packaging,
      catalog.name AS catalog_name,
      catalog.packaging AS catalog_packaging
    FROM public.invoice_trl it
    JOIN public.dispatch_trl dt ON dt.id = it.disp_trl_id
    JOIN public.dispatch d ON d.id = dt.disp_id
    JOIN public.goodsreceived gr ON gr.id = dt.gr_id
    JOIN public.goodsreceived_trl grt ON grt.id = dt.gr_trl_id
    JOIN public.items catalog ON catalog.id = grt.item_id
    CROSS JOIN LATERAL (
      SELECT CASE WHEN gr.pricing_mode = 'ONE_TIME'
        THEN ROUND(COALESCE(it.charge, 0)::numeric * COALESCE(dt.disp_qty, 0)::numeric, 2)
        ELSE ROUND(COALESCE(it.charge, 0)::numeric * COALESCE(dt.disp_qty, 0)::numeric * COALESCE(it.duration, 1)::numeric, 2)
             + ROUND(COALESCE(it.labour_rate, 0)::numeric * COALESCE(dt.disp_qty, 0)::numeric, 2)
        END AS base
    ) AS amount
    WHERE it.invoice_id = p_invoice_id
  ) AS line;

  RETURN utils.success_response(
    jsonb_build_object('items', v_items, 'summary', v_summary),
    'Invoice items retrieved successfully'
  );
END;
$$;

ALTER FUNCTION public.get_invoice_items_detailed(p_invoice_id uuid) OWNER TO supabase_admin;

--
-- Name: get_invoice_range_for_print(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_invoice_range_for_print(start_inv_no_str text, end_inv_no_str text, inv_fin_year integer DEFAULT NULL::integer, limit_count integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_result jsonb;
    start_inv_no integer;
    end_inv_no integer;
    target_fin_year integer;
BEGIN
    start_inv_no := CASE
        WHEN start_inv_no_str ~ '^[0-9]+$' THEN start_inv_no_str::integer
        ELSE REGEXP_REPLACE(start_inv_no_str, '[^0-9]', '', 'g')::integer
    END;

    end_inv_no := CASE
        WHEN end_inv_no_str ~ '^[0-9]+$' THEN end_inv_no_str::integer
        ELSE REGEXP_REPLACE(end_inv_no_str, '[^0-9]', '', 'g')::integer
    END;

    target_fin_year := COALESCE(get_invoice_range_for_print.inv_fin_year, EXTRACT(YEAR FROM CURRENT_DATE)::integer);

    WITH invoice_data AS (
        SELECT
            i.id as invoice_id,
            i.inv_fin_year,
            i.inv_no,
            'INV' || LPAD(i.inv_no::text, 3, '0') as inv_no_str,
            i.gr_id,
            i.gr_no,
            i.customer_id,
            i.customer_name,
            i.inv_name,
            TO_CHAR(i.inv_date, 'YYYY-MM-DD') as formatted_inv_date,
            COALESCE(i.one_time_charge, false) as one_time_charge,
            COALESCE(i.duration_mode, 'legacy') as duration_mode,
            COALESCE(i.labour, 0)::double precision as labour,
            COALESCE(i.tax_amount, 0)::double precision as tax_amount,
            COALESCE(i.total, 0)::double precision as total,
            COALESCE(i.discount, 0)::double precision as discount,
            i.created_by
        FROM invoice i
        WHERE i.inv_no >= start_inv_no
          AND i.inv_no <= end_inv_no
          AND (get_invoice_range_for_print.inv_fin_year IS NULL OR i.inv_fin_year = target_fin_year)
        ORDER BY i.inv_fin_year, i.inv_no
        LIMIT get_invoice_range_for_print.limit_count
    ),
    invoice_with_customer AS (
        SELECT id.*, c.address, c.city, c.mobile, c.gst as gstin
        FROM invoice_data id
        LEFT JOIN customers c ON c.id = id.customer_id::uuid
    ),
    invoice_with_items AS (
        SELECT
            iwc.*,
            jsonb_agg(
                jsonb_build_object(
                    'id', it.id::text,
                    'invoice_id', it.invoice_id::text,
                    'duration_mode', iwc.duration_mode,
                    'charge', COALESCE(it.charge, 0),
                    'dispatches_items_disp_qty', COALESCE(dt.disp_qty, 0),
                    'dispatches_items_id', dt.id::text,
                    'dispatches_customer_id', d.customer_id::text,
                    'dispatches_customer_name', d.customer_name,
                    'dispatches_date', TO_CHAR(d.disp_date, 'YYYY-MM-DD'),
                    'dispatches_id', d.id::text,
                    'dispatches_image_url', d.disp_image_url,
                    'dispatches_no', d.disp_no,
                    'dispatches_note', d.note,
                    'dispatches_registration', d.registration,
                    'dispatches_supervisor_id', d.supervisor_id::text,
                    'dispatches_supervisor_name', d.supervisor_name,
                    'duration', COALESCE(it.duration, 0),
                    'grn_items_id', grt.id::text,
                    'grn_items_image_url', grt.trl_img_url,
                    'grn_items_item_id', grt.item_id::text,
                    'grn_items_item_name', grt.item_name,
                    'grn_items_package_mark', grt.package_mark,
                    'grn_items_packaging', grt.packaging,
                    'grn_items_quantity', COALESCE(grt.qty, 0),
                    'grn_items_rack', grt.rack,
                    'grn_items_stock', COALESCE(grt.stock, 0),
                    'grn_items_weight', COALESCE(grt.weight, 0),
                    'grns_customer_id', gr.customer_id::text,
                    'grns_customer_name', gr.customer_name,
                    'grns_date', TO_CHAR(gr.date, 'YYYY-MM-DD'),
                    'grns_gr_no', gr.gr_no,
                    'grns_id', gr.id::text,
                    'grns_image_url', gr.gr_image_url,
                    'grns_invoiced', COALESCE(gr.invoiced, false),
                    'grns_leon', COALESCE(gr.leon, false),
                    'grns_note', gr.note,
                    'grns_out_of_stock', COALESCE(gr.out_of_stock, false),
                    'grns_registration', gr.registration,
                    'grns_sender_id', gr.sender_id::text,
                    'grns_sender_name', gr.sender_name,
                    'grns_supervisor_id', gr.supervisor_id::text,
                    'grns_supervisor_name', gr.supervisor_name,
                    'inv_fin_year', iwc.inv_fin_year,
                    'inv_no', iwc.inv_no,
                    'no_of_days', COALESCE(it.no_of_days, 0),
                    'tax', COALESCE(it.tax, 0),
                    'inv_item_charge', COALESCE(it.charge, 0),
                    'pricing_mode', gr.pricing_mode,
                    'storage_amount', CASE WHEN gr.pricing_mode = 'ONE_TIME'
                        THEN round(COALESCE(it.charge, 0) * dt.disp_qty, 2)
                        ELSE round(COALESCE(it.charge, 0) * dt.disp_qty * COALESCE(it.duration, 1), 2) END,
                    'labour_amount', CASE WHEN gr.pricing_mode = 'ONE_TIME'
                        THEN 0::numeric
                        ELSE round(COALESCE(it.labour_rate, 0) * dt.disp_qty, 2) END
                ) ORDER BY it.id
            ) FILTER (WHERE it.id IS NOT NULL) as trl_data,
            SUM(COALESCE(it.charge, 0))::double precision as total_inv_item_charges,
            SUM(COALESCE(dt.disp_qty, 0))::integer as total_disp_qty,
            SUM(COALESCE(grt.qty, 0))::integer as total_gr_qty
        FROM invoice_with_customer iwc
        LEFT JOIN invoice_trl it ON it.invoice_id = iwc.invoice_id
        LEFT JOIN dispatch_trl dt ON dt.id = it.disp_trl_id
        LEFT JOIN dispatch d ON d.id = dt.disp_id
        LEFT JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
        LEFT JOIN goodsreceived gr ON gr.id = grt.gr_id
        GROUP BY
            iwc.invoice_id, iwc.inv_fin_year, iwc.inv_no, iwc.inv_no_str, iwc.gr_id, iwc.gr_no,
            iwc.customer_id, iwc.customer_name, iwc.inv_name, iwc.formatted_inv_date,
            iwc.one_time_charge, iwc.duration_mode, iwc.labour, iwc.tax_amount, iwc.total, iwc.discount,
            iwc.address, iwc.city, iwc.mobile, iwc.gstin, iwc.created_by
    ),
    final_result AS (
        SELECT jsonb_agg(
            jsonb_build_object(
                'id', iwi.invoice_id,
                'created_by', iwi.created_by,
                'customer_id', iwi.customer_id,
                'customer_name', iwi.customer_name,
                'gr_id', iwi.gr_id,
                'gr_no', iwi.gr_no,
                'inv_date', iwi.formatted_inv_date,
                'inv_fin_year', iwi.inv_fin_year,
                'inv_name', iwi.inv_name,
                'inv_no', iwi.inv_no,
                'inv_no_str', iwi.inv_no_str,
                'duration_mode', iwi.duration_mode,
                'labour', iwi.labour,
                'discount', iwi.discount,
                'one_time_charge', iwi.one_time_charge,
                'tax_amount', iwi.tax_amount,
                'total', iwi.total,
                'address', iwi.address,
                'city', iwi.city,
                'mobile', iwi.mobile,
                'gstin', iwi.gstin,
                'trl', COALESCE(iwi.trl_data, '[]'::jsonb),
                'inwords', convert_number_to_words(COALESCE(iwi.total, 0)::integer),
                'total_inv_item_charges', COALESCE(iwi.total_inv_item_charges, 0),
                'total_disp_qty', COALESCE(iwi.total_disp_qty, 0),
                'total_gr_qty', COALESCE(iwi.total_gr_qty, 0),
                'total_labour_amount', COALESCE(iwi.labour * iwi.total_disp_qty, 0)
            ) ORDER BY iwi.inv_fin_year, iwi.inv_no
        ) as data
        FROM invoice_with_items iwi
    )
    SELECT COALESCE(data, '[]'::jsonb) INTO v_result FROM final_result;

    RETURN utils.success_response(v_result, NULL);
END;
$_$;

ALTER FUNCTION public.get_invoice_range_for_print(start_inv_no_str text, end_inv_no_str text, inv_fin_year integer, limit_count integer) OWNER TO supabase_admin;

--
-- Name: get_invoiceable_grns(integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_invoiceable_grns(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0) RETURNS TABLE(grn_id uuid, gr_no character varying, gr_date timestamp with time zone, customer_id uuid, customer_name character varying, supervisor_id uuid, supervisor_name character varying, sender_id uuid, sender_name character varying, registration character varying, note character varying, leon boolean, gr_image_url character varying, created_by uuid, updated_by uuid, created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_invoiceable_grns',jsonb_build_object());
      RETURN QUERY
      SELECT
          g.id as grn_id,
          g.gr_no,
          g.date as gr_date,
          g.customer_id,
          g.customer_name,
          g.supervisor_id,
          g.supervisor_name,
          g.sender_id,
          g.sender_name,
          g.registration,
          g.note,
          g.leon,
          g.gr_image_url,
          g.created_by,
          g.updated_by,
          g.created_at,
          g.updated_at
      FROM goodsreceived g
      WHERE g.out_of_stock = true
        AND g.invoiced = false
        AND (
          -- If not authenticated (superuser), show all
          auth.uid() IS NULL
          OR
          -- If authenticated, apply access control
          g.customer_id = ANY (
            CASE
              WHEN warehouse_security.active_role() IN ('admin','supervisor','staff') THEN
                (SELECT array_agg(customers.id) FROM customers)
              ELSE
                user_accessible_customers()
            END
          )
        )
      ORDER BY g.date DESC, g.created_at DESC
      LIMIT p_limit
      OFFSET p_offset;
  END;
  $$;

ALTER FUNCTION public.get_invoiceable_grns(p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_invoiceable_grns(integer, integer, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_invoiceable_grns(p_limit integer DEFAULT 100, p_offset integer DEFAULT 0, p_search_grn_no text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_grns jsonb;
    v_total_count bigint;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_invoiceable_grns',jsonb_build_object());
    SELECT COALESCE(jsonb_agg(grn_data), '[]'::jsonb)
    INTO v_grns
    FROM (
        SELECT jsonb_build_object(
            'grn_id', gr.id,
            'gr_no', gr.gr_no,
            'gr_date', gr.date,
            'customer_id', gr.customer_id,
            'customer_name', gr.customer_name,
            'supervisor_id', gr.supervisor_id,
            'supervisor_name', gr.supervisor_name,
            'sender_id', gr.sender_id,
            'sender_name', gr.sender_name,
            'registration', gr.registration,
            'note', gr.note,
            'leon', gr.leon,
            'gr_image_url', (SELECT storage_path FROM grn_images WHERE grn_id = gr.id AND image_type = 'header' AND warehouse_security.grn_image_visible(grn_images.status, grn_images.uploaded_by) LIMIT 1),
            'created_by', gr.created_by,
            'updated_by', gr.updated_by,
            'created_at', gr.created_at,
            'updated_at', gr.updated_at
        ) as grn_data
        FROM goodsreceived gr
        WHERE gr.deleted_at IS NULL
          AND gr.out_of_stock = true
          AND gr.invoiced = false
          AND (p_search_grn_no IS NULL OR gr.gr_no ILIKE '%' || p_search_grn_no || '%')
        ORDER BY gr.date DESC
        LIMIT p_limit OFFSET p_offset
    ) sub;

    SELECT COUNT(*) INTO v_total_count
    FROM goodsreceived gr
    WHERE gr.deleted_at IS NULL
      AND gr.out_of_stock = true
      AND gr.invoiced = false
      AND (p_search_grn_no IS NULL OR gr.gr_no ILIKE '%' || p_search_grn_no || '%');

    RETURN utils.success_response_paginated(v_grns, v_total_count, p_limit, p_offset);
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to get invoiceable GRNs', SQLERRM, SQLSTATE);
END;
$$;

ALTER FUNCTION public.get_invoiceable_grns(p_limit integer, p_offset integer, p_search_grn_no text) OWNER TO supabase_admin;

--
-- Name: get_invoices_list(integer, integer, uuid, integer, text, text, text, text, integer, integer, text, timestamp with time zone, timestamp with time zone, uuid[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_invoices_list(p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_customer_id uuid DEFAULT NULL::uuid, p_financial_year integer DEFAULT NULL::integer, p_search_invoice_no text DEFAULT NULL::text, p_search_grn_no text DEFAULT NULL::text, p_sort_field text DEFAULT 'inv_date'::text, p_sort_direction text DEFAULT 'desc'::text, p_inv_no_from integer DEFAULT NULL::integer, p_inv_no_to integer DEFAULT NULL::integer, p_search text DEFAULT NULL::text, p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_customer_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_role text;
    v_all_customers boolean := false;
    v_accessible_customers uuid[] := ARRAY[]::uuid[];
    v_total_count integer;
    v_data jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_invoices_list',jsonb_build_object('p_customer_id',p_customer_id));
    -- Which customers the caller may see: administrators, supervisors and staff see every customer that is
    -- not deleted; other roles see the customers assigned to them; nobody signed in sees nothing.
    IF auth.uid() IS NOT NULL THEN
        SELECT role INTO v_user_role
        FROM public.user_profiles
        WHERE auth_user_id = auth.uid();

        IF v_user_role IN ('admin', 'supervisor', 'staff') THEN
            v_all_customers := true;
        ELSE
            SELECT public.user_accessible_customers() INTO v_accessible_customers;
        END IF;
    END IF;

    WITH f AS MATERIALIZED (
        -- The filtered set: once, for the page and for the count.
        SELECT i.id AS invoice_id, i.inv_no, i.inv_fin_year, i.inv_date, i.total,
               c.name AS customer_name, gr.gr_no
        FROM public.invoice i
        JOIN public.customers c ON c.id = i.customer_id
        JOIN public.goodsreceived gr ON gr.id = i.gr_id
        WHERE i.deleted_at IS NULL
            AND (CASE WHEN v_all_customers THEN c.deleted_at IS NULL ELSE c.id = ANY(v_accessible_customers) END)
            AND (p_customer_id IS NULL OR c.id = p_customer_id)
            AND (p_financial_year IS NULL OR i.inv_fin_year = p_financial_year)
            AND (p_search_invoice_no IS NULL OR p_search_invoice_no = '' OR i.inv_no::text ILIKE '%' || p_search_invoice_no || '%')
            AND (p_search_grn_no IS NULL OR p_search_grn_no = '' OR gr.gr_no ILIKE '%' || p_search_grn_no || '%')
            AND (p_inv_no_from IS NULL OR i.inv_no >= p_inv_no_from)
            AND (p_inv_no_to IS NULL OR i.inv_no <= p_inv_no_to)
            AND (p_date_from IS NULL OR i.inv_date >= p_date_from)
            AND (p_date_to IS NULL OR i.inv_date <= p_date_to)
            AND (p_customer_ids IS NULL OR cardinality(p_customer_ids) = 0 OR c.id = ANY(p_customer_ids))
            AND NOT EXISTS (SELECT 1 FROM unnest(warehouse_security.search_terms(p_search)) AS term
              WHERE NOT (i.inv_no::text ILIKE term OR COALESCE(c.name, '') ILIKE term OR COALESCE(gr.gr_no, '') ILIKE term
                OR (i.inv_fin_year::text || '-' || i.inv_no::text) ILIKE term
                OR (i.inv_fin_year::text || '-' || lpad(i.inv_no::text, GREATEST(4, LENGTH(i.inv_no::text)), '0')) ILIKE term))
    ), pg AS MATERIALIZED (
        -- The rows of the page, in the requested order; ord keeps that order for the answer.
        SELECT s.invoice_id, row_number() OVER () AS ord
        FROM (
            SELECT m.invoice_id
            FROM f m
            ORDER BY
                -- inv_date sorting with secondary sort by inv_no DESC
                CASE WHEN p_sort_field = 'inv_date' AND p_sort_direction = 'desc' THEN m.inv_date END DESC,
                CASE WHEN p_sort_field = 'inv_date' AND p_sort_direction = 'asc' THEN m.inv_date END ASC,
                CASE WHEN p_sort_field = 'inv_date' THEN m.inv_no END DESC,
                -- inv_no sorting (invoice number)
                CASE WHEN p_sort_field = 'inv_no' AND p_sort_direction = 'desc' THEN m.inv_no END DESC,
                CASE WHEN p_sort_field = 'inv_no' AND p_sort_direction = 'asc' THEN m.inv_no END ASC,
                -- invoice_number alias (same as inv_no)
                CASE WHEN p_sort_field = 'invoice_number' AND p_sort_direction = 'desc' THEN m.inv_no END DESC,
                CASE WHEN p_sort_field = 'invoice_number' AND p_sort_direction = 'asc' THEN m.inv_no END ASC,
                -- customer_name sorting with secondary sort by inv_date DESC, inv_no DESC
                CASE WHEN p_sort_field = 'customer_name' AND p_sort_direction = 'desc' THEN m.customer_name END DESC,
                CASE WHEN p_sort_field = 'customer_name' AND p_sort_direction = 'asc' THEN m.customer_name END ASC,
                CASE WHEN p_sort_field = 'customer_name' THEN m.inv_date END DESC,
                CASE WHEN p_sort_field = 'customer_name' THEN m.inv_no END DESC,
                -- grn_number / gr_no sorting
                CASE WHEN p_sort_field IN ('grn_number', 'gr_no') AND p_sort_direction = 'desc' THEN m.gr_no END DESC,
                CASE WHEN p_sort_field IN ('grn_number', 'gr_no') AND p_sort_direction = 'asc' THEN m.gr_no END ASC,
                -- total sorting
                CASE WHEN p_sort_field = 'total' AND p_sort_direction = 'desc' THEN m.total END DESC,
                CASE WHEN p_sort_field = 'total' AND p_sort_direction = 'asc' THEN m.total END ASC,
                -- financial_year sorting with secondary sort by inv_no DESC
                CASE WHEN p_sort_field = 'financial_year' AND p_sort_direction = 'desc' THEN m.inv_fin_year END DESC,
                CASE WHEN p_sort_field = 'financial_year' AND p_sort_direction = 'asc' THEN m.inv_fin_year END ASC,
                CASE WHEN p_sort_field = 'financial_year' THEN m.inv_no END DESC,
                -- Default fallback: inv_date DESC, inv_no DESC
                m.inv_date DESC,
                m.inv_no DESC,
                -- Migration 106: rows that tie on every key above keep one fixed order.
                m.invoice_id
            LIMIT p_limit OFFSET p_offset
        ) s
    )
    SELECT (SELECT count(*) FROM f)::integer,
           COALESCE((
               SELECT jsonb_agg(
                   jsonb_build_object(
                       'invoice_id', i.id,
                       'invoice_number', i.inv_no,
                       'invoice_date', i.inv_date,
                       'inv_fin_year', i.inv_fin_year,
                       'financial_year', (i.inv_fin_year || '-'::text) || (i.inv_fin_year + 1),
                       'inv_name', i.inv_name,
                       'invoice_pricing_mode', i.pricing_mode,
                       'notes', i.notes,
                       'is_auto_generated', i.is_auto_generated,
                       'total', i.total,
                       'discount', i.discount,
                       'labour', i.labour,
                       'tax_amount', i.tax_amount,
                       'one_time_charge', i.one_time_charge,
                       'created_by', i.created_by,
                       'total_qty', q.total_qty,
                       'customer', jsonb_build_object(
                           'id', c.id,
                           'name', c.name,
                           'city', c.city,
                           'address', c.address,
                           'phone', c.mobile,
                           'email', c.email,
                           'gst', c.gst,
                           'active', c.active
                       ),
                       'grn', jsonb_build_object(
                           'id', gr.id,
                           'gr_no', gr.gr_no,
                           'registration', gr.registration,
                           'date', gr.date,
                           'sender_id', gr.sender_id,
                           'sender_name', gr.sender_name,
                           'supervisor_id', gr.supervisor_id,
                           'supervisor_name', gr.supervisor_name,
                           'customer_id', gr.customer_id,
                           'customer_name', gr.customer_name
                       )
                   ) ORDER BY pg.ord)
               FROM pg
               JOIN public.invoice i ON i.id = pg.invoice_id
               JOIN public.customers c ON c.id = i.customer_id
               JOIN public.goodsreceived gr ON gr.id = i.gr_id
               -- The line total of the invoice, for the rows of the page only. The inner joins are the ones the
               -- old list view used: a line whose dispatch line or receipt line is missing does not count.
               CROSS JOIN LATERAL (
                   SELECT COALESCE(sum(dt.disp_qty), 0::bigint)::numeric AS total_qty
                   FROM public.invoice_trl it
                   JOIN public.dispatch_trl dt ON dt.id = it.disp_trl_id
                   JOIN public.goodsreceived_trl grt ON grt.id = dt.gr_trl_id
                   WHERE it.invoice_id = i.id
               ) q
           ), '[]'::jsonb)
    INTO v_total_count, v_data;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_data,
        'pagination', jsonb_build_object(
            'total_count', v_total_count,
            'has_more', (p_offset + p_limit) < v_total_count
        )
    );
END;
$$;

ALTER FUNCTION public.get_invoices_list(p_limit integer, p_offset integer, p_customer_id uuid, p_financial_year integer, p_search_invoice_no text, p_search_grn_no text, p_sort_field text, p_sort_direction text, p_inv_no_from integer, p_inv_no_to integer, p_search text, p_date_from timestamp with time zone, p_date_to timestamp with time zone, p_customer_ids uuid[]) OWNER TO supabase_admin;

--
-- Name: get_item(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_item',jsonb_build_object());
    SELECT jsonb_build_object(
        'id', id,
        'name', name,
        'packaging', packaging,
        'description', description,
        'active', active
    ) INTO v_result
    FROM items
    WHERE id = p_item_id;

    IF v_result IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item not found'
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_result
    );
END;
$$;

ALTER FUNCTION public.get_item(p_item_id uuid) OWNER TO supabase_admin;

--
-- Name: get_item_dispatch_records(uuid, jsonb, text, text, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_dispatch_records(p_item_id uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'grn_date'::text, p_sort_order text DEFAULT 'desc'::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_calculate_totals boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_role text;
      v_user_id uuid;
      v_customer_ids uuid[];
      v_sort_field text;
      v_sort_direction text;
      v_total_count integer;
      v_records jsonb;
      v_totals jsonb := NULL;
  BEGIN
      v_user_id := auth.uid();
      SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = v_user_id;

      IF v_user_role IS NULL THEN
          RAISE EXCEPTION 'Access denied: User not found';
      END IF;

      IF v_user_role IN ('admin', 'supervisor', 'staff') THEN
          v_customer_ids := ARRAY(SELECT id FROM customers WHERE deleted_at IS NULL);
      ELSE
          v_customer_ids := ARRAY(
              SELECT DISTINCT customer_id
              FROM users_customers_new
              WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = v_user_id)
              AND active = true
          );
      END IF;

      v_sort_field := COALESCE(p_sort_by, 'grn_date');
      v_sort_direction := UPPER(COALESCE(p_sort_order, 'DESC'));

      -- Get total count (snake_case filter keys)
      SELECT COUNT(*)
      INTO v_total_count
      FROM dispatch_trl dt
      JOIN goodsreceived_trl gt ON dt.gr_trl_id = gt.id
      JOIN goodsreceived gr ON gt.gr_id = gr.id
      JOIN dispatch d ON dt.disp_id = d.id
      WHERE gt.item_id = p_item_id
      AND gr.customer_id = ANY(v_customer_ids)
      AND (NOT p_filters ? 'customer_id' OR gr.customer_id = (p_filters->>'customer_id')::uuid)
      AND (NOT p_filters ? 'disp_date_from' OR p_filters->>'disp_date_from' = ''
           OR d.disp_date >= (p_filters->>'disp_date_from')::timestamptz)
      AND (NOT p_filters ? 'disp_date_to' OR p_filters->>'disp_date_to' = ''
           OR d.disp_date <= (p_filters->>'disp_date_to')::timestamptz);

      -- Get records (snake_case response keys)
      WITH dispatch_records AS (
          SELECT
              dt.id,
              dt.disp_id as dispatch_id,
              dt.disp_qty as qty,
              d.disp_date as dispatch_date,
              d.disp_no,
              gr.id as grn_id,
              gr.date as grn_date,
              gr.gr_no,
              gr.customer_id,
              gr.customer_name,
              gr.sender_name as vendor_name,
              gr.invoiced,
              gt.id as grn_item_id,
              gt.qty as grn_qty,
              gt.item_name,
              gt.weight,
              gt.package_mark,
              gt.packaging,
              gt.rack
          FROM dispatch_trl dt
          JOIN goodsreceived_trl gt ON dt.gr_trl_id = gt.id
          JOIN goodsreceived gr ON gt.gr_id = gr.id
          JOIN dispatch d ON dt.disp_id = d.id
          WHERE gt.item_id = p_item_id
          AND gr.customer_id = ANY(v_customer_ids)
          AND (NOT p_filters ? 'customer_id' OR gr.customer_id = (p_filters->>'customer_id')::uuid)
          AND (NOT p_filters ? 'disp_date_from' OR p_filters->>'disp_date_from' = ''
               OR d.disp_date >= (p_filters->>'disp_date_from')::timestamptz)
          AND (NOT p_filters ? 'disp_date_to' OR p_filters->>'disp_date_to' = ''
               OR d.disp_date <= (p_filters->>'disp_date_to')::timestamptz)
      ),
      sorted_items AS (
          SELECT * FROM dispatch_records
          ORDER BY
              CASE WHEN v_sort_field = 'disp_no' AND v_sort_direction = 'ASC' THEN disp_no END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'disp_no' AND v_sort_direction = 'DESC' THEN disp_no END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'customer_name' AND v_sort_direction = 'ASC' THEN customer_name END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'customer_name' AND v_sort_direction = 'DESC' THEN customer_name END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'gr_no' AND v_sort_direction = 'ASC' THEN gr_no END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'gr_no' AND v_sort_direction = 'DESC' THEN gr_no END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'item_name' AND v_sort_direction = 'ASC' THEN item_name END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'item_name' AND v_sort_direction = 'DESC' THEN item_name END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'grn_date' AND v_sort_direction = 'ASC' THEN grn_date END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'grn_date' AND v_sort_direction = 'DESC' THEN grn_date END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'dispatch_date' AND v_sort_direction = 'ASC' THEN dispatch_date END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'dispatch_date' AND v_sort_direction = 'DESC' THEN dispatch_date END DESC NULLS LAST,
              CASE WHEN v_sort_field = 'qty' AND v_sort_direction = 'ASC' THEN qty END ASC NULLS LAST,
              CASE WHEN v_sort_field = 'qty' AND v_sort_direction = 'DESC' THEN qty END DESC NULLS LAST,
              grn_date DESC
          LIMIT p_limit OFFSET p_offset
      )
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', id,
              'dispatch_id', dispatch_id,
              'dispatch_date', dispatch_date,
              'disp_no', disp_no,
              'qty', qty,
              'grn_id', grn_id,
              'grn_date', grn_date,
              'gr_no', gr_no,
              'customer_id', customer_id,
              'customer_name', customer_name,
              'vendor_name', vendor_name,
              'invoiced', invoiced,
              'grn_item_id', grn_item_id,
              'grn_qty', grn_qty,
              'item_name', item_name,
              'weight', weight,
              'package_mark', package_mark,
              'packaging', packaging,
              'rack', rack
          )
      ) INTO v_records
      FROM sorted_items;

      IF p_calculate_totals THEN
          SELECT jsonb_build_object(
              'total_dispatch_qty', COALESCE(SUM(dt.disp_qty), 0),
              'total_grn_qty', COALESCE(SUM(gt.qty), 0),
              'total_weight', COALESCE(SUM(gt.weight), 0)
          ) INTO v_totals
          FROM dispatch_trl dt
          JOIN goodsreceived_trl gt ON dt.gr_trl_id = gt.id
          JOIN goodsreceived gr ON gt.gr_id = gr.id
          JOIN dispatch d ON dt.disp_id = d.id
          WHERE gt.item_id = p_item_id
          AND gr.customer_id = ANY(v_customer_ids)
          AND (NOT p_filters ? 'customer_id' OR gr.customer_id = (p_filters->>'customer_id')::uuid)
          AND (NOT p_filters ? 'disp_date_from' OR p_filters->>'disp_date_from' = ''
               OR d.disp_date >= (p_filters->>'disp_date_from')::timestamptz)
          AND (NOT p_filters ? 'disp_date_to' OR p_filters->>'disp_date_to' = ''
               OR d.disp_date <= (p_filters->>'disp_date_to')::timestamptz);
      END IF;

      RETURN jsonb_build_object(
          'data', COALESCE(v_records, '[]'::jsonb),
          'total_count', v_total_count,
          'totals', v_totals
      );

  EXCEPTION
      WHEN OTHERS THEN
          RAISE EXCEPTION 'Error retrieving item dispatch records: %', SQLERRM;
  END;
$$;

ALTER FUNCTION public.get_item_dispatch_records(p_item_id uuid, p_filters jsonb, p_sort_by text, p_sort_order text, p_limit integer, p_offset integer, p_calculate_totals boolean) OWNER TO supabase_admin;

--
-- Name: get_item_grn_rates(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_grn_rates(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE v_rates jsonb;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_item_grn_rates', jsonb_build_object());
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', r.id, 'gr_id', g.id, 'gr_no', g.gr_no, 'grn_date', warehouse_security.business_date(g.date),
           'customer_id', g.customer_id, 'customer_name', g.customer_name, 'price_type', r.price_type,
           'weight_min', r.weight_min, 'weight_max', r.weight_max, 'unit_price', r.unit_price,
           'labour_rate', r.labour_rate, 'tax_percent', r.tax_percent,
           'archived', COALESCE(g.invoiced, false), 'created_at', r.created_at)
         ORDER BY COALESCE(g.invoiced, false), warehouse_security.business_date(g.date) DESC, g.gr_no, r.weight_min, r.id), '[]'::jsonb)
    INTO v_rates
    FROM public.grn_rates r JOIN public.goodsreceived g ON g.id = r.gr_id
   WHERE r.item_id = p_item_id AND g.deleted_at IS NULL;
  RETURN jsonb_build_object('success', true, 'data', jsonb_build_object('rates', v_rates));
END;
$$;

ALTER FUNCTION public.get_item_grn_rates(p_item_id uuid) OWNER TO supabase_admin;

--
-- Name: get_item_grn_records(uuid, jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_grn_records(p_item_id uuid, p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'gr_no'::text, p_sort_order text DEFAULT 'asc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_total_count integer;
    v_items jsonb;
    v_user_role text;
    v_user_customer_ids uuid[];
    v_filters_clean jsonb;
    v_sort_by_clean text;
    v_sort_order_clean text;
BEGIN
    SELECT role INTO v_user_role FROM user_profiles WHERE auth.uid() = auth_user_id;

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
        FROM users_customers_new
        WHERE user_profile_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
    END IF;

    IF p_item_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'data', null, 'message', 'Item ID is required');
    END IF;

    v_filters_clean := COALESCE(p_filters, '{}'::jsonb);
    v_sort_by_clean := COALESCE(p_sort_by, 'gr_no');
    v_sort_order_clean := CASE WHEN LOWER(COALESCE(p_sort_order, 'asc')) = 'desc' THEN 'DESC' ELSE 'ASC' END;

    -- Normalize sort column to snake_case
    v_sort_by_clean := CASE v_sort_by_clean
        WHEN 'gr_no' THEN 'gr_no'
        WHEN 'customer_name' THEN 'customer_name'
        WHEN 'grns_customerName' THEN 'customer_name'
        WHEN 'item_name' THEN 'item_name'
        WHEN 'package_mark' THEN 'package_mark'
        WHEN 'created_at' THEN 'created_at'
        WHEN 'updated_at' THEN 'updated_at'
        ELSE v_sort_by_clean
    END;

    -- Get total count (snake_case filter keys)
    WITH base_data AS (
        SELECT 1
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE grt.item_id = p_item_id
        AND (v_user_role IN ('admin', 'supervisor', 'staff') OR (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
        AND (NOT v_filters_clean ? 'date_from' OR v_filters_clean->>'date_from' = '' OR gr.date >= (v_filters_clean->>'date_from')::date::timestamptz)
        AND (NOT v_filters_clean ? 'date_to' OR v_filters_clean->>'date_to' = '' OR gr.date <= (v_filters_clean->>'date_to')::date::timestamptz)
        AND (NOT v_filters_clean ? 'customer_name' OR v_filters_clean->>'customer_name' = '' OR gr.customer_name ILIKE '%' || (v_filters_clean->>'customer_name') || '%')
        AND (NOT v_filters_clean ? 'gr_no' OR v_filters_clean->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (v_filters_clean->>'gr_no') || '%')
        AND (NOT v_filters_clean ? 'qty' OR v_filters_clean->>'qty' = '' OR grt.qty = (v_filters_clean->>'qty')::integer)
        AND (NOT v_filters_clean ? 'qty_from' OR v_filters_clean->>'qty_from' = '' OR grt.qty >= (v_filters_clean->>'qty_from')::integer)
        AND (NOT v_filters_clean ? 'qty_to' OR v_filters_clean->>'qty_to' = '' OR grt.qty <= (v_filters_clean->>'qty_to')::integer)
        AND (NOT v_filters_clean ? 'stock' OR v_filters_clean->>'stock' = '' OR grt.stock = (v_filters_clean->>'stock')::integer)
        AND (NOT v_filters_clean ? 'stock_from' OR v_filters_clean->>'stock_from' = '' OR grt.stock >= (v_filters_clean->>'stock_from')::integer)
        AND (NOT v_filters_clean ? 'stock_to' OR v_filters_clean->>'stock_to' = '' OR grt.stock <= (v_filters_clean->>'stock_to')::integer)
        AND (NOT v_filters_clean ? 'weight' OR v_filters_clean->>'weight' = '' OR grt.weight = (v_filters_clean->>'weight')::integer)
        AND (NOT v_filters_clean ? 'weight_from' OR v_filters_clean->>'weight_from' = '' OR grt.weight >= (v_filters_clean->>'weight_from')::integer)
        AND (NOT v_filters_clean ? 'weight_to' OR v_filters_clean->>'weight_to' = '' OR grt.weight <= (v_filters_clean->>'weight_to')::integer)
        AND (NOT v_filters_clean ? 'package_mark' OR v_filters_clean->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (v_filters_clean->>'package_mark') || '%')
        AND (NOT v_filters_clean ? 'rack' OR v_filters_clean->>'rack' = '' OR grt.rack ILIKE '%' || (v_filters_clean->>'rack') || '%')
    )
    SELECT COUNT(*) INTO v_total_count FROM base_data;

    -- Get paginated data with STABLE sort
    WITH filtered_grn_items AS (
        SELECT grt.id, grt.item_id, grt.item_name, grt.qty, grt.stock, grt.weight,
            grt.rack, grt.package_mark, grt.packaging, grt.trl_img_url, grt.gr_id,
            gr.id as grns_id, gr.gr_no, gr.date,
            gr.customer_id as grns_customer_id, gr.customer_name as grns_customer_name,
            gr.registration as grns_registration, gr.supervisor_name as grns_supervisor_name,
            gr.sender_name as grns_sender_name, gr.invoiced as grns_invoiced,
            gr.leon as grns_leon, gr.out_of_stock as grns_out_of_stock,
            gr.note as grns_note, gr.gr_image_url as grns_image_url,
            gr.created_at, gr.updated_at
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON grt.gr_id = gr.id
        WHERE grt.item_id = p_item_id
        AND (v_user_role IN ('admin', 'supervisor', 'staff') OR (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
        AND (NOT v_filters_clean ? 'date_from' OR v_filters_clean->>'date_from' = '' OR gr.date >= (v_filters_clean->>'date_from')::date::timestamptz)
        AND (NOT v_filters_clean ? 'date_to' OR v_filters_clean->>'date_to' = '' OR gr.date <= (v_filters_clean->>'date_to')::date::timestamptz)
        AND (NOT v_filters_clean ? 'customer_name' OR v_filters_clean->>'customer_name' = '' OR gr.customer_name ILIKE '%' || (v_filters_clean->>'customer_name') || '%')
        AND (NOT v_filters_clean ? 'gr_no' OR v_filters_clean->>'gr_no' = '' OR gr.gr_no ILIKE '%' || (v_filters_clean->>'gr_no') || '%')
        AND (NOT v_filters_clean ? 'qty' OR v_filters_clean->>'qty' = '' OR grt.qty = (v_filters_clean->>'qty')::integer)
        AND (NOT v_filters_clean ? 'qty_from' OR v_filters_clean->>'qty_from' = '' OR grt.qty >= (v_filters_clean->>'qty_from')::integer)
        AND (NOT v_filters_clean ? 'qty_to' OR v_filters_clean->>'qty_to' = '' OR grt.qty <= (v_filters_clean->>'qty_to')::integer)
        AND (NOT v_filters_clean ? 'stock' OR v_filters_clean->>'stock' = '' OR grt.stock = (v_filters_clean->>'stock')::integer)
        AND (NOT v_filters_clean ? 'stock_from' OR v_filters_clean->>'stock_from' = '' OR grt.stock >= (v_filters_clean->>'stock_from')::integer)
        AND (NOT v_filters_clean ? 'stock_to' OR v_filters_clean->>'stock_to' = '' OR grt.stock <= (v_filters_clean->>'stock_to')::integer)
        AND (NOT v_filters_clean ? 'weight' OR v_filters_clean->>'weight' = '' OR grt.weight = (v_filters_clean->>'weight')::integer)
        AND (NOT v_filters_clean ? 'weight_from' OR v_filters_clean->>'weight_from' = '' OR grt.weight >= (v_filters_clean->>'weight_from')::integer)
        AND (NOT v_filters_clean ? 'weight_to' OR v_filters_clean->>'weight_to' = '' OR grt.weight <= (v_filters_clean->>'weight_to')::integer)
        AND (NOT v_filters_clean ? 'package_mark' OR v_filters_clean->>'package_mark' = '' OR grt.package_mark ILIKE '%' || (v_filters_clean->>'package_mark') || '%')
        AND (NOT v_filters_clean ? 'rack' OR v_filters_clean->>'rack' = '' OR grt.rack ILIKE '%' || (v_filters_clean->>'rack') || '%')
        ORDER BY
            CASE WHEN v_sort_by_clean = 'customer_name' AND v_sort_order_clean = 'ASC' THEN gr.customer_name END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'customer_name' AND v_sort_order_clean = 'DESC' THEN gr.customer_name END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'gr_no' AND v_sort_order_clean = 'ASC' THEN gr.gr_no END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'gr_no' AND v_sort_order_clean = 'DESC' THEN gr.gr_no END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'date' AND v_sort_order_clean = 'ASC' THEN gr.date::text END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'date' AND v_sort_order_clean = 'DESC' THEN gr.date::text END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'item_name' AND v_sort_order_clean = 'ASC' THEN grt.item_name END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'item_name' AND v_sort_order_clean = 'DESC' THEN grt.item_name END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'qty' AND v_sort_order_clean = 'ASC' THEN grt.qty END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'qty' AND v_sort_order_clean = 'DESC' THEN grt.qty END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'stock' AND v_sort_order_clean = 'ASC' THEN grt.stock END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'stock' AND v_sort_order_clean = 'DESC' THEN grt.stock END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'weight' AND v_sort_order_clean = 'ASC' THEN grt.weight END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'weight' AND v_sort_order_clean = 'DESC' THEN grt.weight END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'rack' AND v_sort_order_clean = 'ASC' THEN grt.rack END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'rack' AND v_sort_order_clean = 'DESC' THEN grt.rack END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'package_mark' AND v_sort_order_clean = 'ASC' THEN grt.package_mark END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'package_mark' AND v_sort_order_clean = 'DESC' THEN grt.package_mark END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'created_at' AND v_sort_order_clean = 'ASC' THEN gr.created_at::text END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'created_at' AND v_sort_order_clean = 'DESC' THEN gr.created_at::text END DESC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'updated_at' AND v_sort_order_clean = 'ASC' THEN gr.updated_at::text END ASC NULLS LAST,
            CASE WHEN v_sort_by_clean = 'updated_at' AND v_sort_order_clean = 'DESC' THEN gr.updated_at::text END DESC NULLS LAST,
            grt.id ASC
        LIMIT p_limit OFFSET p_offset
    )
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
        'id', id, 'item_id', item_id, 'item_name', item_name, 'qty', qty, 'stock', stock, 'weight', weight,
        'rack', rack, 'package_mark', package_mark, 'packaging', packaging, 'trl_img_url', trl_img_url,
        'gr_id', gr_id, 'grn_id', grns_id, 'gr_no', gr_no, 'grn_date', date,
        'customer_id', grns_customer_id, 'customer_name', grns_customer_name,
        'registration', grns_registration, 'supervisor_name', grns_supervisor_name,
        'sender_name', grns_sender_name, 'invoiced', grns_invoiced,
        'leon', grns_leon, 'out_of_stock', grns_out_of_stock,
        'note', grns_note, 'image_url', grns_image_url,
        'created_at', created_at, 'updated_at', updated_at
    )), '[]'::jsonb) INTO v_items FROM filtered_grn_items;

    v_result := jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', v_items, 'total_count', v_total_count,
            'page_size', p_limit, 'page_offset', p_offset,
            'sort_by', v_sort_by_clean, 'sort_order', v_sort_order_clean
        ),
        'message', 'GRN records retrieved successfully'
    );

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_item_grn_records(p_item_id uuid, p_filters jsonb, p_sort_by text, p_sort_order text, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_item_price_history(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_price_history(p_customer_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 200);
    -- Capped where offset + limit still fits an integer (has_more adds them).
    v_offset integer := LEAST(GREATEST(COALESCE(p_offset, 0), 0), 2147483647 - 200);
    v_total integer;
    v_data jsonb;
BEGIN
    PERFORM warehouse_security.authorize_rpc('get_item_price_history', jsonb_build_object('p_customer_id', p_customer_id));

    SELECT count(*) INTO v_total
    FROM item_price_history h
    WHERE (p_customer_id IS NULL OR h.customer_id = p_customer_id OR h.action = 'truncate')
      AND (p_item_id IS NULL OR h.item_id = p_item_id OR h.action = 'truncate');

    SELECT COALESCE(jsonb_agg(page.row_data ORDER BY page.id DESC), '[]'::jsonb) INTO v_data
    FROM (
        SELECT h.id, jsonb_build_object(
            'id', h.id,
            'changed_at', h.changed_at,
            'action', h.action,
            'price_id', h.price_id,
            'item_id', h.item_id,
            'item_name', h.item_name,
            'customer_id', h.customer_id,
            'customer_name', h.customer_name,
            'old_values', h.old_values,
            'new_values', h.new_values,
            'changed_by', h.changed_by,
            'changed_by_name', COALESCE(h.changed_by_name, (SELECT p.name FROM user_profiles p WHERE p.id = h.changed_by)),
            'changed_by_role', h.changed_by_role
        ) AS row_data
        FROM item_price_history h
        WHERE (p_customer_id IS NULL OR h.customer_id = p_customer_id OR h.action = 'truncate')
          AND (p_item_id IS NULL OR h.item_id = p_item_id OR h.action = 'truncate')
        ORDER BY h.id DESC
        LIMIT v_limit OFFSET v_offset
    ) page;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_data,
        'pagination', jsonb_build_object(
            'total', v_total,
            'limit', v_limit,
            'offset', v_offset,
            'has_more', (v_offset + v_limit) < v_total
        )
    );
END;
$$;

ALTER FUNCTION public.get_item_price_history(p_customer_id uuid, p_item_id uuid, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_item_pricing_config(uuid, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_pricing_config(p_item_id uuid, p_customer_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    SELECT jsonb_build_object(
        'success', true,
        'data', COALESCE(jsonb_agg(jsonb_build_object(
            'id', isp.id,
            'item_id', isp.item_id,
            'customer_id', isp.customer_id,
            'weight_min', isp.weight_min,
            'weight_max', isp.weight_max,
            'unit_price_one_time', isp.unit_price_one_time,
            'unit_price_monthly', isp.unit_price_monthly,
            'labour_rate', isp.labour_rate,
            'tax_percent', isp.tax_percent,
            'effective_from', isp.effective_from,
            'effective_to', isp.effective_to,
            'is_customer_specific', (isp.customer_id IS NOT NULL)
        ) ORDER BY
            CASE WHEN isp.customer_id IS NOT NULL THEN 1 ELSE 2 END,
            isp.weight_min ASC,
            isp.effective_from DESC
        ), '[]'::jsonb),
        'message', null
    ) INTO v_result
    FROM item_storage_prices isp
    WHERE isp.item_id = p_item_id
      AND (p_customer_id IS NULL OR isp.customer_id = p_customer_id OR isp.customer_id IS NULL)
      AND (isp.effective_to IS NULL OR isp.effective_to > CURRENT_DATE);

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.get_item_pricing_config(p_item_id uuid, p_customer_id uuid) OWNER TO supabase_admin;

--
-- Name: get_item_stock_analysis(timestamp with time zone, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_stock_analysis(p_as_of_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_item_filter jsonb DEFAULT '{}'::jsonb, p_customer_filter jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_result jsonb;
      v_total_grn_qty bigint;
      v_total_dispatch_qty bigint;
      v_total_calculated_stock bigint;
      v_item_count integer;
      v_items jsonb;
      v_user_role text;
      v_items_with_negative_stock integer;
      v_item_filter_clean jsonb;
      v_customer_filter_clean jsonb;
  BEGIN
      -- Security: Only admin/supervisor can access this function
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Restrict access to admin/supervisor only
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', null,
              'message', 'Access denied: Only administrators and supervisors can access item stock analysis across all customers'
          );
      END IF;

      -- Handle NULL filters by converting to empty JSONB
      v_item_filter_clean := COALESCE(p_item_filter, '{}'::jsonb);
      v_customer_filter_clean := COALESCE(p_customer_filter, '{}'::jsonb);

      -- Time-traveling inventory calculation across ALL customers
      WITH grn_data AS (
          -- Sum all GRN quantities up to the specified date across all customers
          SELECT
              grt.item_id,
              SUM(grt.qty) as total_grn_qty
          FROM goodsreceived_trl grt
          JOIN goodsreceived gr ON grt.gr_id = gr.id
          WHERE (p_as_of_date IS NULL OR gr.date <= p_as_of_date)
          AND (NOT v_customer_filter_clean ? 'customer_id' OR v_customer_filter_clean->>'customer_id' = ''
               OR gr.customer_id = (v_customer_filter_clean->>'customer_id')::uuid)
          AND (NOT v_customer_filter_clean ? 'customer_name' OR v_customer_filter_clean->>'customer_name' = ''
               OR gr.customer_name ILIKE '%' || (v_customer_filter_clean->>'customer_name') || '%')
          GROUP BY grt.item_id
      ),
      dispatch_data AS (
          -- Sum all dispatch quantities up to the specified date across all customers
          -- CRITICAL: Use dispatch date, not GRN date
          SELECT
              grt.item_id,
              SUM(dt.disp_qty) as total_dispatch_qty
          FROM dispatch_trl dt
          JOIN goodsreceived_trl grt ON dt.gr_trl_id = grt.id
          JOIN dispatch d ON dt.disp_id = d.id
          JOIN goodsreceived gr ON grt.gr_id = gr.id
          WHERE (p_as_of_date IS NULL OR d.disp_date <= p_as_of_date)
          AND (NOT v_customer_filter_clean ? 'customer_id' OR v_customer_filter_clean->>'customer_id' = ''
               OR gr.customer_id = (v_customer_filter_clean->>'customer_id')::uuid)
          AND (NOT v_customer_filter_clean ? 'customer_name' OR v_customer_filter_clean->>'customer_name' = ''
               OR gr.customer_name ILIKE '%' || (v_customer_filter_clean->>'customer_name') || '%')
          GROUP BY grt.item_id
      ),
      stock_calculation AS (
          -- Calculate total stock across all customers for each item
          SELECT
              i.id as item_id,
              i.name as item_name,
              i.packaging,
              i.description,
              COALESCE(grn.total_grn_qty, 0) as grn_qty,
              COALESCE(disp.total_dispatch_qty, 0) as dispatch_qty,
              COALESCE(grn.total_grn_qty, 0) - COALESCE(disp.total_dispatch_qty, 0) as calculated_stock
          FROM items i
          LEFT JOIN grn_data grn ON i.id = grn.item_id
          LEFT JOIN dispatch_data disp ON i.id = disp.item_id
          WHERE i.active = true
          AND (grn.item_id IS NOT NULL OR disp.item_id IS NOT NULL)
          AND (NOT v_item_filter_clean ? 'item_name' OR v_item_filter_clean->>'item_name' = ''
               OR i.name ILIKE '%' || (v_item_filter_clean->>'item_name') || '%')
          AND (NOT v_item_filter_clean ? 'item_id' OR v_item_filter_clean->>'item_id' = ''
               OR i.id = (v_item_filter_clean->>'item_id')::uuid)
      )
      -- Final aggregation and result building
      SELECT
          jsonb_agg(
              jsonb_build_object(
                  'item_id', sc.item_id,
                  'item_name', sc.item_name,
                  'packaging', sc.packaging,
                  'description', sc.description,
                  'grn_qty', sc.grn_qty,
                  'dispatch_qty', sc.dispatch_qty,
                  'stock', sc.calculated_stock,
                  'has_negative_stock', sc.calculated_stock < 0,
                  'as_of_date', COALESCE(p_as_of_date, NOW())
              ) ORDER BY sc.item_name
          ),
          COALESCE(SUM(sc.grn_qty), 0),
          COALESCE(SUM(sc.dispatch_qty), 0),
          COALESCE(SUM(sc.calculated_stock), 0),
          COUNT(*),
          COUNT(*) FILTER (WHERE sc.calculated_stock < 0)
      INTO v_items, v_total_grn_qty, v_total_dispatch_qty, v_total_calculated_stock, v_item_count, v_items_with_negative_stock
      FROM stock_calculation sc;

      -- Build final result
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'items', COALESCE(v_items, '[]'::jsonb),
              'aggregations', jsonb_build_object(
                  'total_grn_qty', v_total_grn_qty,
                  'total_dispatch_qty', v_total_dispatch_qty,
                  'total_stock', v_total_calculated_stock,
                  'item_count', v_item_count,
                  'items_with_negative_stock', v_items_with_negative_stock,
                  'as_of_date', COALESCE(p_as_of_date, NOW()),
                  'has_data_integrity_issues', v_items_with_negative_stock > 0
              )
          ),
          'message', CASE
              WHEN p_as_of_date IS NOT NULL THEN
                  'Historical item stock analysis across all customers as of ' || to_char(p_as_of_date, 'YYYY-MM-DD') || ' retrieved
  successfully'
              ELSE
                  'Current item stock analysis across all customers retrieved successfully'
          END
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'data', NULL,
              'message', 'Error retrieving item stock analysis: ' || SQLERRM
          );
  END;
  $$;

ALTER FUNCTION public.get_item_stock_analysis(p_as_of_date timestamp with time zone, p_item_filter jsonb, p_customer_filter jsonb) OWNER TO supabase_admin;

--
-- Name: get_item_storage_prices(jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_storage_prices(p_filters jsonb DEFAULT '{}'::jsonb, p_sort_by text DEFAULT 'item_name'::text, p_sort_order text DEFAULT 'asc'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_role TEXT;
    v_user_customer_ids UUID[];
    v_where_clauses TEXT[] := ARRAY['1=1'];
    v_order_by TEXT;
    v_data JSONB;
    v_total INTEGER;
    v_item_ids UUID[];
    v_customer_ids UUID[];
    v_include_expired BOOLEAN;
    v_price_type TEXT;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_item_storage_prices',jsonb_build_object());
    -- Authorization: Allow all authenticated users
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();
    IF v_user_role IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    -- For non-admin/supervisor users, auto-filter to their accessible customers
    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        SELECT ARRAY(
            SELECT uc.customer_id
            FROM users_customers_new uc
            JOIN user_profiles up ON up.id = uc.user_profile_id
            WHERE up.auth_user_id = auth.uid() AND uc.active = true
        ) INTO v_user_customer_ids;

        IF v_user_customer_ids IS NULL OR array_length(v_user_customer_ids, 1) IS NULL THEN
            v_where_clauses := array_append(v_where_clauses, 'isp.customer_id IS NULL');
        ELSE
            v_where_clauses := array_append(v_where_clauses,
                format('(isp.customer_id IS NULL OR isp.customer_id = ANY(%L::uuid[]))', v_user_customer_ids));
        END IF;
    END IF;

    -- Item IDs filter
    IF p_filters ? 'item_ids' AND jsonb_array_length(p_filters->'item_ids') > 0 THEN
        SELECT array_agg(x::uuid) INTO v_item_ids
        FROM jsonb_array_elements_text(p_filters->'item_ids') x;
        v_where_clauses := array_append(v_where_clauses, format('isp.item_id = ANY(%L::uuid[])', v_item_ids));
    END IF;

    -- Customer IDs filter
    IF p_filters ? 'customer_ids' THEN
        IF jsonb_array_length(p_filters->'customer_ids') > 0 THEN
            SELECT array_agg(x::uuid) INTO v_customer_ids
            FROM jsonb_array_elements_text(p_filters->'customer_ids') x;
            v_where_clauses := array_append(v_where_clauses, format('isp.customer_id = ANY(%L::uuid[])', v_customer_ids));
        ELSE
            v_where_clauses := array_append(v_where_clauses, 'isp.customer_id IS NULL');
        END IF;
    END IF;

    -- Price type filter (NEW)
    IF p_filters ? 'price_type' THEN
        v_price_type := p_filters->>'price_type';
        IF v_price_type IN ('one_time', 'monthly') THEN
            v_where_clauses := array_append(v_where_clauses, format('isp.price_type = %L', v_price_type));
        END IF;
    END IF;

    -- Weight range filters
    IF p_filters ? 'weight_min' THEN
        v_where_clauses := array_append(v_where_clauses, format('isp.weight_max >= %s', (p_filters->>'weight_min')::numeric));
    END IF;
    IF p_filters ? 'weight_max' THEN
        v_where_clauses := array_append(v_where_clauses, format('isp.weight_min <= %s', (p_filters->>'weight_max')::numeric));
    END IF;

    -- Date range filters
    IF p_filters ? 'effective_from' THEN
        v_where_clauses := array_append(v_where_clauses, format('isp.effective_from >= %L::date', p_filters->>'effective_from'));
    END IF;
    IF p_filters ? 'effective_to' THEN
        v_where_clauses := array_append(v_where_clauses, format('(isp.effective_to IS NULL OR isp.effective_to <= %L::date)', p_filters->>'effective_to'));
    END IF;

    -- Include expired filter
    v_include_expired := COALESCE((p_filters->>'include_expired')::boolean, false);
    IF NOT v_include_expired THEN
        v_where_clauses := array_append(v_where_clauses, '(isp.effective_to IS NULL OR isp.effective_to >= warehouse_security.business_date(now()))');
    END IF;

    -- Build ORDER BY clause
    v_order_by := CASE p_sort_by
        WHEN 'item_name' THEN 'i.name'
        WHEN 'customer_name' THEN 'c.name'
        WHEN 'price_type' THEN 'isp.price_type'
        WHEN 'unit_price' THEN 'isp.unit_price'
        WHEN 'weight_min' THEN 'isp.weight_min'
        WHEN 'weight_max' THEN 'isp.weight_max'
        WHEN 'effective_from' THEN 'isp.effective_from'
        WHEN 'effective_to' THEN 'isp.effective_to'
        WHEN 'created_at' THEN 'isp.created_at'
        ELSE 'i.name'
    END || ' ' || CASE WHEN LOWER(p_sort_order) = 'desc' THEN 'DESC' ELSE 'ASC' END || ' NULLS LAST';

    -- Add secondary sort
    IF p_sort_by NOT IN ('item_name', 'price_type') THEN
        v_order_by := v_order_by || ', i.name ASC NULLS LAST, isp.price_type ASC';
    ELSIF p_sort_by = 'item_name' THEN
        v_order_by := v_order_by || ', isp.price_type ASC, isp.effective_from DESC NULLS LAST';
    ELSIF p_sort_by = 'price_type' THEN
        v_order_by := v_order_by || ', i.name ASC NULLS LAST';
    END IF;

    -- Last tie-breaker, so paging never skips or repeats a row (migration 76).
    v_order_by := v_order_by || ', isp.id ASC';

    -- Get total count
    EXECUTE format(
        'SELECT COUNT(*) FROM item_storage_prices isp
         LEFT JOIN items i ON isp.item_id = i.id
         LEFT JOIN customers c ON isp.customer_id = c.id
         WHERE %s',
        array_to_string(v_where_clauses, ' AND ')
    ) INTO v_total;

    -- Get data with new schema fields
    EXECUTE format(
        'SELECT COALESCE(jsonb_agg(row_data), ''[]''::jsonb)
         FROM (
             SELECT jsonb_build_object(
                 ''id'', isp.id,
                 ''item_id'', isp.item_id,
                 ''item_name'', i.name,
                 ''customer_id'', isp.customer_id,
                 ''customer_name'', c.name,
                 ''price_type'', isp.price_type,
                 ''unit_price'', isp.unit_price,
                 ''weight_min'', isp.weight_min,
                 ''weight_max'', isp.weight_max,
                 ''labour_rate'', isp.labour_rate,
                 ''tax_percent'', isp.tax_percent,
                 ''effective_from'', isp.effective_from,
                 ''effective_to'', isp.effective_to,
                 ''created_at'', isp.created_at,
                 ''created_by'', isp.created_by
             ) as row_data
             FROM item_storage_prices isp
             LEFT JOIN items i ON isp.item_id = i.id
             LEFT JOIN customers c ON isp.customer_id = c.id
             WHERE %s
             ORDER BY %s
             LIMIT %s OFFSET %s
         ) sub',
        array_to_string(v_where_clauses, ' AND '),
        v_order_by,
        p_limit,
        p_offset
    ) INTO v_data;

    RETURN jsonb_build_object(
        'success', true,
        'data', v_data,
        'earliest_start', warehouse_security.rate_start_floor(),
        'pagination', jsonb_build_object(
            'total', v_total,
            'limit', p_limit,
            'offset', p_offset,
            'has_more', (p_offset + p_limit) < v_total
        )
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_code', SQLSTATE
    );
END;
$$;

ALTER FUNCTION public.get_item_storage_prices(p_filters jsonb, p_sort_by text, p_sort_order text, p_limit integer, p_offset integer) OWNER TO supabase_admin;

--
-- Name: get_item_wise_stock_list(uuid, text, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_item_wise_stock_list(p_customer_id uuid DEFAULT NULL::uuid, p_search_query text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_sort_by text DEFAULT 'item_name'::text, p_sort_order text DEFAULT 'asc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_accessible_customers UUID[];
    v_results JSONB;
    v_total_count INTEGER;
    v_is_admin BOOLEAN;
    v_total_stock BIGINT := 0;
    v_total_qty BIGINT := 0;
    v_sort_by TEXT;
    v_sort_sign INTEGER;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_item_wise_stock_list',jsonb_build_object('p_customer_id',p_customer_id));
    -- Sort: a fixed list of keys and two directions; any other value is the
    -- default. The two variables only select branches of the ORDER BY below.
    v_sort_by := lower(COALESCE(p_sort_by, ''));
    IF v_sort_by NOT IN ('item_name', 'total_stock', 'total_qty', 'grn_count') THEN
        v_sort_by := 'item_name';
    END IF;
    v_sort_sign := CASE WHEN lower(COALESCE(p_sort_order, '')) = 'desc' THEN -1 ELSE 1 END;

    -- Determine accessible customers
    v_is_admin := is_admin_or_supervisor();

    IF v_is_admin THEN
        -- Admin/Supervisor: all customers (unless p_customer_id specified)
        IF p_customer_id IS NOT NULL THEN
            v_accessible_customers := ARRAY[p_customer_id];
        ELSE
            SELECT ARRAY_AGG(id) INTO v_accessible_customers
            FROM customers WHERE deleted_at IS NULL;
        END IF;
    ELSE
        -- Customer role: only assigned customers
        SELECT user_accessible_customers() INTO v_accessible_customers;

        -- SECURITY FIX: Return empty result if no accessible customers (instead of all customers)
        IF COALESCE(array_length(v_accessible_customers, 1), 0) = 0 THEN
            RETURN jsonb_build_object(
                'success', true,
                'data', jsonb_build_object(
                    'items', '[]'::jsonb,
                    'total_count', 0, 'summary', jsonb_build_object('total_stock', 0, 'total_qty', 0, 'item_count', 0)
                )
            );
        END IF;

        IF p_customer_id IS NOT NULL THEN
            IF NOT (p_customer_id = ANY(v_accessible_customers)) THEN
                RETURN jsonb_build_object(
                    'success', false,
                    'error', 'Access denied to customer'
                );
            END IF;
            v_accessible_customers := ARRAY[p_customer_id];
        END IF;
    END IF;

    -- Handle empty customers
    IF COALESCE(array_length(v_accessible_customers, 1), 0) = 0 THEN
        RETURN jsonb_build_object(
            'success', true,
            'data', jsonb_build_object(
                'items', '[]'::jsonb,
                'total_count', 0, 'summary', jsonb_build_object('total_stock', 0, 'total_qty', 0, 'item_count', 0)
            )
        );
    END IF;

    -- Count and totals of the whole filtered list, whatever page is asked for
    SELECT COUNT(*), COALESCE(SUM(unique_items.item_stock), 0), COALESCE(SUM(unique_items.item_qty), 0)
    INTO v_total_count, v_total_stock, v_total_qty
    FROM (
        SELECT grt.item_id, SUM(grt.stock) AS item_stock, SUM(grt.qty) AS item_qty
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON gr.id = grt.gr_id
        WHERE gr.customer_id = ANY(v_accessible_customers)
          AND gr.deleted_at IS NULL
          AND grt.stock > 0
          AND (p_search_query IS NULL OR grt.item_name ILIKE '%' || p_search_query || '%')
        GROUP BY grt.item_id
        HAVING SUM(grt.stock) > 0
    ) AS unique_items;

    -- Build aggregated results grouped by item_id
    SELECT COALESCE(jsonb_agg(item_row ORDER BY item_position), '[]'::jsonb)
    INTO v_results
    FROM (
        SELECT jsonb_build_object(
            'item_id', grt.item_id,
            'item_name', MAX(grt.item_name),
            'packaging', MAX(grt.packaging),
            'total_qty', SUM(grt.qty)::INTEGER,
            'total_stock', SUM(grt.stock)::INTEGER,
            'grn_count', COUNT(DISTINCT grt.gr_id)::INTEGER
        ) AS item_row,
        ROW_NUMBER() OVER (ORDER BY
            CASE v_sort_by WHEN 'total_stock' THEN SUM(grt.stock)
                           WHEN 'total_qty' THEN SUM(grt.qty)
                           WHEN 'grn_count' THEN COUNT(DISTINCT grt.gr_id) END * v_sort_sign,
            CASE WHEN v_sort_by = 'item_name' AND v_sort_sign < 0 THEN MAX(grt.item_name) END DESC,
            MAX(grt.item_name),
            grt.item_id
        ) AS item_position
        FROM goodsreceived_trl grt
        JOIN goodsreceived gr ON gr.id = grt.gr_id
        WHERE gr.customer_id = ANY(v_accessible_customers)
          AND gr.deleted_at IS NULL
          AND grt.stock > 0
          AND (p_search_query IS NULL OR grt.item_name ILIKE '%' || p_search_query || '%')
        GROUP BY grt.item_id
        HAVING SUM(grt.stock) > 0
        ORDER BY item_position
        LIMIT p_limit
        OFFSET p_offset
    ) AS aggregated;

    -- Return with expected structure
    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', v_results,
            'total_count', v_total_count,
            'summary', jsonb_build_object(
                'total_stock', v_total_stock,
                'total_qty', v_total_qty,
                'item_count', v_total_count
            )
        )
    );
END;
$$;

ALTER FUNCTION public.get_item_wise_stock_list(p_customer_id uuid, p_search_query text, p_limit integer, p_offset integer, p_sort_by text, p_sort_order text) OWNER TO supabase_admin;

--
-- Name: get_items(text, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_items(p_search_query text DEFAULT NULL::text, p_active_only boolean DEFAULT true, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
    v_total_count integer;
BEGIN
  PERFORM warehouse_security.authorize_rpc('get_items',jsonb_build_object());
    -- Get total count
    SELECT COUNT(*) INTO v_total_count
    FROM items
    WHERE (p_active_only = false OR active = true)
      AND (p_search_query IS NULL OR
           name ILIKE '%' || p_search_query || '%' OR
           description ILIKE '%' || p_search_query || '%');

    -- Get items
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', id,
            'name', name,
            'packaging', packaging,
            'description', description,
            'active', active
        ) ORDER BY name
    ) INTO v_result
    FROM (
        SELECT id, name, packaging, description, active
        FROM items
        WHERE (p_active_only = false OR active = true)
          AND (p_search_query IS NULL OR
               name ILIKE '%' || p_search_query || '%' OR
               description ILIKE '%' || p_search_query || '%')
        ORDER BY name
        LIMIT p_limit OFFSET p_offset
    ) sub;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'items', COALESCE(v_result, '[]'::jsonb),
            'total_count', v_total_count,
            'limit', p_limit,
            'offset', p_offset
        )
    );
END;
$$;

ALTER FUNCTION public.get_items(p_search_query text, p_active_only boolean, p_limit integer, p_offset integer) OWNER TO supabase_admin;

