    SET search_path TO 'public'
    AS $$
      SELECT secret_value
      FROM public.jwt_config
      WHERE secret_name = 'supabase_jwt_secret'
      AND is_active = true
      LIMIT 1;
  $$;

ALTER FUNCTION public.get_jwt_secret() OWNER TO supabase_admin;

--
-- Name: get_my_access_status(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_my_access_status() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  me record;
BEGIN
  SELECT p.id, p.role, p.active INTO me FROM public.user_profiles p WHERE p.auth_user_id = auth.uid();
  IF me.id IS NULL THEN
    RETURN 'none';
  END IF;
  IF NOT me.active THEN
    RETURN 'revoked';
  END IF;
  IF me.role IN ('admin', 'supervisor', 'staff') THEN
    RETURN 'active';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users_customers_new a WHERE a.user_profile_id = me.id AND a.active) THEN
    RETURN 'active';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users_customers_new a WHERE a.user_profile_id = me.id) THEN
    RETURN 'revoked';
  END IF;
  RETURN 'none';
END;
$$;

ALTER FUNCTION public.get_my_access_status() OWNER TO supabase_admin;

--
-- Name: get_my_language(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.get_my_language() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  profile uuid := warehouse_security.own_profile_id();
BEGIN
  IF profile IS NULL THEN
    RAISE EXCEPTION 'Active account required' USING ERRCODE = '42501';
  END IF;
  RETURN jsonb_build_object('success', true, 'language',
    (SELECT p.preferred_language FROM public.user_profiles p WHERE p.id = profile));
END;
$$;

