CREATE FUNCTION public.log_auto_invoice_error(p_customer_id uuid, p_customer_name text, p_gr_id uuid, p_gr_no text, p_gr_date timestamp with time zone, p_error_code text, p_error_message text, p_error_details jsonb DEFAULT NULL::jsonb) RETURNS uuid
