--
-- Name: refresh_jwt_token(text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.refresh_jwt_token(p_refresh_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $_$
DECLARE session_row warehouse_security.refresh_sessions; consumed warehouse_security.consumed_refresh_tokens;
  result jsonb; supplied_hash text; successor text; grace_text text; grace integer;
  rejected constant jsonb := jsonb_build_object('success', false, 'message', 'Invalid refresh token');
BEGIN
  IF p_refresh_token IS NULL OR length(p_refresh_token) <> 64 THEN RETURN rejected; END IF;
  -- Shared lock with logout guarantees its next statement sees rotation history.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_refresh_token, 71041));
  supplied_hash := encode(extensions.digest(p_refresh_token, 'sha256'), 'hex');
  SELECT * INTO session_row FROM warehouse_security.refresh_sessions
    WHERE token_hash = supplied_hash AND expires_at > now() FOR UPDATE;
  IF session_row.id IS NULL THEN
    SELECT * INTO consumed FROM warehouse_security.consumed_refresh_tokens
      WHERE token_hash = supplied_hash AND expires_at > now();
    IF consumed.token_hash IS NULL THEN RETURN rejected; END IF;
    SELECT * INTO session_row FROM warehouse_security.refresh_sessions
      WHERE id = consumed.session_id AND expires_at > now() FOR UPDATE;
    IF session_row.id IS NULL THEN RETURN rejected; END IF;
    SELECT value INTO grace_text FROM warehouse_security.auth_config WHERE key = 'refresh_grace_seconds';
    grace := CASE WHEN grace_text ~ '^[0-9]{1,3}$' THEN least(grace_text::integer, 300) ELSE 60 END;
    -- Retry of the rotation that produced the session's current token: answer
    -- with that same token. Anything else (grace over, or a token from an
    -- earlier generation) is reuse.
    IF consumed.successor_wrap IS NOT NULL AND consumed.consumed_at > now() - make_interval(secs => grace) THEN
      BEGIN
        successor := convert_from(extensions.decrypt(decode(consumed.successor_wrap, 'hex'),
          extensions.hmac('refresh-successor', p_refresh_token, 'sha256'), 'aes'), 'UTF8');
      EXCEPTION WHEN OTHERS THEN successor := NULL;
      END;
      IF successor IS NOT NULL AND encode(extensions.digest(successor, 'sha256'), 'hex') = session_row.token_hash
        AND EXISTS (SELECT 1 FROM public.user_profiles WHERE auth_user_id = session_row.user_id AND active) THEN
        RETURN warehouse_security.sign_access_token(session_row.user_id, session_row.id)
          || jsonb_build_object('refresh_token', successor, 'success', true);
      END IF;
    END IF;
    -- Two parties hold tokens of this session; neither can be told from the
    -- thief, so the whole session ends and the user signs in again.
    DELETE FROM warehouse_security.refresh_sessions WHERE id = session_row.id;
    RAISE LOG 'Refresh token reuse: session % of user % revoked', session_row.id, session_row.user_id;
    RETURN rejected;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE auth_user_id = session_row.user_id AND active) THEN
    RETURN rejected;
  END IF;
  DELETE FROM warehouse_security.consumed_refresh_tokens WHERE expires_at <= now();
  INSERT INTO warehouse_security.consumed_refresh_tokens(token_hash, session_id, expires_at, consumed_at)
    VALUES (supplied_hash, session_row.id, session_row.expires_at, now());
  result := warehouse_security.issue_session(session_row.user_id, session_row.id);
  UPDATE warehouse_security.consumed_refresh_tokens
    SET successor_wrap = encode(extensions.encrypt(convert_to(result->>'refresh_token', 'UTF8'),
      extensions.hmac('refresh-successor', p_refresh_token, 'sha256'), 'aes'), 'hex')
    WHERE token_hash = supplied_hash;
  RETURN result || jsonb_build_object('success', true);
END $_$;

ALTER FUNCTION public.refresh_jwt_token(p_refresh_token text) OWNER TO supabase_admin;

--
-- Name: register_dispatch_image_upload(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.register_dispatch_image_upload(p_dispatch_id uuid, p_file_name text, p_file_size integer, p_mime_type text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_user_profile_id UUID;
    v_image_id UUID;
    v_upload_token UUID;
    v_storage_path TEXT;
    v_timestamp BIGINT;
    v_safe_filename TEXT;
BEGIN
  PERFORM warehouse_security.authorize_rpc('register_dispatch_image_upload',jsonb_build_object('p_dispatch_id',p_dispatch_id));
    -- 1. Authenticate user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'code', 'AUTH_REQUIRED'
        );
    END IF;

    -- Get user profile id
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = v_user_id;

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User profile not found',
            'code', 'USER_NOT_FOUND'
        );
    END IF;

    -- 2. Validate dispatch exists
    IF NOT EXISTS (SELECT 1 FROM dispatch WHERE id = p_dispatch_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Dispatch not found',
            'code', 'DISPATCH_NOT_FOUND'
        );
    END IF;

    -- 3. Validate MIME type
    IF p_mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only image/jpeg, image/png, image/webp allowed',
            'code', 'INVALID_MIME_TYPE'
        );
    END IF;

    -- 4. Validate file size (1 byte to 10MB)
    IF p_file_size < 1 OR p_file_size > 10485760 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'File size must be between 1 byte and 10MB',
            'code', 'FILE_TOO_LARGE'
        );
    END IF;

    -- 5. Generate IDs and storage path
    v_image_id := gen_random_uuid();
    v_upload_token := gen_random_uuid();
    v_timestamp := (EXTRACT(EPOCH FROM NOW()) * 1000)::bigint;
    v_safe_filename := regexp_replace(p_file_name, '[^a-zA-Z0-9._-]', '_', 'g');

    v_storage_path := p_dispatch_id::text || '/' || gen_random_uuid()::text || '_' || v_safe_filename;

    -- 6. Insert pending record
    INSERT INTO dispatch_images (
        id,
        dispatch_id,
        storage_path,
        original_filename,
        file_size,
        mime_type,
        uploaded_by,
        status,
        upload_token
    ) VALUES (
        v_image_id,
        p_dispatch_id,
        v_storage_path,
        p_file_name,
        p_file_size,
        p_mime_type,
        v_user_profile_id,
        'pending',
        v_upload_token
    );

    -- 7. Return success with path for frontend to use
    RETURN jsonb_build_object(
        'success', true,
        'image_id', v_image_id,
        'storage_path', v_storage_path,
        'upload_token', v_upload_token,
        'dispatch_id', p_dispatch_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Unexpected error: ' || SQLERRM,
        'code', 'INTERNAL_ERROR'
    );
END;
$$;

ALTER FUNCTION public.register_dispatch_image_upload(p_dispatch_id uuid, p_file_name text, p_file_size integer, p_mime_type text) OWNER TO supabase_admin;

--
-- Name: register_grn_image_upload(uuid, text, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.register_grn_image_upload(p_grn_id uuid, p_image_type text, p_file_name text, p_file_size integer, p_mime_type text, p_grn_item_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_profile_id uuid;
    v_image_id uuid;
    v_upload_token uuid;
    v_storage_path text;
    v_safe_filename text;
BEGIN
  PERFORM warehouse_security.authorize_rpc('register_grn_image_upload',jsonb_build_object('p_grn_id',p_grn_id,'p_grn_item_id',p_grn_item_id));
    -- 1. Authenticate user
    v_user_id := auth.uid();
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Authentication required',
            'code', 'AUTH_REQUIRED'
        );
    END IF;

    -- Get user profile id
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = v_user_id;

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'User profile not found',
            'code', 'USER_NOT_FOUND'
        );
    END IF;

    -- 2. Validate image_type
    IF p_image_type NOT IN ('header', 'item') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'image_type must be ''header'' or ''item''',
            'code', 'INVALID_IMAGE_TYPE'
        );
    END IF;

    -- 3. Validate item images have grn_item_id
    IF p_image_type = 'item' AND p_grn_item_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Item images require grn_item_id',
            'code', 'ITEM_ID_REQUIRED'
        );
    END IF;

    IF p_grn_item_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM goodsreceived_trl WHERE id = p_grn_item_id AND gr_id = p_grn_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Image line does not belong to this GRN',
            'code', 'ITEM_NOT_IN_GRN'
        );
    END IF;

    -- 4. Validate GRN exists
    IF NOT EXISTS (SELECT 1 FROM goodsreceived WHERE id = p_grn_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'GRN not found',
            'code', 'GRN_NOT_FOUND'
        );
    END IF;

    -- 5. Validate MIME type
    IF p_mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only image/jpeg, image/png, image/webp allowed',
            'code', 'INVALID_MIME_TYPE'
        );
    END IF;

    -- 6. Validate file size (1 byte to 10MB)
    IF p_file_size < 1 OR p_file_size > 10485760 THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'File size must be between 1 byte and 10MB',
            'code', 'FILE_TOO_LARGE'
        );
    END IF;

    -- 7. Generate IDs and storage path (UUID-based for guaranteed uniqueness)
    v_image_id := gen_random_uuid();
    v_upload_token := gen_random_uuid();
    v_safe_filename := regexp_replace(p_file_name, '[^a-zA-Z0-9._-]', '_', 'g');

    -- Use UUID instead of timestamp to guarantee uniqueness even with parallel uploads
    IF p_image_type = 'header' THEN
        v_storage_path := 'headers/' || p_grn_id::text || '/' || gen_random_uuid()::text || '_' || v_safe_filename;
    ELSE
        v_storage_path := 'items/' || p_grn_id::text || '/' || p_grn_item_id::text || '/' || gen_random_uuid()::text || '_' || v_safe_filename;
    END IF;

    -- 8. Insert pending record
    INSERT INTO grn_images (
        id,
        grn_id,
        grn_item_id,
        image_type,
        storage_path,
        original_filename,
        file_size,
        mime_type,
        uploaded_by,
        status,
        upload_token
    ) VALUES (
        v_image_id,
        p_grn_id,
        p_grn_item_id,
        p_image_type,
        v_storage_path,
        p_file_name,
        p_file_size,
        p_mime_type,
        v_user_profile_id,
        'pending',
        v_upload_token
    );

    -- 9. Return success with path for frontend to use
    RETURN jsonb_build_object(
        'success', true,
        'image_id', v_image_id,
        'storage_path', v_storage_path,
        'upload_token', v_upload_token,
        'grn_id', p_grn_id
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Unexpected error: ' || SQLERRM,
        'code', 'INTERNAL_ERROR'
    );
END;
$$;

ALTER FUNCTION public.register_grn_image_upload(p_grn_id uuid, p_image_type text, p_file_name text, p_file_size integer, p_mime_type text, p_grn_item_id uuid) OWNER TO supabase_admin;

--
-- Name: remove_customer_assignment(character varying, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.remove_customer_assignment(target_user_mobile character varying, target_customer_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
  DECLARE
      target_user_id uuid;
BEGIN
  PERFORM warehouse_security.authorize_rpc('remove_customer_assignment',jsonb_build_object());
      -- Check if current user is admin or supervisor
      IF NOT is_admin_or_supervisor() THEN
          RAISE EXCEPTION 'Only admins and supervisors can remove customer assignments';
      END IF;

      -- Get target user profile ID by mobile (changed from email)
      SELECT id INTO target_user_id
      FROM user_profiles
      WHERE mobile = target_user_mobile AND active = true;

      IF target_user_id IS NULL THEN
          RAISE EXCEPTION 'User with mobile % not found or inactive', target_user_mobile;
      END IF;

      -- A supervisor manages other people who are not administrators
      IF warehouse_security.active_role() = 'supervisor' AND (
          target_user_id = public.get_current_user_profile_id()
          OR EXISTS (SELECT 1 FROM user_profiles WHERE id = target_user_id AND role = 'admin')) THEN
          RAISE EXCEPTION 'Supervisors cannot change their own or an administrator''s customer assignments' USING ERRCODE = '42501';
      END IF;

      -- A service account is read-only here (migration 78)
      IF EXISTS (SELECT 1 FROM user_profiles WHERE id = target_user_id AND is_service_account) THEN
          RAISE EXCEPTION 'SERVICE_ACCOUNT_READ_ONLY: A service account cannot be changed here';
      END IF;

      -- Soft delete the assignment
      UPDATE users_customers_new
      SET active = false
      WHERE user_profile_id = target_user_id
      AND customer_id = target_customer_id;

      RETURN true;
  END;
$$;

ALTER FUNCTION public.remove_customer_assignment(target_user_mobile character varying, target_customer_id uuid) OWNER TO supabase_admin;

--
-- Name: remove_item_from_order(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.remove_item_from_order(p_order_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'warehouse_security', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_item record;
BEGIN
  PERFORM warehouse_security.authorize_rpc(
    'remove_item_from_order',
    jsonb_build_object('p_order_item_id', p_order_item_id)
  );

  SELECT id INTO v_user_id
  FROM public.user_profiles
  WHERE auth_user_id = auth.uid() AND active;

  SELECT oi.*, o.status AS order_status, o.deleted_at AS order_deleted_at
  INTO v_item
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
  FOR UPDATE OF oi;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Order item not found');
  END IF;
  IF v_item.order_status <> 'OPEN' OR v_item.order_deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Cannot remove items from ' || COALESCE(v_item.order_status, 'closed') || ' orders',
      'error', jsonb_build_object('code', 'ORDER_NOT_OPEN')
    );
  END IF;

  DELETE FROM public.order_items WHERE id = p_order_item_id;

  -- The removed lot is recorded at quantity 0 so the change log reports a removal.
  PERFORM warehouse_security.record_order_revision(
    v_item.order_id, v_user_id, 'UPDATE',
    jsonb_build_object('removed_item', jsonb_build_object(
      'item_id', v_item.grn_items_item_id,
      'item_name', v_item.grn_items_item_name,
      'grn_no', v_item.grns_gr_no,
      'package_mark', v_item.grn_items_package_mark,
      'requested_quantity', v_item.requested_quantity,
      'fulfilled_quantity', v_item.fulfilled_quantity)),
    jsonb_build_array(jsonb_build_object(
      'item_id', v_item.grn_items_item_id,
      'item_name', v_item.grn_items_item_name,
      'quantity', 0,
      'grn_no', v_item.grns_gr_no,
      'package_mark', v_item.grn_items_package_mark))
  );
  UPDATE public.orders SET updated_at = now(), updated_by = v_user_id WHERE id = v_item.order_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Item removed from order successfully',
    'data', jsonb_build_object(
      'order_item_id', p_order_item_id,
      'removed_item', v_item.grn_items_item_name,
      'removed_quantity', v_item.requested_quantity
    )
  );
EXCEPTION
  WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Error removing item: ' || SQLERRM);
END;
$$;

ALTER FUNCTION public.remove_item_from_order(p_order_item_id uuid) OWNER TO supabase_admin;

--
-- Name: replace_item_rates(uuid, uuid, text, date, jsonb, boolean, text, date, uuid[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.replace_item_rates(p_item_id uuid, p_customer_id uuid, p_price_type text, p_starts_on date, p_bands jsonb, p_replace_later boolean DEFAULT false, p_mode text DEFAULT 'change'::text, p_move_from date DEFAULT NULL::date, p_seen_rows uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
  v_role text; v_profile uuid; v_today date := warehouse_security.business_date(now());
  v_band jsonb; v_ord integer; v_field text; v_n numeric; v_limit numeric;
  v_prev_max integer; v_expected integer; v_min integer; v_max integer;
  v_later jsonb; v_removed jsonb := '[]'::jsonb; v_ended jsonb := '[]'::jsonb; v_added jsonb := '[]'::jsonb;
  v_reopened jsonb := '[]'::jsonb; v_moved integer; v_next date; v_row record;
  v_n_force integer; v_n_notstart integer; v_n_ends integer; v_n_open integer; v_end date;
  v_kept date; v_detail text; v_stop date; v_planned jsonb; v_unseen uuid[]; v_from date;
  v_new public.item_storage_prices;
BEGIN
  PERFORM warehouse_security.authorize_rpc('replace_item_rates', jsonb_build_object('p_customer_id', p_customer_id));
  SELECT up.id, up.role::text INTO v_profile, v_role FROM public.user_profiles up WHERE up.auth_user_id = auth.uid() AND up.active;

  IF p_price_type IS NULL OR p_price_type NOT IN ('monthly','one_time') THEN
    RETURN warehouse_security.rate_failure('INVALID_PRICE_TYPE', 'Price type must be monthly or one_time');
  END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('change','correct') THEN
    RETURN warehouse_security.rate_failure('INVALID_MODE', 'The mode must be change or correct');
  END IF;
  IF p_move_from IS NOT NULL AND p_mode <> 'change' THEN
    RETURN warehouse_security.rate_failure('INVALID_MODE', 'A rate can be moved only in change mode');
  END IF;
  IF p_starts_on IS NULL OR p_starts_on NOT BETWEEN warehouse_security.rate_start_floor() AND v_today + 730 THEN
    RETURN warehouse_security.rate_failure('INVALID_DATE',
      'The start date must be on or after ' || warehouse_security.rate_start_floor()::text || ' and within two years after today',
      jsonb_build_object('earliest', warehouse_security.rate_start_floor()));
  END IF;
  IF p_move_from IS NOT NULL AND p_move_from NOT BETWEEN warehouse_security.rate_start_floor() AND v_today + 730 THEN
    RETURN warehouse_security.rate_failure('INVALID_DATE',
      'The start date must be on or after ' || warehouse_security.rate_start_floor()::text || ' and within two years after today',
      jsonb_build_object('earliest', warehouse_security.rate_start_floor()));
  END IF;
  IF p_starts_on < v_today AND v_role = 'staff' THEN
    RETURN warehouse_security.rate_failure('PAST_DATE_NOT_ALLOWED', 'Only administrators and supervisors can start a rate in the past');
  END IF;
  IF p_move_from IS NOT NULL AND v_role = 'staff' AND (p_move_from <= v_today OR p_starts_on <= v_today) THEN
    RETURN warehouse_security.rate_failure('PAST_DATE_NOT_ALLOWED', 'Only administrators and supervisors can move a rate that has begun or move it to today');
  END IF;
  IF p_item_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.items WHERE id = p_item_id AND active) THEN
    RETURN warehouse_security.rate_failure('ITEM_NOT_FOUND', 'Item not found or inactive');
  END IF;
  IF p_customer_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.customers WHERE id = p_customer_id AND active AND deleted_at IS NULL) THEN
    RETURN warehouse_security.rate_failure('CUSTOMER_NOT_FOUND', 'Customer not found or inactive');
  END IF;

  -- The bands.
  IF p_bands IS NULL OR jsonb_typeof(p_bands) <> 'array' OR jsonb_array_length(p_bands) > 10 THEN
    RETURN warehouse_security.rate_failure('INVALID_BANDS', 'Bands must be a list of at most 10 bands');
  END IF;
  IF p_mode = 'correct' AND jsonb_array_length(p_bands) = 0 THEN
    RETURN warehouse_security.rate_failure('INVALID_BANDS', 'A correction needs at least one band');
  END IF;
  FOR v_band, v_ord IN SELECT e.value, (e.ord - 1)::integer FROM jsonb_array_elements(p_bands) WITH ORDINALITY e(value, ord) ORDER BY e.ord LOOP
    IF jsonb_typeof(v_band) <> 'object' THEN
      RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord));
    END IF;
    FOREACH v_field IN ARRAY ARRAY['weight_min','weight_max'] LOOP
      IF jsonb_typeof(v_band->v_field) IS DISTINCT FROM 'number' THEN
        RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
      v_n := (v_band->>v_field)::numeric;
      IF v_n <> trunc(v_n) OR v_n < 0 OR v_n > 100000 THEN
        RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
    END LOOP;
    IF (v_band->>'weight_min')::numeric > (v_band->>'weight_max')::numeric THEN
      RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord));
    END IF;
    -- Labour of a one-time rate is not used (invoices never charge it): not checked.
    FOREACH v_field IN ARRAY CASE WHEN p_price_type = 'one_time' THEN ARRAY['unit_price','tax_percent'] ELSE ARRAY['unit_price','labour_rate','tax_percent'] END LOOP
      IF jsonb_typeof(v_band->v_field) IS DISTINCT FROM 'number' THEN
        RETURN warehouse_security.rate_failure('INVALID_AMOUNT', 'Rent and labour must be 0 to 999999 with two decimals at most; tax 0 to 100', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
      v_n := (v_band->>v_field)::numeric;
      v_limit := CASE WHEN v_field = 'tax_percent' THEN 100 ELSE 999999 END;
      IF v_n < 0 OR v_n > v_limit OR v_n * 100 <> trunc(v_n * 100) THEN
        RETURN warehouse_security.rate_failure('INVALID_AMOUNT', 'Rent and labour must be 0 to 999999 with two decimals at most; tax 0 to 100', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
    END LOOP;
  END LOOP;
  -- Sorted by start: no overlap; the default rate also starts at 0 and has no gap.
  v_prev_max := NULL; v_expected := 0;
  FOR v_band, v_ord IN SELECT e.value, (e.ord - 1)::integer FROM jsonb_array_elements(p_bands) WITH ORDINALITY e(value, ord)
      ORDER BY (e.value->>'weight_min')::numeric, e.ord LOOP
    v_min := (v_band->>'weight_min')::numeric::integer; v_max := (v_band->>'weight_max')::numeric::integer;
    IF v_prev_max IS NOT NULL AND v_min <= v_prev_max THEN
      RETURN warehouse_security.rate_failure('BANDS_OVERLAP', 'Weight bands overlap', jsonb_build_object('index', v_ord));
    END IF;
    IF p_customer_id IS NULL AND v_min <> v_expected THEN
      RETURN warehouse_security.rate_failure('BANDS_GAP', 'The default rate''s bands must start at 0 kg and follow on without gaps',
        jsonb_build_object('index', v_ord, 'expected_min', v_expected));
    END IF;
    v_prev_max := v_max; v_expected := v_max + 1;
  END LOOP;

  -- One change of this scope at a time.
  PERFORM pg_advisory_xact_lock(hashtextextended('item_rates:' || p_item_id || ':' || COALESCE(p_customer_id::text, 'default') || ':' || p_price_type, 0));
  PERFORM 1 FROM public.item_storage_prices r
   WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type FOR UPDATE;

  -- A rate that began today (or earlier) is changed by administrators and supervisors only,
  -- as delete_ and update_item_storage_price already require.
  IF v_role = 'staff' AND p_starts_on <= v_today AND EXISTS (
       SELECT 1 FROM public.item_storage_prices r
        WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
          AND r.effective_from = p_starts_on) THEN
    RETURN warehouse_security.rate_failure('RATE_IN_FORCE_MANAGER_ONLY', 'Only administrators and supervisors can change a rate that is already in force');
  END IF;

  -- A stale editor: p_seen_rows lists the row ids the editor loaded for this scope. A row this
  -- call would end, move or delete that is not in the list was added or changed by someone else
  -- since, so nothing is written (STALE_RATES; data.ids is the current set). NULL skips the check.
  IF p_seen_rows IS NOT NULL THEN
    v_from := LEAST(p_starts_on, COALESCE(p_move_from, p_starts_on));
    SELECT array_agg(r.id ORDER BY r.id) INTO v_unseen FROM public.item_storage_prices r
     WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
       AND r.id <> ALL (p_seen_rows)
       AND CASE WHEN p_mode = 'correct' THEN r.effective_from = p_starts_on
                ELSE r.effective_from >= v_from OR r.effective_to IS NULL OR r.effective_to >= v_from END;
    IF v_unseen IS NOT NULL THEN
      RETURN warehouse_security.rate_failure('STALE_RATES', 'The rates were changed by someone else; reload and try again',
        jsonb_build_object('ids', to_jsonb(v_unseen)));
    END IF;
  END IF;

  -- The writes sit in a block of their own, so a refusal after the first write undoes them all.
  BEGIN
    -- Move: undo the change that starts on p_move_from (as undo_rate_change does).
    IF p_move_from IS NOT NULL THEN
      WITH gone AS (
        DELETE FROM public.item_storage_prices r
         WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
           AND r.effective_from = p_move_from
        RETURNING r.id, r.effective_to)
      -- v_stop: the scheduled stop the planned rate carried (all its rows end on one day), if any.
      SELECT count(*),
             CASE WHEN count(*) FILTER (WHERE gone.effective_to IS NULL) = 0 AND count(DISTINCT gone.effective_to) = 1
                  THEN max(gone.effective_to) END
        INTO v_moved, v_stop FROM gone;
      IF v_moved = 0 THEN
        RAISE EXCEPTION 'rate_fail' USING ERRCODE = 'P0001',
          DETAIL = warehouse_security.rate_failure('NOTHING_TO_MOVE', 'There is no rate starting on that day to move')::text;
      END IF;
      SELECT min(r.effective_from) INTO v_next FROM public.item_storage_prices r
       WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
         AND r.effective_from >= p_move_from;
      WITH opened AS (
        UPDATE public.item_storage_prices r SET effective_to = COALESCE(v_next - 1, v_stop)
         WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
           AND r.effective_to = p_move_from - 1
        RETURNING r.id, r.effective_from, r.effective_to)
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', opened.id, 'effective_from', opened.effective_from, 'effective_to', opened.effective_to)
               ORDER BY opened.effective_from, opened.id), '[]'::jsonb) INTO v_reopened FROM opened;
    END IF;

    -- The rows in force on the start day: how many, how many start elsewhere, their last days.
    SELECT count(*), count(*) FILTER (WHERE r.effective_from <> p_starts_on),
           count(DISTINCT COALESCE(r.effective_to, 'infinity'::date)), max(r.effective_to), count(*) FILTER (WHERE r.effective_to IS NULL)
      INTO v_n_force, v_n_notstart, v_n_ends, v_end, v_n_open
      FROM public.item_storage_prices r
     WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
       AND r.effective_from <= p_starts_on AND (r.effective_to IS NULL OR r.effective_to >= p_starts_on);

    IF p_mode = 'correct' THEN
      IF v_n_force = 0 OR v_n_notstart > 0 THEN
        RAISE EXCEPTION 'rate_fail' USING ERRCODE = 'P0001',
          DETAIL = warehouse_security.rate_failure('NOT_A_RATE_START', 'A correction must use the day the rate in force began')::text;
      END IF;
      v_kept := CASE WHEN v_n_ends = 1 AND v_n_open = 0 THEN v_end ELSE NULL END;
      WITH gone AS (
        DELETE FROM public.item_storage_prices r
         WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
           AND r.effective_from = p_starts_on
        RETURNING r.id, r.effective_from)
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', gone.id, 'effective_from', gone.effective_from) ORDER BY gone.effective_from, gone.id), '[]'::jsonb)
        INTO v_removed FROM gone;
    ELSE
      -- Rates planned after the start day.
      SELECT jsonb_agg(jsonb_build_object('effective_from', r.effective_from, 'weight_min', r.weight_min, 'weight_max', r.weight_max, 'unit_price', r.unit_price)
               ORDER BY r.effective_from, r.weight_min) INTO v_later
        FROM public.item_storage_prices r
       WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type AND r.effective_from > p_starts_on;
      -- A rate planned (not begun) to start ON the start day is a later rate too: without
      -- p_replace_later it is refused, not silently deleted, unless new bands replace a planned
      -- rate that the editor listed in p_seen_rows. A rate in force from today or
      -- earlier on that day is the one being changed. (p_move_from has already removed the
      -- planned rate being moved.)
      IF NOT COALESCE(p_replace_later, false) THEN
        SELECT jsonb_agg(jsonb_build_object('effective_from', r.effective_from, 'weight_min', r.weight_min, 'weight_max', r.weight_max, 'unit_price', r.unit_price)
                 ORDER BY r.effective_from, r.weight_min) INTO v_planned
          FROM public.item_storage_prices r
         WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
           AND r.effective_from >= p_starts_on AND r.effective_from > v_today
           -- Replacing the planned rate that starts on the day is allowed with new bands when the
           -- editor listed that rate in p_seen_rows; a stop never replaces it silently.
           AND NOT (r.effective_from = p_starts_on AND jsonb_array_length(p_bands) > 0
                    AND p_seen_rows IS NOT NULL AND r.id = ANY (p_seen_rows));
        IF v_planned IS NOT NULL THEN
          RAISE EXCEPTION 'rate_fail' USING ERRCODE = 'P0001',
            DETAIL = warehouse_security.rate_failure('LATER_RATES_EXIST', 'A later rate is already planned', jsonb_build_object('later', v_planned))::text;
        END IF;
      END IF;
      -- A scheduled stop is kept when nothing starts later.
      v_kept := CASE WHEN v_later IS NULL AND v_n_force > 0 AND v_n_ends = 1 AND v_n_open = 0 THEN v_end ELSE NULL END;
      -- Later rows and rows that start on the start day go.
      WITH gone AS (
        DELETE FROM public.item_storage_prices r
         WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
           AND r.effective_from >= p_starts_on
        RETURNING r.id, r.effective_from)
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', gone.id, 'effective_from', gone.effective_from) ORDER BY gone.effective_from, gone.id), '[]'::jsonb)
        INTO v_removed FROM gone;
      -- Rows in force on the start day end the day before.
      WITH ended AS (
        UPDATE public.item_storage_prices r SET effective_to = p_starts_on - 1
         WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
           AND r.effective_from < p_starts_on AND (r.effective_to IS NULL OR r.effective_to >= p_starts_on)
        RETURNING r.id, r.effective_from, r.effective_to)
      SELECT COALESCE(jsonb_agg(jsonb_build_object('id', ended.id, 'effective_from', ended.effective_from, 'effective_to', ended.effective_to)
               ORDER BY ended.effective_from, ended.id), '[]'::jsonb) INTO v_ended FROM ended;

      IF jsonb_array_length(p_bands) = 0 AND jsonb_array_length(v_removed) = 0 AND jsonb_array_length(v_ended) = 0 THEN
        RAISE EXCEPTION 'rate_fail' USING ERRCODE = 'P0001',
          DETAIL = warehouse_security.rate_failure('NOTHING_TO_STOP', 'There is no rate in force on that day to stop')::text;
      END IF;
    END IF;

    FOR v_band IN SELECT e.value FROM jsonb_array_elements(p_bands) WITH ORDINALITY e(value, ord)
        ORDER BY (e.value->>'weight_min')::numeric, e.ord LOOP
      INSERT INTO public.item_storage_prices (
        item_id, customer_id, price_type, unit_price, weight_min, weight_max, labour_rate, tax_percent,
        effective_from, effective_to, created_by, unit_price_one_time, unit_price_monthly)
      VALUES (
        p_item_id, p_customer_id, p_price_type, (v_band->>'unit_price')::numeric,
        (v_band->>'weight_min')::numeric::integer, (v_band->>'weight_max')::numeric::integer,
        CASE WHEN p_price_type = 'one_time' THEN 0 ELSE (v_band->>'labour_rate')::numeric END,
        (v_band->>'tax_percent')::numeric, p_starts_on, v_kept, v_profile,
        CASE WHEN p_price_type = 'one_time' THEN (v_band->>'unit_price')::numeric ELSE 0 END,
        CASE WHEN p_price_type = 'monthly' THEN (v_band->>'unit_price')::numeric ELSE 0 END)
      RETURNING * INTO v_new;
      v_added := v_added || jsonb_build_array(jsonb_build_object('id', v_new.id, 'weight_min', v_new.weight_min,
        'weight_max', v_new.weight_max, 'unit_price', v_new.unit_price, 'labour_rate', v_new.labour_rate, 'tax_percent', v_new.tax_percent));
    END LOOP;

    -- Nothing the call added may overlap another row of the scope.
    FOR v_row IN SELECT r.id, r.weight_min, r.weight_max, r.effective_from, r.effective_to FROM public.item_storage_prices r
        WHERE r.id IN (SELECT (e->>'id')::uuid FROM jsonb_array_elements(v_added) e) LOOP
      IF warehouse_security.price_rows_overlap(p_item_id, p_customer_id, p_price_type,
           v_row.weight_min, v_row.weight_max, v_row.effective_from, v_row.effective_to, v_row.id) THEN
        RAISE EXCEPTION 'rate_fail' USING ERRCODE = 'P0001',
          DETAIL = warehouse_security.rate_failure('BANDS_OVERLAP', 'Weight bands overlap')::text;
      END IF;
    END LOOP;
  EXCEPTION WHEN SQLSTATE 'P0001' THEN
    IF SQLERRM = 'rate_fail' THEN
      GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
      RETURN v_detail::jsonb;
    END IF;
    RAISE;
  END;

  RETURN jsonb_build_object('success', true, 'message', 'Rates saved', 'data', jsonb_build_object(
    'item_id', p_item_id, 'customer_id', p_customer_id, 'price_type', p_price_type, 'starts_on', p_starts_on,
    'mode', p_mode, 'move_from', p_move_from, 'kept_end', v_kept,
    'ended', v_ended, 'removed', v_removed, 'reopened', v_reopened, 'added', v_added));
END;
$$;

ALTER FUNCTION public.replace_item_rates(p_item_id uuid, p_customer_id uuid, p_price_type text, p_starts_on date, p_bands jsonb, p_replace_later boolean, p_mode text, p_move_from date, p_seen_rows uuid[]) OWNER TO supabase_admin;

--
-- Name: reset_grn_invoiced_flag(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.reset_grn_invoiced_flag() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Reset invoiced flag to false for the GRN that was associated with the deleted invoice
    UPDATE goodsreceived
    SET invoiced = false
    WHERE id = OLD.gr_id;

    -- Log the reset action (optional - for audit purposes)
    RAISE NOTICE 'Invoice deleted: %, GRN % invoiced flag reset to false', OLD.inv_no, OLD.gr_no;

    RETURN OLD;
END;
$$;

ALTER FUNCTION public.reset_grn_invoiced_flag() OWNER TO supabase_admin;

--
-- Name: resolve_auto_invoice_error(uuid, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.resolve_auto_invoice_error(p_error_id uuid, p_resolution_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_id UUID;
      v_error_record RECORD;
  BEGIN
      -- Get current user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

      -- Check if error exists
      SELECT * INTO v_error_record FROM auto_invoice_errors WHERE id = p_error_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Error record not found'
          );
      END IF;

      -- Check if already resolved
      IF v_error_record.resolved_at IS NOT NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Error already resolved'
          );
      END IF;

      -- Mark as resolved
      UPDATE auto_invoice_errors
      SET resolved_at = NOW(),
          resolved_by = v_user_id,
          error_details = COALESCE(error_details, '{}'::jsonb) ||
                         jsonb_build_object('resolution_notes', p_resolution_notes)
      WHERE id = p_error_id;

      RETURN jsonb_build_object(
          'success', true,
          'error_id', p_error_id,
          'resolved_at', NOW(),
          'resolved_by', v_user_id,
          'message', 'Error resolved successfully'
      );
  END;
  $$;

ALTER FUNCTION public.resolve_auto_invoice_error(p_error_id uuid, p_resolution_notes text) OWNER TO supabase_admin;

--
-- Name: resolve_auto_invoice_errors_by_grn(uuid, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.resolve_auto_invoice_errors_by_grn(p_gr_id uuid, p_invoice_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_id UUID;
      v_resolved_count INTEGER := 0;
      v_invoice_creation_time TIMESTAMPTZ;
      v_invoice_number VARCHAR(20);
  BEGIN
      -- Get current user
      SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

      -- If invoice_id is provided, get invoice details
      IF p_invoice_id IS NOT NULL THEN
          SELECT inv_date, inv_no INTO v_invoice_creation_time, v_invoice_number
          FROM invoice
          WHERE id = p_invoice_id;

          IF NOT FOUND THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'error', 'Invoice not found',
                  'invoice_id', p_invoice_id
              );
          END IF;
      ELSE
          -- Use current timestamp for manual resolution
          v_invoice_creation_time := NOW();
          v_invoice_number := NULL;
      END IF;

      -- Check if there are any unresolved errors for this GRN
      SELECT COUNT(*) INTO v_resolved_count
      FROM auto_invoice_errors
      WHERE gr_id = p_gr_id
      AND resolved_at IS NULL;

      -- If no errors found, return early
      IF v_resolved_count = 0 THEN
          RETURN jsonb_build_object(
              'success', true,
              'resolved_count', 0,
              'message', 'No unresolved errors found for this GRN'
          );
      END IF;

      -- Mark all related errors as resolved
      UPDATE auto_invoice_errors
      SET
          resolved_at = v_invoice_creation_time,
          resolved_invoice_id = p_invoice_id,
          error_details = COALESCE(error_details, '{}')::jsonb ||
                         jsonb_build_object(
                             'resolution_type', CASE
                                 WHEN p_invoice_id IS NOT NULL THEN 'manual_invoice_created'
                                 ELSE 'manual_resolution'
                             END,
                             'resolution_notes', CASE
                                 WHEN p_invoice_id IS NOT NULL THEN 'Invoice created manually through edit invoice route'
                                 ELSE 'Error manually resolved by supervisor'
                             END,
                             'invoice_id', p_invoice_id,
                             'invoice_number', v_invoice_number,
                             'invoice_date', v_invoice_creation_time,
                             'gr_id', p_gr_id,
                             'resolved_by_user', v_user_id
                         )
      WHERE gr_id = p_gr_id
      AND resolved_at IS NULL;

      -- Get count of resolved errors
      GET DIAGNOSTICS v_resolved_count = ROW_COUNT;

      RETURN jsonb_build_object(
          'success', true,
          'resolved_count', v_resolved_count,
          'gr_id', p_gr_id,
          'invoice_id', p_invoice_id,
          'invoice_number', v_invoice_number,
          'message', format('%s auto-invoice errors resolved for GRN', v_resolved_count)
      );
  END;
  $$;

ALTER FUNCTION public.resolve_auto_invoice_errors_by_grn(p_gr_id uuid, p_invoice_id uuid) OWNER TO supabase_admin;

--
-- Name: restore_cart_quantities_from_dispatch(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.restore_cart_quantities_from_dispatch(p_dispatch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_dispatch_record RECORD;
      v_updates_made INTEGER := 0;
      v_restoration_details JSONB := '[]'::JSONB;
      v_restoration_record JSONB;
  BEGIN
      -- Get dispatch info for validation
      SELECT d.id, d.disp_no, d.source_order_id, d.source_order_no
      INTO v_dispatch_record
      FROM dispatch d
      WHERE d.id = p_dispatch_id;

      IF NOT FOUND THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Dispatch not found',
              'updates_made', 0,
              'restoration_details', '[]'::jsonb
          );
      END IF;

      -- Only process if this dispatch was linked to an order
      IF v_dispatch_record.source_order_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', true,
              'message', 'No cart quantities to restore - dispatch was not from cart',
              'updates_made', 0,
              'restoration_details', '[]'::jsonb
          );
      END IF;

      -- Restore cart quantities for items that came from cart
      FOR v_restoration_record IN
          SELECT
              oi.id as order_item_id,
              oi.order_id,
              oi.grn_items_item_name,
              oi.requested_quantity,
              oi.fulfilled_quantity as current_fulfilled,
              dt.cart_quantity_consumed,
              GREATEST(0, oi.fulfilled_quantity - dt.cart_quantity_consumed) as new_fulfilled_quantity
          FROM order_items oi
          INNER JOIN dispatch_trl dt ON dt.source_order_item_id = oi.id
          WHERE dt.disp_id = p_dispatch_id
          AND dt.source_type = 'cart'
          AND dt.source_order_item_id IS NOT NULL
          AND dt.cart_quantity_consumed > 0
      LOOP
          -- Update the order item quantities atomically
          UPDATE order_items
          SET (fulfilled_quantity, item_status, revisions, updated_at) = (
              v_restoration_record.new_fulfilled_quantity,
              CASE
                  WHEN v_restoration_record.new_fulfilled_quantity = 0 THEN 'pending'
                  WHEN v_restoration_record.new_fulfilled_quantity < requested_quantity THEN 'partial'
                  ELSE 'fulfilled'
              END,
              COALESCE(revisions, '[]'::jsonb) || jsonb_build_object(
                  'action', 'quantity_restored',
                  'timestamp', NOW(),
                  'dispatch_id', p_dispatch_id,
                  'quantity_restored', v_restoration_record.cart_quantity_consumed,
                  'previous_fulfilled_qty', v_restoration_record.current_fulfilled,
                  'new_fulfilled_qty', v_restoration_record.new_fulfilled_quantity,
                  'reason', 'Dispatch deleted - restoring cart to original state'
              ),
              NOW()
          )
          WHERE id = v_restoration_record.order_item_id;

          v_updates_made := v_updates_made + 1;

          -- Build restoration details for response
          v_restoration_details := v_restoration_details || jsonb_build_object(
              'order_item_id', v_restoration_record.order_item_id,
              'item_name', v_restoration_record.grn_items_item_name,
              'quantity_restored', v_restoration_record.cart_quantity_consumed,
              'previous_fulfilled', v_restoration_record.current_fulfilled,
              'new_fulfilled', v_restoration_record.new_fulfilled_quantity
          );
      END LOOP;

      -- ✅ ADD THIS: Update parent order timestamp after restoring cart quantities
      IF v_updates_made > 0 THEN
          UPDATE orders
          SET updated_at = NOW()
          WHERE id = v_dispatch_record.source_order_id;
      END IF;

      RETURN jsonb_build_object(
          'success', true,
          'message', format('Successfully restored cart quantities for %s items from dispatch %s',
                           v_updates_made, v_dispatch_record.disp_no),
          'updates_made', v_updates_made,
          'restoration_details', v_restoration_details,
          'dispatch_id', p_dispatch_id,
          'source_order_id', v_dispatch_record.source_order_id
      );

  EXCEPTION
      WHEN OTHERS THEN
          RAISE EXCEPTION 'Error restoring cart quantities: %', SQLERRM;
  END;
  $$;

ALTER FUNCTION public.restore_cart_quantities_from_dispatch(p_dispatch_id uuid) OWNER TO supabase_admin;

--
-- Name: restore_customer(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.restore_customer(p_customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_customer_name VARCHAR(100);
BEGIN
  PERFORM warehouse_security.authorize_rpc('restore_customer',jsonb_build_object('p_customer_id',p_customer_id));
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
    SELECT name INTO v_customer_name
    FROM customers
    WHERE id = p_customer_id AND (deleted_at IS NOT NULL OR active = FALSE);

    IF v_customer_name IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Customer not found or not deleted');
    END IF;

    UPDATE customers
    SET deleted_at = NULL, deleted_by = NULL, active = TRUE
    WHERE id = p_customer_id;

    RETURN jsonb_build_object(
        'success', TRUE,
        'message', format('Customer "%s" restored successfully', v_customer_name),
        'restored_at', NOW()
    );
END;
$$;

