--
-- Name: restore_stock_on_dispatch_delete(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.restore_stock_on_dispatch_delete() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Restore stock for all items in this dispatch (capped at qty), and log
    -- what each lot really got back (migration 67): the stock before and after
    -- the restore, and their difference, which is less than the dispatched
    -- quantity when the cap applies. before_gt is read before the UPDATE.
    WITH restored AS (
        UPDATE goodsreceived_trl gt
        SET stock = LEAST(gt.qty, gt.stock + dt.disp_qty)  -- Cap at qty
        FROM dispatch_trl dt
        JOIN goodsreceived_trl before_gt ON before_gt.id = dt.gr_trl_id
        WHERE dt.disp_id = OLD.id
        AND gt.id = dt.gr_trl_id
        RETURNING gt.id AS gr_trl_id, before_gt.stock AS old_stock, gt.stock AS new_stock
    )
    INSERT INTO stock_movements (
        gr_trl_id, movement_type, quantity,
        reference_id, reference_type,
        balance_before, balance_after, notes
    )
    SELECT
        r.gr_trl_id,
        'return',
        r.new_stock - r.old_stock,
        OLD.id,
        'dispatch_delete',
        r.old_stock,
        r.new_stock,
        'Stock restored due to dispatch deletion'
    FROM restored r
    WHERE r.new_stock > r.old_stock;

    -- Delete dispatch_trl records
    DELETE FROM dispatch_trl WHERE disp_id = OLD.id;

    -- Restore source order if exists
    IF OLD.source_order_id IS NOT NULL THEN
        UPDATE orders
        SET
            status = 'OPEN',
            updated_at = NOW()
        WHERE id = OLD.source_order_id;

        -- Reset order items to pending
        UPDATE order_items
        SET
            fulfilled_quantity = 0,
            item_status = 'pending',
            updated_at = NOW()
        WHERE order_id = OLD.source_order_id;
    END IF;

    RETURN OLD;
END;
$$;

ALTER FUNCTION public.restore_stock_on_dispatch_delete() OWNER TO supabase_admin;

--
-- Name: safe_delete_customer(uuid, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.safe_delete_customer(p_customer_id uuid, p_permanent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_customer_name VARCHAR(100);
    v_grn_count INTEGER;
    v_dispatch_count INTEGER;
    v_invoice_count INTEGER;
    v_active_stock_count INTEGER;
    v_current_user_id UUID;
    v_user_profile_id UUID;
BEGIN
  PERFORM warehouse_security.authorize_rpc('safe_delete_customer',jsonb_build_object('p_customer_id',p_customer_id));
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
    -- Get current auth user
    SELECT auth.uid() INTO v_current_user_id;

    IF v_current_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Authentication required'
        );
    END IF;

    -- Look up user_profiles.id from auth_user_id (for FK constraint)
    SELECT id INTO v_user_profile_id
    FROM user_profiles
    WHERE auth_user_id = v_current_user_id;

    -- Check if customer exists and is not already deleted
    SELECT name INTO v_customer_name
    FROM customers
    WHERE id = p_customer_id AND deleted_at IS NULL;

    IF v_customer_name IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Customer not found or already deleted'
        );
    END IF;

    -- Nothing with data is ever deleted (migration 82).
    DECLARE
        v_rel jsonb;
    BEGIN
        SELECT jsonb_build_object(
            'grn_count', (SELECT COUNT(*) FROM goodsreceived WHERE customer_id = p_customer_id),
            'dispatch_count', (SELECT COUNT(*) FROM dispatch WHERE customer_id = p_customer_id),
            'invoice_count', (SELECT COUNT(*) FROM invoice WHERE customer_id = p_customer_id),
            'order_count', (SELECT COUNT(*) FROM orders o WHERE o.customer_id = p_customer_id
                            AND (o.status <> 'OPEN' OR EXISTS (SELECT 1 FROM order_items oi WHERE oi.order_id = o.id))),
            'payment_count', (SELECT COUNT(*) FROM payments WHERE customer_id = p_customer_id),
            'rate_count', (SELECT COUNT(*) FROM item_storage_prices WHERE customer_id = p_customer_id),
            'assignment_count', (SELECT COUNT(*) FROM users_customers_new WHERE customer_id = p_customer_id AND active)
        ) INTO v_rel;
        IF EXISTS (SELECT 1 FROM jsonb_each_text(v_rel) WHERE value::bigint > 0) THEN
            IF NOT p_permanent THEN
                UPDATE customers SET active = FALSE, updated_at = NOW(), updated_by = v_user_profile_id
                WHERE id = p_customer_id;
                RETURN jsonb_build_object(
                    'success', TRUE,
                    'message', format('"%s" has records, so it was deactivated instead of deleted.', v_customer_name),
                    'delete_type', 'deactivated',
                    'related_records', v_rel
                );
            END IF;
            RETURN jsonb_build_object(
                'success', FALSE,
                'message', format('Cannot delete "%s": it has GRNs, dispatches, invoices, payments, rates, linked users or orders. Deactivate it instead.', v_customer_name),
                'related_records', v_rel
            );
        END IF;
        IF p_permanent THEN
            -- Only empty OPEN carts and switched-off assignments are left: they go with a permanent delete.
            DELETE FROM orders WHERE customer_id = p_customer_id AND status = 'OPEN';
            DELETE FROM users_customers_new WHERE customer_id = p_customer_id;
        END IF;
    END;

    -- Check for active stock (items with stock > 0)
    SELECT COUNT(*) INTO v_active_stock_count
    FROM goodsreceived_trl grt
    JOIN goodsreceived gr ON gr.id = grt.gr_id
    WHERE gr.customer_id = p_customer_id
      AND gr.deleted_at IS NULL
      AND grt.stock > 0;

    IF v_active_stock_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot deactivate customer "%s". Customer has %s item(s) with active stock. Please dispatch all stock first.',
                v_customer_name, v_active_stock_count),
            'active_stock_count', v_active_stock_count
        );
    END IF;

    -- Check for related records
    SELECT
        COUNT(DISTINCT gr.id),
        COUNT(DISTINCT d.id),
        COUNT(DISTINCT i.id)
    INTO v_grn_count, v_dispatch_count, v_invoice_count
    FROM customers c
    LEFT JOIN goodsreceived gr ON gr.customer_id = c.id AND gr.deleted_at IS NULL
    LEFT JOIN dispatch d ON d.customer_id = c.id AND d.deleted_at IS NULL
    LEFT JOIN invoice i ON i.customer_id = c.id AND i.deleted_at IS NULL
    WHERE c.id = p_customer_id;

    -- If permanent delete requested and has relationships, block it
    IF p_permanent AND (v_grn_count > 0 OR v_dispatch_count > 0 OR v_invoice_count > 0) THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot permanently delete customer "%s". Has %s GRNs, %s dispatches, %s invoices. Use soft delete instead.',
                v_customer_name, v_grn_count, v_dispatch_count, v_invoice_count),
            'related_records', jsonb_build_object(
                'grn_count', v_grn_count,
                'dispatch_count', v_dispatch_count,
                'invoice_count', v_invoice_count
            )
        );
    END IF;

    -- Perform soft delete
    IF NOT p_permanent THEN
        UPDATE customers
        SET
            deleted_at = NOW(),
            deleted_by = v_user_profile_id,
            active = FALSE
        WHERE id = p_customer_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('Customer "%s" soft deleted successfully', v_customer_name),
            'delete_type', 'soft',
            'deleted_at', NOW(),
            'related_records', jsonb_build_object(
                'grn_count', v_grn_count,
                'dispatch_count', v_dispatch_count,
                'invoice_count', v_invoice_count
            )
        );
    ELSE
        -- Permanent delete (only if no relationships)
        DELETE FROM customers WHERE id = p_customer_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('Customer "%s" permanently deleted', v_customer_name),
            'delete_type', 'permanent'
        );
    END IF;
END;
$$;

ALTER FUNCTION public.safe_delete_customer(p_customer_id uuid, p_permanent boolean) OWNER TO supabase_admin;

--
-- Name: safe_delete_dispatch(uuid, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.safe_delete_dispatch(p_dispatch_id uuid, p_permanent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_disp_no VARCHAR(50);
    v_invoice_count INTEGER;
    v_items_count INTEGER;
    v_current_user_id UUID;
BEGIN
    SELECT auth.uid() INTO v_current_user_id;

    IF v_current_user_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Authentication required');
    END IF;

    SELECT disp_no INTO v_disp_no
    FROM dispatch
    WHERE id = p_dispatch_id AND deleted_at IS NULL;

    IF v_disp_no IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'message', 'Dispatch not found or already deleted');
    END IF;

    -- Check for invoices
    SELECT
        COUNT(DISTINCT it.invoice_id),
        COUNT(DISTINCT dt.id)
    INTO v_invoice_count, v_items_count
    FROM dispatch d
    LEFT JOIN dispatch_trl dt ON dt.disp_id = d.id
    LEFT JOIN invoice_trl it ON it.disp_trl_id = dt.id
    WHERE d.id = p_dispatch_id;

    IF v_invoice_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot delete dispatch "%s". Has %s invoices. Delete invoices first.', v_disp_no, v_invoice_count)
        );
    END IF;

    IF NOT p_permanent THEN
        UPDATE dispatch SET deleted_at = NOW(), deleted_by = v_current_user_id WHERE id = p_dispatch_id;
        RETURN jsonb_build_object('success', TRUE, 'message', format('Dispatch "%s" soft deleted', v_disp_no), 'delete_type', 'soft');
    ELSE
        DELETE FROM dispatch WHERE id = p_dispatch_id;
        RETURN jsonb_build_object('success', TRUE, 'message', format('Dispatch "%s" permanently deleted', v_disp_no), 'delete_type', 'permanent');
    END IF;
END;
$$;

ALTER FUNCTION public.safe_delete_dispatch(p_dispatch_id uuid, p_permanent boolean) OWNER TO supabase_admin;

--
-- Name: safe_delete_grn(uuid, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.safe_delete_grn(p_grn_id uuid, p_permanent boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_grn_no VARCHAR(50);
    v_dispatch_count INTEGER;
    v_invoice_count INTEGER;
    v_items_count INTEGER;
    v_current_user_id UUID;
BEGIN
    -- Get current user
    SELECT auth.uid() INTO v_current_user_id;

    IF v_current_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'Authentication required'
        );
    END IF;

    -- Check if GRN exists and is not already deleted
    SELECT gr_no INTO v_grn_no
    FROM goodsreceived
    WHERE id = p_grn_id AND deleted_at IS NULL;

    IF v_grn_no IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', 'GRN not found or already deleted'
        );
    END IF;

    -- Check for related records
    SELECT
        COUNT(DISTINCT dt.disp_id),
        COUNT(DISTINCT it.invoice_id),
        COUNT(DISTINCT grt.id)
    INTO v_dispatch_count, v_invoice_count, v_items_count
    FROM goodsreceived gr
    LEFT JOIN goodsreceived_trl grt ON grt.gr_id = gr.id
    LEFT JOIN dispatch_trl dt ON dt.gr_id = gr.id
    LEFT JOIN invoice_trl it ON it.grn_item_id = grt.id
    WHERE gr.id = p_grn_id;

    -- If has dispatches or invoices, cannot delete
    IF v_dispatch_count > 0 OR v_invoice_count > 0 THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'message', format('Cannot delete GRN "%s". Has %s dispatches and %s invoices. These must be deleted first.',
                v_grn_no, v_dispatch_count, v_invoice_count),
            'related_records', jsonb_build_object(
                'dispatch_count', v_dispatch_count,
                'invoice_count', v_invoice_count,
                'items_count', v_items_count
            )
        );
    END IF;

    -- Perform soft delete
    IF NOT p_permanent THEN
        UPDATE goodsreceived
        SET
            deleted_at = NOW(),
            deleted_by = v_current_user_id
        WHERE id = p_grn_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('GRN "%s" soft deleted successfully', v_grn_no),
            'delete_type', 'soft',
            'deleted_at', NOW(),
            'items_count', v_items_count
        );
    ELSE
        -- Permanent delete (CASCADE will handle goodsreceived_trl and grn_images)
        DELETE FROM goodsreceived WHERE id = p_grn_id;

        RETURN jsonb_build_object(
            'success', TRUE,
            'message', format('GRN "%s" permanently deleted (including %s items)', v_grn_no, v_items_count),
            'delete_type', 'permanent'
        );
    END IF;
END;
$$;

ALTER FUNCTION public.safe_delete_grn(p_grn_id uuid, p_permanent boolean) OWNER TO supabase_admin;

--
-- Name: safe_disable_grn_trl_triggers(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.safe_disable_grn_trl_triggers() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Only disable triggers that actually exist
    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mark_stock_mvs_dirty_grn' AND tgrelid = 'goodsreceived_trl'::regclass) THEN
        ALTER TABLE goodsreceived_trl DISABLE TRIGGER trg_mark_stock_mvs_dirty_grn;
    END IF;
END;
$$;

ALTER FUNCTION public.safe_disable_grn_trl_triggers() OWNER TO supabase_admin;

--
-- Name: safe_enable_grn_trl_triggers(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.safe_enable_grn_trl_triggers() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
    -- Only enable triggers that actually exist
    IF EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'trg_mark_stock_mvs_dirty_grn' AND tgrelid = 'goodsreceived_trl'::regclass) THEN
        ALTER TABLE goodsreceived_trl ENABLE TRIGGER trg_mark_stock_mvs_dirty_grn;
    END IF;
END;
$$;

ALTER FUNCTION public.safe_enable_grn_trl_triggers() OWNER TO supabase_admin;

--
-- Name: save_grn(character varying, timestamp with time zone, uuid, character varying, uuid, character varying, uuid, character varying, character varying, character varying, boolean, character varying, jsonb, jsonb, text, character varying, jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.save_grn(p_gr_no character varying, p_date timestamp with time zone, p_customer_id uuid, p_customer_name character varying, p_sender_id uuid DEFAULT NULL::uuid, p_sender_name character varying DEFAULT NULL::character varying, p_supervisor_id uuid DEFAULT NULL::uuid, p_supervisor_name character varying DEFAULT NULL::character varying, p_registration character varying DEFAULT NULL::character varying, p_note character varying DEFAULT NULL::character varying, p_leon boolean DEFAULT false, p_pricing_mode character varying DEFAULT NULL::character varying, p_items jsonb DEFAULT '[]'::jsonb, p_images jsonb DEFAULT '[]'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_duration_mode character varying DEFAULT 'legacy'::character varying, p_rates jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    SET jit TO 'off'
    AS $$
  DECLARE
      v_user_id uuid;
      v_user_profile_id uuid;
      v_user_role text;
      v_grn_id uuid;
      v_item_id uuid;
      v_item jsonb;
      v_image jsonb;
      v_image_id uuid;
      v_item_ids uuid[] := '{}';
      v_image_ids uuid[] := '{}';
      v_items_created int := 0;
      v_images_saved int := 0;
      v_item_index int;
      v_item_mapping jsonb := '[]'::jsonb;
      v_cached_response jsonb;
      v_result jsonb;
      v_rate_failure jsonb;
      v_detail text;
BEGIN
  PERFORM warehouse_security.authorize_rpc('save_grn',jsonb_build_object('p_customer_id',p_customer_id));
  -- Migration 90: rates typed on the GRN sheet are an administrator's or a supervisor's.
  IF p_rates IS NOT NULL AND warehouse_security.active_role() = 'staff' THEN
    RETURN warehouse_security.rate_failure('RATES_MANAGER_ONLY', 'Only administrators and supervisors can set rates on a GRN');
  END IF;
  -- Migration 95: a line's name and packaging fit the receipt columns (80 and 40 characters, as the catalog).
  IF jsonb_typeof(p_items) = 'array' THEN
    v_item_index := 0;
    FOR v_item IN SELECT e FROM jsonb_array_elements(p_items) AS e LOOP
      IF jsonb_typeof(v_item->'item_name') = 'string' AND char_length(v_item->>'item_name') > 80 THEN
        RETURN warehouse_security.grn_rate_failure('item_name_too_long',
          'An item name can have at most 80 characters', jsonb_build_object('limit', 80, 'index', v_item_index));
      END IF;
      IF jsonb_typeof(v_item->'packaging') = 'string' AND char_length(v_item->>'packaging') > 40 THEN
        RETURN warehouse_security.grn_rate_failure('packaging_too_long',
          'Packaging can have at most 40 characters', jsonb_build_object('limit', 40, 'index', v_item_index));
      END IF;
      v_item_index := v_item_index + 1;
    END LOOP;
  END IF;
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
      -- IDEMPOTENCY CHECK: Return cached response if key exists
      IF p_idempotency_key IS NOT NULL THEN
          SELECT response INTO v_cached_response
          FROM idempotency_keys
          WHERE idempotency_key = p_idempotency_key
            AND rpc_function = 'save_grn'
            AND created_by = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid())
            AND expires_at > now();

          IF v_cached_response IS NOT NULL THEN
              RETURN v_cached_response || jsonb_build_object('idempotent', true);
          END IF;
      END IF;

      v_user_id := auth.uid();

      IF v_user_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Authentication required'
          );
      END IF;

      SELECT id, role INTO v_user_profile_id, v_user_role
      FROM user_profiles
      WHERE auth_user_id = v_user_id;

      IF v_user_profile_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'User profile not found'
          );
      END IF;

      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Insufficient permissions. Only admin and supervisor can create GRNs'
          );
      END IF;

      PERFORM warehouse_security.require_person_supervisor(p_supervisor_id::text);

      IF EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id AND deleted_at IS NOT NULL) THEN
          RAISE EXCEPTION 'Business is not active' USING ERRCODE = 'P0001';
      END IF;

      IF EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id AND active = false) THEN
          RAISE EXCEPTION 'This business is deactivated. Activate it in Customers to receive new goods.' USING ERRCODE = 'P0001';
      END IF;

      IF warehouse_security.is_blank_text(p_gr_no) OR p_date IS NULL OR p_customer_id IS NULL THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'Missing required parameters: gr_no, date, and customer_id are required'
          );
      END IF;

      IF EXISTS (SELECT 1 FROM goodsreceived WHERE gr_no = p_gr_no) THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'GRN number already exists: ' || p_gr_no
          );
      END IF;

      IF jsonb_array_length(p_items) = 0 THEN
          RETURN jsonb_build_object(
              'success', false,
              'message', 'At least one item is required'
          );
      END IF;

      BEGIN
          INSERT INTO goodsreceived (
              gr_no,
              date,
              customer_id,
              customer_name,
              sender_id,
              sender_name,
              supervisor_id,
              supervisor_name,
              registration,
              note,
              leon,
              pricing_mode,
              duration_mode,
              out_of_stock,
              invoiced,
              created_by,
              updated_by
          ) VALUES (
              p_gr_no,
              p_date,
              p_customer_id,
              COALESCE((SELECT name FROM customers WHERE id = p_customer_id), p_customer_name),
              p_sender_id,
              p_sender_name,
              p_supervisor_id,
              p_supervisor_name,
              p_registration,
              p_note,
              COALESCE(p_leon, false),
              p_pricing_mode,
              COALESCE(p_duration_mode, 'legacy'),
              false,
              false,
              v_user_profile_id,
              v_user_profile_id
          ) RETURNING id INTO v_grn_id;

          v_item_index := 0;
          FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
          LOOP
              IF v_item->>'item_name' IS NULL OR (v_item->>'qty')::int IS NULL THEN
                  RAISE EXCEPTION 'Invalid item data: item_name and qty are required for item at index %', v_item_index;
              END IF;
              IF (v_item->>'qty')::int <= 0 THEN
                  RAISE EXCEPTION 'Quantity must be greater than 0 for item at index %', v_item_index;
              END IF;
              IF (v_item->>'weight')::int < 0 THEN
                  RAISE EXCEPTION 'Weight cannot be negative for item at index %', v_item_index;
              END IF;

              INSERT INTO goodsreceived_trl (
                  gr_id,
                  item_id,
                  item_name,
                  packaging,
                  qty,
                  stock,
                  weight,
                  rack,
                  package_mark
              ) VALUES (
                  v_grn_id,
                  (v_item->>'item_id')::uuid,
                  v_item->>'item_name',
                  v_item->>'packaging',
                  (v_item->>'qty')::int,
                  (v_item->>'qty')::int,
                  COALESCE((v_item->>'weight')::int, 0),
                  v_item->>'rack',
                  v_item->>'package_mark'
              ) RETURNING id INTO v_item_id;

              v_item_ids := array_append(v_item_ids, v_item_id);
              v_items_created := v_items_created + 1;

              v_item_mapping := v_item_mapping || jsonb_build_object(
                  'index', v_item_index,
                  'item_id', v_item_id,
                  'item_name', v_item->>'item_name'
              );

              v_item_index := v_item_index + 1;
          END LOOP;

          IF jsonb_array_length(p_images) > 0 THEN
              FOR v_image IN SELECT * FROM jsonb_array_elements(p_images)
              LOOP
                  IF v_image->>'storage_path' IS NULL OR v_image->>'image_type' IS NULL THEN
                      RAISE EXCEPTION 'Invalid image data: storage_path and image_type are required';
                  END IF;

                  v_image_id := gen_random_uuid();

                  PERFORM warehouse_security.require_image_path('grn', v_grn_id, v_image->>'image_type', v_image->>'storage_path');

                  IF v_image->>'image_type' = 'item' THEN
                      IF v_image->>'item_index' IS NOT NULL THEN
                          IF (v_image->>'item_index')::int < 0 OR
                             (v_image->>'item_index')::int >= jsonb_array_length(p_items) THEN
                              RAISE EXCEPTION 'Invalid item_index % for image. Must be between 0 and %',
                                  v_image->>'item_index', jsonb_array_length(p_items) - 1;
                          END IF;

                          v_item_id := v_item_ids[(v_image->>'item_index')::int + 1];

                          INSERT INTO grn_images (
                              id, grn_id, grn_item_id, image_type, storage_path,
                              original_filename, file_size, mime_type, uploaded_by, status
                          ) VALUES (
                              v_image_id, v_grn_id, v_item_id, v_image->>'image_type',
                              v_image->>'storage_path',
                              COALESCE(v_image->>'original_filename', 'unknown'),
                              COALESCE((v_image->>'file_size')::int, 0),
                              COALESCE(v_image->>'mime_type', 'image/jpeg'),
                              v_user_profile_id, 'confirmed'
                          );
                      ELSIF v_image->>'grn_item_id' IS NOT NULL THEN
                          IF NOT EXISTS (SELECT 1 FROM goodsreceived_trl
                              WHERE id = (v_image->>'grn_item_id')::uuid AND gr_id = v_grn_id) THEN
                              RAISE EXCEPTION 'Image line does not belong to this GRN';
                          END IF;
                          INSERT INTO grn_images (
                              id, grn_id, grn_item_id, image_type, storage_path,
                              original_filename, file_size, mime_type, uploaded_by, status
                          ) VALUES (
                              v_image_id, v_grn_id, (v_image->>'grn_item_id')::uuid,
                              v_image->>'image_type', v_image->>'storage_path',
                              COALESCE(v_image->>'original_filename', 'unknown'),
                              COALESCE((v_image->>'file_size')::int, 0),
                              COALESCE(v_image->>'mime_type', 'image/jpeg'),
                              v_user_profile_id, 'confirmed'
                          );
                      ELSE
                          RAISE EXCEPTION 'Item images must have either item_index or grn_item_id';
                      END IF;
                  ELSE
                      INSERT INTO grn_images (
                          id, grn_id, grn_item_id, image_type, storage_path,
                          original_filename, file_size, mime_type, uploaded_by, status
                      ) VALUES (
                          v_image_id, v_grn_id, NULL, v_image->>'image_type',
                          v_image->>'storage_path',
                          COALESCE(v_image->>'original_filename', 'unknown'),
                          COALESCE((v_image->>'file_size')::int, 0),
                          COALESCE(v_image->>'mime_type', 'image/jpeg'),
                          v_user_profile_id, 'confirmed'
                      );
                  END IF;

                  v_image_ids := array_append(v_image_ids, v_image_id);
                  v_images_saved := v_images_saved + 1;
              END LOOP;
          END IF;

          -- Rates typed on the GRN sheet (migration 86). A failure undoes the GRN with it: the
          -- raise leaves this block, whose writes are rolled back, and the handler answers it.
          IF p_rates IS NOT NULL THEN
              v_rate_failure := warehouse_security.apply_grn_rates(v_grn_id, p_rates);
              IF v_rate_failure IS NOT NULL THEN
                  RAISE EXCEPTION 'rate_fail' USING ERRCODE = 'P0001', DETAIL = v_rate_failure::text;
              END IF;
          END IF;

          v_result := jsonb_build_object(
              'success', true,
              'message', 'GRN created successfully',
              'data', jsonb_build_object(
                  'grn_id', v_grn_id,
                  'gr_no', p_gr_no,
                  'items_created', v_items_created,
                  'images_saved', v_images_saved,
                  'item_ids', v_item_ids,
                  'image_ids', v_image_ids,
                  'item_mapping', v_item_mapping
              )
          );

          IF p_idempotency_key IS NOT NULL THEN
              INSERT INTO idempotency_keys (idempotency_key, rpc_function, response, created_by)
              VALUES (p_idempotency_key, 'save_grn', v_result, v_user_profile_id)
              ON CONFLICT (idempotency_key) DO NOTHING;
          END IF;

          RETURN v_result;

      EXCEPTION
          WHEN foreign_key_violation THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'message', 'Invalid reference: ' || SQLERRM
              );
          WHEN unique_violation THEN
              RETURN jsonb_build_object(
                  'success', false,
                  'message', 'Duplicate value: ' || SQLERRM
              );
          WHEN OTHERS THEN
              IF SQLERRM = 'rate_fail' THEN
                  GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
                  RETURN v_detail::jsonb;
              END IF;
              RETURN jsonb_build_object(
                  'success', false,
                  'message', 'Error creating GRN: ' || SQLERRM
              );
      END;
  END;
  $$;

ALTER FUNCTION public.save_grn(p_gr_no character varying, p_date timestamp with time zone, p_customer_id uuid, p_customer_name character varying, p_sender_id uuid, p_sender_name character varying, p_supervisor_id uuid, p_supervisor_name character varying, p_registration character varying, p_note character varying, p_leon boolean, p_pricing_mode character varying, p_items jsonb, p_images jsonb, p_idempotency_key text, p_duration_mode character varying, p_rates jsonb) OWNER TO supabase_admin;

--
-- Name: save_invoice(jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.save_invoice(p_invoice_data jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $_$
DECLARE
    v_invoice_id UUID;
    v_invoice_header JSONB;
    v_invoice_items JSONB;
    v_totals JSONB;
    v_user_id UUID;
    v_created_at TIMESTAMPTZ := NOW();
    v_is_auto_generated BOOLEAN;
    v_items_count INTEGER;
    v_duration_mode text;
    v_invoice_number_text text;
    v_invoice_number_int integer;
    v_fin_year integer;
BEGIN
    PERFORM warehouse_security.authorize_rpc('save_invoice', '{}'::jsonb);
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
  PERFORM set_config('warehouse.discount_reason', COALESCE(p_invoice_data->>'discount_reason', ''), true);
  PERFORM warehouse_security.note_zero_charge_request(NULL, p_invoice_data);
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

    v_invoice_header := COALESCE(p_invoice_data->'data'->'header', p_invoice_data->'header', '{}'::jsonb);
    v_invoice_items := COALESCE(p_invoice_data->'data'->'items', p_invoice_data->'data'->'rows', p_invoice_data->'items', p_invoice_data->'rows', '[]'::jsonb);
    v_duration_mode := public.validate_invoice_duration_mode(COALESCE(p_invoice_data->>'duration_mode', v_invoice_header->>'duration_mode'));

    v_invoice_number_text := COALESCE(v_invoice_header->>'invoice_number', p_invoice_data->>'inv_no');
    PERFORM warehouse_security.check_invoice_number(COALESCE(NULLIF(p_invoice_data->>'inv_no', ''),
        NULLIF(REGEXP_REPLACE(COALESCE(v_invoice_number_text, ''), '^.*-([0-9]+)$', '\1'), '')), NULL);
    v_invoice_number_int := COALESCE(
        NULLIF(p_invoice_data->>'inv_no', '')::integer,
        NULLIF(REGEXP_REPLACE(COALESCE(v_invoice_number_text, ''), '^.*-([0-9]+)$', '\1'), '')::integer
    );
    v_fin_year := COALESCE(
        NULLIF(p_invoice_data->>'inv_fin_year', '')::integer,
        NULLIF(SPLIT_PART(COALESCE(v_invoice_header->>'financial_year', ''), '-', 1), '')::integer,
        CASE WHEN EXTRACT(MONTH FROM CURRENT_DATE) >= 4 THEN EXTRACT(YEAR FROM CURRENT_DATE)::integer ELSE EXTRACT(YEAR FROM CURRENT_DATE)::integer - 1 END
    );

    v_is_auto_generated := COALESCE(
        (p_invoice_data->>'is_auto_generated')::boolean,
        (v_invoice_header->>'is_auto_generated')::boolean,
        false
    );

    IF jsonb_typeof(v_invoice_items) <> 'array' OR jsonb_array_length(v_invoice_items) = 0 THEN
        RAISE EXCEPTION 'Invoice requires at least one dispatch line';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM goodsreceived g
        WHERE g.id = COALESCE(v_invoice_header->>'grn_id', p_invoice_data->>'gr_id')::uuid
          AND g.customer_id = COALESCE(v_invoice_header->>'customer_id', p_invoice_data->>'customer_id')::uuid
          AND g.deleted_at IS NULL
    ) THEN RAISE EXCEPTION 'Invoice customer and GRN must match'; END IF;
    IF (SELECT count(DISTINCT dt.id)
        FROM jsonb_array_elements(v_invoice_items) item
        JOIN dispatch_trl dt ON dt.id = COALESCE(item->>'disp_trl_id', item->>'dispatches_items_id', item->>'dispatch_item_id')::uuid
        JOIN dispatch d ON d.id = dt.disp_id
        WHERE dt.gr_id = COALESCE(v_invoice_header->>'grn_id', p_invoice_data->>'gr_id')::uuid
          AND d.customer_id = COALESCE(v_invoice_header->>'customer_id', p_invoice_data->>'customer_id')::uuid
          AND d.deleted_at IS NULL) <> jsonb_array_length(v_invoice_items)
    THEN RAISE EXCEPTION 'Invoice contains a missing, duplicate or unrelated dispatch line'; END IF;

    PERFORM warehouse_security.claim_invoice_lines(NULL,
        COALESCE(v_invoice_header->>'grn_id', p_invoice_data->>'gr_id')::uuid,
        ARRAY(SELECT COALESCE(item->>'disp_trl_id', item->>'dispatches_items_id', item->>'dispatch_item_id')::uuid
              FROM jsonb_array_elements(v_invoice_items) AS item));

    -- Header money columns are placeholders until the lines are saved below.
    INSERT INTO invoice (
        inv_fin_year, inv_no, gr_id, gr_no,
        customer_id, customer_name, inv_date,
        labour, tax_amount, total, discount,
        one_time_charge, notes, created_by, is_auto_generated, duration_mode
    ) VALUES (
        v_fin_year,
        v_invoice_number_int,
        COALESCE(v_invoice_header->>'grn_id', p_invoice_data->>'gr_id')::UUID,
        COALESCE(v_invoice_header->>'grn_no', p_invoice_data->>'gr_no'),
        COALESCE(v_invoice_header->>'customer_id', p_invoice_data->>'customer_id')::UUID,
        COALESCE(v_invoice_header->>'customer_name', p_invoice_data->>'customer_name'),
        COALESCE((v_invoice_header->>'invoice_date')::TIMESTAMPTZ, (p_invoice_data->>'inv_date')::TIMESTAMPTZ, v_created_at),
        0::NUMERIC(12,2),
        0::NUMERIC(12,2),
        0::NUMERIC(12,2),
        COALESCE(NULLIF(p_invoice_data->>'discount', '')::NUMERIC(12,2), 0),
        COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
        CASE WHEN v_is_auto_generated THEN 'Auto-generated invoice' ELSE COALESCE(p_invoice_data->>'notes', 'Manual invoice') END,
        v_user_id,
        v_is_auto_generated,
        v_duration_mode
    ) RETURNING id INTO v_invoice_id;

    INSERT INTO invoice_trl (invoice_id, disp_trl_id, duration, no_of_days, charge, tax, labour_rate)
    SELECT
        v_invoice_id,
        COALESCE(item->>'disp_trl_id', item->>'dispatches_items_id', item->>'dispatch_item_id')::UUID,
        d.duration,
        d.no_of_days,
        COALESCE(NULLIF(item->>'charge', '')::NUMERIC(12,2), NULLIF(item->>'unit_price', '')::NUMERIC(12,2)),
        COALESCE(NULLIF(item->>'tax', '')::NUMERIC(12,2), NULLIF(item->>'tax_percent', '')::NUMERIC(12,2)),
        (item->>'labour_rate')::NUMERIC
    FROM jsonb_array_elements(v_invoice_items) AS item
    JOIN dispatch_trl dt ON dt.id = COALESCE(item->>'disp_trl_id', item->>'dispatches_items_id', item->>'dispatch_item_id')::UUID
    JOIN dispatch disp ON disp.id = dt.disp_id
    JOIN goodsreceived gr ON gr.id = dt.gr_id
    CROSS JOIN LATERAL public.calculate_invoice_duration(warehouse_security.business_date(gr.date), warehouse_security.business_date(disp.disp_date), v_duration_mode) d;

    GET DIAGNOSTICS v_items_count = ROW_COUNT;
    v_totals := warehouse_security.recalculate_invoice_header(v_invoice_id);

    UPDATE goodsreceived
    SET invoiced = true
    WHERE id = COALESCE(v_invoice_header->>'grn_id', p_invoice_data->>'gr_id')::UUID;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', v_invoice_id,
        'invoice_no', v_invoice_number_text,
        'duration_mode', v_duration_mode,
        'is_auto_generated', v_is_auto_generated,
        'items_count', v_items_count,
        'totals', v_totals,
        'message', 'Invoice saved successfully'
    );
EXCEPTION
    WHEN insufficient_privilege THEN RAISE;
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Database error: ' || SQLERRM || ' (SQLState: ' || SQLSTATE || ')'
        );
END;
$_$;

ALTER FUNCTION public.save_invoice(p_invoice_data jsonb) OWNER TO supabase_admin;

--
-- Name: save_invoice(uuid, jsonb, jsonb[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.save_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_validation_result JSONB;
BEGIN
  PERFORM warehouse_security.authorize_rpc('save_invoice',jsonb_build_object('p_invoice_id',p_invoice_id));
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
  PERFORM set_config('warehouse.discount_reason', COALESCE(p_invoice_data->>'discount_reason', ''), true);
  PERFORM warehouse_security.note_zero_charge_request(p_invoice_id, p_invoice_data);
  PERFORM warehouse_security.check_invoice_number(p_invoice_data->>'inv_no', NULL);
    -- Step 1: Validate invoice data
    v_validation_result := validate_invoice_input(p_invoice_data);
    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid invoice data',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 2: Validate invoice items
    v_validation_result := validate_invoice_items(p_invoice_items);
    IF NOT (v_validation_result->>'valid')::BOOLEAN THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Invalid invoice items',
            'validation_errors', v_validation_result->'errors'
        );
    END IF;

    -- Step 3: Call original function (now named _internal)
    RETURN save_invoice_internal(p_invoice_id, p_invoice_data, p_invoice_items);
END;
$$;

ALTER FUNCTION public.save_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) OWNER TO supabase_admin;

--
-- Name: save_invoice_internal(uuid, jsonb, jsonb[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.save_invoice_internal(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_new_gr_id UUID;
    v_invoice_number_for_resolution VARCHAR(20);
    v_invoice_creation_time TIMESTAMPTZ;
    v_invoice_date TIMESTAMPTZ;
    v_resolved_errors_count INTEGER := 0;
    v_new_items_count INTEGER := 0;
    v_final_invoice_id UUID;
    v_is_auto_generated BOOLEAN;
    v_duration_mode text;
    v_discount NUMERIC(12,2) := COALESCE(NULLIF(p_invoice_data->>'discount', '')::NUMERIC(12,2), 0::NUMERIC(12,2));
    v_function_version TEXT := 'save_invoice_v20260503_duration_mode';
BEGIN
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
    v_new_gr_id := (p_invoice_data->>'gr_id')::uuid;
    v_invoice_creation_time := NOW();
    v_invoice_date := COALESCE((p_invoice_data->>'inv_date')::TIMESTAMPTZ, NOW());
    v_invoice_number_for_resolution := (p_invoice_data->>'inv_no');
    v_is_auto_generated := COALESCE((p_invoice_data->>'is_auto_generated')::boolean, false);
    v_duration_mode := public.validate_invoice_duration_mode(p_invoice_data->>'duration_mode');
    PERFORM warehouse_security.claim_invoice_lines(NULL, v_new_gr_id,
        ARRAY(SELECT (item->>'disp_trl_id')::uuid FROM unnest(p_invoice_items) AS item));

    IF p_invoice_id IS NOT NULL THEN
        INSERT INTO invoice (
            id, inv_fin_year, inv_no, gr_id, gr_no,
            customer_id, customer_name, inv_date,
            labour, tax_amount, total, discount,
            one_time_charge, notes, created_by, is_auto_generated, duration_mode
        ) VALUES (
            p_invoice_id,
            (p_invoice_data->>'inv_fin_year')::integer,
            (p_invoice_data->>'inv_no')::integer,
            v_new_gr_id,
            p_invoice_data->>'gr_no',
            (p_invoice_data->>'customer_id')::uuid,
            p_invoice_data->>'customer_name',
            v_invoice_date,
            0::NUMERIC(12,2),
            0::NUMERIC(12,2),
            0::NUMERIC(12,2),
            v_discount,
            COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
            p_invoice_data->>'notes',
            v_user_id,
            v_is_auto_generated,
            v_duration_mode
        );
        v_final_invoice_id := p_invoice_id;
    ELSE
        INSERT INTO invoice (
            inv_fin_year, inv_no, gr_id, gr_no,
            customer_id, customer_name, inv_date,
            labour, tax_amount, total, discount,
            one_time_charge, notes, created_by, is_auto_generated, duration_mode
        ) VALUES (
            (p_invoice_data->>'inv_fin_year')::integer,
            (p_invoice_data->>'inv_no')::integer,
            v_new_gr_id,
            p_invoice_data->>'gr_no',
            (p_invoice_data->>'customer_id')::uuid,
            p_invoice_data->>'customer_name',
            v_invoice_date,
            0::NUMERIC(12,2),
            0::NUMERIC(12,2),
            0::NUMERIC(12,2),
            v_discount,
            COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
            p_invoice_data->>'notes',
            v_user_id,
            v_is_auto_generated,
            v_duration_mode
        ) RETURNING id INTO v_final_invoice_id;
    END IF;

    INSERT INTO invoice_trl (invoice_id, disp_trl_id, duration, no_of_days, charge, tax, labour_rate)
    SELECT
        v_final_invoice_id,
        (item->>'disp_trl_id')::uuid,
        d.duration,
        d.no_of_days,
        COALESCE(NULLIF(item->>'charge', '')::NUMERIC(12,2), NULLIF(item->>'unit_price', '')::NUMERIC(12,2)),
        COALESCE(NULLIF(item->>'tax', '')::NUMERIC(12,2), NULLIF(item->>'tax_percent', '')::NUMERIC(12,2)),
        (item->>'labour_rate')::numeric
    FROM unnest(p_invoice_items) AS item
    JOIN dispatch_trl dt ON dt.id = (item->>'disp_trl_id')::uuid
    JOIN dispatch disp ON disp.id = dt.disp_id
    JOIN goodsreceived gr ON gr.id = dt.gr_id
    CROSS JOIN LATERAL public.calculate_invoice_duration(warehouse_security.business_date(gr.date), warehouse_security.business_date(disp.disp_date), v_duration_mode) d;

    GET DIAGNOSTICS v_new_items_count = ROW_COUNT;
    PERFORM warehouse_security.assert_invoice_lines(v_final_invoice_id, v_new_gr_id,
        (p_invoice_data->>'customer_id')::uuid, COALESCE(array_length(p_invoice_items, 1), 0));
    PERFORM warehouse_security.recalculate_invoice_header(v_final_invoice_id);

    UPDATE goodsreceived SET invoiced = true WHERE id = v_new_gr_id;

    UPDATE auto_invoice_errors
    SET
        resolved_at = v_invoice_creation_time,
        resolved_invoice_id = v_final_invoice_id,
        error_details = COALESCE(error_details, '{}')::jsonb ||
                       jsonb_build_object(
                           'resolution_type', 'manual_invoice_created',
                           'resolution_notes', 'Invoice created manually through save_invoice',
                           'invoice_id', v_final_invoice_id,
                           'invoice_number', v_invoice_number_for_resolution,
                           'invoice_date', v_invoice_date,
                           'gr_id', v_new_gr_id
                       )
    WHERE gr_id = v_new_gr_id
    AND resolved_at IS NULL;

    GET DIAGNOSTICS v_resolved_errors_count = ROW_COUNT;

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', v_final_invoice_id,
        'invoice_number', v_invoice_number_for_resolution,
        'items_count', v_new_items_count,
        'resolved_errors_count', v_resolved_errors_count,
        'is_auto_generated', v_is_auto_generated,
        'duration_mode', v_duration_mode,
        'function_version', v_function_version
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', SQLERRM,
        'error_code', SQLSTATE,
        'function_version', v_function_version
    );
END;
$$;

ALTER FUNCTION public.save_invoice_internal(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) OWNER TO supabase_admin;

--
-- Name: search_customer_items_for_order(text, uuid, text, integer, integer, integer, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.search_customer_items_for_order(p_search_query text DEFAULT ''::text, p_customer_id uuid DEFAULT NULL::uuid, p_search_type text DEFAULT 'auto'::text, p_stock_filter_min integer DEFAULT 1, p_page_size integer DEFAULT 50, p_offset integer DEFAULT 0, p_catalog_id uuid DEFAULT NULL::uuid, p_weight_min numeric DEFAULT NULL::numeric, p_weight_max numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $_$
DECLARE
    v_search_type_final TEXT;
    v_weight_min_final INTEGER;
    v_weight_max_final INTEGER;
    v_accessible_customers UUID[];
    v_is_admin BOOLEAN;
    v_result JSONB;
BEGIN
  PERFORM warehouse_security.authorize_rpc('search_customer_items_for_order',jsonb_build_object('p_customer_id',p_customer_id));
    v_is_admin := is_admin_or_supervisor();

    IF v_is_admin THEN
        IF p_customer_id IS NOT NULL THEN
            v_accessible_customers := ARRAY[p_customer_id];
        ELSE
            SELECT ARRAY(SELECT id FROM customers WHERE active = true AND deleted_at IS NULL) INTO v_accessible_customers;
        END IF;
    ELSE
        SELECT user_accessible_customers() INTO v_accessible_customers;

        IF v_accessible_customers IS NULL OR array_length(v_accessible_customers, 1) IS NULL THEN
            RETURN jsonb_build_object('items', '[]'::jsonb, 'total_count', 0, 'success', false, 'error', 'No accessible customers');
        END IF;

        IF p_customer_id IS NOT NULL THEN
            IF NOT (p_customer_id = ANY(v_accessible_customers)) THEN
                RETURN jsonb_build_object('items', '[]'::jsonb, 'total_count', 0, 'success', false, 'error', 'Access denied to customer');
            END IF;
            v_accessible_customers := ARRAY[p_customer_id];
        END IF;
    END IF;

    IF p_search_type = 'weight_range' OR (p_weight_min IS NOT NULL AND p_weight_max IS NOT NULL) THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := COALESCE(p_weight_min, 0)::INTEGER;
        v_weight_max_final := COALESCE(p_weight_max, 999999)::INTEGER;
    ELSIF p_search_type = 'auto' AND p_search_query ~ '^[0-9]+\.?[0-9]*-[0-9]+\.?[0-9]*$' THEN
        v_search_type_final := 'weight_range';
        v_weight_min_final := round(split_part(p_search_query, '-', 1)::numeric)::INTEGER;
        v_weight_max_final := round(split_part(p_search_query, '-', 2)::numeric)::INTEGER;
    ELSIF p_search_type = 'weight' OR (p_search_type = 'auto' AND p_search_query ~ '^[0-9]+\.?[0-9]*$') THEN
        v_search_type_final := 'weight_exact';
        v_weight_min_final := round(COALESCE(p_weight_min, p_search_query::numeric))::INTEGER;
        v_weight_max_final := v_weight_min_final;
    ELSIF p_search_query IS NULL OR trim(p_search_query) = '' THEN
        v_search_type_final := 'all';
    ELSE
        v_search_type_final := 'text';
    END IF;

    SELECT jsonb_build_object(
        'items', COALESCE(
            (SELECT jsonb_agg(item_data)
            FROM (
                SELECT jsonb_build_object(
                    'id', grt.id,
                    'grn_id', grt.gr_id,
                    'item_id', grt.item_id,
                    'item_name', grt.item_name,
                    'package_mark', grt.package_mark,
                    'packaging', grt.packaging,
                    'rack', grt.rack,
                    'qty', grt.qty,
                    'stock', grt.stock,
                    'weight', grt.weight,
                    'trl_img_url', grt.trl_img_url,
                    'grn_date', gr.date,
                    'gr_no', gr.gr_no,
                    'customer_id', gr.customer_id,
                    'customer_name', c.name,
                    'master_item_id', i.id,
                    'master_item_name', i.name,
                    'match_type', CASE
                        WHEN v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final THEN 'weight_exact'
                        WHEN v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final THEN 'weight_range'
                        WHEN grt.item_name ILIKE '%' || p_search_query || '%' THEN 'item_name'
                        WHEN grt.package_mark ILIKE '%' || p_search_query || '%' THEN 'package_mark'
                        WHEN grt.packaging ILIKE '%' || p_search_query || '%' THEN 'packaging'
                        WHEN gr.gr_no ILIKE '%' || p_search_query || '%' THEN 'gr_no'
                        WHEN i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%' THEN 'master_item_name'
                        ELSE 'match'
                    END
                ) as item_data
                FROM goodsreceived_trl grt
                JOIN goodsreceived gr ON grt.gr_id = gr.id
                JOIN customers c ON gr.customer_id = c.id
                LEFT JOIN items i ON grt.item_id = i.id
                WHERE gr.customer_id = ANY(v_accessible_customers)
                AND gr.deleted_at IS NULL
                AND grt.stock >= p_stock_filter_min
                AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id)
                AND (p_catalog_id IS NULL OR i.id = p_catalog_id)
                AND (
                    v_search_type_final = 'all'
                    OR (v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final)
                    OR (v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final)
                    OR (v_search_type_final = 'text' AND (
                        grt.item_name ILIKE '%' || p_search_query || '%'
                        OR grt.package_mark ILIKE '%' || p_search_query || '%'
                        OR grt.packaging ILIKE '%' || p_search_query || '%'
                        OR gr.gr_no ILIKE '%' || p_search_query || '%'
                        OR c.name ILIKE '%' || p_search_query || '%'
                        OR (i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%')
                    ))
                )
                ORDER BY
                    CASE
                        WHEN v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final THEN 1
                        WHEN v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final THEN 2
                        WHEN grt.item_name ILIKE '%' || p_search_query || '%' THEN 3
                        WHEN grt.package_mark ILIKE '%' || p_search_query || '%' THEN 4
                        WHEN grt.packaging ILIKE '%' || p_search_query || '%' THEN 5
                        WHEN gr.gr_no ILIKE '%' || p_search_query || '%' THEN 6
                        WHEN i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%' THEN 7
                        ELSE 8
                    END,
                    grt.weight,
                    grt.item_name
                LIMIT p_page_size
                OFFSET p_offset
            ) ordered_items),
            '[]'::jsonb
        ),
        'total_count', (
            SELECT COUNT(*)
            FROM goodsreceived_trl grt
            JOIN goodsreceived gr ON grt.gr_id = gr.id
            JOIN customers c ON gr.customer_id = c.id
            LEFT JOIN items i ON grt.item_id = i.id
            WHERE gr.customer_id = ANY(v_accessible_customers)
            AND gr.deleted_at IS NULL
            AND grt.stock >= p_stock_filter_min
            AND (p_customer_id IS NULL OR gr.customer_id = p_customer_id)
            AND (p_catalog_id IS NULL OR i.id = p_catalog_id)
            AND (
                v_search_type_final = 'all'
                OR (v_search_type_final = 'weight_exact' AND grt.weight = v_weight_min_final)
                OR (v_search_type_final = 'weight_range' AND grt.weight >= v_weight_min_final AND grt.weight <= v_weight_max_final)
                OR (v_search_type_final = 'text' AND (
                    grt.item_name ILIKE '%' || p_search_query || '%'
                    OR grt.package_mark ILIKE '%' || p_search_query || '%'
                    OR grt.packaging ILIKE '%' || p_search_query || '%'
                    OR gr.gr_no ILIKE '%' || p_search_query || '%'
                    OR c.name ILIKE '%' || p_search_query || '%'
                    OR (i.name IS NOT NULL AND i.name ILIKE '%' || p_search_query || '%')
                ))
            )
        )
    ) INTO v_result;

    RETURN v_result;
END;
$_$;

ALTER FUNCTION public.search_customer_items_for_order(p_search_query text, p_customer_id uuid, p_search_type text, p_stock_filter_min integer, p_page_size integer, p_offset integer, p_catalog_id uuid, p_weight_min numeric, p_weight_max numeric) OWNER TO supabase_admin;

--
-- Name: search_customers(text, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.search_customers(p_search_query text, p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
    v_query text := btrim(COALESCE(p_search_query, ''));
    v_prefix text := replace(replace(replace(btrim(COALESCE(p_search_query, '')), '\', '\\'), '%', '\%'), '_', '\_');
BEGIN
  PERFORM warehouse_security.authorize_rpc('search_customers',jsonb_build_object());
    SELECT COALESCE(
        jsonb_agg(sub.customer_row ORDER BY sub.rank, sub.name, sub.id),
        '[]'::jsonb
    ) INTO v_result
    FROM (
        SELECT jsonb_build_object(
            'id', c.id,
            'name', c.name,
            'mobile', c.mobile,
            'city', c.city,
            'email', c.email,
            'address', c.address
        ) as customer_row,
        c.name, c.id,
        CASE WHEN v_query = '' OR c.name ILIKE v_prefix || '%' OR c.mobile ILIKE v_prefix || '%' THEN 0 ELSE 1 END AS rank
        FROM customers c
        WHERE c.active = true
          AND c.deleted_at IS NULL
          AND c.id = ANY(user_accessible_customers())
          AND (
              v_query = ''
              OR c.mobile ILIKE v_prefix || '%'
              OR NOT EXISTS (
                  SELECT 1 FROM regexp_split_to_table(v_query, '\s+') AS w(word)
                  WHERE c.name NOT ILIKE '%' || replace(replace(replace(w.word, '\', '\\'), '%', '\%'), '_', '\_') || '%'
              )
          )
        ORDER BY rank, c.name, c.id
        LIMIT p_limit
    ) sub;

    RETURN utils.success_response(v_result);
END;
$$;

ALTER FUNCTION public.search_customers(p_search_query text, p_limit integer) OWNER TO supabase_admin;

--
-- Name: search_grns(text, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.search_grns(p_search_query text DEFAULT ''::text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      v_user_role text;
      v_user_customer_ids uuid[];
      v_grns jsonb;
      v_total_count integer;
      v_has_more boolean;
      v_result jsonb;
  BEGIN
      -- Get user role and customer access
      SELECT role INTO v_user_role FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Get user's accessible customers (for non-admin users)
      IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
          SELECT ARRAY_AGG(customer_id) INTO v_user_customer_ids
          FROM user_customers
          WHERE user_id = (SELECT id FROM user_profiles WHERE auth_user_id = auth.uid());
      END IF;

      -- Validate limit
      IF p_limit < 1 OR p_limit > 100 THEN
          p_limit := 10;
      END IF;

      -- Get total count first
      SELECT COUNT(*) INTO v_total_count
      FROM goodsreceived gr
      WHERE
          -- Apply customer access control
          (v_user_role IN ('admin', 'supervisor', 'staff') OR
           (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
          AND
          -- Apply search filter
          (p_search_query = '' OR
           gr.gr_no ILIKE '%' || p_search_query || '%' OR
           gr.customer_name ILIKE '%' || p_search_query || '%' OR
           gr.supervisor_name ILIKE '%' || p_search_query || '%');

      -- Get paginated results
      SELECT jsonb_agg(
          jsonb_build_object(
              'id', gr.id,
              'gr_no', gr.gr_no,
              'date', gr.date,
              'customer_name', gr.customer_name,
              'registration', gr.registration,
              'supervisor_name', gr.supervisor_name,
              'sender_name', gr.sender_name,
              'invoiced', gr.invoiced,
              'leon', gr.leon,
              'out_of_stock', gr.out_of_stock,
              'note', gr.note
          )
      ) INTO v_grns
      FROM (
          SELECT gr.*
          FROM goodsreceived gr
          WHERE
              -- Apply customer access control
              (v_user_role IN ('admin', 'supervisor', 'staff') OR
               (v_user_customer_ids IS NOT NULL AND gr.customer_id = ANY(v_user_customer_ids)))
              AND
              -- Apply search filter
              (p_search_query = '' OR
               gr.gr_no ILIKE '%' || p_search_query || '%' OR
               gr.customer_name ILIKE '%' || p_search_query || '%' OR
               gr.supervisor_name ILIKE '%' || p_search_query || '%')
          ORDER BY gr.date DESC, gr.created_at DESC
          LIMIT p_limit
      ) gr;

      -- Check if there are more results
      v_has_more := v_total_count > p_limit;

      -- Build response
      v_result := jsonb_build_object(
          'success', true,
          'data', jsonb_build_object(
              'grns', COALESCE(v_grns, '[]'::jsonb),
              'pagination', jsonb_build_object(
                  'limit', p_limit,
                  'total', v_total_count,
                  'has_more', v_has_more
              )
          ),
          'message', 'GRNs retrieved successfully'
      );

      RETURN v_result;

  EXCEPTION
      WHEN OTHERS THEN
          RETURN jsonb_build_object(
              'success', false,
              'error', 'Failed to search GRNs: ' || SQLERRM,
              'code', 'DATABASE_ERROR'
          );
  END;
  $$;

ALTER FUNCTION public.search_grns(p_search_query text, p_limit integer) OWNER TO supabase_admin;

--
-- Name: search_items_autocomplete(text, boolean, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.search_items_autocomplete(p_search_query text DEFAULT ''::text, p_active_only boolean DEFAULT true, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
BEGIN
  PERFORM warehouse_security.authorize_rpc('search_items_autocomplete',jsonb_build_object());
    RETURN (
        SELECT jsonb_build_object(
            'items', COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'id', id,
                        'name', name,
                        'packaging', packaging,
                        'description', description,
                        'active', active
                    )
                    ORDER BY
                        CASE
                            WHEN name ILIKE p_search_query || '%' THEN 1
                            WHEN name ILIKE '%' || p_search_query || '%' THEN 2
                            ELSE 3
                        END,
                        name ASC
                ),
                '[]'::jsonb
            ),
            'total_count', COUNT(*)::INTEGER
        )
        FROM items
        WHERE (p_active_only = false OR active = true)
          AND (
              p_search_query IS NULL
              OR p_search_query = ''
              OR name ILIKE '%' || p_search_query || '%'
              OR packaging ILIKE '%' || p_search_query || '%'
              OR description ILIKE '%' || p_search_query || '%'
          )
        LIMIT p_limit
    );
END;
$$;

ALTER FUNCTION public.search_items_autocomplete(p_search_query text, p_active_only boolean, p_limit integer) OWNER TO supabase_admin;

