-- Name: send_otp_with_config(character varying, character varying, text, inet); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.send_otp_with_config(p_phone_number character varying, p_purpose character varying DEFAULT 'login'::character varying, p_user_agent text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet) RETURNS TABLE(success boolean, message text, request_id text, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    -- Initialize MSG91 configuration
    PERFORM init_msg91_config();

    -- Call the original send_otp function
