--
-- Name: send_otp_with_hash(character varying, character varying, text, inet); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.send_otp_with_hash(p_phone_number character varying, p_purpose character varying DEFAULT 'login'::character varying, p_user_agent text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet) RETURNS TABLE(success boolean, message text, request_id text, expires_at timestamp with time zone, otp_code text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_phone_formatted VARCHAR(15);
    v_otp_code VARCHAR(6);
    v_otp_hash TEXT;
    v_production_mode BOOLEAN;
    v_otp_id UUID;
    v_expires_at TIMESTAMPTZ;
BEGIN
    v_phone_formatted := REGEXP_REPLACE(p_phone_number, '[^0-9]', '', 'g');
    IF LENGTH(v_phone_formatted) = 10 THEN
        v_phone_formatted := '91' || v_phone_formatted;
    END IF;

    SELECT generate_secure_otp() INTO v_otp_code;
    v_otp_hash := encode(digest(v_otp_code, 'sha256'), 'hex');

    SELECT production_mode INTO v_production_mode
    FROM public.sms_config ORDER BY id DESC LIMIT 1;

    v_expires_at := NOW() + INTERVAL '10 minutes';

    INSERT INTO otp_verifications (
        phone_number, otp_code, otp_code_hash, purpose, expires_at, user_agent, ip_address, failed_attempts, locked_until
    ) VALUES (
        v_phone_formatted,
        CASE WHEN NOT v_production_mode THEN v_otp_code ELSE NULL END,
        v_otp_hash, p_purpose, v_expires_at, p_user_agent, p_ip_address, 0, NULL
    ) RETURNING id INTO v_otp_id;

    RETURN QUERY SELECT TRUE, 'OTP sent successfully'::TEXT, v_otp_id::TEXT, v_expires_at,
        CASE WHEN NOT v_production_mode THEN v_otp_code ELSE NULL END;
EXCEPTION
    WHEN OTHERS THEN
        RAISE WARNING 'send_otp_with_hash failed: % - %', SQLSTATE, SQLERRM;
        RETURN QUERY SELECT FALSE, 'Failed to send OTP: ' || SQLERRM, NULL::TEXT, NULL::TIMESTAMPTZ, NULL::TEXT;
END;
$$;

ALTER FUNCTION public.send_otp_with_hash(p_phone_number character varying, p_purpose character varying, p_user_agent text, p_ip_address inet) OWNER TO supabase_admin;

--
-- Name: set_audit_columns(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.set_audit_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
      current_user_profile_id uuid;
  BEGIN
      -- Get current user's profile ID
      SELECT id INTO current_user_profile_id
      FROM user_profiles
      WHERE auth_user_id = auth.uid();

      -- Set audit columns
      IF TG_OP = 'INSERT' THEN
          NEW.created_by := current_user_profile_id;
          NEW.updated_by := current_user_profile_id;
          NEW.created_at := now();
          NEW.updated_at := now();
          RETURN NEW;
      ELSIF TG_OP = 'UPDATE' THEN
          NEW.updated_by := current_user_profile_id;
          NEW.updated_at := now();
          -- Preserve original created_by and created_at
          NEW.created_by := OLD.created_by;
          NEW.created_at := OLD.created_at;
          RETURN NEW;
      END IF;

      RETURN NULL;
  END;
  $$;

ALTER FUNCTION public.set_audit_columns() OWNER TO supabase_admin;

--
-- Name: set_customer_active(uuid, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.set_customer_active(p_customer_id uuid, p_active boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
  v_customer public.customers;
  v_profile_id uuid;
BEGIN
  PERFORM warehouse_security.authorize_rpc('set_customer_active', jsonb_build_object());
  -- The list-refresh lock comes before any row lock (migration 46).
  PERFORM pg_advisory_xact_lock(71040);
  IF p_customer_id IS NULL OR p_active IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Customer and active flag are required');
  END IF;
  SELECT * INTO v_customer FROM public.customers WHERE id = p_customer_id FOR UPDATE;
  IF v_customer.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'message', 'Customer not found');
  END IF;
  IF v_customer.active = p_active AND (NOT p_active OR v_customer.deleted_at IS NULL) THEN
    RETURN jsonb_build_object('success', true,
      'message', format('Customer "%s" is already %s', v_customer.name, CASE WHEN p_active THEN 'active' ELSE 'inactive' END),
      'data', jsonb_build_object('id', v_customer.id, 'active', v_customer.active));
  END IF;
  SELECT id INTO v_profile_id FROM public.user_profiles WHERE auth_user_id = auth.uid();
  IF p_active THEN
    UPDATE public.customers SET active = true, deleted_at = NULL, deleted_by = NULL, updated_at = now(), updated_by = v_profile_id
      WHERE id = p_customer_id;
  ELSE
    UPDATE public.customers SET active = false, updated_at = now(), updated_by = v_profile_id WHERE id = p_customer_id;
  END IF;
  RETURN jsonb_build_object('success', true,
    'message', format('Customer "%s" %s', v_customer.name, CASE WHEN p_active THEN 'activated' ELSE 'deactivated' END),
    'data', jsonb_build_object('id', p_customer_id, 'active', p_active));
END;
$$;

ALTER FUNCTION public.set_customer_active(p_customer_id uuid, p_active boolean) OWNER TO supabase_admin;

