--
-- Name: track_user_activity(character varying, inet, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.track_user_activity(p_activity_type character varying DEFAULT 'api_call'::character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_user_id UUID;
    v_auth_session_id UUID;
    v_last_activity TIMESTAMPTZ;
    v_inactive_duration INTERVAL;
BEGIN
    SELECT id INTO v_user_id
    FROM user_profiles
    WHERE auth_user_id = auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'User not found or not authenticated'
        );
    END IF;

    SELECT id INTO v_auth_session_id
    FROM auth.sessions
    WHERE user_id = auth.uid()
    AND updated_at > NOW() - INTERVAL '1 hour'
    ORDER BY updated_at DESC
    LIMIT 1;

    SELECT last_activity_at INTO v_last_activity
    FROM user_session_activity
    WHERE user_id = v_user_id
    ORDER BY last_activity_at DESC
    LIMIT 1;

    IF v_last_activity IS NOT NULL THEN
        v_inactive_duration := NOW() - v_last_activity;
    END IF;

    IF v_inactive_duration IS NOT NULL AND v_inactive_duration > INTERVAL '15 minutes' THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Session expired due to inactivity',
            'inactive_duration_seconds', EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER,
            'requires_reauth', TRUE
        );
    END IF;

    INSERT INTO user_session_activity (
        user_id, auth_session_id, last_activity_at, ip_address, user_agent, activity_type
    ) VALUES (
        v_user_id, v_auth_session_id, NOW(), p_ip_address, p_user_agent, p_activity_type
    );

    RETURN jsonb_build_object(
        'success', TRUE,
        'last_activity', v_last_activity,
        'inactive_duration_seconds', COALESCE(EXTRACT(EPOCH FROM v_inactive_duration)::INTEGER, 0)
    );
EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'track_user_activity failed: ' || SQLERRM
        );
END;
$$;

ALTER FUNCTION public.track_user_activity(p_activity_type character varying, p_ip_address inet, p_user_agent text) OWNER TO supabase_admin;

--
-- Name: undo_rate_change(uuid, uuid, text, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.undo_rate_change(p_item_id uuid, p_customer_id uuid, p_price_type text, p_starts_on date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
  v_role text; v_next date; v_stop date;
  v_removed jsonb := '[]'::jsonb; v_reopened jsonb := '[]'::jsonb; v_row record;
BEGIN
  PERFORM warehouse_security.authorize_rpc('undo_rate_change', jsonb_build_object('p_customer_id', p_customer_id));
  SELECT up.role::text INTO v_role FROM public.user_profiles up WHERE up.auth_user_id = auth.uid() AND up.active;

  IF p_price_type IS NULL OR p_price_type NOT IN ('monthly','one_time') THEN
    RETURN warehouse_security.rate_failure('INVALID_PRICE_TYPE', 'Price type must be monthly or one_time');
  END IF;
  IF p_starts_on IS NULL OR p_starts_on NOT BETWEEN warehouse_security.rate_start_floor() AND warehouse_security.business_date(now()) + 730 THEN
    RETURN warehouse_security.rate_failure('INVALID_DATE',
      'The start date must be on or after ' || warehouse_security.rate_start_floor()::text || ' and within two years after today',
      jsonb_build_object('earliest', warehouse_security.rate_start_floor()));
  END IF;
  IF p_starts_on <= warehouse_security.business_date(now()) AND v_role = 'staff' THEN
    RETURN warehouse_security.rate_failure('PAST_DATE_NOT_ALLOWED', 'Only administrators and supervisors can undo a change that has already begun');
  END IF;
  IF p_item_id IS NULL OR NOT EXISTS (SELECT 1 FROM public.items WHERE id = p_item_id AND active) THEN
    RETURN warehouse_security.rate_failure('ITEM_NOT_FOUND', 'Item not found or inactive');
  END IF;
  IF p_customer_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM public.customers WHERE id = p_customer_id AND active AND deleted_at IS NULL) THEN
    RETURN warehouse_security.rate_failure('CUSTOMER_NOT_FOUND', 'Customer not found or inactive');
  END IF;

  -- The same lock as replace_item_rates: one change of this scope at a time.
  PERFORM pg_advisory_xact_lock(hashtextextended('item_rates:' || p_item_id || ':' || COALESCE(p_customer_id::text, 'default') || ':' || p_price_type, 0));
  PERFORM 1 FROM public.item_storage_prices r
   WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type FOR UPDATE;

  -- The writes sit in a block of their own, so an overlap undoes them all.
  BEGIN
    WITH gone AS (
      DELETE FROM public.item_storage_prices r
       WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
         AND r.effective_from = p_starts_on
      RETURNING r.id, r.effective_from, r.effective_to)
    -- v_stop: the scheduled stop the removed rate carried (all its rows end on one day), if any.
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id', gone.id, 'effective_from', gone.effective_from) ORDER BY gone.id), '[]'::jsonb),
           CASE WHEN count(*) > 0 AND count(*) FILTER (WHERE gone.effective_to IS NULL) = 0 AND count(DISTINCT gone.effective_to) = 1
                THEN max(gone.effective_to) END
      INTO v_removed, v_stop FROM gone;

    SELECT min(r.effective_from) INTO v_next FROM public.item_storage_prices r
     WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
       AND r.effective_from >= p_starts_on;

    WITH opened AS (
      UPDATE public.item_storage_prices r SET effective_to = COALESCE(v_next - 1, v_stop)
       WHERE r.item_id = p_item_id AND r.customer_id IS NOT DISTINCT FROM p_customer_id AND r.price_type = p_price_type
         AND r.effective_to = p_starts_on - 1
      RETURNING r.id, r.effective_from, r.effective_to)
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id', opened.id, 'effective_from', opened.effective_from, 'effective_to', opened.effective_to)
             ORDER BY opened.effective_from, opened.id), '[]'::jsonb) INTO v_reopened FROM opened;

    IF jsonb_array_length(v_removed) = 0 AND jsonb_array_length(v_reopened) = 0 THEN
      RETURN warehouse_security.rate_failure('NOTHING_TO_UNDO', 'There is no change starting on that day to undo');
    END IF;

    FOR v_row IN SELECT r.id, r.weight_min, r.weight_max, r.effective_from, r.effective_to FROM public.item_storage_prices r
        WHERE r.id IN (SELECT (e->>'id')::uuid FROM jsonb_array_elements(v_reopened) e) LOOP
      IF warehouse_security.price_rows_overlap(p_item_id, p_customer_id, p_price_type,
           v_row.weight_min, v_row.weight_max, v_row.effective_from, v_row.effective_to, v_row.id) THEN
        RAISE EXCEPTION 'rate rows overlap' USING ERRCODE = 'P0001', DETAIL = 'undo_rate_change';
      END IF;
    END LOOP;
  EXCEPTION WHEN SQLSTATE 'P0001' THEN
    IF SQLERRM = 'rate rows overlap' THEN
      RETURN warehouse_security.rate_failure('BANDS_OVERLAP', 'Undoing would make rates overlap');
    END IF;
    RAISE;
  END;

  RETURN jsonb_build_object('success', true, 'message', 'Change undone', 'data', jsonb_build_object(
    'item_id', p_item_id, 'customer_id', p_customer_id, 'price_type', p_price_type, 'starts_on', p_starts_on,
    'removed', v_removed, 'reopened', v_reopened));
END;
$$;

ALTER FUNCTION public.undo_rate_change(p_item_id uuid, p_customer_id uuid, p_price_type text, p_starts_on date) OWNER TO supabase_admin;

--
-- Name: update_customer(uuid, character varying, character varying, character varying, text, character varying, character varying, character varying, character varying, character varying, boolean, character varying, character varying, character varying, text[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_customer(p_customer_id uuid, p_name character varying DEFAULT NULL::character varying, p_mobile character varying DEFAULT NULL::character varying, p_email character varying DEFAULT NULL::character varying, p_address text DEFAULT NULL::text, p_city character varying DEFAULT NULL::character varying, p_state character varying DEFAULT NULL::character varying, p_pincode character varying DEFAULT NULL::character varying, p_gst character varying DEFAULT NULL::character varying, p_pan character varying DEFAULT NULL::character varying, p_active boolean DEFAULT NULL::boolean, p_contact_person character varying DEFAULT NULL::character varying, p_contact_mobile character varying DEFAULT NULL::character varying, p_contact_email character varying DEFAULT NULL::character varying, p_image_urls text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $_$
DECLARE
    v_existing RECORD;
BEGIN
    PERFORM warehouse_security.authorize_rpc('update_customer', jsonb_build_object('p_customer_id', p_customer_id));
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
    -- Check permission
    IF NOT is_admin_or_supervisor() THEN
        RETURN utils.permission_denied_response('admins and supervisors');
    END IF;

    -- Check if customer exists
    SELECT * INTO v_existing FROM customers WHERE id = p_customer_id;
    IF v_existing IS NULL THEN
        RETURN utils.not_found_response('Customer', p_customer_id::text);
    END IF;

    -- Validate mobile if provided
    IF p_mobile IS NOT NULL AND NOT p_mobile ~ '^[0-9]{10,15}$' THEN
        RETURN utils.validation_error_response('mobile', 'Mobile number must be 10-15 digits');
    END IF;

    -- Check for duplicate mobile
    IF p_mobile IS NOT NULL AND EXISTS(SELECT 1 FROM customers WHERE mobile = p_mobile AND id != p_customer_id AND active = true) THEN
        RETURN utils.error_response('DUPLICATE_MOBILE', 'A customer with this mobile number already exists');
    END IF;

    -- Update customer
    UPDATE customers SET
        name = COALESCE(p_name, name),
        mobile = COALESCE(p_mobile, mobile),
        email = COALESCE(p_email, email),
        address = COALESCE(p_address, address),
        city = COALESCE(p_city, city),
        state = COALESCE(p_state, state),
        pincode = COALESCE(p_pincode, pincode),
        gst = COALESCE(p_gst, gst),
        pan = COALESCE(p_pan, pan),
        active = COALESCE(p_active, active),
        deleted_at = CASE WHEN p_active IS TRUE THEN NULL ELSE deleted_at END,
        deleted_by = CASE WHEN p_active IS TRUE THEN NULL ELSE deleted_by END,
        contact_person = COALESCE(p_contact_person, contact_person),
        contact_mobile = COALESCE(p_contact_mobile, contact_mobile),
        contact_email = COALESCE(p_contact_email, contact_email),
        updated_at = NOW()
    WHERE id = p_customer_id;

    -- Handle images if provided
    IF p_image_urls IS NOT NULL THEN
        UPDATE customers SET image_urls = p_image_urls WHERE id = p_customer_id;
    END IF;

    RETURN utils.success_response(
        jsonb_build_object('customer_id', p_customer_id),
        'Customer updated successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN utils.error_response('DUPLICATE_MOBILE', 'A customer with this mobile number already exists');
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to update customer', SQLERRM, SQLSTATE);
END;
$_$;

ALTER FUNCTION public.update_customer(p_customer_id uuid, p_name character varying, p_mobile character varying, p_email character varying, p_address text, p_city character varying, p_state character varying, p_pincode character varying, p_gst character varying, p_pan character varying, p_active boolean, p_contact_person character varying, p_contact_mobile character varying, p_contact_email character varying, p_image_urls text[]) OWNER TO supabase_admin;

--
-- Name: update_customer_contact_with_auth_phone(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_customer_contact_with_auth_phone() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
    updated_count INTEGER := 0;
    customer_record RECORD;
    auth_phone TEXT;
    final_contact TEXT;
BEGIN
    -- Loop through all customers
    FOR customer_record IN
        SELECT id, mobile, telephone1, contact, created_by
        FROM customers
    LOOP
        auth_phone := NULL;
        final_contact := NULL;

        -- Priority 1: Try to get auth phone from creator (if created_by exists)
        IF customer_record.created_by IS NOT NULL THEN
            SELECT au.phone INTO auth_phone
            FROM user_profiles up
            JOIN auth.users au ON up.auth_user_id = au.id
            WHERE up.id = customer_record.created_by
            AND au.phone IS NOT NULL;
        END IF;

        -- Priority 2: Try to get auth phone from assigned user (if no creator phone)
        IF auth_phone IS NULL THEN
            SELECT au.phone INTO auth_phone
            FROM users_customers_new ucn
            JOIN user_profiles up ON ucn.user_profile_id = up.id
            JOIN auth.users au ON up.auth_user_id = au.id
            WHERE ucn.customer_id = customer_record.id
            AND ucn.active = true
            AND au.phone IS NOT NULL
            ORDER BY ucn.assigned_at DESC
            LIMIT 1;
        END IF;

        -- Determine final contact with priority
        final_contact := COALESCE(
            auth_phone,                    -- Priority 1: Auth phone
            customer_record.mobile,        -- Priority 2: Customer mobile
            customer_record.telephone1     -- Priority 3: Customer telephone1
        );

        -- Update only if contact is different or null
        IF final_contact IS NOT NULL AND (customer_record.contact IS NULL OR customer_record.contact != final_contact) THEN
            UPDATE customers
            SET contact = final_contact
            WHERE id = customer_record.id;

            updated_count := updated_count + 1;
        END IF;
    END LOOP;

    RETURN updated_count;
END;
$$;

ALTER FUNCTION public.update_customer_contact_with_auth_phone() OWNER TO supabase_admin;

--
-- Name: update_customer_contact_with_priority(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_customer_contact_with_priority(customer_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    priority_contact TEXT;
    contact_source TEXT;
    result JSONB;
BEGIN
    -- Get the priority contact
    SELECT priority_contact, contact_source INTO priority_contact, contact_source
    FROM get_customer_with_priority_contact(customer_id);

    IF priority_contact IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'No contact information available'
        );
    END IF;

    -- Update the customer's contact field
    UPDATE customers
    SET contact = priority_contact
    WHERE id = customer_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Customer not found'
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'customer_id', customer_id,
        'contact', priority_contact,
        'contact_source', contact_source
    );
END;
$$;

ALTER FUNCTION public.update_customer_contact_with_priority(customer_id uuid) OWNER TO supabase_admin;

--
-- Name: update_dispatch_smart(uuid, jsonb, jsonb[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_dispatch_smart(p_dispatch_id uuid, p_dispatch_data jsonb, p_dispatch_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_invoiced_items text;
    v_insufficient_stock text;
    v_foreign_lots text;
    v_affected_gr_ids uuid[];
    v_dispatch_items_result jsonb[];
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_dispatch_smart',jsonb_build_object('p_dispatch_id',p_dispatch_id));
  PERFORM warehouse_security.require_person_supervisor(p_dispatch_data->>'supervisor_id',
    (SELECT supervisor_id FROM dispatch WHERE id = p_dispatch_id));
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
    -- Check if user is admin or supervisor
    IF NOT warehouse_security.active_role() IN ('admin','supervisor','staff') THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'Only administrators and supervisors can update dispatches'
        );
    END IF;

    -- Get current user
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();

    IF p_dispatch_data->>'disp_no' IS NOT NULL AND warehouse_security.is_blank_text(p_dispatch_data->>'disp_no') THEN
        RAISE EXCEPTION 'disp_no is required' USING ERRCODE = 'WH409';
    END IF;

    -- Every line names a lot that exists and a whole quantity above zero.
    IF EXISTS (
        SELECT 1 FROM unnest(p_dispatch_items) AS new_item
        WHERE NOT EXISTS (
            SELECT 1 FROM goodsreceived_trl gt WHERE gt.id = (new_item->>'gr_trl_id')::uuid
        )
    ) THEN
        RAISE EXCEPTION 'Dispatch item does not exist in inventory' USING ERRCODE = 'WH409';
    END IF;
    IF EXISTS (
        SELECT 1 FROM unnest(p_dispatch_items) AS new_item
        WHERE new_item->>'disp_qty' IS NULL
           OR (new_item->>'disp_qty')::numeric <= 0
           OR (new_item->>'disp_qty')::numeric <> floor((new_item->>'disp_qty')::numeric)
    ) THEN
        RAISE EXCEPTION 'Dispatch quantity must be a whole number greater than 0' USING ERRCODE = 'WH409';
    END IF;

    -- A lot appears once in the dispatch lines (migration 87).
    IF EXISTS (
        SELECT 1 FROM unnest(p_dispatch_items) AS d
        GROUP BY (d->>'gr_trl_id')::uuid HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'The same lot appears twice in the dispatch lines' USING ERRCODE = 'WH409';
    END IF;

    -- A dispatch carries only its own customer's lots: a line this edit adds
    -- must belong to the dispatch customer, and the customer may change only
    -- when every line the edit leaves belongs to the new one. The receipts are
    -- key-share locked so update_grn cannot move one to another customer meanwhile.
    PERFORM gr.id
    FROM goodsreceived gr
    WHERE gr.id IN (
        SELECT gt.gr_id
        FROM unnest(p_dispatch_items) AS new_item
        JOIN goodsreceived_trl gt ON gt.id = (new_item->>'gr_trl_id')::uuid
        UNION
        SELECT dt.gr_id FROM dispatch_trl dt WHERE dt.disp_id = p_dispatch_id
    )
    FOR KEY SHARE OF gr;

    SELECT string_agg(gt.item_name || ' (' || gr.gr_no || ')', ', ')
    INTO v_foreign_lots
    FROM dispatch d
    JOIN LATERAL (
        -- Lines the edit leaves: the new list, or the present lines when no list is sent
        SELECT (new_item->>'gr_trl_id')::uuid AS gr_trl_id
        FROM unnest(p_dispatch_items) AS new_item
        UNION
        SELECT dt.gr_trl_id FROM dispatch_trl dt
        WHERE dt.disp_id = d.id AND p_dispatch_items IS NULL
    ) AS kept ON true
    JOIN goodsreceived_trl gt ON gt.id = kept.gr_trl_id
    JOIN goodsreceived gr ON gr.id = gt.gr_id
    WHERE d.id = p_dispatch_id
    AND gr.customer_id IS DISTINCT FROM COALESCE((p_dispatch_data->>'customer_id')::uuid, d.customer_id)
    AND (
        -- The header customer is changing
        d.customer_id IS DISTINCT FROM COALESCE((p_dispatch_data->>'customer_id')::uuid, d.customer_id)
        OR
        -- The line is being added
        NOT EXISTS (
            SELECT 1 FROM dispatch_trl dt
            WHERE dt.disp_id = d.id AND dt.gr_trl_id = kept.gr_trl_id
        )
    );

    IF v_foreign_lots IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM dispatch d
            WHERE d.id = p_dispatch_id
            AND d.customer_id IS DISTINCT FROM COALESCE((p_dispatch_data->>'customer_id')::uuid, d.customer_id)
        ) THEN
            RAISE EXCEPTION 'Cannot change the dispatch customer: items belong to another customer: %', v_foreign_lots USING ERRCODE = 'WH409';
        END IF;
        RAISE EXCEPTION 'Item belongs to another customer: %', v_foreign_lots USING ERRCODE = 'WH409';
    END IF;

    -- A dispatch made from a cart stays with the cart's customer (migration 87).
    IF EXISTS (
        SELECT 1 FROM dispatch d
        WHERE d.id = p_dispatch_id
        AND d.source_order_id IS NOT NULL
        AND COALESCE((p_dispatch_data->>'customer_id')::uuid, d.customer_id) IS DISTINCT FROM d.customer_id
        AND COALESCE((p_dispatch_data->>'customer_id')::uuid, d.customer_id)
            IS DISTINCT FROM (SELECT o.customer_id FROM orders o WHERE o.id = d.source_order_id)
    ) THEN
        RAISE EXCEPTION 'The order belongs to another customer' USING ERRCODE = 'WH409';
    END IF;

    -- Update dispatch header if data provided (single statement - OK)
    IF p_dispatch_data IS NOT NULL THEN
        UPDATE dispatch SET
            disp_no = COALESCE(p_dispatch_data->>'disp_no', disp_no),
            disp_date = COALESCE((p_dispatch_data->>'disp_date')::date::timestamptz, disp_date),
            registration = COALESCE(p_dispatch_data->>'registration', registration),
            customer_id = COALESCE((p_dispatch_data->>'customer_id')::uuid, customer_id),
            customer_name = COALESCE(p_dispatch_data->>'customer_name', customer_name),
            supervisor_id = COALESCE((p_dispatch_data->>'supervisor_id')::uuid, supervisor_id),
            supervisor_name = COALESCE(p_dispatch_data->>'supervisor_name', supervisor_name),
            note = COALESCE(p_dispatch_data->>'note', note),
            updated_by = v_user_id,
            updated_at = NOW()
        WHERE id = p_dispatch_id;
    END IF;

    -- Handle items if provided
    IF p_dispatch_items IS NOT NULL THEN
        -- ========== STEP 1: VALIDATION - Check invoiced items ==========
        -- Check if any items being modified or deleted are invoiced
        SELECT string_agg(gt.item_name, ', ')
        INTO v_invoiced_items
        FROM dispatch_trl dt
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND EXISTS (SELECT 1 FROM invoice_trl WHERE disp_trl_id = dt.id)
        AND (
            -- Item is being deleted (not in new list)
            NOT EXISTS (
                SELECT 1 FROM unnest(p_dispatch_items) AS new_item
                WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
            )
            OR
            -- Item qty is being changed
            EXISTS (
                SELECT 1 FROM unnest(p_dispatch_items) AS new_item
                WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
                AND (new_item->>'disp_qty')::integer != dt.disp_qty
            )
        );

        IF v_invoiced_items IS NOT NULL THEN
            RAISE EXCEPTION 'Cannot modify invoiced items: %', v_invoiced_items USING ERRCODE = 'WH409';
        END IF;

        -- ========== STEP 2: LOCK all affected GRN items ==========
        PERFORM gt.id
        FROM goodsreceived_trl gt
        WHERE gt.id IN (
            -- Existing items in dispatch
            SELECT dt.gr_trl_id FROM dispatch_trl dt WHERE dt.disp_id = p_dispatch_id
            UNION
            -- New items being added
            SELECT (new_item->>'gr_trl_id')::uuid FROM unnest(p_dispatch_items) AS new_item
        )
        FOR UPDATE OF gt;

        -- ========== STEP 3: VALIDATE stock for increases and new items ==========
        SELECT string_agg(
            gt.item_name || ' (Available: ' || gt.stock || ', Need: ' || needed.additional || ')',
            ', '
        )
        INTO v_insufficient_stock
        FROM (
            -- New items need full qty
            SELECT (new_item->>'gr_trl_id')::uuid AS gr_trl_id,
                   (new_item->>'disp_qty')::integer AS additional
            FROM unnest(p_dispatch_items) AS new_item
            WHERE NOT EXISTS (
                SELECT 1 FROM dispatch_trl dt
                WHERE dt.disp_id = p_dispatch_id
                AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
            )
            UNION ALL
            -- Existing items with qty increase need the difference
            SELECT dt.gr_trl_id,
                   (new_item->>'disp_qty')::integer - dt.disp_qty AS additional
            FROM dispatch_trl dt
            JOIN unnest(p_dispatch_items) AS new_item ON (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
            WHERE dt.disp_id = p_dispatch_id
            AND (new_item->>'disp_qty')::integer > dt.disp_qty
        ) AS needed
        JOIN goodsreceived_trl gt ON gt.id = needed.gr_trl_id
        WHERE gt.stock < needed.additional;

        IF v_insufficient_stock IS NOT NULL THEN
            RAISE EXCEPTION 'Insufficient stock: %', v_insufficient_stock USING ERRCODE = 'WH409';
        END IF;

        -- ========== STEP 4: Collect affected GR_IDs for out_of_stock update ==========
        SELECT ARRAY(
            SELECT DISTINCT gr_id FROM (
                SELECT dt.gr_id FROM dispatch_trl dt WHERE dt.disp_id = p_dispatch_id
                UNION
                SELECT gt.gr_id FROM unnest(p_dispatch_items) AS new_item
                JOIN goodsreceived_trl gt ON gt.id = (new_item->>'gr_trl_id')::uuid
            ) AS all_gr_ids
        ) INTO v_affected_gr_ids;

        -- ========== STEP 5: BULK restore stock for DELETED items ==========
        UPDATE goodsreceived_trl gt
        SET stock = gt.stock + dt.disp_qty
        FROM dispatch_trl dt
        WHERE dt.disp_id = p_dispatch_id
        AND gt.id = dt.gr_trl_id
        AND NOT EXISTS (
            SELECT 1 FROM unnest(p_dispatch_items) AS new_item
            WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        );

        -- ========== STEP 6: BULK log movements for DELETED items ==========
        INSERT INTO stock_movements (gr_trl_id, movement_type, quantity, reference_id, reference_type, balance_before, balance_after, created_by, notes)
        SELECT
            dt.gr_trl_id,
            'return',
            dt.disp_qty,
            dt.id,
            'dispatch_item_delete',
            gt.stock - dt.disp_qty,  -- balance_before (stock was already restored)
            gt.stock,                 -- balance_after
            v_user_id,
            'Item removed from dispatch'
        FROM dispatch_trl dt
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND NOT EXISTS (
            SELECT 1 FROM unnest(p_dispatch_items) AS new_item
            WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        );

        -- ========== STEP 7: BULK delete removed items ==========
        DELETE FROM dispatch_trl dt
        WHERE dt.disp_id = p_dispatch_id
        AND NOT EXISTS (
            SELECT 1 FROM unnest(p_dispatch_items) AS new_item
            WHERE (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        );

        -- ========== STEP 8: BULK update stock for QTY CHANGES ==========
        UPDATE goodsreceived_trl gt
        SET stock = gt.stock - ((new_item->>'disp_qty')::integer - dt.disp_qty)
        FROM dispatch_trl dt
        JOIN unnest(p_dispatch_items) AS new_item ON (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND gt.id = dt.gr_trl_id
        AND (new_item->>'disp_qty')::integer != dt.disp_qty;

        -- ========== STEP 9: BULK log movements for QTY CHANGES ==========
        INSERT INTO stock_movements (gr_trl_id, movement_type, quantity, reference_id, reference_type, balance_before, balance_after, created_by, notes)
        SELECT
            dt.gr_trl_id,
            CASE WHEN (new_item->>'disp_qty')::integer > dt.disp_qty THEN 'dispatch' ELSE 'return' END,
            -((new_item->>'disp_qty')::integer - dt.disp_qty),
            dt.id,
            'dispatch_update',
            gt.stock + ((new_item->>'disp_qty')::integer - dt.disp_qty),  -- balance_before
            gt.stock,  -- balance_after (already updated)
            v_user_id,
            format('Qty changed from %s to %s', dt.disp_qty, (new_item->>'disp_qty')::integer)
        FROM dispatch_trl dt
        JOIN unnest(p_dispatch_items) AS new_item ON (new_item->>'gr_trl_id')::uuid = dt.gr_trl_id
        JOIN goodsreceived_trl gt ON gt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
        AND (new_item->>'disp_qty')::integer != dt.disp_qty;

        -- ========== STEP 10: BULK update dispatch_trl quantities ==========
        UPDATE dispatch_trl dt
        SET disp_qty = (new_item->>'disp_qty')::integer
        FROM unnest(p_dispatch_items) AS new_item
        WHERE dt.disp_id = p_dispatch_id
        AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
        AND dt.disp_qty != (new_item->>'disp_qty')::integer;

        -- ========== STEP 11: BULK deduct stock for NEW items ==========
        UPDATE goodsreceived_trl gt
        SET stock = gt.stock - (new_item->>'disp_qty')::integer
        FROM unnest(p_dispatch_items) AS new_item
        WHERE gt.id = (new_item->>'gr_trl_id')::uuid
        AND NOT EXISTS (
            SELECT 1 FROM dispatch_trl dt
            WHERE dt.disp_id = p_dispatch_id
            AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
        );

        -- ========== STEP 12: BULK insert NEW dispatch items, and log a
        -- movement for exactly the rows inserted (migration 67) ==========
        -- A line added to a dispatch from the cart is marked 'cart' (it takes
        -- nothing from the cart, so nothing is given back for it on deletion).
        WITH inserted AS (
            INSERT INTO dispatch_trl (disp_id, gr_trl_id, gr_id, disp_qty, source_type)
            SELECT
                p_dispatch_id,
                (new_item->>'gr_trl_id')::uuid,
                gt.gr_id,
                (new_item->>'disp_qty')::integer,
                CASE WHEN EXISTS (SELECT 1 FROM dispatch d WHERE d.id = p_dispatch_id AND d.source_order_id IS NOT NULL)
                     THEN 'cart' ELSE 'direct' END
            FROM unnest(p_dispatch_items) AS new_item
            JOIN goodsreceived_trl gt ON gt.id = (new_item->>'gr_trl_id')::uuid
            WHERE NOT EXISTS (
                SELECT 1 FROM dispatch_trl dt
                WHERE dt.disp_id = p_dispatch_id
                AND dt.gr_trl_id = (new_item->>'gr_trl_id')::uuid
            )
            RETURNING gr_trl_id, disp_qty
        )
        INSERT INTO stock_movements (gr_trl_id, movement_type, quantity, reference_id, reference_type, balance_before, balance_after, created_by)
        SELECT
            ins.gr_trl_id,
            'dispatch',
            -ins.disp_qty,
            p_dispatch_id,
            'dispatch',
            gt.stock + ins.disp_qty,  -- balance_before
            gt.stock,  -- balance_after (already updated in step 11)
            v_user_id
        FROM inserted ins
        JOIN goodsreceived_trl gt ON gt.id = ins.gr_trl_id;

        -- ========== STEP 14: BULK update out_of_stock status ==========
        UPDATE goodsreceived gr
        SET out_of_stock = NOT EXISTS (
            SELECT 1 FROM goodsreceived_trl grt
            WHERE grt.gr_id = gr.id AND grt.stock > 0
        )
        WHERE gr.id = ANY(v_affected_gr_ids);

    END IF;

    -- ========== Build response (single query) ==========
    SELECT ARRAY(
        SELECT jsonb_build_object(
            'id', dt.id,
            'gr_trl_id', dt.gr_trl_id,
            'gr_id', dt.gr_id,
            'disp_qty', dt.disp_qty,
            'item_id', grt.item_id,
            'item_name', grt.item_name,
            'packaging', grt.packaging,
            'weight', grt.weight,
            'rack', grt.rack
        )
        FROM dispatch_trl dt
        JOIN goodsreceived_trl grt ON grt.id = dt.gr_trl_id
        WHERE dt.disp_id = p_dispatch_id
    ) INTO v_dispatch_items_result;

    RETURN jsonb_build_object(
        'success', true,
        'dispatch_id', p_dispatch_id,
        'dispatch_items', v_dispatch_items_result
    );

EXCEPTION
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM
        );
END;
$$;

ALTER FUNCTION public.update_dispatch_smart(p_dispatch_id uuid, p_dispatch_data jsonb, p_dispatch_items jsonb[]) OWNER TO supabase_admin;

--
-- Name: update_grn(uuid, character varying, timestamp with time zone, uuid, character varying, uuid, character varying, uuid, character varying, character varying, character varying, boolean, character varying, jsonb, jsonb, character varying, text, jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_grn(p_grn_id uuid, p_gr_no character varying DEFAULT NULL::character varying, p_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_customer_id uuid DEFAULT NULL::uuid, p_customer_name character varying DEFAULT NULL::character varying, p_sender_id uuid DEFAULT NULL::uuid, p_sender_name character varying DEFAULT NULL::character varying, p_supervisor_id uuid DEFAULT NULL::uuid, p_supervisor_name character varying DEFAULT NULL::character varying, p_registration character varying DEFAULT NULL::character varying, p_note character varying DEFAULT NULL::character varying, p_leon boolean DEFAULT NULL::boolean, p_pricing_mode character varying DEFAULT NULL::character varying, p_items jsonb DEFAULT '[]'::jsonb, p_images jsonb DEFAULT '[]'::jsonb, p_duration_mode character varying DEFAULT NULL::character varying, p_idempotency_key text DEFAULT NULL::text, p_rates jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    SET jit TO 'off'
    AS $$
DECLARE
    v_user_id uuid;
    v_user_profile_id uuid;
    v_user_role text;
    v_item jsonb;
    v_image jsonb;
    v_grn_trl_item_id uuid;
    v_image_id uuid;
    v_current_qty int;
    v_current_stock int;
    v_item_name_from_db varchar;
    v_dispatched_qty int;
    v_items_updated int := 0;
    v_items_added int := 0;
    v_items_deleted int := 0;
    v_images_updated int := 0;
    v_images_added int := 0;
    v_images_deleted int := 0;
    v_items_skipped_stock jsonb := '[]'::jsonb;
    v_existing_grn_item_ids uuid[];
    v_provided_grn_item_ids uuid[];
    v_items_to_delete uuid[];
    v_item_index int;
    v_item_mapping jsonb := '[]'::jsonb;
    v_resolved_item_id uuid;
    v_existing_image_ids uuid[];
    v_kept_image_ids uuid[];
    v_final_grn_data jsonb;
    v_grn_items jsonb := '[]'::jsonb;
    v_grn_images jsonb;
    v_temp_item jsonb;
    v_grn_header jsonb;
    v_item_master_id uuid;
    v_item_name varchar;
    v_cached_response jsonb;
    v_result jsonb;
    v_line_rows integer;
    v_bad_line text;
    v_rate_failure jsonb;
    v_detail text;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_grn',jsonb_build_object('p_grn_id',p_grn_id,'p_customer_id',p_customer_id));
  -- Migration 90: rates typed on the GRN sheet are an administrator's or a supervisor's.
  IF p_rates IS NOT NULL AND warehouse_security.active_role() = 'staff' THEN
    RETURN warehouse_security.rate_failure('RATES_MANAGER_ONLY', 'Only administrators and supervisors can set rates on a GRN');
  END IF;
  -- Migration 95: a line's name and packaging fit the receipt columns (80 and 40 characters, as the catalog).
  IF jsonb_typeof(p_items) = 'array' THEN
    v_item_index := 0;
    FOR v_item IN SELECT e FROM jsonb_array_elements(p_items) AS e LOOP
      IF jsonb_typeof(v_item->'item_name') = 'string' AND char_length(v_item->>'item_name') > 80 THEN
        RETURN warehouse_security.grn_rate_failure('item_name_too_long',
          'An item name can have at most 80 characters', jsonb_build_object('limit', 80, 'index', v_item_index));
      END IF;
      IF jsonb_typeof(v_item->'packaging') = 'string' AND char_length(v_item->>'packaging') > 40 THEN
        RETURN warehouse_security.grn_rate_failure('packaging_too_long',
          'Packaging can have at most 40 characters', jsonb_build_object('limit', 40, 'index', v_item_index));
      END IF;
      v_item_index := v_item_index + 1;
    END LOOP;
  END IF;
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Authentication required'
        );
    END IF;

    SELECT id, role INTO v_user_profile_id, v_user_role
    FROM user_profiles
    WHERE auth_user_id = v_user_id;

    IF v_user_profile_id IS NULL THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'User profile not found'
        );
    END IF;

    IF v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Insufficient permissions. Only admin and supervisor can update GRNs'
        );
    END IF;

    -- IDEMPOTENCY CHECK: a repeated save answers with the stored result (migration 47)
    IF p_idempotency_key IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(71040);

        SELECT response INTO v_cached_response
        FROM idempotency_keys
        WHERE idempotency_key = p_idempotency_key
          AND rpc_function = 'update_grn'
          AND created_by = v_user_profile_id
          AND response #>> '{grn,id}' = p_grn_id::text
          AND expires_at > now();

        IF v_cached_response IS NOT NULL THEN
            RETURN v_cached_response || jsonb_build_object('idempotent', true);
        END IF;
    END IF;

    IF NOT EXISTS (SELECT 1 FROM goodsreceived WHERE id = p_grn_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'GRN not found'
        );
    END IF;

    PERFORM warehouse_security.require_person_supervisor(p_supervisor_id::text,
      (SELECT supervisor_id FROM goodsreceived WHERE id = p_grn_id));

    IF p_gr_no IS NOT NULL AND warehouse_security.is_blank_text(p_gr_no) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'GRN number is required'
        );
    END IF;

    IF p_gr_no IS NOT NULL AND EXISTS (
        SELECT 1 FROM goodsreceived
        WHERE gr_no = p_gr_no AND id != p_grn_id
    ) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'GRN number already exists: ' || p_gr_no
        );
    END IF;

    BEGIN
        PERFORM pg_advisory_xact_lock(71040);

        IF p_customer_id IS NOT NULL AND EXISTS (
            SELECT 1 FROM goodsreceived
            WHERE id = p_grn_id AND customer_id IS DISTINCT FROM p_customer_id
        ) THEN
            IF EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id AND deleted_at IS NOT NULL) THEN
                RAISE EXCEPTION 'Business is not active' USING ERRCODE = 'P0001';
            END IF;
            IF EXISTS (SELECT 1 FROM customers WHERE id = p_customer_id AND active = false) THEN
                RAISE EXCEPTION 'This business is deactivated. Activate it in Customers to receive new goods.' USING ERRCODE = 'P0001';
            END IF;
            PERFORM 1 FROM goodsreceived WHERE id = p_grn_id FOR UPDATE;

            IF EXISTS (SELECT 1 FROM dispatch_trl WHERE gr_id = p_grn_id)
               OR EXISTS (SELECT 1 FROM invoice WHERE gr_id = p_grn_id)
               OR EXISTS (
                   SELECT 1 FROM order_items oi
                   JOIN orders o ON o.id = oi.order_id
                   JOIN goodsreceived_trl gt ON gt.id = oi.grn_items_id
                   WHERE gt.gr_id = p_grn_id AND o.deleted_at IS NULL
               ) THEN
                RAISE EXCEPTION 'Cannot change the customer of a GRN that has dispatches, invoices or order items';
            END IF;
        END IF;
        IF p_pricing_mode IS NOT NULL AND EXISTS (
            SELECT 1 FROM goodsreceived
            WHERE id = p_grn_id AND COALESCE(pricing_mode, 'MONTHLY') IS DISTINCT FROM p_pricing_mode
        ) THEN
            PERFORM 1 FROM goodsreceived WHERE id = p_grn_id FOR UPDATE;

            IF EXISTS (SELECT 1 FROM invoice WHERE gr_id = p_grn_id AND deleted_at IS NULL)
               OR EXISTS (
                   SELECT 1 FROM invoice_trl it
                   JOIN dispatch_trl dt ON dt.id = it.disp_trl_id
                   JOIN invoice inv ON inv.id = it.invoice_id
                   WHERE dt.gr_id = p_grn_id AND inv.deleted_at IS NULL
               ) THEN
                RAISE EXCEPTION 'Cannot change the pricing mode of a GRN that has invoices: delete invoices first, then change the pricing mode and invoice again';
            END IF;
        END IF;

        SELECT (e->>'id')::uuid::text INTO v_bad_line
        FROM jsonb_array_elements(p_items) AS e
        WHERE e->>'id' IS NOT NULL
        GROUP BY (e->>'id')::uuid
        HAVING count(*) > 1
        LIMIT 1;
        IF v_bad_line IS NOT NULL THEN
            RAISE EXCEPTION 'A GRN line is sent more than once in this edit; reload the GRN and edit again';
        END IF;

        SELECT x.e->>'id' INTO v_bad_line
        FROM jsonb_array_elements(p_items) WITH ORDINALITY AS x(e, n)
        WHERE x.e->>'id' IS NOT NULL
          AND NOT EXISTS (
              SELECT 1 FROM goodsreceived_trl t
              WHERE t.id = (x.e->>'id')::uuid AND t.gr_id = p_grn_id
          )
        ORDER BY x.n
        LIMIT 1;
        IF v_bad_line IS NOT NULL THEN
            RAISE EXCEPTION 'GRN line % is not a line of this GRN; reload the GRN and edit again', v_bad_line;
        END IF;

        PERFORM safe_disable_grn_trl_triggers();

        UPDATE goodsreceived SET
            gr_no = COALESCE(p_gr_no, gr_no),
            date = COALESCE(p_date, date),
            customer_id = COALESCE(p_customer_id, customer_id),
            customer_name = CASE
                WHEN p_customer_id IS NOT NULL AND p_customer_id IS DISTINCT FROM customer_id
                THEN COALESCE((SELECT c.name FROM customers c WHERE c.id = p_customer_id), customer_name)
                ELSE customer_name END,
            sender_id = COALESCE(p_sender_id, sender_id),
            sender_name = COALESCE(p_sender_name, sender_name),
            supervisor_id = COALESCE(p_supervisor_id, supervisor_id),
            supervisor_name = COALESCE(p_supervisor_name, supervisor_name),
            registration = COALESCE(p_registration, registration),
            note = COALESCE(p_note, note),
            leon = COALESCE(p_leon, leon),
            pricing_mode = COALESCE(p_pricing_mode, pricing_mode),
            duration_mode = COALESCE(p_duration_mode, duration_mode),
            updated_by = v_user_profile_id,
            updated_at = now()
        WHERE id = p_grn_id;

        SELECT array_agg(id) INTO v_existing_grn_item_ids
        FROM goodsreceived_trl
        WHERE gr_id = p_grn_id;

        v_provided_grn_item_ids := ARRAY[]::uuid[];

        v_item_index := 0;
        FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
        LOOP
            v_item_master_id := (v_item->>'item_id')::uuid;
            v_item_name := v_item->>'item_name';

            IF v_item_master_id IS NULL THEN
                RAISE EXCEPTION 'itemId is required for all items';
            END IF;
            IF v_item_name IS NULL OR v_item_name = '' THEN
                RAISE EXCEPTION 'itemName is required for all items';
            END IF;
            IF (v_item->>'qty')::int <= 0 THEN
                RAISE EXCEPTION 'Quantity must be greater than 0 for item "%"', v_item_name;
            END IF;
            IF (v_item->>'weight')::int < 0 THEN
                RAISE EXCEPTION 'Weight cannot be negative for item "%"', v_item_name;
            END IF;

            IF v_item->>'id' IS NOT NULL THEN
                SELECT qty, stock, item_name
                INTO v_current_qty, v_current_stock, v_item_name_from_db
                FROM goodsreceived_trl
                WHERE id = (v_item->>'id')::uuid AND gr_id = p_grn_id
                FOR UPDATE;

                IF NOT FOUND THEN
                    RAISE EXCEPTION 'GRN line % is not a line of this GRN; reload the GRN and edit again', v_item->>'id';
                END IF;

                SELECT COALESCE(SUM(disp_qty), 0)
                INTO v_dispatched_qty
                FROM dispatch_trl
                WHERE gr_trl_id = (v_item->>'id')::uuid;

                IF v_dispatched_qty = 0 THEN
                    UPDATE goodsreceived_trl SET
                        item_id = v_item_master_id,
                        item_name = v_item_name,
                        packaging = v_item->>'packaging',
                        qty = (v_item->>'qty')::int,
                        stock = (v_item->>'qty')::int,
                        weight = COALESCE((v_item->>'weight')::int, 0),
                        rack = v_item->>'rack',
                        package_mark = v_item->>'package_mark'
                    WHERE id = (v_item->>'id')::uuid AND gr_id = p_grn_id;

                    GET DIAGNOSTICS v_line_rows = ROW_COUNT;
                    IF v_line_rows <> 1 THEN
                        RAISE EXCEPTION 'GRN line % is not a line of this GRN; reload the GRN and edit again', v_item->>'id';
                    END IF;

                    v_items_updated := v_items_updated + 1;
                ELSE
                    UPDATE goodsreceived_trl SET
                        item_id = v_item_master_id,
                        item_name = v_item_name,
                        packaging = v_item->>'packaging',
                        weight = COALESCE((v_item->>'weight')::int, 0),
                        rack = v_item->>'rack',
                        package_mark = v_item->>'package_mark'
                    WHERE id = (v_item->>'id')::uuid AND gr_id = p_grn_id;

                    GET DIAGNOSTICS v_line_rows = ROW_COUNT;
                    IF v_line_rows <> 1 THEN
                        RAISE EXCEPTION 'GRN line % is not a line of this GRN; reload the GRN and edit again', v_item->>'id';
                    END IF;

                    v_items_updated := v_items_updated + 1;

                    v_items_skipped_stock := v_items_skipped_stock || jsonb_build_object(
                        'grn_trl_item_id', v_item->>'id',
                        'item_name', v_item_name_from_db,
                        'reason', format('Cannot update qty/stock - item has %s units dispatched', v_dispatched_qty),
                        'current_qty', v_current_qty,
                        'current_stock', v_current_stock,
                        'dispatched_qty', v_dispatched_qty
                    );
                END IF;

                v_provided_grn_item_ids := array_append(v_provided_grn_item_ids, (v_item->>'id')::uuid);
            ELSE
                INSERT INTO goodsreceived_trl (
                    gr_id, item_id, item_name, packaging, qty, stock, weight, rack, package_mark
                ) VALUES (
                    p_grn_id, v_item_master_id, v_item_name, v_item->>'packaging',
                    (v_item->>'qty')::int, (v_item->>'qty')::int,
                    COALESCE((v_item->>'weight')::int, 0), v_item->>'rack', v_item->>'package_mark'
                ) RETURNING id INTO v_grn_trl_item_id;

                v_items_added := v_items_added + 1;

                v_item_mapping := v_item_mapping || jsonb_build_object(
                    'index', v_item_index,
                    'grn_trl_item_id', v_grn_trl_item_id,
                    'item_name', v_item_name
                );
            END IF;

            v_item_index := v_item_index + 1;
        END LOOP;

        IF v_existing_grn_item_ids IS NOT NULL THEN
            v_items_to_delete := ARRAY(
                SELECT unnest(v_existing_grn_item_ids)
                EXCEPT
                SELECT unnest(v_provided_grn_item_ids)
            );

            IF v_items_to_delete IS NOT NULL THEN
                FOR v_grn_trl_item_id IN SELECT unnest(v_items_to_delete)
                LOOP
                    SELECT COUNT(*) INTO v_dispatched_qty
                    FROM dispatch_trl
                    WHERE gr_trl_id = v_grn_trl_item_id;

                    IF v_dispatched_qty > 0 THEN
                        SELECT item_name INTO v_item_name_from_db
                        FROM goodsreceived_trl
                        WHERE id = v_grn_trl_item_id;

                        RAISE EXCEPTION 'Cannot delete item "%" - has % existing dispatches',
                            v_item_name_from_db, v_dispatched_qty;
                    END IF;

                    DELETE FROM goodsreceived_trl WHERE id = v_grn_trl_item_id;
                    v_items_deleted := v_items_deleted + 1;
                END LOOP;
            END IF;
        END IF;

        IF jsonb_array_length(p_images) > 0 THEN
            v_kept_image_ids := ARRAY[]::uuid[];

            FOR v_image IN SELECT * FROM jsonb_array_elements(p_images)
            LOOP
                IF v_image->>'storage_path' IS NULL OR v_image->>'image_type' IS NULL THEN
                    RAISE EXCEPTION 'Invalid image data: storage_path and image_type are required';
                END IF;

                v_resolved_item_id := NULL;
                IF v_image->>'image_type' = 'item' THEN
                    IF v_image->>'grn_item_id' IS NOT NULL THEN
                        v_resolved_item_id := (v_image->>'grn_item_id')::uuid;
                    ELSIF v_image->>'item_index' IS NOT NULL THEN
                        SELECT (mapping->>'grn_trl_item_id')::uuid INTO v_resolved_item_id
                        FROM jsonb_array_elements(v_item_mapping) mapping
                        WHERE (mapping->>'index')::int = (v_image->>'item_index')::int;

                        IF v_resolved_item_id IS NULL THEN
                            RAISE EXCEPTION 'Invalid item_index % for image', v_image->>'item_index';
                        END IF;
                    ELSE
                        RAISE EXCEPTION 'Item images must have either grn_item_id or item_index';
                    END IF;
                END IF;

                IF v_resolved_item_id IS NOT NULL AND NOT EXISTS (
                    SELECT 1 FROM goodsreceived_trl WHERE id = v_resolved_item_id AND gr_id = p_grn_id) THEN
                    RAISE EXCEPTION 'Image line does not belong to this GRN';
                END IF;

                v_image_id := NULL;
                IF v_image->>'id' IS NOT NULL AND NOT (v_image->>'id' LIKE 'temp_%') THEN
                    SELECT id INTO v_image_id FROM grn_images
                    WHERE id = (v_image->>'id')::uuid AND grn_id = p_grn_id;
                END IF;
                IF v_image_id IS NULL THEN
                    SELECT id INTO v_image_id FROM grn_images
                    WHERE grn_id = p_grn_id AND storage_path = v_image->>'storage_path'
                    ORDER BY created_at, id LIMIT 1;
                END IF;

                IF v_image_id IS NOT NULL AND NOT EXISTS (
                    SELECT 1 FROM grn_images seen
                    WHERE seen.id = v_image_id
                    AND warehouse_security.grn_image_visible(seen.status, seen.uploaded_by)) THEN
                    -- Migration 69: another person's pending photo, named in the list, stays as it is.
                    v_kept_image_ids := array_append(v_kept_image_ids, v_image_id);
                ELSIF v_image_id IS NOT NULL THEN
                    UPDATE grn_images SET
                        grn_item_id = v_resolved_item_id,
                        updated_at = now()
                    WHERE id = v_image_id AND grn_id = p_grn_id;

                    v_images_updated := v_images_updated + 1;
                    v_kept_image_ids := array_append(v_kept_image_ids, v_image_id);
                ELSE
                    PERFORM warehouse_security.require_image_path('grn', p_grn_id, v_image->>'image_type', v_image->>'storage_path');

                    v_image_id := gen_random_uuid();

                    INSERT INTO grn_images (
                        id, grn_id, grn_item_id, image_type, storage_path,
                        original_filename, file_size, mime_type, uploaded_by, status
                    ) VALUES (
                        v_image_id, p_grn_id, v_resolved_item_id, v_image->>'image_type',
                        v_image->>'storage_path', COALESCE(v_image->>'original_filename', 'unknown'),
                        COALESCE((v_image->>'file_size')::int, 0),
                        COALESCE(v_image->>'mime_type', 'image/jpeg'), v_user_profile_id, 'confirmed'
                    );

                    v_images_added := v_images_added + 1;
                    v_kept_image_ids := array_append(v_kept_image_ids, v_image_id);
                END IF;
            END LOOP;

            DELETE FROM grn_images
            WHERE grn_id = p_grn_id
            AND id NOT IN (SELECT unnest(v_kept_image_ids))
            AND warehouse_security.grn_image_visible(grn_images.status, grn_images.uploaded_by);

            GET DIAGNOSTICS v_images_deleted = ROW_COUNT;
        ELSE
            v_images_deleted := 0;
        END IF;

        -- The GRN's own rates follow its lines, whether or not p_rates came: a rate of another pricing
        -- kind, or one whose band holds no weight of its item's lines any more, goes. An invoiced
        -- GRN keeps its (archived) rates.
        DELETE FROM public.grn_rates gr WHERE gr.gr_id = p_grn_id
          AND NOT EXISTS (SELECT 1 FROM public.goodsreceived g WHERE g.id = p_grn_id AND g.invoiced IS TRUE)
          AND (gr.price_type <> (SELECT CASE WHEN upper(COALESCE(g.pricing_mode, '')) = 'ONE_TIME' THEN 'one_time' ELSE 'monthly' END
                                   FROM public.goodsreceived g WHERE g.id = p_grn_id)
               OR NOT EXISTS (SELECT 1 FROM public.goodsreceived_trl t WHERE t.gr_id = p_grn_id AND t.item_id = gr.item_id
                                AND COALESCE(t.weight, 0) BETWEEN gr.weight_min AND gr.weight_max));

        -- Rates typed on the GRN sheet (migration 86), after the lines are written. A failure
        -- raises out of this block, which undoes the update, and the handler answers it.
        IF p_rates IS NOT NULL THEN
            v_rate_failure := warehouse_security.apply_grn_rates(p_grn_id, p_rates);
            IF v_rate_failure IS NOT NULL THEN
                RAISE EXCEPTION 'rate_fail' USING ERRCODE = 'P0001', DETAIL = v_rate_failure::text;
            END IF;
        END IF;

        PERFORM safe_enable_grn_trl_triggers();

        PERFORM pg_advisory_xact_lock(71040);

        SELECT jsonb_agg(
            jsonb_build_object(
                'id', t.id,
                'item_id', t.item_id,
                'item_name', t.item_name,
                'packaging', t.packaging,
                'qty', t.qty,
                'stock', t.stock,
                'weight', t.weight,
                'rack', t.rack,
                'package_mark', t.package_mark
            )
        ) INTO v_grn_items
        FROM goodsreceived_trl t
        WHERE t.gr_id = p_grn_id;

        SELECT jsonb_agg(
            jsonb_build_object(
                'id', i.id,
                'image_type', i.image_type,
                'storage_path', i.storage_path,
                'grn_item_id', i.grn_item_id,
                'original_filename', i.original_filename
            )
        ) INTO v_grn_images
        FROM grn_images i
        WHERE i.grn_id = p_grn_id
        AND warehouse_security.grn_image_visible(i.status, i.uploaded_by);

        SELECT jsonb_build_object(
            'id', g.id,
            'gr_no', g.gr_no,
            'date', g.date,
            'customer_id', g.customer_id,
            'customer_name', g.customer_name,
            'sender_id', g.sender_id,
            'sender_name', g.sender_name,
            'supervisor_id', g.supervisor_id,
            'supervisor_name', g.supervisor_name,
            'registration', g.registration,
            'note', g.note,
            'leon', g.leon,
            'pricing_mode', g.pricing_mode,
            'duration_mode', g.duration_mode
        ) INTO v_grn_header
        FROM goodsreceived g
        WHERE g.id = p_grn_id;

        v_final_grn_data := v_grn_header || jsonb_build_object(
            'items', COALESCE(v_grn_items, '[]'::jsonb),
            'images', COALESCE(v_grn_images, '[]'::jsonb)
        );

        v_result := jsonb_build_object(
            'success', true,
            'message', 'GRN updated successfully',
            'grn', v_final_grn_data,
            'stats', jsonb_build_object(
                'items_updated', v_items_updated,
                'items_added', v_items_added,
                'items_deleted', v_items_deleted,
                'images_updated', v_images_updated,
                'images_added', v_images_added,
                'images_deleted', v_images_deleted,
                'items_skipped_stock', v_items_skipped_stock
            ),
            'item_mapping', v_item_mapping
        );

        -- Kept for the 24 hours a retry is answered from it. A key another
        -- function or user holds is left alone unless it has expired.
        IF p_idempotency_key IS NOT NULL THEN
            INSERT INTO idempotency_keys (idempotency_key, rpc_function, response, created_by, expires_at)
            VALUES (p_idempotency_key, 'update_grn', v_result, v_user_profile_id, now() + interval '24 hours')
            ON CONFLICT (idempotency_key) DO UPDATE SET
                rpc_function = EXCLUDED.rpc_function,
                response = EXCLUDED.response,
                created_by = EXCLUDED.created_by,
                created_at = now(),
                expires_at = EXCLUDED.expires_at
            WHERE idempotency_keys.expires_at <= now()
               OR (idempotency_keys.rpc_function = EXCLUDED.rpc_function
                   AND idempotency_keys.created_by IS NOT DISTINCT FROM EXCLUDED.created_by);
        END IF;

        RETURN v_result;

    EXCEPTION WHEN OTHERS THEN
        IF SQLERRM = 'rate_fail' THEN
            GET STACKED DIAGNOSTICS v_detail = PG_EXCEPTION_DETAIL;
            PERFORM safe_enable_grn_trl_triggers();
            RETURN v_detail::jsonb;
        END IF;
        PERFORM safe_enable_grn_trl_triggers();
        RAISE;
    END;
END;
$$;

ALTER FUNCTION public.update_grn(p_grn_id uuid, p_gr_no character varying, p_date timestamp with time zone, p_customer_id uuid, p_customer_name character varying, p_sender_id uuid, p_sender_name character varying, p_supervisor_id uuid, p_supervisor_name character varying, p_registration character varying, p_note character varying, p_leon boolean, p_pricing_mode character varying, p_items jsonb, p_images jsonb, p_duration_mode character varying, p_idempotency_key text, p_rates jsonb) OWNER TO supabase_admin;

--
-- Name: update_grn_out_of_stock_status(uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_grn_out_of_stock_status(p_gr_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
  BEGIN
      -- Update out_of_stock flag based on whether any items have stock
      UPDATE goodsreceived
      SET out_of_stock = NOT EXISTS (
          SELECT 1
          FROM goodsreceived_trl
          WHERE gr_id = p_gr_id
          AND stock > 0
      )
      WHERE id = p_gr_id;
  END;
  $$;

ALTER FUNCTION public.update_grn_out_of_stock_status(p_gr_id uuid) OWNER TO supabase_admin;

--
-- Name: update_invoice(uuid, jsonb, jsonb[]); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_id UUID;
    v_new_gr_id UUID;
    v_old_gr_id UUID;
    v_discount NUMERIC(12,2);
    v_items_count INTEGER;
    v_duration_mode text;
    v_invoice_no integer;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_invoice',jsonb_build_object('p_invoice_id',p_invoice_id));
    -- The list-refresh lock comes before any row lock (migration 46).
    PERFORM pg_advisory_xact_lock(71040);
  PERFORM set_config('warehouse.discount_reason', COALESCE(p_invoice_data->>'discount_reason', ''), true);
  PERFORM warehouse_security.note_zero_charge_request(p_invoice_id, p_invoice_data);
  PERFORM warehouse_security.check_invoice_number(p_invoice_data->>'inv_no', p_invoice_id);
    SELECT id INTO v_user_id FROM user_profiles WHERE auth_user_id = auth.uid();
    v_discount := COALESCE(NULLIF(p_invoice_data->>'discount', '')::NUMERIC(12,2), 0::NUMERIC(12,2));
    v_new_gr_id := (p_invoice_data->>'gr_id')::uuid;
    v_duration_mode := public.validate_invoice_duration_mode(p_invoice_data->>'duration_mode');

    SELECT gr_id INTO v_old_gr_id FROM invoice WHERE id = p_invoice_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invoice not found');
    END IF;

    PERFORM warehouse_security.claim_invoice_lines(p_invoice_id, v_new_gr_id,
        ARRAY(SELECT (item->>'disp_trl_id')::uuid FROM unnest(p_invoice_items) AS item));

    IF v_old_gr_id IS DISTINCT FROM v_new_gr_id THEN
        IF v_old_gr_id IS NOT NULL THEN
            UPDATE goodsreceived SET invoiced = false WHERE id = v_old_gr_id;
        END IF;

        IF v_new_gr_id IS NOT NULL THEN
            UPDATE goodsreceived SET invoiced = true WHERE id = v_new_gr_id;
        END IF;
    END IF;

    UPDATE invoice SET
        inv_fin_year = (p_invoice_data->>'inv_fin_year')::integer,
        inv_no = (p_invoice_data->>'inv_no')::integer,
        gr_id = v_new_gr_id,
        gr_no = p_invoice_data->>'gr_no',
        customer_id = (p_invoice_data->>'customer_id')::uuid,
        customer_name = p_invoice_data->>'customer_name',
        inv_date = (p_invoice_data->>'inv_date')::TIMESTAMPTZ,
        labour = 0,
        tax_amount = 0,
        total = 0,
        discount = v_discount,
        one_time_charge = COALESCE((p_invoice_data->>'one_time_charge')::boolean, false),
        notes = p_invoice_data->>'notes',
        duration_mode = v_duration_mode
    WHERE id = p_invoice_id
    RETURNING inv_no INTO v_invoice_no;

    DELETE FROM invoice_trl WHERE invoice_id = p_invoice_id;

    INSERT INTO invoice_trl (invoice_id, disp_trl_id, duration, no_of_days, charge, tax, labour_rate)
    SELECT
        p_invoice_id,
        (item->>'disp_trl_id')::uuid,
        d.duration,
        d.no_of_days,
        COALESCE(NULLIF(item->>'charge', '')::NUMERIC(12,2), NULLIF(item->>'unit_price', '')::NUMERIC(12,2)),
        COALESCE(NULLIF(item->>'tax', '')::NUMERIC(12,2), NULLIF(item->>'tax_percent', '')::NUMERIC(12,2)),
        (item->>'labour_rate')::numeric
    FROM unnest(p_invoice_items) AS item
    JOIN dispatch_trl dt ON dt.id = (item->>'disp_trl_id')::uuid
    JOIN dispatch disp ON disp.id = dt.disp_id
    JOIN goodsreceived gr ON gr.id = dt.gr_id
    CROSS JOIN LATERAL public.calculate_invoice_duration(warehouse_security.business_date(gr.date), warehouse_security.business_date(disp.disp_date), v_duration_mode) d;

    GET DIAGNOSTICS v_items_count = ROW_COUNT;
    PERFORM warehouse_security.assert_invoice_lines(p_invoice_id, v_new_gr_id,
        (p_invoice_data->>'customer_id')::uuid, COALESCE(array_length(p_invoice_items, 1), 0));
    PERFORM warehouse_security.recalculate_invoice_header(p_invoice_id);

    RETURN jsonb_build_object(
        'success', true,
        'invoice_id', p_invoice_id,
        'invoice_no', v_invoice_no,
        'invoice_number', v_invoice_no,
        'items_count', v_items_count,
        'duration_mode', v_duration_mode,
        'message', 'Invoice updated successfully'
    );
EXCEPTION WHEN insufficient_privilege THEN RAISE;
WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM, 'error_code', SQLSTATE);
END;
$$;

ALTER FUNCTION public.update_invoice(p_invoice_id uuid, p_invoice_data jsonb, p_invoice_items jsonb[]) OWNER TO supabase_admin;

--
-- Name: update_item(uuid, character varying, character varying, character varying, boolean); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_item(p_item_id uuid, p_name character varying, p_packaging character varying DEFAULT NULL::character varying, p_description character varying DEFAULT NULL::character varying, p_active boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
    v_was_active boolean;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_item',jsonb_build_object());
    -- Security check
    IF NOT is_admin_or_supervisor() THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Access denied: Admin or supervisor role required'
        );
    END IF;

    -- Check if item exists
    IF NOT EXISTS (SELECT 1 FROM items WHERE id = p_item_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item not found'
        );
    END IF;

    -- Validate name
    IF p_name IS NULL OR TRIM(p_name) = '' THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Item name is required'
        );
    END IF;

    -- Check for duplicate name (excluding self)
    IF EXISTS (SELECT 1 FROM items WHERE LOWER(name) = LOWER(TRIM(p_name)) AND id != p_item_id) THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'An item with this name already exists'
        );
    END IF;

    SELECT active INTO v_was_active FROM items WHERE id = p_item_id;

    -- Update item
    UPDATE items
    SET name = TRIM(p_name),
        packaging = NULLIF(TRIM(p_packaging), ''),
        description = NULLIF(TRIM(p_description), ''),
        active = p_active
    WHERE id = p_item_id;

    -- An item that turns active and has no default rate gets the standard tiers from today (migration 85).
    IF COALESCE(v_was_active, false) = false AND p_active IS TRUE THEN
        PERFORM pg_advisory_xact_lock_shared(hashtextextended('standard_rate', 0));
        PERFORM warehouse_security.give_standard_rate(p_item_id, warehouse_security.business_date(now()));
    END IF;

    -- Return updated item
    SELECT jsonb_build_object(
        'id', id,
        'name', name,
        'packaging', packaging,
        'description', description,
        'active', active
    ) INTO v_result
    FROM items
    WHERE id = p_item_id;

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Item updated successfully',
        'data', v_result
    );
END;
$$;

ALTER FUNCTION public.update_item(p_item_id uuid, p_name character varying, p_packaging character varying, p_description character varying, p_active boolean) OWNER TO supabase_admin;

--
-- Name: update_item_storage_price(uuid, numeric, numeric, numeric, numeric, numeric, date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_item_storage_price(p_id uuid, p_unit_price numeric, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_tax_percent numeric, p_effective_from date, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_role TEXT;
    v_existing RECORD;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_item_storage_price',jsonb_build_object());
    -- Authorization: admin/supervisor only
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();

    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Get existing record (price_type cannot be changed)
    SELECT id, price_type, item_id, customer_id, effective_from INTO v_existing FROM item_storage_prices WHERE id = p_id;
    IF v_existing.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Price record not found');
    END IF;

    -- One change of this scope at a time, as in replace_item_rates; the row is read again under lock (migration 87).
    PERFORM pg_advisory_xact_lock(hashtextextended('item_rates:' || v_existing.item_id || ':' || COALESCE(v_existing.customer_id::text, 'default') || ':' || v_existing.price_type, 0));
    SELECT id, price_type, item_id, customer_id, effective_from INTO v_existing FROM item_storage_prices WHERE id = p_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Price record not found');
    END IF;

    -- A rate that is already in force is changed by administrators and supervisors (migration 76).
    IF v_user_role = 'staff' AND (v_existing.effective_from <= warehouse_security.business_date(now()) OR p_effective_from < warehouse_security.business_date(now())) THEN
        RETURN warehouse_security.rate_failure('RATE_IN_FORCE_MANAGER_ONLY',
          'Only administrators and supervisors can change a rate that is already in force');
    END IF;

    -- Validate weight range
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validate unit_price
    IF p_unit_price IS NULL OR p_unit_price < 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'unit_price must be >= 0');
    END IF;

    -- Validate date range
    IF p_effective_to IS NOT NULL AND p_effective_to < p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must not be before effective_from');
    END IF;

    -- No other row of this item, customer and price type may share a weight and a day (migration 76).
    IF warehouse_security.price_rows_overlap(v_existing.item_id, v_existing.customer_id, v_existing.price_type,
         p_weight_min::integer, p_weight_max::integer, p_effective_from, p_effective_to, p_id) THEN
        RETURN warehouse_security.rate_failure('BANDS_OVERLAP', 'Weight bands overlap');
    END IF;

    -- Update the record (price_type, item_id, customer_id cannot be changed)
    UPDATE item_storage_prices SET
        unit_price = p_unit_price,
        weight_min = p_weight_min,
        weight_max = p_weight_max,
        labour_rate = CASE WHEN v_existing.price_type = 'one_time' THEN 0 ELSE p_labour_rate END,
        tax_percent = p_tax_percent,
        effective_from = p_effective_from,
        effective_to = p_effective_to,
        -- Keep old columns in sync for backward compat
        unit_price_one_time = CASE WHEN v_existing.price_type = 'one_time' THEN p_unit_price ELSE 0 END,
        unit_price_monthly = CASE WHEN v_existing.price_type = 'monthly' THEN p_unit_price ELSE 0 END
    WHERE id = p_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object('id', p_id),
        'message', 'Price updated successfully'
    );

EXCEPTION
    WHEN unique_violation THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', 'A price with the same item, customer, weight range, price type and effective dates already exists'
        );
    WHEN OTHERS THEN
        RETURN jsonb_build_object(
            'success', false,
            'error', SQLERRM,
            'error_code', SQLSTATE
        );
END;
$$;

ALTER FUNCTION public.update_item_storage_price(p_id uuid, p_unit_price numeric, p_weight_min numeric, p_weight_max numeric, p_labour_rate numeric, p_tax_percent numeric, p_effective_from date, p_effective_to date) OWNER TO supabase_admin;

--
-- Name: update_item_storage_price(uuid, numeric, numeric, numeric, numeric, numeric, numeric, date, date); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_item_storage_price(p_id uuid, p_weight_min numeric, p_weight_max numeric, p_unit_price_one_time numeric, p_unit_price_monthly numeric, p_labour_rate numeric, p_tax_percent numeric, p_effective_from date, p_effective_to date DEFAULT NULL::date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $$
DECLARE
    v_user_role TEXT;
    v_existing RECORD;
    v_validation JSONB;
    v_result RECORD;
    v_overlap_count INTEGER;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_item_storage_price',jsonb_build_object());
    -- Authorization: admin/supervisor only
    SELECT role INTO v_user_role FROM user_profiles WHERE auth_user_id = auth.uid();
    IF v_user_role IS NULL OR v_user_role NOT IN ('admin', 'supervisor', 'staff') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Permission denied');
    END IF;

    -- Get existing record (item_id and customer_id are immutable)
    SELECT * INTO v_existing FROM item_storage_prices WHERE id = p_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Price record not found');
    END IF;

    -- One change of this scope at a time, as in replace_item_rates; the row is read again under lock (migration 87).
    PERFORM pg_advisory_xact_lock(hashtextextended('item_rates:' || v_existing.item_id || ':' || COALESCE(v_existing.customer_id::text, 'default') || ':' || v_existing.price_type, 0));
    SELECT * INTO v_existing FROM item_storage_prices WHERE id = p_id FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Price record not found');
    END IF;

    -- A rate that is already in force is changed by administrators and supervisors (migration 76).
    IF v_user_role = 'staff' AND (v_existing.effective_from <= warehouse_security.business_date(now()) OR p_effective_from < warehouse_security.business_date(now())) THEN
        RETURN warehouse_security.rate_failure('RATE_IN_FORCE_MANAGER_ONLY',
          'Only administrators and supervisors can change a rate that is already in force');
    END IF;

    -- Validation 1: weight_max >= weight_min
    IF p_weight_max < p_weight_min THEN
        RETURN jsonb_build_object('success', false, 'error', 'weight_max must be >= weight_min');
    END IF;

    -- Validation 2: At least one price must be > 0
    IF COALESCE(p_unit_price_one_time, 0) <= 0 AND COALESCE(p_unit_price_monthly, 0) <= 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'At least one of unit_price_one_time or unit_price_monthly must be > 0');
    END IF;

    -- Validation 3: effective_to >= effective_from (if provided)
    IF p_effective_to IS NOT NULL AND p_effective_to < p_effective_from THEN
        RETURN jsonb_build_object('success', false, 'error', 'effective_to must be >= effective_from');
    END IF;

    -- Validation 4: no other row of this item, customer and price type may share a weight and a day (migration 87).
    IF warehouse_security.price_rows_overlap(v_existing.item_id, v_existing.customer_id, v_existing.price_type,
         p_weight_min::integer, p_weight_max::integer, p_effective_from, p_effective_to, p_id) THEN
        RETURN warehouse_security.rate_failure('BANDS_OVERLAP', 'Weight bands overlap');
    END IF;

    -- Update the record
    UPDATE item_storage_prices SET
        weight_min = p_weight_min::integer,
        weight_max = p_weight_max::integer,
        unit_price_one_time = COALESCE(p_unit_price_one_time, 0),
        unit_price_monthly = COALESCE(p_unit_price_monthly, 0),
        labour_rate = p_labour_rate,
        tax_percent = p_tax_percent,
        effective_from = p_effective_from,
        effective_to = p_effective_to
    WHERE id = p_id;

    -- Fetch the updated record with joined data
    SELECT
        isp.id,
        isp.item_id,
        i.name as item_name,
        isp.customer_id,
        c.name as customer_name,
        isp.weight_min,
        isp.weight_max,
        isp.unit_price_one_time,
        isp.unit_price_monthly,
        isp.labour_rate,
        isp.tax_percent,
        isp.effective_from,
        isp.effective_to,
        isp.created_at,
        isp.created_by
    INTO v_result
    FROM item_storage_prices isp
    LEFT JOIN items i ON isp.item_id = i.id
    LEFT JOIN customers c ON isp.customer_id = c.id
    WHERE isp.id = p_id;

    RETURN jsonb_build_object(
        'success', true,
        'data', jsonb_build_object(
            'id', v_result.id,
            'item_id', v_result.item_id,
            'item_name', v_result.item_name,
            'customer_id', v_result.customer_id,
            'customer_name', v_result.customer_name,
            'weight_min', v_result.weight_min,
            'weight_max', v_result.weight_max,
            'unit_price_one_time', v_result.unit_price_one_time,
            'unit_price_monthly', v_result.unit_price_monthly,
            'labour_rate', v_result.labour_rate,
            'tax_percent', v_result.tax_percent,
            'effective_from', v_result.effective_from,
            'effective_to', v_result.effective_to,
            'created_at', v_result.created_at,
            'created_by', v_result.created_by
        ),
        'message', 'Price updated successfully'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object(
        'success', false,
        'error', 'Update failed: ' || SQLERRM
    );
END;
$$;

ALTER FUNCTION public.update_item_storage_price(p_id uuid, p_weight_min numeric, p_weight_max numeric, p_unit_price_one_time numeric, p_unit_price_monthly numeric, p_labour_rate numeric, p_tax_percent numeric, p_effective_from date, p_effective_to date) OWNER TO supabase_admin;

--
-- Name: update_order(uuid, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_order(p_order_id uuid, p_order_data jsonb, p_items jsonb, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM orders WHERE id = p_order_id) THEN
        RETURN utils.not_found_response('Order', p_order_id::text);
    END IF;

    -- Update order fields if provided
    UPDATE orders SET
        note = COALESCE(p_order_data->>'note', note),
        priority = COALESCE(p_order_data->>'priority', priority),
        requested_dispatch_date = COALESCE((p_order_data->>'requested_dispatch_date')::timestamp, requested_dispatch_date),
        updated_at = NOW(),
        updated_by = p_user_id
    WHERE id = p_order_id;

    RETURN utils.success_response(jsonb_build_object('order_id', p_order_id), 'Order updated successfully');
EXCEPTION
    WHEN OTHERS THEN
        RETURN utils.database_error_response('Failed to update order', SQLERRM, SQLSTATE);
END;
$$;

ALTER FUNCTION public.update_order(p_order_id uuid, p_order_data jsonb, p_items jsonb, p_user_id uuid) OWNER TO supabase_admin;

--
-- Name: update_order_item_quantity(uuid, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_order_item_quantity(p_order_item_id uuid, p_new_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'warehouse_security', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_item record;
  v_stock integer;
BEGIN
  PERFORM warehouse_security.authorize_rpc(
    'update_order_item_quantity',
    jsonb_build_object('p_order_item_id', p_order_item_id)
  );

  IF p_new_quantity IS NULL OR p_new_quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'message', 'Quantity must be greater than zero');
  END IF;

  SELECT id INTO v_user_id
  FROM public.user_profiles
  WHERE auth_user_id = auth.uid() AND active;

  SELECT oi.id, oi.order_id, oi.requested_quantity, oi.fulfilled_quantity,
         oi.grn_items_id, oi.grn_items_item_name, o.status, o.deleted_at
  INTO v_item
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE oi.id = p_order_item_id
  FOR UPDATE OF oi;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Order item not found');
  END IF;
  IF v_item.status <> 'OPEN' OR v_item.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', 'Cannot change items on ' || COALESCE(v_item.status, 'closed') || ' orders',
      'error', jsonb_build_object('code', 'ORDER_NOT_OPEN')
    );
  END IF;
  IF p_new_quantity < v_item.fulfilled_quantity THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', format('Quantity cannot be below the %s already dispatched', v_item.fulfilled_quantity)
    );
  END IF;

  SELECT stock INTO v_stock FROM public.goodsreceived_trl WHERE id = v_item.grn_items_id;
  IF COALESCE(v_stock, 0) < p_new_quantity THEN
    RETURN jsonb_build_object(
      'success', false,
      'message', format('Insufficient stock. Available: %s, Requested: %s', COALESCE(v_stock, 0), p_new_quantity)
    );
  END IF;

  UPDATE public.order_items
  SET requested_quantity = p_new_quantity,
      current_stock = v_stock,
      updated_at = now()
  WHERE id = p_order_item_id;

  PERFORM warehouse_security.record_order_revision(v_item.order_id, v_user_id);
  UPDATE public.orders SET updated_at = now(), updated_by = v_user_id WHERE id = v_item.order_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', 'Quantity updated successfully',
    'data', jsonb_build_object(
      'order_item_id', p_order_item_id,
      'old_quantity', v_item.requested_quantity,
      'new_quantity', p_new_quantity,
      'item_name', v_item.grn_items_item_name
    )
  );
EXCEPTION
  WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Error updating quantity: ' || SQLERRM);
END;
$$;

ALTER FUNCTION public.update_order_item_quantity(p_order_item_id uuid, p_new_quantity integer) OWNER TO supabase_admin;

--
-- Name: update_order_items_batch(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_order_items_batch(p_order_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'warehouse_security', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
  v_item jsonb;
  v_update_count integer := 0;
  v_rows integer;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_order_items_batch', jsonb_build_object('p_order_id', p_order_id));

  SELECT id INTO v_user_id FROM public.user_profiles WHERE auth_user_id = auth.uid() AND active;
  IF NOT EXISTS (SELECT 1 FROM public.orders WHERE id = p_order_id) THEN
    RETURN jsonb_build_object('success', false, 'message', 'Order not found');
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) LOOP
    UPDATE public.order_items
    SET requested_quantity = (v_item->>'quantity')::integer,
        updated_at = now()
    WHERE id = (v_item->>'order_item_id')::uuid AND order_id = p_order_id;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    v_update_count := v_update_count + v_rows;
  END LOOP;

  PERFORM warehouse_security.record_order_revision(
    p_order_id, v_user_id, 'UPDATE',
    jsonb_build_object('batch_update', true, 'items_updated', v_update_count));
  UPDATE public.orders SET updated_at = now(), updated_by = v_user_id WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'message', format('%s items updated successfully', v_update_count),
    'data', jsonb_build_object('items_updated', v_update_count)
  );
EXCEPTION
  WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Error in batch update: ' || SQLERRM);
END;
$$;

ALTER FUNCTION public.update_order_items_batch(p_order_id uuid, p_items jsonb) OWNER TO supabase_admin;

--
-- Name: update_order_metadata(uuid, text, text, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_order_metadata(p_order_id uuid, p_note text DEFAULT NULL::text, p_priority text DEFAULT NULL::text, p_requested_dispatch_date timestamp without time zone DEFAULT NULL::timestamp without time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'warehouse_security', 'pg_temp'
    AS $$
DECLARE
  v_user_id uuid;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_order_metadata', jsonb_build_object('p_order_id', p_order_id));

  SELECT id INTO v_user_id FROM public.user_profiles WHERE auth_user_id = auth.uid() AND active;

  UPDATE public.orders
  SET note = COALESCE(p_note, note),
      priority = COALESCE(p_priority, priority),
      requested_dispatch_date = COALESCE(p_requested_dispatch_date, requested_dispatch_date),
      updated_at = now(),
      updated_by = v_user_id
  WHERE id = p_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'message', 'Order not found');
  END IF;

  PERFORM warehouse_security.record_order_revision(p_order_id, v_user_id);

  RETURN jsonb_build_object('success', true, 'message', 'Order metadata updated successfully');
EXCEPTION
  WHEN insufficient_privilege THEN RAISE;
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Error updating order metadata: ' || SQLERRM);
END;
$$;

ALTER FUNCTION public.update_order_metadata(p_order_id uuid, p_note text, p_priority text, p_requested_dispatch_date timestamp without time zone) OWNER TO supabase_admin;

--
-- Name: update_order_updated_at_on_item_change(); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_order_updated_at_on_item_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_order_id UUID;
BEGIN
    -- Get the order_id depending on operation
    IF TG_OP = 'DELETE' THEN
        v_order_id := OLD.order_id;
    ELSE
        v_order_id := NEW.order_id;
    END IF;

    -- Update the parent order's updated_at
    UPDATE orders
    SET updated_at = NOW()
    WHERE id = v_order_id;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$$;

ALTER FUNCTION public.update_order_updated_at_on_item_change() OWNER TO supabase_admin;

--
-- Name: update_sensor_device(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_sensor_device(p_device_id uuid, p_device_name text DEFAULT NULL::text, p_location text DEFAULT NULL::text, p_staleness_threshold_minutes integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions', 'utils', 'pg_temp'
    AS $_$
DECLARE
  v_name text;
  v_location text;
  v_device public.sensor_devices;
BEGIN
  PERFORM warehouse_security.authorize_rpc('update_sensor_device', jsonb_build_object('p_device_id', p_device_id));
  v_name := btrim(p_device_name);
  v_location := btrim(p_location);
  IF p_device_name IS NOT NULL AND v_name !~ '^[^[:cntrl:]]{1,100}$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'The name must have 1 to 100 characters', 'error_code', 'INVALID_NAME');
  END IF;
  IF p_location IS NOT NULL AND v_location !~ '^[^[:cntrl:]]{0,200}$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'The location must have at most 200 characters', 'error_code', 'INVALID_LOCATION');
  END IF;
  IF p_staleness_threshold_minutes IS NOT NULL AND p_staleness_threshold_minutes NOT BETWEEN 5 AND 1440 THEN
    RETURN jsonb_build_object('success', false, 'error', 'The threshold must be 5 to 1440 minutes', 'error_code', 'INVALID_THRESHOLD');
  END IF;
  UPDATE public.sensor_devices d SET
    device_name = COALESCE(v_name, d.device_name),
    location = CASE WHEN p_location IS NULL THEN d.location ELSE NULLIF(v_location, '') END,
    staleness_threshold_minutes = COALESCE(p_staleness_threshold_minutes, d.staleness_threshold_minutes),
    updated_at = now()
  WHERE d.id = p_device_id
  RETURNING d.* INTO v_device;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Device not found', 'error_code', 'DEVICE_NOT_FOUND');
  END IF;
  UPDATE public.sensor_latest l SET device_name = v_device.device_name, location = v_device.location, updated_at = now()
  WHERE l.device_id = p_device_id;
  RETURN jsonb_build_object('success', true, 'data', jsonb_build_object(
    'device_id', v_device.id, 'device_name', v_device.device_name, 'location', v_device.location,
    'staleness_threshold_minutes', v_device.staleness_threshold_minutes));
END;
$_$;

ALTER FUNCTION public.update_sensor_device(p_device_id uuid, p_device_name text, p_location text, p_staleness_threshold_minutes integer) OWNER TO supabase_admin;

--
-- Name: update_service_credentials(character varying, jsonb); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.update_service_credentials(p_service_name character varying, p_credentials jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    -- Check if user is admin
    IF NOT EXISTS (
        SELECT 1 FROM user_profiles
        WHERE auth_user_id = auth.uid()
        AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Only admins can update service credentials';
    END IF;

    -- Update or insert credentials
    INSERT INTO public.secrets_vault (service_name, credentials, is_active, updated_at)
    VALUES (p_service_name, p_credentials, true, NOW())
    ON CONFLICT (service_name) DO UPDATE SET
        credentials = EXCLUDED.credentials,
        updated_at = NOW()
    RETURNING jsonb_build_object(
        'success', true,
        'service_name', service_name,
        'updated_at', updated_at
    ) INTO v_result;

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.update_service_credentials(p_service_name character varying, p_credentials jsonb) OWNER TO supabase_admin;

