--
-- Name: verify_otp_secure(character varying, character varying, inet, text); Type: FUNCTION; Schema: public; Owner: supabase_admin
--

CREATE FUNCTION public.verify_otp_secure(p_phone_number character varying, p_otp_code character varying, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
    v_user_id uuid;
BEGIN
    -- Call verify_otp
    v_result := verify_otp(p_phone_number, p_otp_code, 'login');

    -- Log the authentication attempt
    IF (v_result->>'success')::boolean THEN
        v_user_id := (v_result->'data'->>'user_id')::uuid;
    END IF;

    PERFORM log_authentication_attempt(
        p_phone_number,
        v_user_id,
        (v_result->>'success')::boolean,
        p_ip_address::text,
        p_user_agent,
        jsonb_build_object('method', 'otp_secure')
    );

    RETURN v_result;
END;
$$;

ALTER FUNCTION public.verify_otp_secure(p_phone_number character varying, p_otp_code character varying, p_ip_address inet, p_user_agent text) OWNER TO supabase_admin;

