--
-- Name: expired_generated_documents(timestamp with time zone); Type: FUNCTION; Schema: warehouse_maintenance; Owner: supabase_admin
--

CREATE FUNCTION warehouse_maintenance.expired_generated_documents(p_now timestamp with time zone DEFAULT now()) RETURNS SETOF text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'warehouse_maintenance'
    AS $_$
  SELECT o.name FROM storage.objects o
  WHERE o.bucket_id = 'documents'
    AND o.created_at < p_now - make_interval(days => (SELECT days FROM warehouse_maintenance.retention_policy WHERE key = 'generated_documents'))
    AND (o.name ~ '^(grn|dispatch|invoice|stock)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$'
      OR o.name ~ '^report/(grn-activity|dispatch-activity|invoice-history|stock-summary|stock-aging|item-stock-summary|customer-activity)/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}|all)/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.pdf$')
  ORDER BY o.created_at, o.name
$_$;

ALTER FUNCTION warehouse_maintenance.expired_generated_documents(p_now timestamp with time zone) OWNER TO supabase_admin;

--
-- Name: misplaced_image_paths(); Type: FUNCTION; Schema: warehouse_maintenance; Owner: supabase_admin
--

CREATE FUNCTION warehouse_maintenance.misplaced_image_paths() RETURNS TABLE(kind text, image_id uuid, document_id uuid, status text, storage_path text, reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT 'grn', i.id, i.grn_id, i.status::text, i.storage_path, 'outside the folder of its GRN'
  FROM public.grn_images i
  WHERE NOT COALESCE(starts_with(i.storage_path, warehouse_security.image_path_prefix('grn', i.grn_id, i.image_type::text)), false)
  UNION ALL
  SELECT 'dispatch', i.id, i.dispatch_id, i.status::text, i.storage_path, 'outside the folder of its dispatch'
  FROM public.dispatch_images i
  WHERE NOT COALESCE(starts_with(i.storage_path, warehouse_security.image_path_prefix('dispatch', i.dispatch_id, NULL)), false)
  UNION ALL
  SELECT 'grn', i.id, i.grn_id, i.status::text, i.storage_path, 'path also on another image row'
  FROM public.grn_images i
  WHERE EXISTS (SELECT 1 FROM public.grn_images o WHERE o.storage_path = i.storage_path AND o.id <> i.id)
  UNION ALL
  SELECT 'dispatch', i.id, i.dispatch_id, i.status::text, i.storage_path, 'path also on another image row'
  FROM public.dispatch_images i
  WHERE EXISTS (SELECT 1 FROM public.dispatch_images o WHERE o.storage_path = i.storage_path AND o.id <> i.id)
$$;

ALTER FUNCTION warehouse_maintenance.misplaced_image_paths() OWNER TO supabase_admin;

--
-- Name: run_database_retention(timestamp with time zone, boolean); Type: FUNCTION; Schema: warehouse_maintenance; Owner: supabase_admin
--

CREATE FUNCTION warehouse_maintenance.run_database_retention(p_now timestamp with time zone DEFAULT now(), p_apply boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'warehouse_security', 'warehouse_maintenance'
    AS $$
DECLARE
  auth_cutoff timestamptz;
  activity_cutoff timestamptz;
  log_cutoff timestamptz;
  sensor_cutoff timestamptz;
  result jsonb := '{}'::jsonb;
  affected bigint;
BEGIN
  SELECT p_now - make_interval(days => days) INTO auth_cutoff
    FROM warehouse_maintenance.retention_policy WHERE key = 'ephemeral_auth';
  SELECT p_now - make_interval(days => days) INTO activity_cutoff
    FROM warehouse_maintenance.retention_policy WHERE key = 'session_activity';
  SELECT p_now - make_interval(days => days) INTO log_cutoff
    FROM warehouse_maintenance.retention_policy WHERE key = 'security_logs';
  SELECT p_now - make_interval(days => days) INTO sensor_cutoff
    FROM warehouse_maintenance.retention_policy WHERE key = 'sensor_readings';

  IF p_apply THEN
    DELETE FROM warehouse_security.consumed_refresh_tokens WHERE expires_at < p_now;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('consumed_refresh_tokens', affected);
    DELETE FROM warehouse_security.refresh_sessions WHERE expires_at < p_now;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('refresh_sessions', affected);
    DELETE FROM warehouse_security.central_token_use WHERE expires_at < p_now;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('central_token_use', affected);
    DELETE FROM public.otp_verifications WHERE expires_at < auth_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('otp_verifications', affected);
    DELETE FROM public.otp_rate_limits WHERE updated_at < auth_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('otp_rate_limits', affected);
    DELETE FROM public.ip_rate_limits WHERE updated_at < auth_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('ip_rate_limits', affected);
    DELETE FROM public.idempotency_keys WHERE COALESCE(expires_at, created_at) < p_now;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('idempotency_keys', affected);
    DELETE FROM public.user_session_activity WHERE last_activity_at < activity_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('user_session_activity', affected);
    DELETE FROM public.auth_logs WHERE created_at < log_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('auth_logs', affected);
    DELETE FROM public.config_access_logs WHERE accessed_at < log_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('config_access_logs', affected);
    DELETE FROM public.intrusion_events WHERE recorded_at < log_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('intrusion_events', affected);
    DELETE FROM public.sensor_readings WHERE measured_at < sensor_cutoff;
    GET DIAGNOSTICS affected = ROW_COUNT; result := result || jsonb_build_object('sensor_readings', affected);
  ELSE
    SELECT result || jsonb_build_object(
      'consumed_refresh_tokens', (SELECT count(*) FROM warehouse_security.consumed_refresh_tokens WHERE expires_at < p_now),
      'refresh_sessions', (SELECT count(*) FROM warehouse_security.refresh_sessions WHERE expires_at < p_now),
      'central_token_use', (SELECT count(*) FROM warehouse_security.central_token_use WHERE expires_at < p_now),
      'otp_verifications', (SELECT count(*) FROM public.otp_verifications WHERE expires_at < auth_cutoff),
      'otp_rate_limits', (SELECT count(*) FROM public.otp_rate_limits WHERE updated_at < auth_cutoff),
      'ip_rate_limits', (SELECT count(*) FROM public.ip_rate_limits WHERE updated_at < auth_cutoff),
      'idempotency_keys', (SELECT count(*) FROM public.idempotency_keys WHERE COALESCE(expires_at, created_at) < p_now),
      'user_session_activity', (SELECT count(*) FROM public.user_session_activity WHERE last_activity_at < activity_cutoff),
      'auth_logs', (SELECT count(*) FROM public.auth_logs WHERE created_at < log_cutoff),
      'config_access_logs', (SELECT count(*) FROM public.config_access_logs WHERE accessed_at < log_cutoff),
      'intrusion_events', (SELECT count(*) FROM public.intrusion_events WHERE recorded_at < log_cutoff),
      'sensor_readings', (SELECT count(*) FROM public.sensor_readings WHERE measured_at < sensor_cutoff)
    ) INTO result;
  END IF;
  RETURN jsonb_build_object('applied', p_apply, 'as_of', p_now, 'rows', result);
END $$;

ALTER FUNCTION warehouse_maintenance.run_database_retention(p_now timestamp with time zone, p_apply boolean) OWNER TO supabase_admin;

