--
-- Name: check_invoice_number(text, uuid); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.check_invoice_number(p_number text, p_invoice_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $_$
DECLARE
  written text := btrim(p_number, E' \t\n\r\v\f');
  number numeric;
BEGIN
  IF written IS NULL OR written !~ '^[+-]?[0-9]+$' THEN RETURN; END IF;
  number := written::numeric;
  IF number BETWEEN 1 AND warehouse_security.invoice_number_max() THEN RETURN; END IF;
  IF p_invoice_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM public.invoice i WHERE i.id = p_invoice_id AND i.inv_no::numeric = number) THEN
    RETURN;
  END IF;
  RAISE EXCEPTION 'Invoice number must be between 1 and %', warehouse_security.invoice_number_max()
    USING ERRCODE = 'WH422';
END $_$;

ALTER FUNCTION warehouse_security.check_invoice_number(p_number text, p_invoice_id uuid) OWNER TO supabase_admin;

--
-- Name: claim_invoice_lines(uuid, uuid, uuid[]); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.claim_invoice_lines(p_invoice_id uuid, p_gr_id uuid, p_lines uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE receipt_invoiced boolean; own_receipt uuid;
BEGIN
  SELECT g.invoiced INTO receipt_invoiced FROM public.goodsreceived g WHERE g.id=p_gr_id FOR NO KEY UPDATE;
  SELECT i.gr_id INTO own_receipt FROM public.invoice i WHERE i.id=p_invoice_id;
  IF receipt_invoiced IS TRUE AND own_receipt IS DISTINCT FROM p_gr_id THEN
    RAISE EXCEPTION 'GRN is already invoiced' USING ERRCODE = 'WH409';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.invoice_trl other
    JOIN public.invoice holder ON holder.id=other.invoice_id
    WHERE other.disp_trl_id = ANY(p_lines)
      AND holder.deleted_at IS NULL
      AND other.invoice_id IS DISTINCT FROM p_invoice_id
      AND NOT EXISTS (SELECT 1 FROM public.invoice_trl mine
                      WHERE mine.invoice_id=p_invoice_id AND mine.disp_trl_id=other.disp_trl_id)
  ) THEN
    RAISE EXCEPTION 'A dispatch line is already on another invoice' USING ERRCODE = 'WH409';
  END IF;
END $$;

ALTER FUNCTION warehouse_security.claim_invoice_lines(p_invoice_id uuid, p_gr_id uuid, p_lines uuid[]) OWNER TO supabase_admin;

--
-- Name: clean_person_name(text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.clean_person_name(p_value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE cleaned text := btrim(regexp_replace(COALESCE(p_value, ''), '\s+', ' ', 'g'));
BEGIN
  IF cleaned = '' OR cleaned !~ '^([A-Za-z0-9 .,''&()/-]|[^\u0001-\u007F])+$'
    OR cleaned ~ '[\u0080-\u009F‎‏‪-‮⁦-⁩]'
    OR cleaned !~ '[A-Za-z]|[^\u0001-\u007F]' THEN
    RETURN NULL;
  END IF;
  RETURN btrim(left(cleaned, 30));
END $_$;

ALTER FUNCTION warehouse_security.clean_person_name(p_value text) OWNER TO supabase_admin;

--
-- Name: copy_default_rates(uuid, uuid, date); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.copy_default_rates(p_from_item uuid, p_to_item uuid, p_day date) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE v_profile uuid; v_added integer;
BEGIN
  SELECT up.id INTO v_profile FROM public.user_profiles up WHERE up.auth_user_id = auth.uid() AND up.active;
  WITH picked AS (
    SELECT DISTINCT ON (r.price_type, r.weight_min, r.weight_max) r.*
      FROM public.item_storage_prices r
     WHERE r.item_id = p_from_item AND r.customer_id IS NULL
       AND r.effective_from <= p_day AND (r.effective_to IS NULL OR r.effective_to >= p_day)
     ORDER BY r.price_type, r.weight_min, r.weight_max, r.effective_from DESC, r.id)
  INSERT INTO public.item_storage_prices (
    item_id, customer_id, price_type, unit_price, weight_min, weight_max, labour_rate, tax_percent,
    effective_from, effective_to, created_by, unit_price_one_time, unit_price_monthly)
  SELECT p_to_item, NULL, r.price_type, r.unit_price, r.weight_min, r.weight_max,
         CASE WHEN r.price_type = 'one_time' THEN 0 ELSE r.labour_rate END, r.tax_percent,
         p_day, NULL, v_profile,
         CASE WHEN r.price_type = 'one_time' THEN r.unit_price ELSE 0 END,
         CASE WHEN r.price_type = 'monthly' THEN r.unit_price ELSE 0 END
    FROM picked r
   WHERE NOT EXISTS (SELECT 1 FROM picked a JOIN picked b ON a.price_type = b.price_type AND a.id <> b.id
                      AND a.weight_min <= b.weight_max AND b.weight_min <= a.weight_max)
   ORDER BY r.price_type, r.weight_min;
  GET DIAGNOSTICS v_added = ROW_COUNT;
  RETURN v_added;
END $$;

ALTER FUNCTION warehouse_security.copy_default_rates(p_from_item uuid, p_to_item uuid, p_day date) OWNER TO supabase_admin;

--
-- Name: document_number_sort_key(text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.document_number_sort_key(doc_no text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $_$
  SELECT to_char(
           CASE WHEN p.up COLLATE "C" ~ '^[A-Z]$'
                THEN CASE WHEN p.up COLLATE "C" >= 'X' THEN ascii(p.up) - ascii('X') ELSE ascii(p.up) - ascii('A') + 3 END
                ELSE 100 END, 'FM000')
         || chr(1) || p.prefix || chr(1) || lpad(p.digits, 20, '0') || chr(1) || p.whole
  FROM (SELECT COALESCE(doc_no, '') AS whole,
               regexp_replace(COALESCE(doc_no, ''), '[0-9]+$', '') AS prefix,
               upper(regexp_replace(COALESCE(doc_no, ''), '[0-9]+$', '')) AS up,
               COALESCE(substring(COALESCE(doc_no, '') FROM '[0-9]+$'), '') AS digits) p
$_$;

ALTER FUNCTION warehouse_security.document_number_sort_key(doc_no text) OWNER TO supabase_admin;

--
-- Name: enrollment_allowed(inet); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.enrollment_allowed(p_ip_address inet) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE cap_text text; daily_cap integer;
BEGIN
  SELECT value INTO cap_text FROM warehouse_security.auth_config WHERE key = 'enrollment_daily_cap';
  daily_cap := CASE WHEN cap_text ~ '^[0-9]{1,5}$' THEN cap_text::integer ELSE 30 END;
  RETURN (SELECT count(*) FROM warehouse_security.enrollment_log WHERE created_at > now() - interval '1 day') < daily_cap
    AND (p_ip_address IS NULL OR (SELECT count(*) FROM warehouse_security.enrollment_log
      WHERE created_at > now() - interval '1 day' AND ip_address = p_ip_address) < 3);
END $_$;

ALTER FUNCTION warehouse_security.enrollment_allowed(p_ip_address inet) OWNER TO supabase_admin;

