--
-- Name: issue_session(uuid, uuid); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.issue_session(p_user uuid, p_session uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE refresh text; session_id uuid;
BEGIN
  PERFORM 1 FROM public.user_profiles WHERE auth_user_id = p_user AND active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Active account required' USING ERRCODE = 'P0002'; END IF;
  refresh := encode(extensions.gen_random_bytes(32), 'hex');
  IF p_session IS NULL THEN
    INSERT INTO warehouse_security.refresh_sessions(user_id, token_hash, expires_at)
    VALUES (p_user, encode(extensions.digest(refresh, 'sha256'), 'hex'), now() + interval '7 days') RETURNING id INTO session_id;
  ELSE
    UPDATE warehouse_security.refresh_sessions SET token_hash = encode(extensions.digest(refresh, 'sha256'), 'hex')
    WHERE id = p_session AND user_id = p_user AND expires_at > now() RETURNING id INTO session_id;
    IF session_id IS NULL THEN RAISE EXCEPTION 'Session expired'; END IF;
  END IF;
  RETURN warehouse_security.sign_access_token(p_user, session_id) || jsonb_build_object('refresh_token', refresh);
END $$;

ALTER FUNCTION warehouse_security.issue_session(p_user uuid, p_session uuid) OWNER TO supabase_admin;

--
-- Name: jwt_sign_hs256(json, text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.jwt_sign_hs256(p_payload json, p_secret text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'extensions'
    AS $$
  SELECT signing_input || '.' ||
         translate(encode(hmac(convert_to(signing_input, 'UTF8'), convert_to(p_secret, 'UTF8'), 'sha256'), 'base64'), E'+/=\n', '-_')
  FROM (SELECT translate(encode(convert_to('{"alg":"HS256","typ":"JWT"}', 'UTF8'), 'base64'), E'+/=\n', '-_') || '.' ||
               translate(encode(convert_to(p_payload::text, 'UTF8'), 'base64'), E'+/=\n', '-_') AS signing_input) s
$$;

ALTER FUNCTION warehouse_security.jwt_sign_hs256(p_payload json, p_secret text) OWNER TO supabase_admin;

--
-- Name: FUNCTION jwt_sign_hs256(p_payload json, p_secret text); Type: COMMENT; Schema: warehouse_security; Owner: supabase_admin
--

COMMENT ON FUNCTION warehouse_security.jwt_sign_hs256(p_payload json, p_secret text) IS 'Migration 108: HS256 JWT, byte-identical to pgjwt extensions.sign(payload, secret). Internal: no API role can execute it.';

--
-- Name: like_literal(text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.like_literal(value text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT replace(replace(replace(value, '\', '\\'), '%', '\%'), '_', '\_')
$$;

ALTER FUNCTION warehouse_security.like_literal(value text) OWNER TO supabase_admin;

--
-- Name: normalize_phone(text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.normalize_phone(value text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE result text := regexp_replace(value, '[^0-9]', '', 'g');
BEGIN
  IF length(result) = 10 THEN result := '91' || result; END IF;
  IF result IS NULL OR result !~ '^91[0-9]{10}$' THEN RAISE EXCEPTION 'Expected a 10-digit Indian mobile number' USING ERRCODE = '22023'; END IF;
  RETURN result;
END $_$;

ALTER FUNCTION warehouse_security.normalize_phone(value text) OWNER TO supabase_admin;

--
-- Name: note_zero_charge_request(uuid, jsonb); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.note_zero_charge_request(p_invoice_id uuid, p_invoice_data jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
  PERFORM set_config('warehouse.zero_charge_request', jsonb_build_object(
    'invoice_id', p_invoice_id,
    'reason_sent', COALESCE((SELECT bool_or(jsonb_typeof(place) = 'object' AND place ? 'zero_charge_reason')
                             FROM (VALUES (p_invoice_data), (p_invoice_data->'header'), (p_invoice_data#>'{data,header}')) AS places(place)), false),
    'reason', COALESCE(p_invoice_data->>'zero_charge_reason', p_invoice_data#>>'{header,zero_charge_reason}',
                       p_invoice_data#>>'{data,header,zero_charge_reason}'),
    'lines_before', COALESCE((SELECT jsonb_agg(it.disp_trl_id) FROM public.invoice_trl it
                              WHERE it.invoice_id = p_invoice_id AND COALESCE(it.charge, 0) = 0), '[]'::jsonb))::text, true);
END $$;

ALTER FUNCTION warehouse_security.note_zero_charge_request(p_invoice_id uuid, p_invoice_data jsonb) OWNER TO supabase_admin;

--
-- Name: other_active_admin_exists(uuid); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.other_active_admin_exists(p_profile uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(71043);
  RETURN EXISTS (SELECT 1 FROM public.user_profiles WHERE role='admin' AND active
    AND enrollment_status='approved' AND NOT is_service_account AND id IS DISTINCT FROM p_profile);
END $$;

ALTER FUNCTION warehouse_security.other_active_admin_exists(p_profile uuid) OWNER TO supabase_admin;

--
-- Name: own_profile_id(); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.own_profile_id() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT p.id FROM public.user_profiles p WHERE p.auth_user_id = auth.uid() AND p.active
    AND EXISTS (SELECT 1 FROM warehouse_security.refresh_sessions s
      WHERE s.user_id = p.auth_user_id AND s.id::text = auth.jwt()->>'session_id' AND s.expires_at > now());
$$;

ALTER FUNCTION warehouse_security.own_profile_id() OWNER TO supabase_admin;

--
-- Name: owns_customer(uuid); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.owns_customer(customer uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT warehouse_security.active_role() IS NOT NULL AND (
    warehouse_security.active_role() IN ('admin','supervisor') OR EXISTS (
      SELECT 1 FROM public.users_customers_new a JOIN public.user_profiles p ON p.id=a.user_profile_id
      WHERE a.customer_id=customer AND a.active AND p.active AND p.auth_user_id=auth.uid()
    )
  );
$$;

ALTER FUNCTION warehouse_security.owns_customer(customer uuid) OWNER TO supabase_admin;

--
-- Name: price_rows_overlap(uuid, uuid, text, integer, integer, date, date, uuid); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.price_rows_overlap(p_item_id uuid, p_customer_id uuid, p_price_type text, p_weight_min integer, p_weight_max integer, p_from date, p_to date, p_exclude_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.item_storage_prices r
    WHERE r.item_id = p_item_id
      AND r.customer_id IS NOT DISTINCT FROM p_customer_id
      AND r.price_type = p_price_type
      AND r.id IS DISTINCT FROM p_exclude_id
      AND r.weight_min <= p_weight_max AND p_weight_min <= r.weight_max
      AND r.effective_from <= COALESCE(p_to, 'infinity'::date)
      AND p_from <= COALESCE(r.effective_to, 'infinity'::date));
$$;

ALTER FUNCTION warehouse_security.price_rows_overlap(p_item_id uuid, p_customer_id uuid, p_price_type text, p_weight_min integer, p_weight_max integer, p_from date, p_to date, p_exclude_id uuid) OWNER TO supabase_admin;

