    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE refusal text := warehouse_security.image_path_refusal(p_kind, p_document_id, p_image_type, p_storage_path);
BEGIN
  IF refusal IS NOT NULL THEN RAISE EXCEPTION '%', refusal USING ERRCODE = '22023'; END IF;
END $$;

ALTER FUNCTION warehouse_security.require_image_path(p_kind text, p_document_id uuid, p_image_type text, p_storage_path text) OWNER TO supabase_admin;

--
-- Name: require_person_supervisor(text, uuid); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.require_person_supervisor(p_supervisor text, p_current uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
  IF p_supervisor ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     AND EXISTS (SELECT 1 FROM public.user_profiles p
                 WHERE p.id = p_supervisor::uuid AND p.is_service_account
                   AND p.auth_user_id IS DISTINCT FROM auth.uid()
                   AND p.id IS DISTINCT FROM p_current) THEN
    RAISE EXCEPTION 'Supervisor must be a person, not a service account' USING ERRCODE = 'P0001';
  END IF;
END;
$_$;

ALTER FUNCTION warehouse_security.require_person_supervisor(p_supervisor text, p_current uuid) OWNER TO supabase_admin;

--
-- Name: reset_otp_limits(text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.reset_otp_limits(p_phone text) RETURNS integer
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE phone text := warehouse_security.normalize_phone(p_phone); cleared integer;
BEGIN
  IF session_user <> 'supabase_admin' THEN RAISE EXCEPTION 'Installer only' USING ERRCODE='42501'; END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(phone,71044));
  DELETE FROM warehouse_security.otp_send_log WHERE phone_number=phone;
  GET DIAGNOSTICS cleared = ROW_COUNT;
  UPDATE public.otp_rate_limits SET hourly_count=0,daily_count=0,last_reset_hour=now(),last_reset_day=now(),updated_at=now()
    WHERE phone_number=phone;
  RETURN cleared;
END $$;

ALTER FUNCTION warehouse_security.reset_otp_limits(p_phone text) OWNER TO supabase_admin;

--
-- Name: search_terms(text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.search_terms(query text) RETURNS text[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT COALESCE(array_agg('%' || replace(replace(replace(word, '\', '\\'), '%', '\%'), '_', '\_') || '%'), '{}')
  FROM (SELECT word FROM regexp_split_to_table(btrim(left(COALESCE(query, ''), 120)), '\s+') AS word
        WHERE word <> '' LIMIT 8) words
$$;

ALTER FUNCTION warehouse_security.search_terms(query text) OWNER TO supabase_admin;

--
-- Name: sign_access_token(uuid, uuid); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.sign_access_token(p_user uuid, p_session uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE profile public.user_profiles; secret text; expiry bigint; access_token text; access_lifetime integer := 3600;
BEGIN
  SELECT * INTO STRICT profile FROM public.user_profiles WHERE auth_user_id = p_user AND active;
  SELECT value INTO secret FROM warehouse_security.auth_config WHERE key = 'jwt_secret';
  IF length(COALESCE(secret, '')) < 32 THEN RAISE EXCEPTION 'Auth configuration missing'; END IF;
  SELECT COALESCE((SELECT value::integer FROM warehouse_security.auth_config WHERE key = 'access_seconds'), 3600) INTO access_lifetime;
  access_lifetime := greatest(60, least(access_lifetime, 86400));
  expiry := extract(epoch FROM now())::bigint + access_lifetime;
  access_token := warehouse_security.jwt_sign_hs256(jsonb_build_object('iss', 'supabase', 'aud', 'authenticated',
    'role', 'authenticated', 'sub', p_user, 'iat', extract(epoch FROM now())::bigint, 'exp', expiry,
    'session_id', p_session, 'phone', profile.mobile, 'user_role', profile.role,
    'user_metadata', jsonb_build_object('name', profile.name, 'display_name', profile.display_name, 'role', profile.role))::json, secret);
  RETURN jsonb_build_object('access_token', access_token,
    'expires_at', to_timestamp(expiry), 'expires_in', access_lifetime, 'token_type', 'bearer');
END $$;

ALTER FUNCTION warehouse_security.sign_access_token(p_user uuid, p_session uuid) OWNER TO supabase_admin;

--
-- Name: staff_may_remove_image_file(text, text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.staff_may_remove_image_file(p_bucket text, p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  SELECT warehouse_security.active_role() = 'staff' AND CASE p_bucket
    WHEN 'grn-images' THEN
      NOT EXISTS (SELECT 1 FROM public.grn_images i WHERE i.storage_path = p_name)
      AND EXISTS (SELECT 1 FROM public.goodsreceived g
        WHERE g.id::text = substring(p_name from '^(?:headers|items)/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/[^/]')
          AND g.deleted_at IS NULL
          AND (g.gr_image_url IS NULL OR position(p_name IN g.gr_image_url) = 0))
    WHEN 'dispatch-images' THEN
      NOT EXISTS (SELECT 1 FROM public.dispatch_images i WHERE i.storage_path = p_name)
      AND EXISTS (SELECT 1 FROM public.dispatch d
        WHERE d.id::text = substring(p_name from '^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/[^/]')
          AND d.deleted_at IS NULL
          AND (d.disp_image_url IS NULL OR position(p_name IN d.disp_image_url) = 0))
    ELSE false END;
$$;

ALTER FUNCTION warehouse_security.staff_may_remove_image_file(p_bucket text, p_name text) OWNER TO supabase_admin;

--
-- Name: standard_rate_failure(jsonb); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.standard_rate_failure(p_tiers jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE
  v_band jsonb; v_ord integer; v_field text; v_n numeric; v_limit numeric;
  v_prev_max integer; v_expected integer; v_min integer; v_max integer;
BEGIN
  IF p_tiers IS NULL OR jsonb_typeof(p_tiers) <> 'array' OR jsonb_array_length(p_tiers) = 0 OR jsonb_array_length(p_tiers) > 10 THEN
    RETURN warehouse_security.rate_failure('INVALID_BANDS', 'Bands must be a list of 1 to 10 bands');
  END IF;
  FOR v_band, v_ord IN SELECT e.value, (e.ord - 1)::integer FROM jsonb_array_elements(p_tiers) WITH ORDINALITY e(value, ord) ORDER BY e.ord LOOP
    IF jsonb_typeof(v_band) <> 'object' THEN
      RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord));
    END IF;
    FOREACH v_field IN ARRAY ARRAY['weight_min','weight_max'] LOOP
      IF jsonb_typeof(v_band->v_field) IS DISTINCT FROM 'number' THEN
        RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
      v_n := (v_band->>v_field)::numeric;
      IF v_n <> trunc(v_n) OR v_n < 0 OR v_n > 100000 THEN
        RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
    END LOOP;
    IF (v_band->>'weight_min')::numeric > (v_band->>'weight_max')::numeric THEN
      RETURN warehouse_security.rate_failure('INVALID_BAND', 'Each band needs whole kilograms with the start at most the end', jsonb_build_object('index', v_ord));
    END IF;
    FOREACH v_field IN ARRAY ARRAY['unit_price','labour_rate','tax_percent'] LOOP
      IF jsonb_typeof(v_band->v_field) IS DISTINCT FROM 'number' THEN
        RETURN warehouse_security.rate_failure('INVALID_AMOUNT', 'Rent and labour must be 0 to 999999 with two decimals at most; tax 0 to 100', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
      v_n := (v_band->>v_field)::numeric;
      v_limit := CASE WHEN v_field = 'tax_percent' THEN 100 ELSE 999999 END;
      IF v_n < 0 OR v_n > v_limit OR v_n * 100 <> trunc(v_n * 100) THEN
        RETURN warehouse_security.rate_failure('INVALID_AMOUNT', 'Rent and labour must be 0 to 999999 with two decimals at most; tax 0 to 100', jsonb_build_object('index', v_ord, 'field', v_field));
      END IF;
    END LOOP;
  END LOOP;
  -- Sorted by start: no overlap; the first tier starts at 0 and none leaves a gap.
  v_prev_max := NULL; v_expected := 0;
  FOR v_band, v_ord IN SELECT e.value, (e.ord - 1)::integer FROM jsonb_array_elements(p_tiers) WITH ORDINALITY e(value, ord)
      ORDER BY (e.value->>'weight_min')::numeric, e.ord LOOP
    v_min := (v_band->>'weight_min')::numeric::integer; v_max := (v_band->>'weight_max')::numeric::integer;
    IF v_prev_max IS NOT NULL AND v_min <= v_prev_max THEN
      RETURN warehouse_security.rate_failure('BANDS_OVERLAP', 'Weight bands overlap', jsonb_build_object('index', v_ord));
    END IF;
    IF v_min <> v_expected THEN
      RETURN warehouse_security.rate_failure('BANDS_GAP', 'The default rate''s bands must start at 0 kg and follow on without gaps',
        jsonb_build_object('index', v_ord, 'expected_min', v_expected));
    END IF;
    v_prev_max := v_max; v_expected := v_max + 1;
  END LOOP;
  RETURN NULL;
END $$;

ALTER FUNCTION warehouse_security.standard_rate_failure(p_tiers jsonb) OWNER TO supabase_admin;

--
-- Name: trimmed_reason(text); Type: FUNCTION; Schema: warehouse_security; Owner: supabase_admin
--

CREATE FUNCTION warehouse_security.trimmed_reason(reason text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
  SELECT NULLIF(regexp_replace(COALESCE(reason, ''),
    '^[\s\u0085\u00A0\u00AD\u1680\u180E\u2000-\u200F\u2028-\u202F\u205F-\u2064\u3000\uFEFF]+|[\s\u0085\u00A0\u00AD\u1680\u180E\u2000-\u200F\u2028-\u202F\u205F-\u2064\u3000\uFEFF]+$',
    '', 'g'), '')
$_$;

ALTER FUNCTION warehouse_security.trimmed_reason(reason text) OWNER TO supabase_admin;

