--
-- Name: intrusion_events; Type: TABLE; Schema: public; Owner: supabase_admin
--

CREATE TABLE public.intrusion_events (
    id integer NOT NULL,
    event_type text NOT NULL,
    severity text NOT NULL,
    source_ip text,
    destination_ip text,
    port integer,
    process_name text,
    process_pid integer,
    details jsonb,
    recorded_at timestamp with time zone DEFAULT now()
)
WITH (autovacuum_vacuum_threshold='100', autovacuum_vacuum_scale_factor='0.02', autovacuum_analyze_threshold='100', autovacuum_analyze_scale_factor='0.01');

ALTER TABLE public.intrusion_events OWNER TO supabase_admin;

--
-- Name: high_cpu_analysis; Type: VIEW; Schema: public; Owner: supabase_admin
--

CREATE VIEW public.high_cpu_analysis AS
 SELECT (intrusion_events.recorded_at AT TIME ZONE 'Asia/Kolkata'::text) AS "time",
    intrusion_events.process_name,
    intrusion_events.process_pid,
    ((intrusion_events.details ->> 'cpu_percent'::text))::numeric AS cpu_percent,
    (intrusion_events.details ->> 'full_command'::text) AS full_command,
        CASE
            WHEN (intrusion_events.process_name = ANY (ARRAY['ps'::text, 'awk'::text, 'grep'::text, 'intrusion-metrics'::text])) THEN 'Monitoring (Ignore)'::text
            WHEN (intrusion_events.process_name = ANY (ARRAY['npm'::text, 'node'::text, 'yarn'::text, 'webpack'::text])) THEN 'Development Server (Normal)'::text
            WHEN (intrusion_events.process_name = ANY (ARRAY['docker'::text, 'containerd'::text, 'dockerd'::text])) THEN 'Docker (Normal)'::text
            WHEN (intrusion_events.process_name = ANY (ARRAY['postgres'::text, 'postgrest'::text, 'supavisor'::text])) THEN 'Database (Normal)'::text
            WHEN (intrusion_events.process_name = ANY (ARRAY['chrome'::text, 'firefox'::text, 'chromium'::text])) THEN 'Browser (Normal)'::text
            WHEN ((intrusion_events.process_name ~~ '%miner%'::text) OR (intrusion_events.process_name ~~ '%crypto%'::text)) THEN 'SUSPICIOUS - Potential Miner'::text
            WHEN (intrusion_events.process_name = ANY (ARRAY['xmrig'::text, 'minerd'::text, 'cpuminer'::text])) THEN 'CRITICAL - Known Miner'::text
            ELSE 'Review Required'::text
        END AS classification
   FROM public.intrusion_events
  WHERE (intrusion_events.event_type = 'high_cpu_process'::text)
  ORDER BY intrusion_events.recorded_at DESC;

ALTER TABLE public.high_cpu_analysis OWNER TO supabase_admin;

