--
-- Name: sensor_status; Type: VIEW; Schema: public; Owner: supabase_admin
--

CREATE VIEW public.sensor_status WITH (security_invoker='true') AS
 WITH base AS (
         SELECT d.id AS device_id,
            d.device_name,
            d.location,
            d.active,
            d.external_id,
            d.mac_address,
            d.model,
            d.hub_id,
            h.host AS hub_host,
            h.online AS hub_online,
            l.temperature,
            l.humidity,
            l.measured_at,
            l.temperature_at,
            l.humidity_at,
            COALESCE(l.battery_low, d.battery_low) AS battery_low,
            d.battery_percent,
            COALESCE(l.signal_level, d.signal_level) AS signal_level,
            COALESCE(l.report_interval_s, d.report_interval_s) AS report_interval_s,
            GREATEST(l.last_seen_at, d.last_seen_at) AS last_seen_at,
            COALESCE(d.staleness_threshold_minutes, 30) AS staleness_threshold_minutes,
            d.alert_config,
            d.consecutive_failures,
            l.updated_at
           FROM ((public.sensor_devices d
             LEFT JOIN public.sensor_latest l ON ((l.device_id = d.id)))
             LEFT JOIN public.sensor_hubs h ON ((h.hub_id = d.hub_id)))
        ), flagged AS (
         SELECT b.device_id,
            b.device_name,
            b.location,
            b.active,
            b.external_id,
            b.mac_address,
            b.model,
            b.hub_id,
            b.hub_host,
            b.hub_online,
            b.temperature,
            b.humidity,
            b.measured_at,
            b.temperature_at,
            b.humidity_at,
            b.battery_low,
            b.battery_percent,
            b.signal_level,
            b.report_interval_s,
            b.last_seen_at,
            b.staleness_threshold_minutes,
            b.alert_config,
            b.consecutive_failures,
            b.updated_at,
            ((b.last_seen_at IS NULL) OR (b.last_seen_at < (now() - make_interval(mins => b.staleness_threshold_minutes)))) AS stale,
            ((b.measured_at IS NULL) OR (b.measured_at < (now() - make_interval(mins => b.staleness_threshold_minutes)))) AS values_stale
           FROM base b
        ), status AS (
         SELECT f.device_id,
            f.device_name,
            f.location,
            f.active,
            f.external_id,
            f.mac_address,
            f.model,
            f.hub_id,
            f.hub_host,
            f.hub_online,
            f.temperature,
            f.humidity,
            f.measured_at,
            f.temperature_at,
            f.humidity_at,
            f.battery_low,
            f.battery_percent,
            f.signal_level,
            f.report_interval_s,
            f.last_seen_at,
            f.staleness_threshold_minutes,
            f.alert_config,
            f.consecutive_failures,
            f.updated_at,
            f.stale,
            f.values_stale,
                CASE
                    WHEN (f.hub_online IS FALSE) THEN 'OFFLINE'::text
                    WHEN (f.last_seen_at IS NULL) THEN 'UNKNOWN'::text
                    WHEN f.stale THEN 'STALE'::text
                    ELSE 'ONLINE'::text
                END AS connectivity_status,
                CASE
                    WHEN f.battery_low THEN 'LOW'::text
                    WHEN (NOT f.battery_low) THEN 'OK'::text
                    ELSE 'UNKNOWN'::text
                END AS battery_status
           FROM flagged f
        )
 SELECT s.device_id,
    s.device_name,
    s.location,
    s.active,
    s.external_id,
    s.mac_address,
    s.model,
    s.hub_id,
    s.hub_host,
    s.hub_online,
    s.temperature,
    s.humidity,
    s.measured_at,
    s.temperature_at,
    s.humidity_at,
    s.battery_low,
    s.battery_percent,
    s.signal_level,
    s.report_interval_s,
    s.last_seen_at,
    s.staleness_threshold_minutes,
    s.alert_config,
    s.consecutive_failures,
    s.updated_at,
    s.stale,
    s.values_stale,
    s.connectivity_status,
    s.battery_status,
        CASE
            WHEN (s.connectivity_status = 'UNKNOWN'::text) THEN 'unknown'::text
            WHEN (s.connectivity_status = ANY (ARRAY['OFFLINE'::text, 'STALE'::text])) THEN 'offline'::text
            WHEN (s.battery_low OR s.values_stale) THEN 'warning'::text
            ELSE 'healthy'::text
        END AS health_status
   FROM status s;

