--
-- Name: users_customers_new starter_assignments; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_assignments ON public.users_customers_new FOR SELECT TO authenticated USING (((warehouse_security.active_role() = ANY (ARRAY['admin'::text, 'supervisor'::text])) OR (user_profile_id = public.get_current_user_profile_id())));

--
-- Name: items starter_catalog; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_catalog ON public.items FOR SELECT TO authenticated USING ((warehouse_security.active_role() IS NOT NULL));

--
-- Name: customers starter_customer; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_customer ON public.customers FOR SELECT TO authenticated USING (warehouse_security.owns_customer(id));

--
-- Name: dispatch starter_customer; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_customer ON public.dispatch FOR SELECT TO authenticated USING (warehouse_security.owns_customer(customer_id));

--
-- Name: dispatch_images starter_customer; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_customer ON public.dispatch_images FOR SELECT TO authenticated USING ((((status)::text = 'confirmed'::text) AND (EXISTS ( SELECT 1
   FROM public.dispatch d
  WHERE ((d.id = dispatch_images.dispatch_id) AND warehouse_security.owns_customer(d.customer_id))))));

--
-- Name: dispatch_trl starter_customer; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_customer ON public.dispatch_trl FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.dispatch d
  WHERE ((d.id = dispatch_trl.disp_id) AND warehouse_security.owns_customer(d.customer_id)))));

--
-- Name: goodsreceived starter_customer; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_customer ON public.goodsreceived FOR SELECT TO authenticated USING (warehouse_security.owns_customer(customer_id));

--
-- Name: goodsreceived_trl starter_customer; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_customer ON public.goodsreceived_trl FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM public.goodsreceived g
  WHERE ((g.id = goodsreceived_trl.gr_id) AND warehouse_security.owns_customer(g.customer_id)))));

--
-- Name: grn_images starter_customer; Type: POLICY; Schema: public; Owner: supabase_admin
--

CREATE POLICY starter_customer ON public.grn_images FOR SELECT TO authenticated USING ((((status)::text = 'confirmed'::text) AND (EXISTS ( SELECT 1
